// Gerado via AI Gateway com base em diretrizes BR/AHA/ESC/SBC/MS 2024-2026
import type { QuizQuestion } from "@/types/medical";

export const quizQuestionsExtra: QuizQuestion[] = [
  { id: 101, question: "Um paciente de 65 anos, tabagista (40 anos-maço), procura o pronto-socorro devido a dispneia progressiva e tosse produtiva há 3 dias. Ao exame físico, apresenta FR 26 irpm, ausculta pulmonar com sibilos difusos e roncos. Apresenta história prévia de múltiplos episódios de exacerbação de DPOC nos últimos anos. Qual a conduta inicial mais adequada para este paciente, considerando a suspeita de exacerbação aguda de DPOC?", options: ["Oxigenoterapia para manter SpO2 entre 88-92%, β2-agonista de curta duração e corticosteroides sistêmicos.", "Início imediato de antibiótico de amplo espectro, oxigenoterapia e broncodilatadores de longa duração.", "Internação em UTI para intubação orotraqueal e ventilação mecânica invasiva de imediato.", "Administração de diurético de alça intravenoso e avaliação para ventilação não invasiva."], correctIndex: 0, explanation: "A conduta inicial para exacerbação aguda de DPOC inclui oxigenoterapia para SpO2 88-92%, broncodilatadores de curta duração (β2-agonista e/ou anticolinérgico) e corticosteroides sistêmicos, conforme diretrizes GOLD.", category: "Pneumologia" },
  { id: 102, question: "Em relação ao diagnóstico e acompanhamento da asma, qual dos seguintes exames complementares é considerado o padrão-ouro para avaliar a limitação do fluxo aéreo?", options: ["Radiografia de tórax.", "Gasometria arterial.", "Espirometria.", "Teste de broncoprovocação."], correctIndex: 2, explanation: "A espirometria é o padrão-ouro para o diagnóstico e avaliação da gravidade da asma, medindo volumes e fluxos pulmonares e demonstrando a limitação do fluxo aéreo, que é reversível.", category: "Pneumologia" },
  { id: 103, question: "Uma paciente de 30 anos, sem comorbidades, é diagnosticada com pneumonia adquirida na comunidade (PAC). Ela apresenta boa condição geral, sem fatores de risco para microrganismos resistentes. Qual a terapia antibiótica empírica de primeira linha recomendada para tratamento ambulatorial de PAC em paciente previamente saudável, conforme as diretrizes atuais?", options: ["Azitromicina.", "Amoxicilina associada a clavulanato.", "Ceftriaxona intravenosa.", "Levofloxacina."], correctIndex: 0, explanation: "Para pacientes ambulatoriais, previamente saudáveis e sem uso recente de antibióticos, a azitromicina (macrolídeo) é uma das opções de primeira linha, sendo bem estabelecida nas diretrizes brasileiras.", category: "Pneumologia" },
  { id: 104, question: "Qual das seguintes características clínicas NÃO é tipicamente associada ao derrame pleural parapneumônico complicado ou empiema?", options: ["Líquido pleural com pH < 7,2.", "Líquido pleural com glicose < 40 mg/dL.", "Líquido pleural com LDH < 200 UI/L.", "Presença de bactérias no Gram ou cultura do líquido pleural."], correctIndex: 2, explanation: "Derrame pleural parapneumônico complicado ou empiema geralmente se associa a pH baixo (< 7,2), glicose baixa (< 40 mg/dL) e LDH elevado (> 1000 UI/L ou > 3x o limite superior do soro). LDH < 200 UI/L seria mais compatível com derrame não complicado.", category: "Pneumologia" },
  { id: 105, question: "Um homem de 55 anos, tabagista e etilista, foi submetido a uma tomografia de tórax que revelou um nódulo pulmonar sólido, com 15 mm de diâmetro, bordas espiculadas e sem calcificações. A chance de malignidade é considerada alta. Qual a próxima conduta para investigação diagnóstica?", options: ["Acompanhamento com nova tomografia em 6 meses.", "Biopsia guiada por tomografia ou broncoscopia.", "PET-CT com FDG para avaliação metabólica.", "Prescrição empírica de antibiótico."], correctIndex: 1, explanation: "Nódulos com alta probabilidade de malignidade (tamanho > 8mm, espiculados, sem calcificação em pacientes de risco) requerem investigação diagnóstica definitiva, como biópsia, para confirmação histopatológica.", category: "Pneumologia" },
  { id: 106, question: "Em relação à ventilação mecânica não invasiva (VMNI), qual das seguintes condições é uma contraindicação ABSOLUTA para seu uso na insuficiência respiratória aguda?", options: ["Insuficiência respiratória hipoxêmica grave.", "Instabilidade hemodinâmica e parada cardiorrespiratória.", "DPOC exacerbado com acidose respiratória leve.", "Edema agudo de pulmão cardiogênico."], correctIndex: 1, explanation: "A instabilidade hemodinâmica, parada cardiorrespiratória e a ausência de drive respiratório são contraindicações absolutas para VMNI, requerendo via aérea definitiva e ventilação mecânica invasiva.", category: "Pneumologia" },
  { id: 107, question: "Qual é a principal causa de derrame pleural em pacientes com insuficiência cardíaca congestiva?", options: ["Infecção bacteriana.", "Tromboembolismo pulmonar.", "Aumento da pressão hidrostática nos capilares pleurais.", "Diminuição da pressão oncótica plasmática."], correctIndex: 2, explanation: "Na insuficiência cardíaca congestiva, o derrame pleural é tipicamente um transudato causado pelo aumento da pressão hidrostática nos capilares pleurais, o que favorece o extravasamento de líquido para o espaço pleural.", category: "Pneumologia" },
  { id: 108, question: "Um paciente de 40 anos, com história de asma persistente moderada, em uso regular de corticosteroide inalatório e agonista beta-2 de longa duração, mantém sintomas diurnos frequentes e despertares noturnos. Qual a próxima etapa na otimização do tratamento, conforme as diretrizes GINA?", options: ["Aumentar a dose do corticosteroide inalatório.", "Adicionar um antagonista do receptor de leucotrienos.", "Trocar o agonista beta-2 de longa duração por um agonista beta-2 de curta duração.", "Iniciar corticosteroide oral em baixas doses."], correctIndex: 0, explanation: "De acordo com o GINA, se os sintomas persistirem apesar do tratamento inicial, a próxima etapa é otimizar a dose do corticosteroide inalatório, aumentando-a antes de considerar outras classes de medicamentos.", category: "Pneumologia" },
  { id: 109, question: "Em um paciente com suspeita de tromboembolismo pulmonar (TEP), qual o exame complementar padrão-ouro para o diagnóstico?", options: ["Radiografia de tórax.", "Eletrocardiograma.", "Angiografia pulmonar por tomografia (Angio-TC).", "Dímero-D."], correctIndex: 2, explanation: "A Angio-TC de tórax é o exame padrão-ouro e de escolha para o diagnóstico confirmatório de tromboembolismo pulmonar, permitindo a visualização direta dos trombos nas artérias pulmonares.", category: "Pneumologia" },
  { id: 110, question: "Qual das seguintes opções CORRETAMENTE descreve a fisiopatologia da síndrome do desconforto respiratório agudo (SDRA)?", options: ["Obstrução das vias aéreas com aprisionamento de ar.", "Inflamação sistêmica resultando em aumento da permeabilidade capilar pulmonar e edema.", "Fibrose progressiva do interstício pulmonar.", "Infecção bacteriana das vias aéreas superiores."], correctIndex: 1, explanation: "A SDRA é caracterizada por inflamação pulmonar difusa, aumento da permeabilidade capilar pulmonar, resultando em edema pulmonar não cardiogênico, e hipoxemia refratária.", category: "Pneumologia" },
  { id: 111, question: "Um paciente de 65 anos, hipertenso e diabético, é admitido no pronto-socorro com dor torácica retroesternal irradiada para o membro superior esquerdo, de forte intensidade, iniciada há 30 minutos. O eletrocardiograma (ECG) inicial revela supradesnivelamento do segmento ST em V1-V4. Qual a conduta inicial mais apropriada para este paciente?", options: ["Administrar oxigênio, nitrato sublingual, morfina e considerar fibrinolíticos imediatamente.", "Administrar oxigênio, nitrato sublingual, morfina, antiagregantes plaquetários e transferir para hemodinâmica para angioplastia primária.", "Administrar AAS, clopidogrel, heparina de baixo peso molecular e solicitar troponina.", "Realizar ecocardiograma de urgência para avaliar função ventricular antes de qualquer intervenção."], correctIndex: 1, explanation: "O paciente apresenta um infarto agudo do miocárdio com supradesnivelamento do ST na parede anterior. A conduta prioritária é a reperfusão coronariana. A angioplastia primária é a estratégia preferencial quando o tempo para realização é inferior a 120 minutos, precedida de dupla antiagregação e anticoagulação.", category: "Cardiologia" },
  { id: 112, question: "Qual dos seguintes fármacos anti-hipertensivos é contraindicado em pacientes com estenose bilateral da artéria renal?", options: ["Anlodipino", "Hidroclorotiazida", "Lisinopril", "Prazosina"], correctIndex: 2, explanation: "Inibidores da enzima conversora de angiotensina (IECA), como o lisinopril, são contraindicados em estenose bilateral da artéria renal, pois podem precipitar insuficiência renal aguda ao comprometer a filtração glomerular dependente da angiotensina II.", category: "Cardiologia" },
  { id: 113, question: "No manejo da insuficiência cardíaca com fração de ejeção reduzida (ICFEr), qual classe de medicamentos demonstrou consistentemente reduzir mortalidade e reinternações, sendo considerada um dos pilares do tratamento?", options: ["Diuréticos de alça", "Bloqueadores dos canais de cálcio", "Inibidores do cotransportador de sódio-glicose 2 (iSGLT2)", "Alfa-bloqueadores"], correctIndex: 2, explanation: "Os iSGLT2, como dapagliflozina ou empagliflozina, demonstraram em grandes ensaios clínicos reduzir significativamente mortalidade cardiovascular e hospitalizações por IC em pacientes com ICFEr, independentemente da presença de diabetes.", category: "Cardiologia" },
  { id: 114, question: "Um paciente de 70 anos apresenta palpitações e dispneia leve. O ECG mostra ritmo irregularmente irregular, ausência de ondas P e complexos QRS estreitos. Qual o diagnóstico mais provável e a principal complicação a ser prevenida a longo prazo?", options: ["Taquicardia ventricular; insuficiência cardíaca.", "Fibrilação atrial; acidente vascular cerebral isquêmico.", "Bradicardia sinusal; síncope.", "Flutter atrial; tromboembolismo pulmonar."], correctIndex: 1, explanation: "A descrição do ECG é clássica de fibrilação atrial. A principal complicação a longo prazo da fibrilação atrial é a formação de trombos no átrio esquerdo, levando a acidente vascular cerebral isquêmico, o que justifica a anticoagulação.", category: "Cardiologia" },
  { id: 115, question: "Qual exame complementar é o padrão-ouro para avaliar a disfunção diastólica e a fração de ejeção do ventrículo esquerdo na maioria dos cenários clínicos?", options: ["Cintilografia miocárdica", "Ressonância magnética cardíaca", "Ecocardiograma transtorácico", "Cateterismo cardíaco"], correctIndex: 2, explanation: "O ecocardiograma transtorácico é um método não invasivo, amplamente disponível e de baixo custo, que fornece informações detalhadas sobre a estrutura cardíaca, função sistólica e diastólica, além de valvopatias, sendo o padrão-ouro inicial.", category: "Cardiologia" },
  { id: 116, question: "Um paciente de 45 anos, exfumante, apresenta claudicação intermitente em panturrilha direita após caminhar 200 metros. O exame físico revela pulsos pediosos e tibiais posteriores diminuídos à direita e índice tornozelo-braquial (ITB) de 0,7. Qual o diagnóstico mais provável?", options: ["Trombose venosa profunda", "Neuropatia periférica", "Doença arterial periférica", "Síndrome do túnel do tarso"], correctIndex: 2, explanation: "Claudicação intermitente associada a pulsos diminuídos e ITB reduzido (<0,9) são achados clássicos de doença arterial periférica, causada por aterosclerose que obstrui as artérias dos membros inferiores.", category: "Cardiologia" },
  { id: 117, question: "Qual das seguintes válvulas cardíacas é mais frequentemente acometida em pacientes com febre reumática?", options: ["Válvula pulmonar", "Válvula aórtica", "Válvula mitral", "Válvula tricúspide"], correctIndex: 2, explanation: "A válvula mitral é a mais frequentemente e gravemente afetada pela febre reumática, resultando em estenose ou insuficiência mitral, ou ambas, com sequelas a longo prazo.", category: "Cardiologia" },
  { id: 118, question: "Sobre o tratamento da hipertensão arterial sistêmica, qual a meta pressórica para a maioria dos adultos acima de 18 anos, segundo as diretrizes brasileiras?", options: ["Pressão arterial sistólica < 140 mmHg e pressão arterial diastólica < 90 mmHg.", "Pressão arterial sistólica < 130 mmHg e pressão arterial diastólica < 80 mmHg.", "Pressão arterial sistólica < 120 mmHg e pressão arterial diastólica < 80 mmHg.", "Pressão arterial sistólica < 150 mmHg e pressão arterial diastólica < 90 mmHg."], correctIndex: 1, explanation: "As diretrizes atuais preconizam que para a maioria dos adultos, a meta pressórica deve ser <130/80 mmHg, desde que bem tolerada, para otimizar a redução de eventos cardiovasculares.", category: "Cardiologia" },
  { id: 119, question: "Um paciente com diagnóstico recente de angina estável foi prescrito com ácido acetilsalicílico (AAS) e atorvastatina. Qual é o principal mecanismo de ação do AAS nesse contexto?", options: ["Vasodilatação coronariana.", "Inibição da agregação plaquetária via bloqueio da COX-1.", "Redução da frequência cardíaca.", "Diminuição da pré-carga cardíaca."], correctIndex: 1, explanation: "O AAS inibe irreversivelmente a ciclooxigenase-1 (COX-1) nas plaquetas, impedindo a síntese de tromboxano A2, um potente agregante plaquetário, e prevenindo eventos trombóticos em pacientes com aterosclerose.", category: "Cardiologia" },
  { id: 120, question: "Qual das seguintes condições clínicas representa uma contraindicação absoluta para o uso de betabloqueadores em pacientes com síndromes coronarianas agudas?", options: ["Asma brônquica grave não controlada.", "Diabetes mellitus tipo 2.", "Doença pulmonar obstrutiva crônica (DPOC) leve.", "Hipertireoidismo."], correctIndex: 0, explanation: "Asma brônquica grave não controlada é uma contraindicação absoluta para betabloqueadores, devido ao risco de broncoespasmo severo. DPOC leve ou moderada permite o uso com cautela de betabloqueadores cardioseletivos.", category: "Cardiologia" },
  { id: 121, question: "Em um paciente jovem com dor torácica atípica e sopro sistólico ejetivo paraesternal esquerdo com irradiação para borda esternal esquerda que aumenta com a manobra de Valsalva, qual a hipótese diagnóstica mais provável?", options: ["Estenose aórtica severa.", "Cardiomiopatia hipertrófica obstrutiva.", "Insuficiência mitral.", "Prolapso da válvula mitral."], correctIndex: 1, explanation: "A cardiomiopatia hipertrófica obstrutiva (CMHO) classicamente apresenta um sopro sistólico ejetivo que aumenta com a manobra de Valsalva, devido à diminuição do volume ventricular e exacerbação da obstrução da via de saída do VE.", category: "Cardiologia" },
  { id: 122, question: "Qual das seguintes arritmias cardíacas é mais frequentemente associada a corações estruturalmente normais e, em alguns casos, pode ser curada por ablação por cateter?", options: ["Fibrilação atrial persistente.", "Taquicardia ventricular em cardiopatia estrutural.", "Taquicardia por reentrada nodal (TRN).", "Fibrilação ventricular."], correctIndex: 2, explanation: "A taquicardia por reentrada nodal (TRN) é uma taquicardia supraventricular comum em corações estruturalmente normais, caracterizada por um mecanismo de reentrada no nó atrioventricular, sendo frequentemente curável por ablação. Fibrilação atrial e taquicardia ventricular têm associação mais forte com cardiopatia estrutural.", category: "Cardiologia" },
  { id: 123, question: "Na emergência, qual dos seguintes achados clínicos é o mais indicativo de tamponamento cardíaco em um paciente com derrame pericárdico?", options: ["Sopro sistólico novo.", "Pressão arterial elevada e síncope.", "Taquicardia sinusal e dor torácica pleurítica.", "Hipofonese de bulhas, distensão jugular e hipotensão (Tríade de Beck)."], correctIndex: 3, explanation: "A Tríade de Beck (hipotensão arterial, distensão das veias jugulares e abafamento das bulhas cardíacas) é o achado clínico clássico e mais indicativo de tamponamento cardíaco, refletindo a compressão cardíaca pelo líquido pericárdico.", category: "Cardiologia" },
  { id: 124, question: "Um indivíduo assintomático de 50 anos apresenta pressão arterial de consultório consistentemente acima de 140/90 mmHg em três diferentes ocasiões. Exames laboratoriais e eletrocardiograma são normais. Qual o estágio da hipertensão, de acordo com as diretrizes brasileiras, e qual a recomendação inicial?", options: ["Estágio 1; iniciar tratamento farmacológico e medidas não farmacológicas.", "Pré-hipertensão; apenas medidas não farmacológicas.", "Estágio 2; iniciar tratamento farmacológico e medidas não farmacológicas.", "Hipertensão do avental branco; monitorização ambulatorial da pressão arterial (MAPA) ou residencial (MRPA)."], correctIndex: 0, explanation: "Pressão arterial entre 140-159/90-99 mmHg caracteriza Hipertensão Estágio 1. Nesses casos, em pacientes sem lesão de órgão-alvo ou alto risco cardiovascular, inicia-se com tratamento farmacológico e medidas não farmacológicas.", category: "Cardiologia" },
  { id: 125, question: "Qual antídoto é utilizado para reverter os efeitos anticoagulantes da heparina não fracionada em caso de sangramento grave?", options: ["Vitamina K", "Sulfato de protamina", "Plasma fresco congelado", "Ácido tranexâmico"], correctIndex: 1, explanation: "O sulfato de protamina é o antídoto específico para a heparina não fracionada, formando um complexo estável que neutraliza sua atividade anticoagulante. A vitamina K é para antagonistas da vitamina K, e o plasma fresco congelado para reposição de fatores de coagulação.", category: "Cardiologia" },
  { id: 126, question: "Um paciente de 65 anos, hipertenso e diabético, é internado com dor torácica típica que iniciou há 3 horas. O eletrocardiograma (ECG) de entrada mostra supradesnivelamento do segmento ST em V1-V4. Qual a conduta inicial mais apropriada para este paciente, considerando a logística de um hospital terciário com capacidade para cateterismo?", options: ["Administração de trombolítico e acompanhamento em unidade coronariana.", "Preparo para angioplastia primária em até 90 minutos do primeiro contato médico.", "Administração de nitrato sublingual e aguardar melhora dos sintomas para avaliar conduta.", "Realizar ecocardiograma transesofágico para descartar dissecção aórtica antes de qualquer intervenção."], correctIndex: 1, explanation: "O supradesnivelamento do segmento ST (STEMI) indica infarto agudo do miocárdio com elevação do ST. A angioplastia primária é a estratégia de reperfusão preferencial e deve ser realizada o mais rápido possível, idealmente em até 90 minutos do primeiro contato médico, se disponível.", category: "Cardiologia" },
  { id: 127, question: "Qual das seguintes medicações de escolha tem a principal função de reduzir o remodelamento ventricular pós-infarto agudo do miocárdio e diminuir a mortalidade em pacientes com disfunção de ventrículo esquerdo?", options: ["Anlodipino", "Sinvastatina", "Enalapril", "Digoxina"], correctIndex: 2, explanation: "Inibidores da enzima conversora de angiotensina (IECA), como o enalapril, são essenciais no manejo pós-infarto com disfunção ventricular. Eles reduzem o remodelamento, a progressão da insuficiência cardíaca e a mortalidade, atuando no sistema renina-angiotensina-aldosterona.", category: "Cardiologia" },
  { id: 128, question: "Um homem de 45 anos, obeso, tabagista, apresenta-se com dor torácica opressiva aos esforços, que alivia com repouso. O eletrocardiograma em repouso é normal. Qual é o exame complementar inicial de maior utilidade para investigar a doença arterial coronariana neste paciente?", options: ["Angiotomografia de coronárias", "Teste ergométrico", "Cateterismo cardíaco", "Ecocardiograma com estresse farmacológico"], correctIndex: 1, explanation: "Pelos sintomas típicos de angina estável em paciente com fatores de risco e ECG normal em repouso, o teste ergométrico é o exame não invasivo inicial mais custo-efetivo para avaliar isquemia miocárdica induzível.", category: "Cardiologia" },
  { id: 129, question: "Qual é o principal critério diagnóstico para a definição de hipertensão arterial sistêmica em adultos, segundo a maioria das diretrizes brasileiras?", options: ["Pressão arterial sistólica ≥ 130 mmHg e/ou diastólica ≥ 80 mmHg em uma única aferição.", "Pressão arterial sistólica ≥ 140 mmHg e/ou diastólica ≥ 90 mmHg, confirmada em pelo menos duas aferições em diferentes visitas médicas.", "Pressão arterial sistólica flutuante entre 120 e 139 mmHg em mais de uma ocasião.", "Apenas relato do paciente de cefaleia ou tontura associada à pressão alta."], correctIndex: 1, explanation: "De acordo com as Diretrizes Brasileiras de Hipertensão, o diagnóstico de HAS é estabelecido por valores de PAS ≥ 140 mmHg e/ou PAD ≥ 90 mmHg, confirmados em pelo menos duas aferições em diferentes visitas médicas, excluindo HA do jaleco branco.", category: "Cardiologia" },
  { id: 130, question: "Uma paciente de 70 anos, com história prévia de acidente vascular cerebral isquêmico, apresenta fibrilação atrial permanente. Qual das seguintes opções é a mais indicada para a profilaxia de novos eventos tromboembólicos?", options: ["Ácido acetilsalicílico em baixa dose.", "Clopidogrel isolado.", "Varfarina ou um anticoagulante oral direto (DOAC).", "Associação de ácido acetilsalicílico e clopidogrel."], correctIndex: 2, explanation: "Em pacientes com fibrilação atrial e alto risco de AVC (como história prévia de AVC), a anticoagulação oral é a conduta de escolha. Varfarina ou DOACs são superiores à terapia antiplaquetária isolada na prevenção de eventos tromboembólicos.", category: "Cardiologia" },
  { id: 131, question: "Durante a avaliação de um paciente com insuficiência cardíaca crônica de fração de ejeção reduzida (ICFEr), qual das seguintes opções de tratamento demonstrou reduzir mortalidade e reinternações, sendo considerada um pilar terapêutico?", options: ["Digoxina", "Furosemida", "Sacubitril/valsartana", "Anlodipino"], correctIndex: 2, explanation: "Os inibidores da neprilisina/bloqueadores do receptor da angiotensina (ARNI), como sacubitril/valsartana, são uma classe de drogas que comprovadamente reduzem a morbimortalidade em pacientes com ICFEr, sendo um dos pilares atuais do tratamento.", category: "Cardiologia" },
  { id: 132, question: "Qual arritmia cardíaca geralmente está associada a um ritmo irregularmente irregular no eletrocardiograma e ausência de ondas P bem definidas?", options: ["Taquicardia ventricular", "Fibrilação atrial", "Flutter atrial", "Taquicardia supraventricular paroxística"], correctIndex: 1, explanation: "A fibrilação atrial é caracterizada eletrocardiograficamente por irregularidade na frequência ventricular (ritmo irregularmente irregular) e ausência de ondas P discerníveis, substituídas por ondas f de fibrilação.", category: "Cardiologia" },
  { id: 133, question: "Um paciente jovem, previamente hígido, apresenta síncope súbita durante exercício físico intenso. O eletrocardiograma de repouso mostra ondas Q patológicas em V2-V5 e supradesnivelamento persistente do segmento ST em algumas derivações. Qual hipótese diagnóstica deve ser fortemente considerada?", options: ["Estenose aórtica congênita", "Cardiomiopatia hipertrófica", "Displasia arritmogênica do ventrículo direito", "Cardiomiopatia dilatada"], correctIndex: 2, explanation: "A síncope durante o exercício em jovem, associada a alterações no ECG como ondas Q anômalas e supradesnivelamento de ST (indicando aneurisma ventricular ou dilatação), pode sugerir displasia arritmogênica do ventrículo direito, pela sua predisposição a arritmias ventriculares.", category: "Cardiologia" },
  { id: 134, question: "No tratamento da crise hipertensiva (emergência hipertensiva), qual é o objetivo principal da redução da pressão arterial nas primeiras horas?", options: ["Reduzir a pressão arterial diastólica para menos de 60 mmHg.", "Reduzir a pressão arterial sistólica para valores <120 mmHg rapidamente.", "Reduzir a pressão arterial média em não mais que 25% na primeira hora.", "Normalizar completamente a pressão arterial em até 30 minutos."], correctIndex: 2, explanation: "Em emergências hipertensivas, a meta é reduzir a pressão arterial média em 10-20% na primeira hora e não mais que 25% nas primeiras 24 horas para evitar hipoperfusão e danos isquêmicos de órgãos-alvo, exceto em condições específicas como dissecção aórtica ou AVC hemorrágico.", category: "Cardiologia" },
  { id: 135, question: "Qual das seguintes condições clínicas é uma contraindicação absoluta para o uso de betabloqueadores em pacientes com insuficiência cardíaca crônica?", options: ["Asma brônquica grave em vigência de broncoespasmo.", "Diabetes mellitus tipo 2 controlado.", "Doença pulmonar obstrutiva crônica (DPOC) leve.", "Hipertireoidismo compensado."], correctIndex: 0, explanation: "Betabloqueadores são contraindicados em pacientes com asma brônquica grave em vigência de broncoespasmo, devido ao risco de piora da obstrução brônquica. Em DPOC, devem ser usados com cautela e preferência por agentes cardiosseletivos.", category: "Cardiologia" },
  { id: 136, question: "Um paciente apresenta-se com dispneia progressiva, ortopneia e edema de membros inferiores. O ecocardiograma revela aumento de câmaras cardíacas, disfunção sistólica importante e fração de ejeção de 25%. Qual o diagnóstico mais provável?", options: ["Miocardite aguda", "Tamponamento cardíaco", "Cardiomiopatia dilatada", "Estenose aórtica grave"], correctIndex: 2, explanation: "A cardiomiopatia dilatada é caracterizada por aumento das câmaras cardíacas e disfunção sistólica, levando a sintomas como dispneia, ortopneia e edema, compatíveis com insuficiência cardíaca de fração de ejeção reduzida.", category: "Cardiologia" },
  { id: 137, question: "Qual marcador bioquímico cardíaco é considerado o \"gold standard\" para o diagnóstico de necrose miocárdica em síndromes coronarianas agudas?", options: ["Creatinoquinase MB (CK-MB)", "Mioglobina", "Proteína C reativa (PCR)", "Troponinas cardíacas de alta sensibilidade (TCHS)"], correctIndex: 3, explanation: "As troponinas cardíacas de alta sensibilidade (TCHS) são os biomarcadores mais sensíveis e específicos para detectar necrose miocárdica, sendo o \"gold standard\" para o diagnóstico de infarto agudo do miocárdio, com elevação precoce e prolongada.", category: "Cardiologia" },
  { id: 138, question: "Qual é a principal indicação para o uso de desfibrilador cardíaco implantável (CDI) em pacientes com insuficiência cardíaca?", options: ["Prevenção primária de morte súbita em pacientes com fração de ejeção ventricular esquerda (FEVE) ≤ 35% e sintomas de classe funcional II/III, apesar de tratamento otimizado.", "Cardioversão de fibrilação atrial em pacientes instáveis.", "Controle de frequência para taquicardias supraventriculares.", "Estimulação cardíaca em bradicardias sintomáticas."], correctIndex: 0, explanation: "O CDI é indicado para prevenção primária de morte súbita cardíaca em pacientes com insuficiência cardíaca de fração de ejeção reduzida (FEVE ≤ 35%) e sintomas moderados a graves (CF II/III), que recebem terapia otimizada, ou em prevenção secundária após eventos como parada cardíaca por TV/FV.", category: "Cardiologia" },
  { id: 139, question: "Uma gestante de 32 semanas, previamente normotensa, apresenta pressão arterial de 150/95 mmHg em duas aferições com diferença de 4 horas, associada a edema de face e proteinúria de 2+. Qual o diagnóstico mais provável?", options: ["Hipertensão gestacional", "Hipertensão crônica", "Pré-eclâmpsia", "Eclâmpsia"], correctIndex: 2, explanation: "A pré-eclâmpsia é caracterizada pelo desenvolvimento de hipertensão em gestantes após 20 semanas de gestação, associada a proteinúria (ou outros sinais de disfunção de órgão-alvo), como no caso descrito.", category: "Cardiologia" },
  { id: 140, question: "Em relação à farmacodinâmica dos nitratos (ex: dinitrato de isossorbida), qual é o principal mecanismo de ação que contribui para o alívio da angina pectoris?", options: ["Aumento da contratilidade miocárdica.", "Vasoconstrição arterial coronariana.", "Vasodilatação venosa, reduzindo a pré-carga e o trabalho cardíaco.", "Aumento da pós-carga ventricular esquerda."], correctIndex: 2, explanation: "Os nitratos agem principalmente pela vasodilatação venosa, o que reduz o retorno venoso ao coração (pré-carga), diminui o volume diastólico final e, consequentemente, o trabalho cardíaco, aliviando a angina. Também promovem vasodilatação coronariana.", category: "Cardiologia" },
  { id: 141, question: "Um paciente com insuficiência cardíaca descompensada apresenta congestão pulmonar, edema e sinais de hipoperfusão periférica (choque cardiogênico). Qual é a principal prioridade terapêutica inicial?", options: ["Início de diuréticos orais em altas doses.", "Administração de betabloqueadores para controle da frequência.", "Suporte inotrópico e/ou vasopressor para estabilização hemodinâmica.", "Realização de ecocardiograma transesofágico."], correctIndex: 2, explanation: "Em choque cardiogênico (pacientes \"úmidos e frios\"), a prioridade é estabilizar a hemodinâmica com agentes inotrópicos (para melhorar a contratilidade) e/ou vasopressores (para elevar a PA), visando melhorar a perfusão de órgãos-alvo.", category: "Cardiologia" },
  { id: 142, question: "Qual das seguintes etiologias de taquicardia de QRS largo (QRS > 0,12s) é a mais comum e potencialmente mais grave?", options: ["Taquicardia supraventricular com aberrância", "Taquicardia ventricular", "Síndrome de Wolff-Parkinson-White com condução antidrômica", "Taquicardia atrial multifocal"], correctIndex: 1, explanation: "A taquicardia ventricular é a causa mais comum de taquicardia de QRS largo e é potencialmente fatal devido ao risco de degeneração para fibrilação ventricular. Sempre deve-se presumir TV até prova em contrário na presença de QRS largo.", category: "Cardiologia" },
  { id: 143, question: "Qual o achado eletrocardiográfico clássico sugestivo de pericardite aguda?", options: ["Supradesnivelamento do segmento ST difuso e concavo para cima, acompanhado de infradesnivelamento do segmento PR.", "Ondas Q patológicas e supradesnivelamento do segmento ST em parede inferior.", "Infradesnivelamento difuso do segmento ST e ondas T invertidas.", "Bloqueio de ramo esquerdo novo ou presumivelmente novo."], correctIndex: 0, explanation: "A pericardite aguda é caracterizada classicamente por supradesnivelamento difuso e côncavo do segmento ST em múltiplas derivações (exceto aVR e V1) e, frequentemente, infradesnivelamento do segmento PR.", category: "Cardiologia" },
  { id: 144, question: "Um homem de 50 anos, diabético tipo 2, com dislipidemia e hipertensão, apresenta-se com dor epigástrica e mal-estar. O ECG de 12 derivações mostra infradesnivelamento do segmento ST em D2, D3 e aVF. Qual a principal hipótese diagnóstica?", options: ["Gastroenterite aguda", "Esofagite", "Síndrome coronariana aguda sem supradesnivelamento do ST (SCASSST)", "Pericardite aguda"], correctIndex: 2, explanation: "A dor epigástrica e o mal-estar podem ser equivalentes anginosos, especialmente em pacientes com múltiplos fatores de risco. O infradesnivelamento do ST na parede inferior é um sinal de isquemia miocárdica, indicando uma SCASSST (infarto sem supra ou angina instável).", category: "Cardiologia" },
  { id: 145, question: "Qual dos seguintes parâmetros é fundamental para o cálculo do escore de CHA2DS2-VASc, utilizado para estratificação de risco de AVC em pacientes com fibrilação atrial?", options: ["Nível plasmático de colesterol total.", "Presença de doença pulmonar obstrutiva crônica (DPOC).", "Idade do paciente (≥ 65 ou ≥ 75 anos).", "História de apendicectomia."], correctIndex: 2, explanation: "O escore CHA2DS2-VASc inclui fatores como insuficiência cardíaca congestiva, hipertensão, idade (≥65 e ≥75 anos), diabetes mellitus, AVC/AIT/TE prévios, doença vascular e sexo (feminino), sendo a idade um importante componente.", category: "Cardiologia" },
  { id: 146, question: "Qual é a principal função dos diuréticos de alça (ex: furosemida) no tratamento da insuficiência cardíaca descompensada?", options: ["Reduzir o remodelamento ventricular esquerdo.", "Controlar a frequência ventricular na fibrilação atrial.", "Promover a diurese e aliviar a congestão.", "Diminuir a sensibilidade à angiotensina II."], correctIndex: 2, explanation: "Diuréticos de alça são potentes diuréticos que atuam no segmento ascendente da alça de Henle, promovendo uma rápida e significativa diurese, essencial para aliviar a sobrecarga de volume e a congestão em pacientes com IC descompensada.", category: "Cardiologia" },
  { id: 147, question: "Qual a principal causa de mortalidade em longo prazo em pacientes com insuficiência cardíaca crônica?", options: ["Acidente vascular cerebral", "Morte súbita cardíaca", "Câncer", "Doença renal crônica"], correctIndex: 1, explanation: "A morte súbita cardíaca (MSC), frequentemente devido a arritmias ventriculares, é a principal causa de mortalidade em longo prazo em pacientes com insuficiência cardíaca crônica, superando o número de mortes por progressão da IC.", category: "Cardiologia" },
  { id: 148, question: "Um paciente apresenta dispneia paroxística noturna, ortopneia e crepitantes finos na base pulmonar, sugestivo de insuficiência cardíaca. Qual exame complementar inicial é mais adequado para confirmar a disfunção ventricular e avaliar a etiologia?", options: ["Raio-X de tórax", "Ecocardiograma transtorácico", "Tomografia computadorizada de tórax", "Eletrocardiograma de repouso"], correctIndex: 1, explanation: "O ecocardiograma transtorácico é o exame de escolha para avaliar a função cardíaca (sistólica e diastólica), volumes das câmaras, pressões e etiologias da insuficiência cardíaca, sendo crucial para o diagnóstico e manejo.", category: "Cardiologia" },
  { id: 149, question: "Qual dos seguintes achados eletrocardiográficos é mais sugestivo de isquemia subendocárdica?", options: ["Supradesnivelamento do segmento ST.", "Inversão da onda T simétrica e profunda.", "Onda Q patológica.", "Infradesnivelamento do segmento ST horizontal ou descendente."], correctIndex: 3, explanation: "O infradesnivelamento do segmento ST, horizontal ou descendente, especialmente em múltiplas derivações, é o achado eletrocardiográfico mais característico de isquemia subendocárdica (angina instável ou infarto sem supra), indicando comprometimento de uma parte do miocárdio.", category: "Cardiologia" },
  { id: 150, question: "No tratamento da hipertensão arterial, qual classe de anti-hipertensivos é contraindicada em pacientes com estenose bilateral da artéria renal?", options: ["Diuréticos tiazídicos", "Bloqueadores dos canais de cálcio", "Inibidores da enzima conversora de angiotensina (IECA) e bloqueadores do receptor da angiotensina (BRA)", "Betabloqueadores"], correctIndex: 2, explanation: "IECA e BRA são contraindicados em estenose bilateral da artéria renal (ou estenose em rim único funcionante) devido ao risco de insuficiência renal aguda grave, pois dependem da angiotensina II para manter a filtração glomerular através da vasoconstrição da arteríola eferente.", category: "Cardiologia" },
  { id: 151, question: "Um paciente de 65 anos, tabagista (40 anos-maço), apresenta dispneia progressiva há 5 anos e tosse crônica com expectoração matinal. À espirometria, observa-se VEF1/CVF < 0,7 pós-broncodilatador e VEF1 55% do previsto. Qual o diagnóstico e a classificação GOLD mais provável?", options: ["Asma, GOLD 2", "DPOC, GOLD B", "DPOC, GOLD C", "DPOC, GOLD D"], correctIndex: 3, explanation: "O paciente possui DPOC (tabagismo + obstrução persistente) com VEF1 55% (GOLD 2) e sintomas importantes (dispneia progressiva), o que o classifica como GOLD D, de acordo com as diretrizes GOLD 2024.", category: "Pneumologia" },
  { id: 152, question: "Qual das seguintes intervenções não medicamentosas é a mais eficaz para melhorar a sobrevida em pacientes com Doença Pulmonar Obstrutiva Crônica (DPOC)?", options: ["Vacinação contra influenza e pneumococo", "Reabilitação pulmonar", "Oxigenoterapia domiciliar em pacientes com hipoxemia crônica grave", "Cessação do tabagismo"], correctIndex: 3, explanation: "A cessação do tabagismo é a única intervenção que comprovadamente altera o curso natural da DPOC, retardando a progressão da doença e melhorando a sobrevida dos pacientes.", category: "Pneumologia" },
  { id: 153, question: "Um paciente de 40 anos, asmático, em uso de formoterol/budesonida, procura o pronto-socorro com crise de asma grave (dispneia intensa, fala em frases, sibilos difusos, SpO2 90% em ar ambiente). Qual a conduta inicial mais adequada?", options: ["Internação em UTI e intubação orotraqueal imediata", "Administração de oxigênio suplementar, agonista beta-2 de curta ação (SABA) e corticoide sistêmico", "Manter o uso do formoterol/budesonida e aguardar melhora", "Administração de sulfato de magnésio endovenoso como primeira linha"], correctIndex: 1, explanation: "Diante de uma crise asmática grave, a conduta inicial envolve oxigênio, SABA (broncodilatador de resgate) e corticoide sistêmico para controlar a inflamação e a obstrução brônquica, conforme diretrizes GINA 2024.", category: "Pneumologia" },
  { id: 154, question: "Qual o principal critério para o diagnóstico de tuberculose pulmonar ativa em um paciente com tosse por mais de 3 semanas, febre e perda de peso?", options: ["Radiografia de tórax com infiltrado apical", "Prova tuberculínica (PPD) fortemente reatora", "Baciloscopia de escarro positiva para bacilos álcool-ácido resistentes (BAAR)", "Cultura de escarro com crescimento de Mycobacterium tuberculosis"], correctIndex: 2, explanation: "A baciloscopia de escarro positiva para BAAR confirma o diagnóstico de tuberculose pulmonar ativa, especialmente em pacientes sintomáticos respiratórios, sendo um método rápido e disponível pelo SUS.", category: "Pneumologia" },
  { id: 155, question: "Um paciente de 70 anos, previamente hígido, desenvolve pneumonia comunitária grave. Apresenta febre, tosse produtiva e dispneia, com SpO2 88% em ar ambiente. A radiografia de tórax mostra infiltrado em lobo inferior direito. Qual a terapia antibiótica empírica de primeira linha, de acordo com as diretrizes brasileiras?", options: ["Amoxicilina", "Azitromicina", "Ceftriaxona + Azitromicina", "Ciprofloxacino"], correctIndex: 2, explanation: "Para pneumonia comunitária grave, a antibioticoterapia empírica, segundo as diretrizes de 2024, deve cobrir patógenos típicos e atípicos, sendo a combinação de betalactâmico (ceftriaxona) e macrolídeo (azitromicina) a escolha adequada.", category: "Pneumologia" },
  { id: 156, question: "Qual das seguintes características clínicas é mais sugestiva de embolia pulmonar?", options: ["Dor pleurítica de início súbito, dispneia e taquicardia", "Tosse crônica, sibilância e dispneia noturna", "Expectoração mucopurulenta, febre e calafrios", "Perda de peso, sudorese noturna e tosse seca"], correctIndex: 0, explanation: "A embolia pulmonar classicamente apresenta-se com dispneia de início súbito, dor torácica pleurítica e taquicardia, embora possa ter manifestações variadas.", category: "Pneumologia" },
  { id: 157, question: "Qual o principal fator de risco modificável para o desenvolvimento de fibrose pulmonar idiopática?", options: ["Exposição a amianto", "Refluxo gastroesofágico", "Tabagismo", "Infecções virais prévias"], correctIndex: 2, explanation: "O tabagismo é o principal fator de risco modificável para a fibrose pulmonar idiopática, embora a etiopatogenia seja multifatorial e ainda não totalmente compreendida.", category: "Pneumologia" },
  { id: 158, question: "No manejo da asma, a principal diferença entre os esquemas 'step-up' e 'step-down' refere-se a:", options: ["Aumento ou diminuição da dose do corticoide inalatório", "Inclusão ou retirada de broncodilatador de longa duração", "Estrutura da titulação do tratamento de acordo com o controle da doença", "Substituição de um medicamento por outro mais potente"], correctIndex: 2, explanation: "'Step-up' é o aumento da intensidade do tratamento quando o controle da asma não é atingido; 'step-down' é a redução da terapia quando o controle é mantido por período prolongado, ambos visando a menor dose eficaz para o controle.", category: "Pneumologia" },
  { id: 159, question: "Qual o principal exame para confirmação diagnóstica de bronquiectasias?", options: ["Radiografia de tórax", "Tomografia computadorizada de alta resolução (TCAR) de tórax", "Espirometria", "Broncoscopia"], correctIndex: 1, explanation: "A TCAR de tórax é o 'padrão-ouro' para o diagnóstico de bronquiectasias, permitindo a visualização detalhada da dilatação e espessamento das vias aéreas.", category: "Pneumologia" },
  { id: 160, question: "Em um paciente com efusão pleural unilateral, qual o padrão-ouro para diferenciar transudato de exsudato?", options: ["Análise bioquímica do líquido pleural (Critérios de Light)", "Achados da radiografia de tórax", "Punção e drenagem do líquido pleural", "Biópsia pleural"], correctIndex: 0, explanation: "Os critérios de Light, que avaliam proteínas e desidrogenase lática (DHL) no líquido pleural e no soro, são o padrão-ouro para classificar o derrame como transudato ou exsudato.", category: "Pneumologia" },
  { id: 161, question: "Qual das seguintes vacinas é recomendada para todos os pacientes com DPOC, independentemente da idade?", options: ["Vacina contra Haemophilus influenzae tipo b", "Vacina contra difteria, tétano e coqueluche (dTpa)", "Vacina contra influenza (gripe)", "Vacina oral contra poliomielite"], correctIndex: 2, explanation: "A vacina anual contra influenza é fortemente recomendada para todos os pacientes com DPOC para prevenir exacerbações e reduzir morbimortalidade, conforme diretrizes GOLD.", category: "Pneumologia" },
  { id: 162, question: "Um paciente tabagista (20 anos-maço) de 50 anos apresenta-se com tosse persistente por 6 meses, associada à perda ponderal e hemoptise ocasional. A radiografia de tórax mostra nódulo pulmonar irregular de 3 cm no lobo superior esquerdo. Qual a próxima conduta diagnóstica mais apropriada?", options: ["Prescrição de antibióticos e reavaliação em 3 semanas", "Tomografia computadorizada de tórax com contraste", "Biópsia do nódulo pulmonar (guiada por TC ou broncoscopia)", "Acompanhamento radiológico em 6 meses"], correctIndex: 2, explanation: "Diante de um nódulo pulmonar com características suspeitas em paciente de alto risco (tabagista, idade, sintomas), a biópsia para diagnóstico histopatológico é a conduta mais apropriada e urgente para investigação de neoplasia.", category: "Pneumologia" },
  { id: 163, question: "Qual o mecanismo de ação da combinação formoterol/budesonida no tratamento da asma?", options: ["Ação anti-inflamatória e imunossupressora", "Broncodilatação rápida e prolongada e ação anti-inflamatória", "Apenas broncodilatação de curta duração", "Redução da produção de muco e expectoração"], correctIndex: 1, explanation: "O formoterol é um agonista beta-2 de longa ação com início rápido (broncodilatador), e a budesonida é um corticoide inalatório (anti-inflamatório), agindo em conjunto para controle da asma.", category: "Pneumologia" },
  { id: 164, question: "Em relação à Síndrome da Apneia Obstrutiva do Sono (SAOS), qual o 'padrão-ouro' para o seu diagnóstico?", options: ["Polissonografia noturna", "Questionário de Epworth", "Monitorização ambulatorial da pressão arterial", "Oximetria noturna"], correctIndex: 0, explanation: "A polissonografia noturna é o exame que registra múltiplas variáveis fisiológicas durante o sono, sendo o 'padrão-ouro' para o diagnóstico e quantificação da SAOS.", category: "Pneumologia" },
  { id: 165, question: "Um paciente jovem sem comorbidades subitamente apresenta dispneia e dor torácica aguda após esforço. Ao exame físico, observa-se murmúrio vesicular abolido no hemitórax esquerdo e hipertimpanismo à percussão. Qual o diagnóstico mais provável?", options: ["Edema agudo de pulmão", "Embolia pulmonar", "Pneumotórax espontâneo", "Crise asmática"], correctIndex: 2, explanation: "A tríade de instalação súbita, dispneia, dor torácica pleurítica, ausência de murmúrio vesicular e hipertimpanismo é clássica de pneumotórax, especialmente em jovens sem comorbidades (pneumotórax espontâneo primário).", category: "Pneumologia" },
  { id: 166, question: "Qual a principal complicação cardiovascular da hipertensão pulmonar?", options: ["Hipertrofia ventricular esquerda", "Insuficiência cardíaca diastólica", "Cor pulmonale (insuficiência ventricular direita)", "Miocardiopatia dilatada"], correctIndex: 2, explanation: "A hipertensão pulmonar leva a um aumento da pós-carga do ventrículo direito, culminando em sua hipertrofia e dilatação, caracterizando o cor pulmonale (insuficiência ventricular direita).", category: "Pneumologia" },
  { id: 167, question: "Qual o principal grupo farmacológico utilizado no tratamento de manutenção da fibrose pulmonar idiopática para retardar a progressão da doença?", options: ["Corticoesteroides", "Broncodilatadores", "Antibióticos de amplo espectro", "Antifibróticos (pirfenidona, nintedanibe)"], correctIndex: 3, explanation: "Os antifibróticos (pirfenidona e nintedanibe) são os únicos medicamentos aprovados que demonstraram reduzir a taxa de declínio da função pulmonar na fibrose pulmonar idiopática.", category: "Pneumologia" },
  { id: 168, question: "Na asma, qual dos seguintes achados espirométricos é esperado após o uso de broncodilatador em um paciente com obstrução de vias aéreas reversível?", options: ["Aumento do VEF1 em mais de 12% E 200 mL", "Diminuição do VEF1 em mais de 12% E 200 mL", "VEF1/CVF menor que 0,7", "Aumento da CVF em mais de 15%"], correctIndex: 0, explanation: "A reversibilidade da obstrução, característica da asma, é definida por um aumento do VEF1 maior ou igual a 12% E 200 mL após a inalação de um broncodilatador.", category: "Pneumologia" },
  { id: 169, question: "Um paciente chega ao pronto-socorro com tosse, febre, dor torácica e radiografia de tórax mostrando um derrame pleural volumoso. A toracocentese revela um líquido purulento. Qual o diagnóstico e a conduta imediata mais adequada?", options: ["Derrame pleural parapneumônico não complicado; antibioticoterapia oral", "Empiema pleural; drenagem torácica e antibioticoterapia venosa", "Derrame pleural maligno; encaminhamento para oncologista", "Tuberculose pleural; iniciar esquema RIPE"], correctIndex: 1, explanation: "Líquido purulento é diagnóstico de empiema pleural, que requer drenagem torácica (tórax com dreno) e antibioticoterapia sistêmica venosa para resolução da infecção.", category: "Pneumologia" },
  { id: 170, question: "Qual das seguintes etiologias é a mais comum para as bronquiectasias no Brasil, excluindo a fibrose cística?", options: ["Deficiência de alfa-1 antitripsina", "Infecções pulmonares na infância (sarampo, coqueluche, tuberculose)", "Pneumonite de hipersensibilidade", "Doença do refluxo gastroesofágico"], correctIndex: 1, explanation: "No Brasil, infecções pulmonares graves na infância, como tuberculose, sarampo e coqueluche, são importantes causas de bronquiectasias adquiridas não associadas à fibrose cística.", category: "Pneumologia" },
  { id: 171, question: "Qual medicação é contraindicada para alívio de sintomas em pacientes com bronquiolite viral aguda grave, em lactentes?", options: ["Oxigênio suplementar", "Nebulização com solução salina hipertônica", "Broncodilatadores inalatórios", "Hidratação venosa"], correctIndex: 2, explanation: "Segundo as diretrizes de 2024, broncodilatadores inalatórios não são recomendados rotineiramente para o tratamento da bronquiolite viral aguda em lactentes, pois não demonstram benefício consistente e podem causar efeitos adversos.", category: "Pneumologia" },
  { id: 172, question: "Um recém-nascido pré-termo nasce com 28 semanas de gestação e desenvolve desconforto respiratório grave logo após o nascimento. A radiografia de tórax revela baixo volume pulmonar e opacidades reticulogranulares difusas. Qual o diagnóstico mais provável?", options: ["Taquipneia transitória do recém-nascido", "Síndrome de aspiração de mecônio", "Doença da membrana hialina (DMH)", "Pneumonia congênita"], correctIndex: 2, explanation: "A Doença da Membrana Hialina (DMH) é comum em prematuros, decorrente da deficiência de surfactante pulmonar, e se manifesta com desconforto respiratório e achados radiográficos característicos.", category: "Pneumologia" },
  { id: 173, question: "Em pacientes com DPOC, qual o principal desfecho clínico que a terapia com corticoide inalatório (CI) busca prevenir, especialmente em pacientes com fenótipo de exacerbações frequentes?", options: ["Melhora da função pulmonar", "Diminuição da progressão da doença", "Redução do risco de exacerbações", "Aumento da sobrevida"], correctIndex: 2, explanation: "Em pacientes com DPOC e histórico de exacerbações (especialmente se com eosinofilia), a adição de corticoide inalatório à broncodilatação reduz significativamente a frequência de exacerbações.", category: "Pneumologia" },
  { id: 174, question: "Qual a principal causa infecciosa de pneumonia adquirida na comunidade em pacientes imunocompetentes no Brasil?", options: ["Mycoplasma pneumoniae", "Chlamydia pneumoniae", "Streptococcus pneumoniae", "Haemophilus influenzae"], correctIndex: 2, explanation: "Streptococcus pneumoniae (pneumococo) é consistentemente o agente etiológico bacteriano mais comum de pneumonia adquirida na comunidade em adultos imunocompetentes em todo o mundo, incluindo o Brasil.", category: "Pneumologia" },
  { id: 175, question: "Um paciente de 80 anos com histórico de insuficiência cardíaca congestiva apresenta dispneia súbita, tosse com expectoração rosa espumosa e crepitações em bases pulmonares à ausculta. A radiografia de tórax mostra cardiomegalia e infiltrados bilaterais em 'asas de borboleta'. Qual o diagnóstico mais provável?", options: ["Pneumonia bacteriana", "Embolia pulmonar", "Edema agudo de pulmão cardiogênico", "Exacerbação de DPOC"], correctIndex: 2, explanation: "A história de insuficiência cardíaca, dispneia súbita, expectoração rosa espumosa e os achados radiográficos (cardiomegalia, infiltrados em 'asas de borboleta') são clássicos do edema agudo de pulmão cardiogênico.", category: "Pneumologia" },
  { id: 176, question: "Um paciente de 35 anos, HIV positivo em uso de terapia antirretroviral regular e carga viral indetectável há 2 anos, apresenta-se com febre, tosse produtiva e dispneia há 5 dias. Radiografia de tórax revela infiltrado pulmonar extenso bilateral. A contagem de CD4 é de 50 células/mm³. Qual é o diagnóstico etiológico mais provável?", options: ["Pneumocystis jirovecii", "Tuberculose pulmonar", "Citomegalovírus", "Histoplasmose"], correctIndex: 0, explanation: "Em pacientes com HIV e CD4 abaixo de 200 células/mm³, a pneumonia por Pneumocystis jirovecii é uma das infecções oportunistas mais comuns e graves, manifestando-se com quadro respiratório agudo e infiltrados pulmonares difusos.", category: "Infectologia" },
  { id: 177, question: "Qual a principal recomendação para profilaxia primária de toxoplasmose cerebral em pacientes com HIV?", options: ["Sulfametoxazol-trimetoprim se CD4 < 100 células/mm³", "Azitromicina se CD4 < 50 células/mm³", "Isoniazida se PPD positivo", "Pirimetamina se CD4 < 200 células/mm³"], correctIndex: 0, explanation: "A profilaxia primária para toxoplasmose cerebral é indicada para pacientes com HIV e contagem de CD4 abaixo de 100 células/mm³, utilizando sulfametoxazol-trimetoprim, que também confere proteção contra Pneumocystis jirovecii.", category: "Infectologia" },
  { id: 178, question: "Um paciente de 60 anos, diabético e imunocompetente, é internado com quadro de erisipela em membro inferior, com bolhas e febre. Qual o tratamento antimicrobiano de primeira escolha para este caso?", options: ["Penicilina cristalina intravenosa", "Ciprofloxacino oral", "Doxiciclina oral", "Clindamicina intravenosa"], correctIndex: 0, explanation: "A erisipela é uma infecção cutânea aguda que comumente afeta as camadas mais superficiais da derme. A penicilina, especialmente a cristalina intravenosa para casos mais graves, é a droga de escolha devido à sua eficácia contra os estreptococos, principais agentes etiológicos.", category: "Infectologia" },
  { id: 179, question: "Em relação à febre maculosa (Rickettsia rickettsii) no Brasil, qual das seguintes afirmativas está correta?", options: ["A transmissão ocorre principalmente pelo carrapato-estrela (Amblyomma sculptum, A. cajennense).", "O tratamento de escolha é a amoxicilina.", "A doença apresenta quadro clínico geralmente brando e autolimitado.", "O diagnóstico definitivo é feito pela cultura de amostras de sangue."], correctIndex: 0, explanation: "A febre maculosa é transmitida principalmente pelo carrapato-estrela e exige início precoce do tratamento com doxiciclina. É uma doença grave que pode evoluir rapidamente para óbito se não tratada adequadamente.", category: "Infectologia" },
  { id: 180, question: "Qual é a principal indicação para o uso de ribavirina no tratamento de hepatites virais?", options: ["Hepatite C crônica, em combinação com agentes de ação direta (DAAs).", "Hepatite B aguda em pacientes imunocompetentes.", "Hepatite A grave com falência hepática aguda.", "Profilaxia pós-exposição para hepatite E."], correctIndex: 0, explanation: "A ribavirina, em combinação com agentes de ação direta (DAAs), ainda possui um papel no tratamento da hepatite C crônica, especialmente em casos selecionados com cirrose descompensada ou em regimes específicos, embora seu uso tenha diminuído com os novos DAAs.", category: "Infectologia" },
  { id: 181, question: "Um paciente de 40 anos, sem comorbidades, relata picada de animal em região rural há 3 dias. Apresenta febre, cefaleia e mialgia. Ao exame físico, nota-se lesão eritematosa circular com centro claro, tipo 'olho de boi', em coxa. Qual a conduta terapêutica mais adequada?", options: ["Doxiciclina oral por 14 a 21 dias", "Amoxicilina oral por 7 dias", "Cloroquina oral por 5 dias", "Prednisona oral por 10 dias"], correctIndex: 0, explanation: "O quadro clínico descrito, com eritema migratório após picada de carrapato em área rural, é altamente sugestivo de Doença de Lyme (neuroborreliose). A doxiciclina é o tratamento de escolha para as fases iniciais da doença.", category: "Infectologia" },
  { id: 182, question: "Em relação à meningite bacteriana em adultos, qual a estratégia de tratamento empírico inicial mais recomendada em um paciente imunocompetente, sem comorbidades e sem risco para Listeria, na ausência de dados de cultura?", options: ["Ceftriaxona e Vancomicina", "Amoxicilina e Vancomicina", "Ampicilina e Gentamicina", "Meropenem e Daptomicina"], correctIndex: 0, explanation: "Para meningite bacteriana empírica em adultos imunocompetentes, a combinação de ceftriaxona (cobrindo Streptococcus pneumoniae e Neisseria meningitidis) e vancomicina (para S. pneumoniae resistente) é a recomendação padrão, devendo-se adicionar ampicilina se houver suspeita de Listeria.", category: "Infectologia" },
  { id: 183, question: "Qual dos seguintes agentes fúngicos está mais comumente associado a meningite em pacientes com HIV e CD4 abaixo de 100 células/mm³?", options: ["Cryptococcus neoformans", "Candida albicans", "Aspergillus fumigatus", "Histoplasma capsulatum"], correctIndex: 0, explanation: "O Cryptococcus neoformans é o principal agente etiológico de meningite fúngica em pacientes com HIV, especialmente aqueles com CD4 muito baixos. O diagnóstico é feito principalmente pela pesquisa de antígeno criptocócico no LCR.", category: "Infectologia" },
  { id: 184, question: "Um paciente jovem, previamente hígido, desenvolve quadro de febre, prostração, icterícia e hepatomegalia, com elevação acentuada de transaminases. Relata viagem recente para área endêmica de saneamento precário. Qual a etiologia mais provável?", options: ["Hepatite A", "Hepatite B aguda", "Hepatite C aguda", "Hepatite alcoólica"], correctIndex: 0, explanation: "A hepatite A é uma infecção entérica transmitida por via fecal-oral, comum em áreas com saneamento precário. Em jovens e adultos, pode apresentar quadro sintomático com icterícia e elevação de transaminases.", category: "Infectologia" },
  { id: 185, question: "Em relação à malária, qual a conduta mais apropriada para um caso de malária grave por Plasmodium falciparum com nível de consciência rebaixado?", options: ["Artesunato intravenoso", "Cloroquina intravenosa", "Primaquina oral", "Mefloquina oral"], correctIndex: 0, explanation: "A malária grave por Plasmodium falciparum é uma emergência médica. O artesunato intravenoso é o tratamento de primeira escolha recomendado pela OMS e pelo Ministério da Saúde do Brasil para malária grave, incluindo casos com rebaixamento do nível de consciência.", category: "Infectologia" },
  { id: 186, question: "Qual a principal via de transmissão da hanseníase (Mycobacterium leprae)?", options: ["Contato íntimo e prolongado com gotículas de secreção de vias aéreas superiores de doentes não tratados.", "Picada de mosquito infectado.", "Ingestão de alimentos ou água contaminados.", "Contato sexual desprotegido."], correctIndex: 0, explanation: "A hanseníase é transmitida principalmente através do contato íntimo e prolongado de uma pessoa suscetível com um doente multibacilar não tratado, por via respiratória (gotículas e aerossóis).", category: "Infectologia" },
  { id: 187, question: "Um viajante retorna de área endêmica e apresenta febre alta súbita, mialgia intensa, dor retro-ocular e exantema maculopapular. Qual a principal suspeita diagnóstica?", options: ["Dengue", "Chikungunya", "Zika", "Varíola dos macacos"], correctIndex: 0, explanation: "Os sintomas descritos (febre alta súbita, mialgia intensa, dor retro-ocular) são clássicos da fase febril da dengue, especialmente após retorno de área endêmica. O exantema é comum.", category: "Infectologia" },
  { id: 188, question: "Qual das seguintes condições caracteriza-se pela presença de úlcera genital indolor, com bordas elevadas e fundo limpo, que desparece espontaneamente em algumas semanas, mesmo sem tratamento?", options: ["Sífilis primária", "Cancro mole", "Herpes genital", "Linfogranuloma venéreo"], correctIndex: 0, explanation: "A úlcera característica da sífilis primária é o cancro duro, que é tipicamente indolor, com bordas elevadas e fundo limpo, e pode desaparecer espontaneamente, o que não significa cura da infecção sistêmica.", category: "Infectologia" },
  { id: 189, question: "Em relação ao tratamento da sífilis primária e secundária, qual a principal recomendação para pacientes não alérgicos à penicilina?", options: ["Penicilina benzatina intramuscular, dose única", "Azitromicina oral por 7 dias", "Doxiciclina oral por 14 dias", "Ceftriaxona intramuscular por 10 dias"], correctIndex: 0, explanation: "A penicilina benzatina, em dose única intramuscular, é o tratamento de escolha para sífilis primária e secundária em pacientes não alérgicos, conforme as diretrizes do Ministério da Saúde do Brasil.", category: "Infectologia" },
  { id: 190, question: "Qual o principal critério para definir sucesso terapêutico na infecção por Helicobacter pylori?", options: ["Teste respiratório com ureia negativo após 4-6 semanas do término do tratamento", "Desaparecimento dos sintomas em 2 semanas", "Melhora endoscópica da gastrite", "Ausência de H. pylori em biópsia gástrica imediatamente após o tratamento"], correctIndex: 0, explanation: "O teste de ureia por expiração ou pesquisa de antígeno fecal são os métodos mais indicados para confirmar a erradicação do Helicobacter pylori, devendo ser realizados 4 a 6 semanas após o término do tratamento para evitar resultados falso-negativos.", category: "Infectologia" },
  { id: 191, question: "Um paciente com diagnóstico de cistite não complicada apresenta disúria, polaciúria e urgência miccional. Qual o tratamento empírico de primeira linha mais adequado, considerando o cenário brasileiro?", options: ["Fosfomicina trometamol dose única", "Ciprofloxacino por 3 dias", "Amoxicilina clavulanato por 7 dias", "Gentamicina intramuscular dose única"], correctIndex: 0, explanation: "A fosfomicina trometamol em dose única é uma opção eficaz e recomendada para o tratamento da cistite não complicada, especialmente frente à crescente resistência antimicrobiana a outras classes de drogas.", category: "Infectologia" },
  { id: 192, question: "Qual o principal fator fisiopatológico associado ao desenvolvimento de doença invasiva por Streptococcus pneumoniae em pacientes esplenectomizados?", options: ["Diminuição da capacidade de depuração de bactérias encapsuladas", "Deficiência de células T CD4+", "Aumento da produção de citocinas inflamatórias", "Aumento da colonização faríngea por S. pneumoniae"], correctIndex: 0, explanation: "O baço é fundamental na depuração de bactérias encapsuladas, como o Streptococcus pneumoniae. A esplenectomia compromete essa função, tornando os indivíduos mais suscetíveis a infecções graves e fulminantes por esses microrganismos.", category: "Infectologia" },
  { id: 193, question: "Qual a principal complicação infecciosa da caxumba em homens adultos?", options: ["Orquite", "Meningite asséptica", "Pancreatite", "Nefrite"], correctIndex: 0, explanation: "A orquite é a complicação mais comum da caxumba em homens adultos pós-puberais, podendo levar à atrofia testicular e, em alguns casos, à infertilidade. Meningite asséptica e pancreatite são outras complicações menos frequentes.", category: "Infectologia" },
  { id: 194, question: "Em surtos de sarampo, qual a principal medida de controle e profilaxia pós-exposição para contatos suscetíveis (não vacinados ou com esquema vacinal incompleto)?", options: ["Vacinação com a tríplice viral (SCR) em até 72 horas após o primeiro contato", "Administração de imunoglobulina humana específica", "Quimioprofilaxia com antiviral por 7 dias", "Isolamento social por 21 dias sem intervenção"], correctIndex: 0, explanation: "A vacinação com a tríplice viral (SCR) em até 72 horas após o contato é a medida mais eficaz para profilaxia pós-exposição ao sarampo em suscetíveis. A imunoglobulina é reservada para grupos de risco específicos.", category: "Infectologia" },
  { id: 195, question: "Um paciente de 25 anos apresenta febre de padrão diário, hepatosplenomegalia e linfadenopatia generalizada. A sorologia para doença de Chagas é positiva e a pesquisa de parasitemia por gota espessa é negativa, mas a cultura de sangue é positiva para Trypanosoma cruzi. Qual a fase clínica da doença?", options: ["Fase aguda com parasitemia detectável por cultura", "Fase crônica indeterminada", "Fase crônica cardíaca", "Fase crônica digestiva"], correctIndex: 0, explanation: "Na fase aguda da doença de Chagas, há sinais e sintomas como febre, hepatoesplenomegalia e linfadenopatia, acompanhados de parasitemia que é detectável por métodos diretos como a cultura de sangue ou esfregaço sanguíneo.", category: "Infectologia" },
  { id: 196, question: "Qual a principal via de transmissão da Leishmaniose visceral (Calazar) para humanos?", options: ["Picada do flebotomíneo (mosquito-palha) infectado", "Ingestão de alimentos contaminados com fezes de cães", "Contato direto com animal doente", "Transmissão vertical da mãe para o filho"], correctIndex: 0, explanation: "A leishmaniose visceral é transmitida ao ser humano pela picada de fêmeas de flebotomíneos infectados, que adquirem o parasita ao se alimentarem do sangue de animais reservatórios, principalmente cães.", category: "Infectologia" },
  { id: 197, question: "Em relação à esquistossomose, qual a complicação mais grave e frequente da fase crônica em adultos?", options: ["Hipertensão portal com varizes esofágicas e hemorragia digestiva", "Insuficiência renal crônica", "Paraplegia por mielopatia", "Cirrose biliar primária"], correctIndex: 0, explanation: "A esquistossomose mansônica crônica leva principalmente à fibrose periportal (fibrose de Symmers), que pode resultar em hipertensão portal, esplenomegalia e varizes esofágicas, com risco de hemorragia digestiva alta.", category: "Infectologia" },
  { id: 198, question: "Qual é o objetivo principal da terapia antirretroviral (TARV) em pacientes com HIV?", options: ["Reduzir a carga viral a níveis indetectáveis e otimizar a contagem de CD4.", "Erradicar o vírus HIV do organismo.", "Prevenir a transmissão sexual do HIV em 100% dos casos.", "Tratar todas as infecções oportunistas simultaneamente."], correctIndex: 0, explanation: "O principal objetivo da TARV é suprimir a replicação viral a níveis indetectáveis, restaurar ou preservar a imunidade (aumentando o CD4) e, consequentemente, melhorar a qualidade de vida e reduzir a morbimortalidade e a transmissibilidade do HIV.", category: "Infectologia" },
  { id: 199, question: "Um paciente apresenta lesões de cor acastanhada, com descamação fina e leve prurido, localizadas no tronco e face. O exame micológico direto revela hifas curtas e esporos arredondados, 'spaghetti and meatballs'. Qual o diagnóstico mais provável?", options: ["Pitiríase versicolor", "Tinea corporis", "Candidíase cutânea", "Psoríase vulgar"], correctIndex: 0, explanation: "A pitiríase versicolor, causada por Malassezia spp., manifesta-se com manchas hipo ou hiperpigmentadas e descamativas. A visibilização de hifas curtas e esporos ('spaghetti and meatballs') no exame micológico direto é diagnóstica.", category: "Infectologia" },
  { id: 200, question: "Em relação à profilaxia da endocardite infecciosa, em qual das seguintes situações está indicada a antibioticoterapia para um paciente com valva protética que será submetido a um procedimento dentário invasivo?", options: ["Sim, em todas as situações de procedimentos dentários que envolvam manipulação da gengiva ou da região periapical dentária.", "Não é mais indicada para pacientes com valva protética.", "Apenas se o paciente tiver histórico prévio de endocardite.", "Somente para procedimentos cirúrgicos maiores, não dentários."], correctIndex: 0, explanation: "A profilaxia da endocardite infecciosa é indicada para pacientes com próteses valvares que serão submetidos a procedimentos dentários com manipulação da gengiva ou região periapical, devido ao alto risco de bacteremia e subsequentemente de endocardite.", category: "Infectologia" },
  { id: 201, question: "Um paciente de 65 anos, hipertenso e diabético, é internado com dor torácica atípica. O eletrocardiograma (ECG) inicial não mostra alterações isquêmicas. Os níveis de troponina T ultrassensível são: 0h - 15 ng/L (normal < 14 ng/L); 3h - 18 ng/L. Qual a conduta inicial mais apropriada?", options: ["Descartar síndrome coronariana aguda (SCA) e investigar causas não cardíacas.", "Internar o paciente em unidade de dor torácica para novo ECG e troponina em 6 horas.", "Realizar investigação invasiva imediata (cineangiocoronariografia).", "Considerar SCA sem supradesnivelamento do segmento ST (SCASSST) e iniciar dupla antiagregação plaquetária."], correctIndex: 1, explanation: "A elevação e/ou curva da troponina, mesmo que discreta, exige investigação contínua. Para casos de baixo risco ou dúvida diagnóstica, novos exames (ECG e troponina) em 3-6 horas são fundamentais para definir a conduta, conforme diretrizes de SCA.", category: "Cardiologia" },
  { id: 202, question: "Qual das seguintes medicações é contraindicada na fase aguda de um infarto agudo do miocárdio com supradesnivelamento do segmento ST (IAMCSST) de parede inferior, associado a bradicardia e hipotensão?", options: ["Sulfato de morfina", "Atropina", "Nitroglicerina sublingual", "Aspirina"], correctIndex: 2, explanation: "A hipotensão e bradicardia em IAMCSST de parede inferior podem indicar envolvimento do ventrículo direito, que é pré-carga dependente. Nitratos causam vasodilatação e podem agravar a hipotensão. Morfina, aspirina e atropina (para bradicardia) são condutas típicas.", category: "Cardiologia" },
  { id: 203, question: "Uma paciente de 35 anos, previamente hígida, apresenta palpitações, tontura e síncope. O ECG revela taquicardia com complexos QRS estreitos e ritmo irregularmente irregular, sem ondas P visíveis. Qual o diagnóstico mais provável?", options: ["Taquicardia ventricular polimórfica", "Fibrilação atrial de alta resposta ventricular", "Taquicardia supraventricular paroxística", "Flutter atrial com condução AV variável"], correctIndex: 1, explanation: "Taquicardia com QRS estreito e ritmo irregularmente irregular sem ondas P visíveis é classicamente a apresentação eletrocardiográfica de fibrilação atrial. Taquicardia ventricular apresenta QRS largo. Flutter atrial pode ter ritmo irregular, mas geralmente são visíveis ondas F.", category: "Cardiologia" },
  { id: 204, question: "Qual o principal mecanismo de ação dos inibidores da enzima conversora de angiotensina (IECA) que contribui para o tratamento da insuficiência cardíaca com fração de ejeção reduzida (ICFEd)?", options: ["Aumento da contratilidade miocárdica", "Redução da pré-carga e pós-carga", "Bloqueio da aldosterona no receptor", "Potencialização da liberação de óxido nítrico"], correctIndex: 1, explanation: "Os IECA inibem a conversão de angiotensina I em angiotensina II, resultando em vasodilatação (reduzindo pré e pós-carga) e inibição da remodelamento cardíaco deletério, fundamental na fisiopatologia da ICFEd.", category: "Cardiologia" },
  { id: 205, question: "Um homem de 50 anos, tabagista, apresenta claudicação intermitente na panturrilha esquerda, que ocorre após caminhar 200 metros e alivia com o repouso. O exame físico revela pulsos pediosos e tibiais posteriores diminuídos à esquerda. Qual o índice tornozelo-braquial (ITB) mais provável neste caso?", options: ["ITB > 1,3", "ITB entre 1,0 e 1,3", "ITB entre 0,7 e 0,9", "ITB < 0,9"], correctIndex: 3, explanation: "Claudicação intermitente com pulsos diminuídos é altamente sugestiva de doença arterial periférica (DAP). Um ITB < 0,9 é o critério diagnóstico para DAP, indicando obstrução significativa do fluxo arterial para as extremidades inferiores.", category: "Cardiologia" },
  { id: 206, question: "Qual das seguintes condições representa uma contraindicação ABSOLUTA ao uso de betabloqueadores em pacientes com insuficiência cardíaca crônica?", options: ["Doença pulmonar obstrutiva crônica (DPOC) grave", "Bradicardia sinusal sintomática", "Bloqueio atrioventricular de primeiro grau", "Asma grave ativa"], correctIndex: 3, explanation: "Asma grave ativa é uma contraindicação absoluta ao uso de betabloqueadores devido ao risco de broncoespasmo fatal. DPOC grave é uma contraindicação relativa. Bradicardia sintomática requer cuidado, mas não é absoluta. BAV de primeiro grau não contraindica.", category: "Cardiologia" },
  { id: 207, question: "Uma paciente de 28 anos, gestante de 20 semanas, apresenta pressão arterial de 150/95 mmHg em duas ocasiões separadas por 4 horas. Não há proteinúria ou outros sinais de dano em órgão-alvo. Qual o diagnóstico mais provável?", options: ["Pré-eclâmpsia", "Hipertensão gestacional", "Hipertensão crônica", "Hipertensão do avental branco"], correctIndex: 1, explanation: "Hipertensão gestacional é definida como hipertensão arterial (PA ≥ 140/90 mmHg) que surge após a 20ª semana de gestação, sem proteinúria ou sinais de dano em órgão-alvo. Pré-eclâmpsia requer proteinúria ou outros achados.", category: "Cardiologia" },
  { id: 208, question: "Qual das seguintes manobras é a mais indicada para tentar abortar uma taquicardia supraventricular paroxística (TSVP) em um paciente hemodinamicamente estável?", options: ["Cardioversão elétrica sincronizada", "Massagem do seio carotídeo", "Administração intravenosa de adenosina", "Administração intravenosa de diltiazem"], correctIndex: 1, explanation: "Em pacientes hemodinamicamente estáveis com TSVP, as manobras vagais, como a manobra de Valsalva ou massagem do seio carotídeo, são a primeira linha de tratamento para tentar restaurar o ritmo sinusal, conforme diretrizes.", category: "Cardiologia" },
  { id: 209, question: "Os principais critérios maiores do diagnóstico de febre reumática são:", options: ["Artrite, cardite, nódulos subcutâneos, coreia de Sydenham e febre", "Artrite migratória, cardite, nódulos subcutâneos, eritema marginado e coreia de Sydenham", "Artrite, cardite, eritema marginado, coreia de Sydenham e valvulopatia", "Artrite, cardiomegalia, nódulos subcutâneos, coreia de Sydenham e dor articular"], correctIndex: 1, explanation: "Os critérios maiores de Jones modificados para febre reumática são: cardite, poliartrite migratória, coreia de Sydenham, eritema marginado e nódulos subcutâneos. Febre e valvulopatia são achados, mas não critérios maiores isolados.", category: "Cardiologia" },
  { id: 210, question: "Qual o achado eletrocardiográfico MAIS específico para o diagnóstico de pericardite aguda?", options: ["Infradesnivelamento difuso do segmento ST", "Supradesnivelamento difuso do segmento ST com concavidade para cima", "Ondas Q patológicas em parede anterior", "Alterações de repolarização em parede inferior"], correctIndex: 1, explanation: "O supradesnivelamento difuso do segmento ST com concavidade para cima (não limitado a uma área vascular) é o achado mais característico no ECG de pericardite aguda, frequentemente acompanhado por infradesnivelamento do segmento PR.", category: "Cardiologia" },
  { id: 211, question: "Um paciente de 70 anos apresenta dispneia progressiva, esforço físico limitado e sopro sistólico ejetivo audível em foco aórtico, que irradia para carótidas. O ecocardiograma revela estenose valvar aórtica grave. Qual a conduta MAIS apropriada para este paciente?", options: ["Início de diuréticos e betabloqueadores para controle sintomático.", "Considerar substituição valvar aórtica (TAVI ou cirurgia).", "Aconselhar repouso absoluto para evitar sobrecarga cardíaca.", "Realizar balão valvuloplastia aórtica para alívio dos sintomas."], correctIndex: 1, explanation: "Em pacientes sintomáticos com estenose valvar aórtica grave, a substituição valvar é a pedra angular do tratamento para melhorar os sintomas e prolongar a sobrevida. A balão valvuloplastia é paliativa e geralmente para pacientes inoperáveis.", category: "Cardiologia" },
  { id: 212, question: "Qual a principal causa de morte súbita em atletas jovens?", options: ["Miocardite", "Displasia arritmogênica do ventrículo direito", "Cardiopatia isquêmica", "Cardiomiopatia hipertrófica"], correctIndex: 3, explanation: "A cardiomiopatia hipertrófica é a causa mais comum de morte súbita em atletas jovens, devido ao risco de arritmias ventriculares malignas em corações submetidos a estresse físico intenso. As outras opções são menos frequentes nesse grupo.", category: "Cardiologia" },
  { id: 213, question: "Qual o tratamento farmacológico de escolha para pacientes com hipertensão arterial sistêmica e insuficiência cardíaca com fração de ejeção preservada (ICFEp)?", options: ["Diuréticos de alça e digoxina", "Inibidores da SGLT2 (glicozúricos orais) e antagonistas do receptor de mineralocorticoide", "Betabloqueadores e nitratos", "IECA/BRA e bloqueadores dos canais de cálcio"], correctIndex: 1, explanation: "As diretrizes recentes (ESC 2021/AHA 2022) recomendam os inibidores da SGLT2 como a terapia fundamental para ICFEp. Antagonistas do receptor de mineralocorticoide também têm papel estabelecido, focando no controle da sobrecarga e remodelamento.", category: "Cardiologia" },
  { id: 214, question: "Um paciente de 40 anos é diagnosticado com trombose venosa profunda (TVP) distal. Além da anticoagulação, qual outro fator deve ser prontamente investigado, especialmente se não houver fatores de risco identificáveis?", options: ["Doença arterial periférica assintomática", "Anemia ferropriva", "Trombofilia adquirida ou hereditária", "Diabetes mellitus tipo 2"], correctIndex: 2, explanation: "Em pacientes jovens ou sem fatores de risco claros para TVP, a investigação de trombofilias (adquiridas, como síndrome do anticorpo antifosfolípide, ou hereditárias, como deficiência de antitrombina, proteína C ou S) é crucial para guiar a duração da anticoagulação e monitoramento.", category: "Cardiologia" },
  { id: 215, question: "Qual a principal alteração hemodinâmica na estenose mitral grave?", options: ["Aumento da pressão diastólica final do ventrículo esquerdo", "Aumento da pressão no átrio esquerdo e hipertensão venocapilar pulmonar", "Diminuição do débito cardíaco devido à insuficiência tricúspide secundária", "Aumento da pressão sistólica da artéria pulmonar com baixa pressão no átrio direito"], correctIndex: 1, explanation: "A estenose mitral dificulta o esvaziamento do átrio esquerdo para o ventrículo esquerdo durante a diástole, resultando em um represamento de sangue. Isso eleva a pressão no átrio esquerdo e, consequentemente, na circulação pulmonar, levando à hipertensão venocapilar pulmonar.", category: "Cardiologia" },
  { id: 216, question: "Em pacientes com fibrilação atrial não valvar, qual escore é utilizado para avaliar o risco de acidente vascular cerebral (AVC) e guiar a decisão de anticoagulação oral?", options: ["CHA2DS2-VASc", "HAS-BLED", "NYHA (New York Heart Association)", "TIMI risk score"], correctIndex: 0, explanation: "O escore CHA2DS2-VASc é universalmente recomendado para estratificação do risco de AVC em pacientes com fibrilação atrial não valvar, orientando a indicação de anticoagulação oral. O HAS-BLED avalia risco de sangramento.", category: "Cardiologia" },
  { id: 217, question: "Qual das seguintes classes de fármacos é de primeira linha para o tratamento da hipertensão arterial em pacientes com hipertensão e diabetes mellitus, sem proteinúria?", options: ["Betabloqueadores", "Diuréticos de alça", "Inibidores da enzima conversora de angiotensina (IECA) ou bloqueadores do receptor de angiotensina (BRA)", "Bloqueadores dos canais de cálcio não diidropiridínicos"], correctIndex: 2, explanation: "IECA ou BRA são a primeira linha de tratamento em pacientes com hipertensão e diabetes mellitus, independentemente da presença de proteinúria, devido aos seus efeitos benéficos na proteção renal e cardiovascular, além do controle pressórico.", category: "Cardiologia" },
  { id: 218, question: "Um paciente de 45 anos apresenta febre prolongada, lesões em Roth na retina e sopro diastólico em foco aórtico recém-surgido. Hemoculturas estão pendentes. Qual a hipótese diagnóstica principal e a próxima etapa na investigação?", options: ["Miocardite aguda; realizar biópsia endomiocárdica.", "Endocardite infecciosa; realizar ecocardiograma transesofágico.", "Lúpus eritematoso sistêmico; solicitar anticorpos antinucleares (FAN).", "Pericardite constritiva; realizar tomografia computadorizada de tórax."], correctIndex: 1, explanation: "A tríade de febre, sopro cardíaco novo e sinais periféricos (lesões de Roth, nódulos de Osler, manchas de Janeway) é altamente sugestiva de endocardite infecciosa. O ecocardiograma transesofágico é o método de imagem de escolha para confirmar o diagnóstico e avaliar a extensão do dano valvar.", category: "Cardiologia" },
  { id: 219, question: "Qual a principal complicação cardiovascular a longo prazo da hipertensão arterial sistêmica não controlada?", options: ["Aneurisma de aorta abdominal", "Doença pulmonar obstrutiva crônica", "Insuficiência cardíaca e doença arterial coronariana", "Varizes de membros inferiores"], correctIndex: 2, explanation: "A hipertensão arterial sistêmica não controlada é um dos principais fatores de risco para o desenvolvimento de doença arterial coronariana e insuficiência cardíaca (tanto ICFEp quanto ICFEr), além de AVC e doença renal crônica.", category: "Cardiologia" },
  { id: 220, question: "Qual o principal critério utilizado para diferenciar Taquicardia Ventricular de Taquicardia Supraventricular com aberrância (QRS largo) em um ECG?", options: ["Eixo do QRS", "Presença de dissociação atrioventricular", "Frequência ventricular", "Duração do segmento PR"], correctIndex: 1, explanation: "A dissociação atrioventricular (atividade atrial independente da ventricular) é o achado mais específico para o diagnóstico de taquicardia ventricular em cenários de QRS largo, pois sugere uma origem no ventrículo independentemente do átrio. Outros critérios são menos específicos.", category: "Cardiologia" },
  { id: 221, question: "Um paciente com insuficiência cardíaca crônica grave com fração de ejeção do ventrículo esquerdo de 25% é internado com dispneia e edema. Qual o diurético de escolha para o manejo sintomático da sobrecarga volêmica neste cenário?", options: ["Clortalidona", "Hidroclorotiazida", "Espironolactona", "Furosemida"], correctIndex: 3, explanation: "Em casos de insuficiência cardíaca grave com sobrecarga volêmica, os diuréticos de alça, como a furosemida, são os mais potentes e eficazes para promover a diurese e aliviar os sintomas congestivos.", category: "Cardiologia" },
  { id: 222, question: "Qual das seguintes terapias é indicada para um paciente com infarto agudo do miocárdio com supradesnivelamento do segmento ST (IAMCSST) há 3 horas, sem contraindicações para reperfusão, em uma unidade que NÃO dispõe de laboratório de hemodinâmica?", options: ["Administrar apenas dupla antiagregação plaquetária e betabloqueadores.", "Realizar trombólise farmacológica e transferir o paciente para um centro com ICP.", "Transferir o paciente imediatamente para um centro com ICP, sem trombólise prévia.", "Administrar anti-inflamatórios não esteroidais para alívio da dor torácica."], correctIndex: 1, explanation: "Em casos de IAMCSST, a reperfusão é crucial. Se a angioplastia primária (ICP) não puder ser realizada em centro experiente dentro do tempo recomendado (120 min do primeiro contato médico), a trombólise farmacológica é a alternativa e deve ser seguida de transferência para centro com ICP para angiografia e tratamento subsequente, se necessário.", category: "Cardiologia" },
  { id: 223, question: "Um paciente de 60 anos, com história de hipertensão, tabagismo e dislipidemia, apresenta dor súbita e intensa em flanco esquerdo, com irradiação para a região inguinal e diminuição da pressão arterial no membro inferior esquerdo. Ao exame físico, nota-se massa pulsátil e dolorosa no abdome. Qual a principal hipótese diagnóstica?", options: ["Aneurisma de aorta abdominal roto", "Estenose da artéria renal", "Diverticulite aguda", "Trombose de veia renal"], correctIndex: 0, explanation: "A tríade de dor abdominal/flanco, massa pulsátil e hipotensão em paciente com fatores de risco para doença aterosclerótica é altamente sugestiva de aneurisma de aorta abdominal roto, uma emergência médica com alta mortalidade.", category: "Cardiologia" },
  { id: 224, question: "Qual condição cardíaca é mais comumente associada à coarctação da aorta?", options: ["Comunicação interatrial", "Persistência do canal arterial", "Estenose valvar aórtica bicúspide", "Tetralogia de Fallot"], correctIndex: 2, explanation: "A valva aórtica bicúspide é a anomalia cardíaca congênita mais comum, e sua associação com a coarctação da aorta é frequente (cerca de 50% dos casos de coarctação). Outras associações são menos comuns.", category: "Cardiologia" },
  { id: 225, question: "Em um ECG, a presença de ondas T invertidas em V1-V3 sem elevação do segmento ST, acompanhadas de dor torácica, em um paciente com dor torácica, sugere qual alteração cardíaca aguda, se associada a história de infarto recente?", options: ["Pericardite aguda", "Angina de Prinzmetal", "Síndrome de Wellens", "Taquicardia ventricular não sustentada"], correctIndex: 2, explanation: "A Síndrome de Wellens é um padrão de ECG (ondas T bifásicas ou invertidas profundas em V2-V3) que indica estenose crítica da artéria descendente anterior, mesmo em pacientes sem dor presente ao momento do ECG. É um preditor de IAM extenso.", category: "Cardiologia" },
  { id: 226, question: "Um paciente de 65 anos, hipertenso e diabético, é admitido com dor torácica retroesternal irradiada para membro superior esquerdo, de forte intensidade, há 30 minutos. O eletrocardiograma (ECG) inicial mostra supradesnivelamento do segmento ST de 3 mm em V1-V4 e 2 mm em DII, DIII e aVF. Qual a conduta inicial mais apropriada?", options: ["Administrar AAS 300mg mastigável, clopidogrel 300mg e encaminhar para angioplastia primária.", "Administrar AAS 300mg mastigável, nitrato sublingual e aguardar enzimas cardíacas.", "Administrar heparina não fracionada e solicitar cintilografia miocárdica.", "Iniciar betabloqueador oral e aguardar evolução da dor."], correctIndex: 0, explanation: "O paciente apresenta um infarto agudo do miocárdio com supradesnivelamento do segmento ST. A conduta prioritária é a reperfusão miocárdica (angioplastia primária ou trombólise), associada à antiagregação plaquetária dupla com AAS e um inibidor P2Y12 (como clopidogrel ou ticagrelor).", category: "Cardiologia" },
  { id: 227, question: "Em relação à farmacoterapia da insuficiência cardíaca com fração de ejeção reduzida (ICFEr), qual das seguintes medicações é considerada um pilar do tratamento, com comprovada redução de mortalidade?", options: ["Digoxina", "Anlodipino", "Ambas as respostas B e C", "Um inibidor da enzima conversora de angiotensina (IECA) ou bloqueador do receptor de angiotensina (BRA) ou inibidor do receptor de angiotensina e neprilisina (IRAN)."], correctIndex: 3, explanation: "IECA/BRA/IRAN são pilares do tratamento da ICFEr, juntamente com betabloqueadores e antagonistas do receptor de mineralocorticoides (ARM), demonstrando redução significativa de mortalidade. A digoxina pode melhorar os sintomas, mas não reduz mortalidade, e o anlodipino não é a primeira escolha.", category: "Cardiologia" },
  { id: 228, question: "Qual é a principal complicação aguda e potencialmente fatal de um cardiomiopatia hipertrófica obstrutiva?", options: ["Endocardite infecciosa", "Flutter atrial", "Morte súbita cardíaca", "Trombose arterial periférica"], correctIndex: 2, explanation: "A morte súbita cardíaca é a principal causa de mortalidade em pacientes com cardiomiopatia hipertrófica, especialmente em jovens, devido a arritmias ventriculares malignas. A estratificação de risco é fundamental para a prevenção.", category: "Cardiologia" },
  { id: 229, question: "Na avaliação laboratorial de um paciente com suspeita de insuficiência cardíaca crônica, qual biomarcador cardíaco apresenta alto valor preditivo negativo para excluir o diagnóstico?", options: ["Troponina I", "Creatinoquinase MB (CK-MB)", "Peptídeo natriurético tipo B (BNP) ou N-terminal pro-BNP (NT-proBNP)", "Mioglobina"], correctIndex: 2, explanation: "Níveis normais de BNP ou NT-proBNP em pacientes sem IC sistólica ou diastólica são altamente eficazes para afastar o diagnóstico de insuficiência cardíaca, especialmente em cenários de emergência, devido ao seu elevado valor preditivo negativo.", category: "Cardiologia" },
  { id: 230, question: "Um paciente de 50 anos, com história de febre reumática na infância, apresenta dispneia progressiva, tosse seca e palpitações. Ao exame físico, ausculta-se um sopro diastólico em foco mitral, precedido por estalido de abertura. Qual a valvopatia mais provável?", options: ["Insuficiência aórtica", "Estenose tricúspide", "Estenose mitral", "Prolapso da valva mitral"], correctIndex: 2, explanation: "A história de febre reumática, dispneia, tosse, palpitações e o sopro diastólico em foco mitral com estalido de abertura são achados clássicos da estenose mitral, uma sequela comum da febre reumática.", category: "Cardiologia" },
  { id: 231, question: "Qual dos seguintes medicamentos é contraindicado em pacientes com estenose aórtica grave sintomática?", options: ["Inibidor da enzima conversora de angiotensina (IECA)", "Betabloqueador", "Nitrato", "Diurético de alça"], correctIndex: 2, explanation: "Nitrato e outros vasodilatadores devem ser usados com extrema cautela ou evitados em pacientes com estenose aórtica grave sintomática, pois podem causar grave hipotensão devido à dependência de pré-carga e à limitação da capacidade de aumentar o débito cardíaco.", category: "Cardiologia" },
  { id: 232, question: "No manejo da fibrilação atrial (FA) em pacientes com alto risco tromboembólico, qual é a principal classe de medicamentos utilizada para a prevenção de acidente vascular cerebral isquêmico?", options: ["Antiagregantes plaquetários", "Betabloqueadores", "Anticoagulantes orais (antagonistas da vitamina K ou anticoagulantes orais diretos - DOACs)", "Antiarrítmicos"], correctIndex: 2, explanation: "Anticoagulantes orais (DOACs ou antagonistas da vitamina K) são a pedra angular da prevenção do AVC em pacientes com FA e alto risco tromboembólico, conforme estratificado pelo escore CHA2DS2-VASc.", category: "Cardiologia" },
  { id: 233, question: "Em um paciente com bradicardia sinusal assintomática e estável hemodinamicamente, qual é a conduta mais adequada?", options: ["Implante de marcapasso provisório de urgência.", "Administração de atropina intravenosa.", "Observação clínica e busca por causas reversíveis.", "Administração de dopamina."], correctIndex: 2, explanation: "Bradicardia sinusal assintomática e hemodinamicamente estável geralmente não requer tratamento agudo. A conduta é observar o paciente, monitorar e investigar causas reversíveis, como medicamentos ou hipotireoidismo.", category: "Cardiologia" },
  { id: 234, question: "Qual dos seguintes achados eletrocardiográficos é sugestivo de pericardite aguda?", options: ["Supradesnivelamento difuso do segmento ST com concavidade para cima e infradesnivelamento do segmento PR.", "Supradesnivelamento do segmento ST em parede inferior com imagem em espelho.", "Ondas Q patológicas e inversão de onda T.", "Bloqueio de ramo esquerdo completo."], correctIndex: 0, explanation: "O supradesnivelamento difuso do segmento ST com concavidade para cima e o infradesnivelamento do segmento PR são achados clássicos e característicos da pericardite aguda no ECG.", category: "Cardiologia" },
  { id: 235, question: "Um homem de 45 anos, obeso e dislipidêmico, apresenta pressão arterial de 150/95 mmHg em três aferições em dias diferentes. Não possui lesão de órgão-alvo. Qual a classificação da sua hipertensão arterial, segundo as diretrizes mais recentes?", options: ["Pré-hipertensão", "Hipertensão estágio 1", "Hipertensão estágio 2", "Hipertensão estágio 3"], correctIndex: 2, explanation: "De acordo com as diretrizes brasileiras de hipertensão, uma pressão arterial sustentada entre 140-159/90-99 mmHg é classificada como Hipertensão Estágio 1, e acima de 160/100 mmHg como estágio 2. 150/95mmHg é estágio 2.", category: "Cardiologia" },
  { id: 236, question: "Qual a principal intervenção não farmacológica recomendada para todos os pacientes com hipertensão arterial sistêmica?", options: ["Restrição severa de carboidratos.", "Dieta rica em proteínas.", "Modificação do estilo de vida, incluindo redução do peso corporal, dieta DASH e atividade física regular.", "Uso exclusivo de suplementos de potássio."], correctIndex: 2, explanation: "Modificações no estilo de vida são a base do tratamento da hipertensão arterial, incluindo perda de peso, dieta saudável (como a dieta DASH - Dietary Approaches to Stop Hypertension), restrição de sódio e prática de atividade física regular.", category: "Cardiologia" },
  { id: 237, question: "Em um paciente com crise hipertensiva (pressão arterial > 180/120 mmHg) e sinais de lesão de órgão-alvo aguda (ex: edema agudo de pulmão), qual a conduta inicial mais urgente?", options: ["Iniciar tratamento anti-hipertensivo oral e observar.", "Administrar nifedipino sublingual.", "Iniciar anti-hipertensivos intravenosos com monitorização em unidade de terapia intensiva.", "Prescrever diurético oral e pedir para o paciente ir para casa."], correctIndex: 2, explanation: "A presença de lesão de órgão-alvo define urgência hipertensiva. Nesses casos, é crucial o controle rápido e gradual da PA com medicação intravenosa em ambiente monitorizado (UTI), para evitar piora da lesão.", category: "Cardiologia" },
  { id: 238, question: "A etiologia mais comum de endocardite infecciosa em valvas nativas no ambiente hospitalar, especialmente após manipulação de cateteres, é o(a):", options: ["Streptococcus viridans", "Staphylococcus aureus", "Enterococcus faecalis", "Staphylococcus epidermidis"], correctIndex: 1, explanation: "Staphylococcus aureus é o agente etiológico mais comum de endocardite infecciosa em valvas nativas, principalmente em pacientes com uso de drogas intravenosas ou infecções relacionadas à assistência à saúde, como manipulação de cateteres.", category: "Cardiologia" },
  { id: 239, question: "Qual dos seguintes critérios diagnósticos é considerado um critério maior nos Critérios de Duke Modificados para endocardite infecciosa?", options: ["Febre", "Achados ecocardiográficos de vegetação", "Fenômenos vasculares (embolia arterial ou infarto pulmonar)", "Embolia séptica"], correctIndex: 1, explanation: "Achados ecocardiográficos consistentes com endocardite (vegetação, abscesso, ou deiscência de prótese) são considerados um critério maior nos Critérios de Duke Modificados, juntamente com hemoculturas positivas para microrganismos típicos.", category: "Cardiologia" },
  { id: 240, question: "Em um paciente jovem com dor torácica atípica e sopro sistólico ejetivo em foco pulmonar que aumenta à inspiração, qual valvopatia deve ser considerada?", options: ["Estenose aórtica", "Insuficiência mitral", "Estenose pulmonar", "Prolapso da valva mitral"], correctIndex: 2, explanation: "O sopro sistólico ejetivo em foco pulmonar que aumenta com a inspiração é um achado típico de estenose pulmonar discreta ou de sopro inocente, que é mais perceptível devido ao aumento do retorno venoso ao coração direito durante a inspiração.", category: "Cardiologia" },
  { id: 241, question: "Qual das seguintes condições é uma contraindicação absoluta ao uso de betabloqueadores em pacientes com insuficiência cardíaca?", options: ["Doença pulmonar obstrutiva crônica (DPOC) leve.", "Asma brônquica grave não controlada.", "Diabetes mellitus tipo 2.", "Hipertensão arterial não controlada."], correctIndex: 1, explanation: "Asma brônquica grave e ativa, com broncoespasmo, é uma contraindicação absoluta para o uso de betabloqueadores, devido ao risco de desencadear ou agravar crises de broncoespasmo. DPOC leve não é contraindicação absoluta.", category: "Cardiologia" },
  { id: 242, question: "Qual o principal mecanismo de ação dos inibidores da SGLT2 (iSGLT2) que justifica seu benefício cardiovascular na insuficiência cardíaca?", options: ["Aumento da excreção de sódio e água independentemente da glicemia, melhora do metabolismo energético cardíaco e redução da inflamação.", "Vasodilatação arterial e venosa, reduzindo pré e pós-carga.", "Aumento da contratilidade miocárdica.", "Redução da frequência cardíaca e melhora do enchimento ventricular."], correctIndex: 0, explanation: "Os iSGLT2 atuam primariamente através da glicosúria e natriurese, levando a uma diurese osmótica. Além disso, promovem benefícios cardíacos e renais que vão além do controle glicêmico, incluindo melhora do estresse oxidativo, inflamação e metabolismo energético cardíaco.", category: "Cardiologia" },
  { id: 243, question: "Um paciente de 70 anos apresenta síncope de esforço, dor torácica e dispneia (a tríade clássica). Ao exame, pulso parvus et tardus e sopro sistólico ejetivo em foco aórtico irradiando para o pescoço. O diagnóstico mais provável é:", options: ["Insuficiência mitral grave", "Estenose aórtica grave", "Prolapso da valva mitral", "Insuficiência tricúspide"], correctIndex: 1, explanation: "A tríade síncope, dor torácica e dispneia, associada ao pulso parvus et tardus e sopro sistólico ejetivo em foco aórtico com irradiação para o pescoço, são achados altamente sugestivos de estenose aórtica grave.", category: "Cardiologia" },
  { id: 244, question: "A terapêutica de reperfusão de escolha para infarto agudo do miocárdio com supradesnivelamento do segmento ST (IAMCSST) quando disponível em até 120 minutos do primeiro contato médico é:", options: ["Trombolíticos intravenosos.", "Angioplastia primária.", "Oxigenoterapia e nitratos.", "Betabloqueadores orais."], correctIndex: 1, explanation: "A angioplastia primária é a estratégia de reperfusão preferencial no IAMCSST, se realizada em um centro com cardiologia intervencionista disponível em tempo hábil (idealmente <90 minutos do primeiro contato médico ou <120 minutos se for necessário o transporte).", category: "Cardiologia" },
  { id: 245, question: "Qual das seguintes condições é considerada o principal fator de risco modificável para aterosclerose e suas manifestações clínicas?", options: ["Idade avançada.", "Gênero masculino.", "Dislipidemia.", "História familiar de doença cardiovascular."], correctIndex: 2, explanation: "Dislipidemia, especialmente níveis elevados de LDL-colesterol, é um dos fatores de risco modificáveis mais importantes para o desenvolvimento e progressão da aterosclerose. Outros incluem hipertensão, diabetes e tabagismo.", category: "Cardiologia" },
  { id: 246, question: "Um paciente submetido a angioplastia coronariana com implante de stent farmacológico necessita de dupla antiagregação plaquetária. Qual a duração mínima recomendada para esta terapia na ausência de alto risco de sangramento?", options: ["1 mês", "3 meses", "6 meses", "12 meses"], correctIndex: 3, explanation: "Após implante de stent farmacológico, a duração recomendada da dupla antiagregação plaquetária (AAS + inibidor P2Y12) é geralmente de 12 meses, conforme as diretrizes atuais, para reduzir o risco de trombose de stent.", category: "Cardiologia" },
  { id: 247, question: "Em caso de parada cardiorrespiratória em ritmo chocável (fibrilação ventricular ou taquicardia ventricular sem pulso), qual a primeira intervenção prioritária após o reconhecimento e acionamento da equipe?", options: ["Administração de epinefrina.", "Compressões torácicas de alta qualidade e desfibrilação imediata.", "Intubação orotraqueal.", "Acesso venoso e administração de antiarrítmicos."], correctIndex: 1, explanation: "Para ritmos chocáveis, a desfibrilação precoce (juntamente com compressões torácicas ininterruptas) é a intervenção mais crítica e com maior impacto na sobrevida. A epinefrina é administrada após a primeira ou segunda desfibrilação falha.", category: "Cardiologia" },
  { id: 248, question: "Paciente com insuficiência cardíaca com fração de ejeção reduzida (ICFEr) que permanece sintomático e em classe funcional NYHA II-IV, apesar de terapia otimizada com IECA/BRA/IRAN, betabloqueador e ARM. Qual medicação pode ser adicionada ao esquema para reduzir hospitalizações e mortalidade?", options: ["Anlodipino", "Clonidina", "Digoxina", "Inibidor da SGLT2 (iSGLT2), como dapagliflozina ou empagliflozina."], correctIndex: 3, explanation: "Os iSGLT2, como dapagliflozina e empagliflozina, demonstraram reduzir hospitalizações por IC e mortalidade cardiovascular em pacientes com ICFEr que já estão em terapia otimizada, tornando-se um quarto pilar do tratamento.", category: "Cardiologia" },
  { id: 249, question: "Assinalar a opção que apresenta um fator de risco modificável para doença arterial periférica (DAP)?", options: ["Idade avançada.", "Gênero feminino.", "História familiar.", "Tabagismo."], correctIndex: 3, explanation: "Tabagismo é o fator de risco modificável mais potente para o desenvolvimento e progressão da doença arterial periférica. A cessação do tabagismo é fundamental para o manejo da DAP.", category: "Cardiologia" },
  { id: 250, question: "Qual é a principal indicação para o uso de Amiodarona intravenosa em emergências?", options: ["Taquicardia sinusal persistente.", "Bradicardia sinusal sintomática.", "Fibrilação atrial com resposta ventricular rápida em pacientes com disfunção de ventrículo esquerdo.", "Crise hipertensiva."], correctIndex: 2, explanation: "A amiodarona intravenosa é frequentemente utilizada para controle de ritmo e frequência em pacientes com fibrilação atrial ou outras taquiarritmias, especialmente naqueles com disfunção ventricular ou insuficiência cardíaca, devido ao seu perfil de segurança cardiovascular.", category: "Cardiologia" },
  { id: 251, question: "Um paciente de 65 anos, tabagista de 40 anos-maço, apresenta dispneia progressiva nos últimos 2 anos, tosse produtiva e chiado no peito. A espirometria revela VEF1/CVF < 0,7 pós-broncodilatador e VEF1 55% do previsto. Qual o diagnóstico e a classificação GOLD corretos?", options: ["Asma, GOLD B", "DPOC, GOLD 2", "Bronquiectasias, GOLD C", "Fibrose Pulmonar, GOLD 3"], correctIndex: 1, explanation: "A história de tabagismo e a obstrução fixa ao fluxo aéreo (VEF1/CVF < 0,7 pós-broncodilatador) confirmam DPOC. VEF1 entre 50-79% do previsto classifica como GOLD 2 (moderado).", category: "Pneumologia" },
  { id: 252, question: "No manejo do broncoespasmo agudo grave em um paciente asmático na emergência, qual a associação medicamentosa mais indicada inicialmente, conforme as diretrizes do GINA?", options: ["Salbutamol inalatório e teofilina endovenosa", "Ipratrópio inalatório e montelucaste oral", "Salbutamol inalatório e brometo de ipratrópio inalatório, associado a corticoide sistêmico", "Formoterol inalatório e azitromicina oral"], correctIndex: 2, explanation: "As diretrizes GINA recomendam broncodilatadores de curta ação (salbutamol e brometo de ipratrópio) associados a corticoide sistêmico no manejo inicial da crise asmática grave para melhora rápida da obstrução e redução da inflamação.", category: "Pneumologia" },
  { id: 253, question: "Um paciente de 40 anos é admitido com pneumonia adquirida na comunidade (PAC) grave, com necessidade de ventilação mecânica. Ele não tem comorbidades significativas e não usou antibióticos nos últimos 3 meses. Qual a primeira opção de tratamento empírico, segundo as recomendações do MS-Brasil?", options: ["Amoxicilina e claritromicina", "Ceftriaxona e azitromicina", "Levofloxacina em monoterapia", "Penicilina cristalina e doxiciclina"], correctIndex: 1, explanation: "Para PAC grave em pacientes sem comorbidades e sem uso recente de antibióticos, a combinação de betalactâmico (ceftriaxona) com macrolídeo (azitromicina) é a terapia empírica de escolha, cobrindo os principais patógenos como S. pneumoniae, H. influenzae e atípicos.", category: "Pneumologia" },
  { id: 254, question: "Qual das seguintes condições NÃO é uma indicação para o rastreamento de tuberculose latente?", options: ["Contatos próximos de pacientes com tuberculose pulmonar ativa", "Pacientes em uso de terapia imunossupressora (ex: anti-TNF alfa)", "Profissionais de saúde com exposição de risco", "Pacientes com história de tabagismo leve"], correctIndex: 3, explanation: "O rastreamento de tuberculose latente é indicado para grupos de alto risco de desenvolver a doença, o que não inclui tabagismo leve isoladamente. As outras opções representam indicações claras para o rastreio.", category: "Pneumologia" },
  { id: 255, question: "Em relação à fibrose cística, qual das seguintes afirmativas está INCORRETA?", options: ["É uma doença genética autossômica recessiva.", "Atinge principalmente os sistemas respiratório e gastrointestinal.", "O diagnóstico é confirmado pelo teste do suor positivo.", "A principal causa de óbito é a doença hepática crônica terminal."], correctIndex: 3, explanation: "A principal causa de morbimortalidade na fibrose cística é a doença pulmonar progressiva (infecções crônicas e bronquiectasias), e não a doença hepática terminal, embora esta possa ocorrer.", category: "Pneumologia" },
  { id: 256, question: "Um paciente com Síndrome da Angústia Respiratória Aguda (SARA) grave é intubado e ventilado mecanicamente. Qual a estratégia ventilatória protetora recomendada?", options: ["Volume corrente de 10-12 mL/kg de peso predito, PEEP de 5 cmH2O", "Volume corrente de 4-8 mL/kg de peso predito, Pressão de platô < 30 cmH2O", "Frequência respiratória baixa e tempo inspiratório prolongado", "Ventilação com altos volumes e pressões para recrutar alvéolos"], correctIndex: 1, explanation: "A estratégia protetora na SARA visa minimizar a lesão pulmonar induzida pelo ventilador, utilizando baixos volumes correntes (4-8 mL/kg de peso predito) e mantendo a pressão de platô abaixo de 30 cmH2O, com PEEP apropriada.", category: "Pneumologia" },
  { id: 257, question: "Qual das seguintes características clínicas é mais sugestiva de pneumonia por Pneumocystis jirovecii em um paciente imunocomprometido, como um portador de HIV?", options: ["Início súbito de febre alta com calafrios e tosse produtiva", "Dispineia progressiva, tosse seca e hipoxemia acentuada, com infiltrado intersticial difuso na radiografia de tórax", "Dor pleurítica e derrame pleural volumoso", "Hemoptise e cavitação pulmonar"], correctIndex: 1, explanation: "A pneumonia por Pneumocystis jirovecii (PCP) classicamente se manifesta com dispneia progressiva, tosse seca, hipoxemia desproporcional à ausculta e infiltrado intersticial difuso, especialmente em pacientes imunocomprometidos.", category: "Pneumologia" },
  { id: 258, question: "Um paciente de 70 anos desenvolve embolia pulmonar (EP) hemodinamicamente instável. Qual o tratamento de escolha?", options: ["Anticoagulação com heparina de baixo peso molecular", "Filtro de veia cava inferior", "Trombólise sistêmica", "Embolectomia cirúrgica"], correctIndex: 2, explanation: "Em casos de embolia pulmonar com instabilidade hemodinâmica (choque ou hipotensão persistente), a trombólise sistêmica é a terapia de escolha para rápida restauração da perfusão pulmonar e reversão do choque.", category: "Pneumologia" },
  { id: 259, question: "Qual a principal causa infecciosa de bronquiolite em lactentes?", options: ["Vírus influenza", "Adenovírus", "Vírus sincicial respiratório (VSR)", "Rinovírus"], correctIndex: 2, explanation: "O Vírus Sincicial Respiratório (VSR) é o agente etiológico mais comum da bronquiolite viral aguda em lactentes, responsável pela maioria dos casos e hospitalizações.", category: "Pneumologia" },
  { id: 260, question: "Na avaliação da dispneia em um paciente, qual o exame complementar que fornece informações mais detalhadas sobre a função pulmonar global, incluindo volumes e fluxos?", options: ["Radiografia de tórax", "Eletrocardiograma", "Espirometria completa com prova broncodilatadora", "Gasometria arterial"], correctIndex: 2, explanation: "A espirometria completa com prova broncodilatadora é o exame padrão ouro para avaliar a função pulmonar, medindo fluxos inspiratórios/expiratórios e volumes pulmonares, sendo essencial no diagnóstico e acompanhamento de doenças como asma e DPOC.", category: "Pneumologia" },
  { id: 261, question: "Um paciente com DPOC apresenta exacerbação grave, com aumento da dispneia, tosse e piora da expectoração. Qual a conduta inicial mais apropriada, além da otimização da oxigenoterapia e broncodilatadores?", options: ["Início de corticoide inalatório de alta dose", "Exames de imagem avançados (PET-CT)", "Início de antibiótico e corticoide sistêmico", "Hidratação venosa agressiva"], correctIndex: 2, explanation: "As exacerbações de DPOC graves, especialmente com aumento da purulência do escarro ou sinais de falha respiratória, beneficiam-se da adição de antibióticos (se há suspeita bacteriana) e corticoide sistêmico para reduzir a inflamação e o risco de falha terapêutica.", category: "Pneumologia" },
  { id: 262, question: "Qual dos seguintes tumores pulmonares é mais fortemente associado ao tabagismo?", options: ["Adenocarcinoma", "Carcinoma de pequenas células", "Carcinóide típico", "Hamartoma"], correctIndex: 1, explanation: "O carcinoma de pequenas células é o tipo histológico de câncer de pulmão mais fortemente associado ao tabagismo, representando cerca de 15% dos casos e sendo altamente agressivo.", category: "Pneumologia" },
  { id: 263, question: "Em um paciente jovem com pneumotórax espontâneo primário pequeno (ápice a cúpula < 2 cm), qual a conduta inicial mais recomendada, na ausência de sintomas graves?", options: ["Drenagem torácica imediata", "Toracostomia com agulha", "Observação clínica e oxigenoterapia", "Toracotomia de urgência"], correctIndex: 2, explanation: "Em casos de pneumotórax espontâneo primário pequeno e assintomático ou pouco sintomático, a observação clínica com oxigenoterapia e controle radiográfico é a conduta inicial, pois a maioria se resolve espontaneamente.", category: "Pneumologia" },
  { id: 264, question: "Um paciente em uso de metotrexato para artrite reumatoide desenvolve dispneia progressiva, tosse seca e infiltrado intersticial bilateral na radiografia. Qual a principal suspeita de complicação pulmonar relacionada ao medicamento?", options: ["Asma induzida por metotrexato", "Pneumonite de hipersensibilidade", "Edema pulmonar cardiogênico", "Fibrose pulmonar idiopática"], correctIndex: 1, explanation: "A pneumonite de hipersensibilidade (ou pneumonite induzida por metotrexato) é uma complicação conhecida do uso de metotrexato, manifestando-se com dispneia, tosse seca e padrão intersticial na imagem.", category: "Pneumologia" },
  { id: 265, question: "Qual das seguintes é uma causa comum de derrame pleural exsudativo?", options: ["Insuficiência cardíaca congestiva", "Cirrose hepática com ascite", "Síndrome nefrótica", "Pneumonia bacteriana"], correctIndex: 3, explanation: "A pneumonia bacteriana é uma causa clássica de derrame pleural exsudativo (parapneumônico), devido ao processo inflamatório na pleura. As outras opções são causas de derrame pleural transudativo.", category: "Pneumologia" },
  { id: 266, question: "Na hipertensão pulmonar, qual o tratamento de primeira linha para pacientes com o grupo 1 (Hipertensão Arterial Pulmonar - HAP) idiopática documentada?", options: ["Diuréticos e oxigenoterapia", "Anticoagulação e digoxina", "Terapia específica para HAP (ex: antagonistas do receptor de endotelina, inibidores da fosfodiesterase-5)", "Bloqueadores de canal de cálcio em altas doses para todos os pacientes"], correctIndex: 2, explanation: "Para pacientes com HAP idiopática confirmada e teste de vasorreatividade negativo ou não realizado, o tratamento de primeira linha envolve terapias específicas que atuam nas vias patogênicas da doença, como os antagonistas do receptor de endotelina ou inibidores da fosfodiesterase-5.", category: "Pneumologia" },
  { id: 267, question: "Qual o principal critério para o diagnóstico de Apneia Obstrutiva do Sono (SAOS) grave na polissonografia?", options: ["Dessaturações de oxigênio abaixo de 90%", "Índice de Apneia-Hipopneia (IAH) > 30 eventos/hora", "Presença de roncos frequentes", "Sonolência diurna excessiva (escala de Epworth > 10)"], correctIndex: 1, explanation: "A gravidade da SAOS é classificada principalmente pelo Índice de Apneia-Hipopneia (IAH): leve (5-15), moderada (15-30) e grave (> 30 eventos por hora). Embora os outros sinais sejam importantes, o IAH é o principal critério polisssonográfico.", category: "Pneumologia" },
  { id: 268, question: "Um paciente em ventilação mecânica invasiva desenvolve febre, secreção purulenta abundante e novo infiltrado pulmonar na radiografia de tórax. Qual a conduta inicial mais apropriada para a suspeita de Pneumonia Associada à Ventilação Mecânica (PAV)?", options: ["Início de antibióticos de largo espectro empíricos imediatamente", "Coleta de culturas respiratórias (ex: lavado broncoalveolar) e início de antibióticos conforme o patógeno isolado", "Apenas otimizar a higiene brônquica e aguardar melhora", "Iniciar corticoide sistêmico"], correctIndex: 1, explanation: "Diante da suspeita de PAV, a coleta de culturas respiratórias é fundamental para guiar a terapia antimicrobiana, mas o início de antibióticos empíricos de amplo espectro, cobrindo os patógenos prováveis, não deve ser atrasado, especialmente em casos graves, aguardando-se os resultados das culturas para de-escalonamento.", category: "Pneumologia" },
  { id: 269, question: "Qual das seguintes doenças granulomatosas pulmonares é causada pela inalação de esporos encontrados em solo contaminado com fezes de morcegos ou aves?", options: ["Sarcoidose", "Tuberculose", "Histoplasmose", "Nocardia"], correctIndex: 2, explanation: "A histoplasmose é uma infecção fúngica causada pela inalação de esporos de Histoplasma capsulatum, frequentemente encontrados em solos contaminados por fezes de morcegos e aves, e pode causar doença pulmonar granulomatosa.", category: "Pneumologia" },
  { id: 270, question: "A principal indicação para o uso de N-Acetilcisteína em doenças respiratórias crônicas é:", options: ["Broncodilatação imediata", "Redução da inflamação pulmonar", "Fluidificação e expectoração do muco", "Prevenção de infecções bacterianas"], correctIndex: 2, explanation: "A N-Acetilcisteína possui ação mucolítica, quebrando as ligações dissulfeto das proteínas do muco, tornando-o mais fluido e facilitando sua expectoração. É usada como adjuvante em condições com hipersecreção e estagnação de muco.", category: "Pneumologia" },
  { id: 271, question: "Qual a principal técnica para confirmação diagnóstica de tuberculose pulmonar ativa?", options: ["Radiografia de tórax", "Teste tuberculínico (PPD)", "Pesquisa de BAAR no escarro e cultura para micobactérias", "Tomografia computadorizada de tórax"], correctIndex: 2, explanation: "A confirmação diagnóstica da tuberculose pulmonar ativa é feita primariamente pela pesquisa de bacilos álcool-ácido resistentes (BAAR) no escarro e, idealmente, pela cultura para micobactérias, que é o padrão ouro.", category: "Pneumologia" },
  { id: 272, question: "Em um paciente com asma grave não controlada, qual o biológico que age no receptor de IL-5 e é recomendado para pacientes com fenótipo eosinofílico?", options: ["Omalizumabe", "Mepolizumabe", "Dupilumabe", "Tezepelumabe"], correctIndex: 1, explanation: "O mepolizumabe é um anticorpo monoclonal que age inibindo a IL-5, uma citocina chave na eosinofilia. É indicado para asma grave eosinofílica refratária ao tratamento convencional.", category: "Pneumologia" },
  { id: 273, question: "O diagnóstico de derrame pleural complicado (parapneumônico complicado ou empiema) é fortemente sugerido por qual achado na análise do líquido pleural?", options: ["DHL < 2/3 do limite superior do soro", "Glicose < 40 mg/dL ou pH < 7,20", "Proteínas < 0,5", "Contagem de células brancas < 1000/microL"], correctIndex: 1, explanation: "Um derrame pleural parapneumônico complicado ou empiema é sugerido por achados de pH < 7,20, glicose < 40-60 mg/dL ou DHL > 1000 U/L no líquido pleural, indicando atividade bacteriana e inflamação significativa.", category: "Pneumologia" },
  { id: 274, question: "Qual dos seguintes é um fator de risco mais importante para o desenvolvimento de doença pulmonar obstrutiva crônica (DPOC) em não tabagistas?", options: ["Exposição a poeiras industriais ou agentes químicos no trabalho", "Obesidade mórbida", "Asma na infância resolvida", "Uso de beta-bloqueadores"], correctIndex: 0, explanation: "A exposição ocupacional a poeiras, produtos químicos e vapores é um fator de risco bem estabelecido para o desenvolvimento de DPOC, mesmo em indivíduos que nunca fumaram. Asma grave e infecções respiratórias na infância também aumentam o risco, mas a exposição ocupacional é um fator de risco próprio e significativo.", category: "Pneumologia" },
  { id: 275, question: "Um paciente submetido à toracocentese diagnóstica desenvolve dor pleural súbita e dispneia leve imediatamente após o procedimento. A conduta inicial mais apropriada é:", options: ["Administar analgésicos e observar por 24 horas", "Realizar eletrocardiograma de urgência", "Solicitar radiografia de tórax e avaliar para pneumotórax", "Administrar broncodilatadores inalatórios"], correctIndex: 2, explanation: "A dor súbita e dispneia após toracocentese são altamente sugestivas de pneumotórax, uma complicação comum do procedimento. A radiografia de tórax é essencial para confirmar o diagnóstico e avaliar a extensão do pneumotórax.", category: "Pneumologia" },
  { id: 276, question: "Um paciente de 35 anos, HIV positivo em uso irregular de terapia antirretroviral, procura o pronto-socorro com queixa de febre alta, cefaleia intensa e rigidez de nuca há 3 dias. Ao exame físico, apresenta sinais de Kernig e Brudzinski positivos. A punção lombar revela líquor criptocócico. Qual a conduta inicial mais adequada para este paciente?", options: ["Iniciar Anfotericina B desoxicolato intravenosa e Flucitosina oral.", "Iniciar Anfotericina B lipossomal intravenosa e Flucitosina oral.", "Iniciar Voriconazol intravenoso e aumentar a dose da terapia antirretroviral.", "Iniciar Fluconazol oral em dose alta e aguardar cultura de líquor."], correctIndex: 1, explanation: "A meningite criptocócica em pacientes HIV positivos, especialmente em uso irregular da terapia antirretroviral, é uma infecção grave que exige tratamento imediato. A diretriz atual recomenda Anfotericina B lipossomal associada à Flucitosina na fase de indução devido à sua maior eficácia e menor toxicidade renal em comparação à formulação desoxicolato.", category: "Infectologia" },
  { id: 277, question: "Em relação à Profilaxia Pré-Exposição (PrEP) ao HIV, qual das seguintes afirmações está correta?", options: ["A PrEP diária é recomendada para todos os indivíduos sexualmente ativos que não usam preservativo regularmente.", "A PrEP sob demanda (2-1-1) com tenofovir/entricitabina pode ser utilizada para todos os tipos de exposição sexual.", "A adesão irregular à PrEP não compromete significativamente sua eficácia na prevenção da infecção pelo HIV.", "A PrEP não protege contra outras infecções sexualmente transmissíveis (ISTs), reforçando a necessidade do uso de preservativos."], correctIndex: 3, explanation: "A PrEP é altamente eficaz na prevenção da infecção pelo HIV, mas sua ação é específica para o vírus HIV, não oferecendo proteção contra outras ISTs. Portanto, o uso consistente de preservativos é fundamental para a prevenção de diversas infecções. A PrEP sob demanda não é recomendada para todas as populações, como mulheres cis e pessoas que usam drogas injetáveis.", category: "Infectologia" },
  { id: 278, question: "Um paciente de 40 anos, com história de viagem recente a uma área endêmica de febre amarela, evolui com febre, icterícia, sangramentos e alterações neurológicas. O quadro clínico sugere febre amarela grave. Qual o principal vetor de transmissão da febre amarela urbana?", options: ["Anopheles darlingi", "Aedes aegypti", "Lutzomyia longipalpis", "Culex quinquefasciatus"], correctIndex: 1, explanation: "O Aedes aegypti é o principal vetor da febre amarela na área urbana. Embora a febre amarela silvestre seja transmitida por mosquitos dos gêneros Haemagogus e Sabethes, a preocupação com a reurbanização da doença recai sobre o Aedes aegypti.", category: "Infectologia" },
  { id: 279, question: "Qual dos seguintes agentes antimicrobianos possui ação seletiva contra anaeróbios e protozoários, sendo amplamente utilizado no tratamento de infecções causadas por Clostridioides difficile e Gardnerella vaginalis?", options: ["Azitromicina", "Ciprofloxacino", "Metronidazol", "Cefalexina"], correctIndex: 2, explanation: "O metronidazol é um nitroimidazol com atividade bactericida contra anaeróbios obrigatórios e protozoários como Giardia lamblia, Entamoeba histolytica e Trichomonas vaginalis. É a droga de escolha para certas infecções por Clostridioides difficile e vaginose bacteriana (causada por Gardnerella vaginalis).", category: "Infectologia" },
  { id: 280, question: "Em um surto de meningite meningocócica tipo C em uma creche, qual a melhor medida de profilaxia para os comunicantes próximos?", options: ["Vacinação imediata de todos os comunicantes com a vacina meningocócica ACWY.", "Administração de rifampicina oral ou ceftriaxona intramuscular em dose única.", "Apenas observação dos comunicantes e orientação sobre sinais de alerta da doença.", "Isolamento domiciliar dos comunicantes por 10 dias."], correctIndex: 1, explanation: "A quimioprofilaxia para comunicantes próximos de casos de meningite meningocócica é essencial para controlar a disseminação da doença. A rifampicina e a ceftriaxona são opções eficazes para erradicar o meningococo da nasofaringe dos indivíduos expostos, reduzindo o risco de novas transmissões. A vacina não é uma medida de profilaxia pós-exposição imediata para os comunicantes já expostos.", category: "Infectologia" },
  { id: 281, question: "Um paciente de 60 anos, diabético e tabagista, apresenta uma úlcera em pé com sinais de celulite e secreção purulenta. Não houve melhora significativa com antibiótico tópico e ele é internado. Qual a principal preocupação etiológica em infecções de pé diabético, especialmente em casos de maior gravidade?", options: ["Staphylococcus aureus resistente à meticilina (MRSA).", "Streptococcus pyogenes.", "Pseudomonas aeruginosa.", "Escherichia coli."], correctIndex: 0, explanation: "O Staphylococcus aureus, incluindo o MRSA, é um patógeno muito comum em infecções de pé diabético, especialmente naquelas que requerem hospitalização ou que falham ao tratamento inicial. A cobertura para MRSA deve ser considerada nessas situações, dependendo da epidemiologia local e da gravidade da infecção. A presença de Pseudomonas aeruginosa é mais comum em ambientes aquáticos ou feridas crônicas e não é a principal preocupação etiológica inicial.", category: "Infectologia" },
  { id: 282, question: "Qual das seguintes estratégias não faz parte das recomendações para o manejo da infecção por H. pylori, de acordo com as diretrizes mais recentes?", options: ["Realizar teste e tratar (test-and-treat) para dispepsia em populações de alta prevalência e sem sinais de alarme.", "Utilizar terapia quádrupla com bismuto como primeira linha em regiões com alta resistência à claritromicina.", "Reavaliar a erradicação após o tratamento através de teste de urease respiratória ou antígeno fecal.", "Tratamento empírico com terapia tríplice contendo claritromicina na maioria dos casos, sem considerar a taxa de resistência local."], correctIndex: 3, explanation: "As diretrizes atuais enfatizam a importância de considerar as taxas de resistência local à claritromicina antes de iniciar a terapia tríplice. Em áreas com alta resistência, terapias alternativas como a quádrupla com bismuto ou terapias concomitantes são preferidas como primeira linha para aumentar a taxa de erradicação.", category: "Infectologia" },
  { id: 283, question: "Em relação à tuberculose latente (ITBL), qual das seguintes afirmações é incorreta?", options: ["A ITBL significa que o indivíduo está infectado pelo Mycobacterium tuberculosis, mas não possui a doença ativa.", "O tratamento da ITBL é recomendado para evitar a progressão para tuberculose ativa em grupos de risco.", "Um teste tuberculínico (TT) positivo sempre indica tuberculose ativa.", "O diagnóstico da ITBL pode ser feito pelo teste tuberculínico (TT) ou pelo IGRA (Interferon-Gamma Release Assay)."], correctIndex: 2, explanation: "Um teste tuberculínico (TT) positivo indica apenas infecção pelo Mycobacterium tuberculosis (ITBL), não necessariamente tuberculose ativa. Para o diagnóstico de TB ativa, são necessários achados clínicos, radiológicos e/ou bacteriológicos. Portanto, TT positivo pode indicar doença latente ou doença ativa, sendo necessária investigação adicional.", category: "Infectologia" },
  { id: 284, question: "Um paciente com história de febre e cefaleia há 5 dias, procurou o médico após o surgimento de um exantema maculopapular ascendente que poupava palmas e plantas. Em seguida, uma semana após, apresentou quadro de hemorragia digestiva alta culminando em choque hemorrágico. Qual o diagnóstico mais provável?", options: ["Dengue grave com choque.", "Febre maculosa, em sua forma grave.", "Malária falciparum.", "Leptospirose grave."], correctIndex: 1, explanation: "A febre maculosa, especialmente a brasileira, causada pela Rickettsia rickettsii e transmitida por carrapatos, pode apresentar exantema maculopapular ascendente que poupa certas áreas e evoluir rapidamente para quadros graves com vasculite, sangramentos e choque, assemelhando-se ao caso descrito. A dengue apresenta exantema diferente, e a leptospirose não costuma ter exantema como característica marcante.", category: "Infectologia" },
  { id: 285, question: "Qual das seguintes infecções não é considerada uma infecção sexualmente transmissível (IST) classicamente prevenida pelo uso de preservativo de barreira (camisinha)?", options: ["Gonorreia", "Clamídia", "HPV (papilomavírus humano)", "Herpes labial (HSV-1)"], correctIndex: 3, explanation: "A gonorreia, clamídia e o HPV são ISTs que têm sua transmissão significativamente reduzida pelo uso correto e consistente do preservativo. O herpes labial (causado pelo HSV-1) é transmitido principalmente por contato direto com lesões, beijo, e não é considerado uma IST clássica que o preservativo genital previna diretamente. Embora o sexo oral possa transmitir HSV, a prevenção primária não se baseia no preservativo genital para essa manifestação específica.", category: "Infectologia" },
  { id: 286, question: "Qual a principal indicação para o uso de oseltamivir em pacientes com suspeita ou confirmação de influenza?", options: ["Prevenção da gripe em contactantes de casos confirmados, independentemente do tempo de contato.", "Tratamento de casos leves de influenza em indivíduos saudáveis.", "Tratamento em casos graves ou de alto risco, idealmente nas primeiras 48 horas do início dos sintomas.", "Profilaxia pós-exposição para todos os profissionais de saúde após contato com pacientes influenza positivo."], correctIndex: 2, explanation: "O oseltamivir é recomendado para o tratamento da influenza, especialmente em casos graves ou em pacientes de alto risco para complicações, e sua eficácia é maior quando iniciado nas primeiras 48 horas do início dos sintomas. A prevenção para contactantes é seletiva e o tratamento de casos leves em saudáveis geralmente não é indicado.", category: "Infectologia" },
  { id: 287, question: "Um paciente de 28 anos, previamente hígido, desenvolve mononucleose infecciosa causada pelo vírus Epstein-Barr (EBV). Qual das seguintes manifestações clínicas NÃO é tipicamente associada à mononucleose infecciosa por EBV?", options: ["Linfadenopatia cervical posterior.", "Esplenomegalia.", "Pneumonia atípica.", "Faringite exudativa."], correctIndex: 2, explanation: "As manifestações clássicas da mononucleose infecciosa por EBV incluem febre, faringite exudativa, linfadenopatia (especialmente cervical posterior) e esplenomegalia. Enquanto algumas complicações pulmonares raras podem ocorrer, a pneumonia atípica não é uma manifestação típica ou esperada da mononucleose infecciosa por EBV na maioria dos casos.", category: "Infectologia" },
  { id: 288, question: "Qual o mecanismo de ação da vancomicina, um dos principais antibióticos utilizados contra bactérias gram-positivas multirresistentes?", options: ["Inibição da síntese da parede celular bacteriana.", "Inibição da síntese proteica bacteriana por ligação à subunidade 30S do ribossomo.", "Inibição da replicação do DNA bacteriano.", "Aumento da permeabilidade da membrana celular bacteriana."], correctIndex: 0, explanation: "A vancomicina é um glicopeptídeo que exerce seu efeito bactericida e bacteriostático (dependendo da dose e do microrganismo) inibindo a síntese da parede celular bacteriana, especificamente agindo na fase de transpeptidação e transglicosidação, ligando-se às extremidades D-Ala-D-Ala dos precursores do peptideoglicano.", category: "Infectologia" },
  { id: 289, question: "Em relação à toxoplasmose congênita, qual a principal medida de prevenção em gestantes soronegativas para Toxoplasma gondii?", options: ["Uso profilático de sulfametoxazol-trimetoprima durante toda a gestação.", "Evitar o contato com gatos e a ingestão de carne crua ou malpassada.", "Vacinação contra Toxoplasma gondii antes da concepção.", "Realização de amniocentese para diagnóstico precoce em todas as gestantes."], correctIndex: 1, explanation: "Aprincipal medida de prevenção da toxoplasmose congênita em gestantes soronegativas é a modificação de hábitos para evitar a infecção primária. Isso inclui evitar a ingestão de carne crua ou malpassada, lavar bem frutas e verduras, e evitar contato com fezes de gatos. Vacinação não está disponível e o uso profilático de antibióticos não é indicado universalmente.", category: "Infectologia" },
  { id: 290, question: "Qual das seguintes situações NÃO é uma indicação para terapia antirretroviral (TARV) em pacientes vivendo com HIV/AIDS, de acordo com as diretrizes atuais?", options: ["Indivíduos assintomáticos com contagem de CD4 acima de 500 células/mm³.", "Pessoas que vivem com HIV e apresentam coinfecção por hepatite B crônica ativa.", "Gestantes e lactantes vivendo com HIV.", "Exposição ocupacional ou não ocupacional ao HIV com risco de transmissão."], correctIndex: 3, explanation: "A TARV é recomendada para todos os indivíduos vivendo com HIV, independentemente da contagem de CD4 ou do estado clínico, visando a melhora da saúde individual e a prevenção da transmissão. A exposição ocupacional ou não ocupacional ao HIV com risco de transmissão (PEP) utiliza a TARV para profilaxia pós-exposição e não como tratamento para um HIV já estabelecido.", category: "Infectologia" },
  { id: 291, question: "Um homem de 65 anos, hipertenso e diabético, é trazido ao pronto-socorro com queixa de instalação súbita de fraqueza no hemicorpo direito e dificuldade para falar. Ao exame físico, apresenta afasia motora e hemiparesia braquiocrural direita. A tomografia computadorizada de crânio inicial sem contraste não evidenciou sinais de hemorragia. Qual a próxima conduta mais adequada para este paciente?", options: ["Iniciar trombólise endovenosa com alteplase, se preenchidos os critérios de janela terapêutica.", "Solicitar angiotomografia de crânio e pescoço para avaliar lesões de grandes vasos.", "Administrar AAS e clopidogrel imediatamente.", "Internar para monitorização e iniciar profilaxia para trombose venosa profunda."], correctIndex: 0, explanation: "Diante de um acidente vascular cerebral isquêmico agudo dentro da janela terapêutica e sem contraindicações hemorrágicas na TC de crânio, a trombólise endovenosa é a conduta de escolha para reperfusão e melhora do prognóstico, conforme as diretrizes atuais.", category: "Neurologia" },
  { id: 292, question: "Qual das seguintes condições é considerada uma contraindicação absoluta para o uso de alteplase em pacientes com Acidente Vascular Cerebral Isquêmico Agudo?", options: ["Pressão arterial sistólica acima de 185 mmHg e/ou diastólica acima de 110 mmHg, que não responde à redução com anti-hipertensivos.", "História de AVC prévio em menos de 3 meses.", "Hipoglicemia (glicemia &lt; 50 mg/dL).", "Plaquetas abaixo de 100.000/mm³."], correctIndex: 3, explanation: "Plaquetas abaixo de 100.000/mm³ representam uma contraindicação absoluta para a trombólise com alteplase devido ao risco aumentado de sangramento. As demais são contraindicações relativas ou tratáveis.", category: "Neurologia" },
  { id: 293, question: "Sobre a fisiopatologia da doença de Parkinson, qual das seguintes afirmativas está correta?", options: ["É caracterizada pela degeneração de neurônios produtores de acetilcolina na substância negra.", "A principal via dopaminérgica afetada é a nigroestriatal, resultando em diminuição da dopamina nos gânglios da base.", "A formação de corpos de Lewy é patognomônica, e são compostos principalmente por proteína tau hiperfosforilada.", "Os sintomas motores são decorrentes do excesso de dopamina nos receptores D1 e D2."], correctIndex: 1, explanation: "A doença de Parkinson é caracterizada pela perda de neurônios dopaminérgicos na parte compacta da substância negra (via nigroestriatal), levando à deficiência de dopamina nos gânglios da base e aos sintomas motores. Os corpos de Lewy são compostos primariamente por alfa-sinucleína.", category: "Neurologia" },
  { id: 294, question: "Uma mulher de 30 anos apresenta crises convulsivas parciais complexas de repetição, refratárias ao tratamento com dois fármacos antiepilépticos em doses adequadas. Sua ressonância magnética de crânio revelou esclerose mesial temporal. Qual conduta é a mais indicada neste caso?", options: ["Aumentar a dose de um dos fármacos atuais até a dose máxima tolerada.", "Associar um terceiro fármaco antiepiléptico de amplo espectro.", "Encaminhar para avaliação cirúrgica como tratamento para epilepsia refratária.", "Sugere-se um período de jejum e uma dieta cetogênica."], correctIndex: 2, explanation: "Em casos de epilepsia refratária com foco epileptogênico bem localizado, como a esclerose mesial temporal, a cirurgia de epilepsia pode oferecer um controle significativo das crises, sendo a conduta mais indicada após falha de dois antiepilépticos, conforme as diretrizes.", category: "Neurologia" },
  { id: 295, question: "Qual das seguintes opções representa uma apresentação clínica atípica de esclerose múltipla, que pode dificultar o diagnóstico inicial?", options: ["Neurite óptica unilateral com dor à movimentação ocular e perda visual.", "Diplopia intermitente devido a oftalmoplegia internuclear.", "Disartria e ataxia de membros inferiores.", "Crises epilépticas focais motoras isoladas."], correctIndex: 3, explanation: "Embora crises epilépticas possam ocorrer em pacientes com esclerose múltipla, elas são consideradas manifestações menos comuns ou atípicas, enquanto as outras opções são classicamente reconhecidas como sintomas iniciais ou comuns da doença.", category: "Neurologia" },
  { id: 296, question: "Um paciente de 55 anos apresenta cefaleia holocraniana de moderada intensidade há duas semanas, associada a febre baixa e perda ponderal. Ao exame físico, observa-se dor à palpação da artéria temporal e claudicação de mandíbula. Qual é a principal suspeita diagnóstica e o exame complementar mais indicado para confirmação?", options: ["Meningite viral; punção lombar.", "Cefaleia tensional; ressonância magnética de crânio.", "Arterite temporal (arterite de células gigantes); biópsia da artéria temporal.", "Migrânea crônica; eletroneuromiografia."], correctIndex: 2, explanation: "Os sintomas descritos (cefaleia em idoso, febre, perda ponderal, dor à palpação da artéria temporal e claudicação de mandíbula) são altamente sugestivos de arterite temporal. A biópsia da artéria temporal é o padrão-ouro para confirmação diagnóstica.", category: "Neurologia" },
  { id: 297, question: "Qual a principal complicação neurológica aguda que um paciente em crise miastênica pode desenvolver?", options: ["Acidente Vascular Cerebral Isquêmico.", "Crises epilépticas generalizadas.", "Insuficiência respiratória por fraqueza da musculatura diafragmática.", "Paralisia permanente de membros superiores."], correctIndex: 2, explanation: "A crise miastênica é uma exacerbação grave da miastenia gravis caracterizada por fraqueza muscular significativa que pode comprometer a musculatura respiratória, levando à insuficiência respiratória, uma emergência médica.", category: "Neurologia" },
  { id: 298, question: "Sobre a doença de Alzheimer, qual achado neuropatológico é considerado um marcador essencial para o diagnóstico post-mortem?", options: ["Corpos de Lewy.", "Vacuolização espongiforme.", "Degeneração Walleriana.", "Placas senis (amiloides) e emaranhados neurofibrilares (tau)."], correctIndex: 3, explanation: "As placas senis (formadas por peptídeos beta-amiloides) e os emaranhados neurofibrilares (compostos por proteína tau hiperfosforilada) são os principais achados neuropatológicos que definem a doença de Alzheimer post-mortem.", category: "Neurologia" },
  { id: 299, question: "Um paciente refere dormência e formigamento nas mãos e pés, com progressão para fraqueza simétrica ascendente nos últimos dias. Refere ter tido um quadro gripal há duas semanas. Ao exame, arreflexia e alteração sensitiva em 'meia e luva'. A principal hipótese diagnóstica é síndrome de Guillain-Barré. Qual é o tratamento de escolha para esta condição?", options: ["Dose alta de corticosteroides por via oral.", "Terapia com imunoglobulina intravenosa ou plasmaférese.", "Fisioterapia intensiva como única modalidade de tratamento.", "Antibioticoterapia de amplo espectro."], correctIndex: 1, explanation: "A síndrome de Guillain-Barré, uma polirradiculoneuropatia desmielinizante inflamatória aguda, é tratada primariamente com imunoglobulina intravenosa ou plasmaférese para modular a resposta imune e acelerar a recuperação.", category: "Neurologia" },
  { id: 300, question: "Qual é o principal neurotransmissor envolvido na fisiopatologia da migrânea (enxaqueca)?", options: ["Acetilcolina.", "Dopamina.", "Serotonina (5-HT).", "Norepinefrina."], correctIndex: 2, explanation: "A serotonina (5-HT) desempenha um papel crucial na fisiopatologia da migrânea, estando envolvida na neurotransmissão da dor e na regulação do tônus vascular, o que justifica a eficácia de fármacos como os triptanos que atuam em seus receptores.", category: "Neurologia" },
  { id: 301, question: "Um paciente de 35 anos, HIV positivo, em uso irregular de terapia antirretroviral, apresenta cefaleia intensa, febre, náuseas e vômitos há 1 semana, evoluindo com rebaixamento do nível de consciência. A tomografia de crânio mostra hidrocefalia. A punção lombar revela líquor cristalinocheio, pressão de abertura elevada, proteínas elevadas e glicose diminuída. A pesquisa de tinta da China é positiva. Qual o diagnóstico mais provável?", options: ["Meningite por Cryptococcus neoformans", "Meningite tuberculosa", "Meningite bacteriana aguda", "Toxoplasmose cerebral"], correctIndex: 0, explanation: "A cefaleia, febre, náuseas, vômitos e rebaixamento do nível de consciência em paciente HIV com baixa imunidade, juntamente com hidrocefalia e líquor com padrão de meningite subaguda (proteínas elevadas, glicose diminuída) e tinta da China positiva, são achados clássicos da meningite criptocócica.", category: "Infectologia" },
  { id: 302, question: "Qual das seguintes condutas é recomendada para a profilaxia primária da Pneumonia por Pneumocystis jirovecii (PCP) em pacientes HIV-positivos?", options: ["Início de terapia antirretroviral (TARV) para todos os pacientes, independentemente da contagem de CD4.", "Sulfametoxazol-trimetoprim para pacientes com contagem de CD4 < 200 células/mm³.", "Isoniazida para pacientes com esquema vacinal incompleto.", "Azitromicina para pacientes com carga viral detectável."], correctIndex: 1, explanation: "A profilaxia primária para PCP é indicada para pacientes HIV-positivos com contagem de CD4 abaixo de 200 células/mm³ ou em outras situações de imunodepressão grave, e o fármaco de escolha é o sulfametoxazol-trimetoprim.", category: "Infectologia" },
  { id: 303, question: "Com relação à febre maculosa brasileira, qual a principal forma de transmissão e os achados laboratoriais típicos?", options: ["Transmissão por mosquito Aedes aegypti; plaquetopenia e aumento de transaminases.", "Transmissão por carrapato do gênero Amblyomma; plaquetopenia, leucopenia e hiponatremia.", "Transmissão por água contaminada; leucocitose e hemoconcentração.", "Transmissão por roedores; anemia e uremia."], correctIndex: 1, explanation: "A febre maculosa é transmitida por carrapatos do gênero Amblyomma. Os achados laboratoriais comuns incluem plaquetopenia, leucopenia (ou leucocitose dependendo da fase) e hiponatremia, além de elevação de enzimas hepáticas.", category: "Infectologia" },
  { id: 304, question: "Um homem de 40 anos, pescador, apresenta febre, calafrios, cefaleia e mialgia há 5 dias. Refere contato com água de enchente. Ao exame físico, icterícia, conjuntivas avermelhadas e dor à palpação de panturrilhas. Exames laboratoriais mostram aumento de bilirrubinas, creatinina e CPK. Qual o diagnóstico mais provável?", options: ["Dengue grave", "Leptospirose", "Malária", "Hepatite A"], correctIndex: 1, explanation: "O quadro clínico de febre, mialgia intensa com dor em panturrilhas, icterícia, conjuntivite e sinais de disfunção renal e hepática em um pescador com história de contato com água de enchente é altamente sugestivo de leptospirose.", category: "Infectologia" },
  { id: 305, question: "Qual é o principal mecanismo de ação do aciclovir no tratamento de infecções virais por herpesvírus?", options: ["Inibição da transcriptase reversa viral.", "Inibição da DNA polimerase viral.", "Quebra da cápside viral.", "Bloqueio da fusão viral à célula hospedeira."], correctIndex: 1, explanation: "O aciclovir é um análogo de nucleosídeo que, após ser ativado pela timidina quinase viral, inibe seletivamente a DNA polimerase viral, interrompendo a replicação do DNA do vírus.", category: "Infectologia" },
  { id: 306, question: "Um paciente de 60 anos, diabético e em uso de prednisona, apresenta dor e inchaço na região cervical associado a febre. Há drenagem purulenta com grânulos amarelados. A coloração de Gram da secreção mostra bacilos Gram-positivos ramificados e filamentosos. Qual o agente etiológico mais provável?", options: ["Staphylococcus aureus", "Streptococcus pyogenes", "Nocardia spp.", "Actinomyces israelii"], correctIndex: 3, explanation: "A apresentação clínica de uma infecção crônica supurativa com múltiplos orifícios de drenagem e saída de grânulos de enxofre, juntamente com a identificação de bacilos Gram-positivos ramificados e filamentosos, é característica da actinomicose causada por Actinomyces israelii.", category: "Infectologia" },
  { id: 307, question: "Qual das seguintes infecções oportunistas é mais comumente associada à reativação em pacientes HIV-positivos quando a contagem de CD4 cai abaixo de 50 células/mm³?", options: ["Toxoplasmose cerebral", "Meningite criptocócica", "Citomegalovírus (doença sistêmica)", "Tuberculose pulmonar"], correctIndex: 2, explanation: "A doença por Citomegalovírus (CMV), especialmente retinite e doença disseminada, é mais comum em pacientes com contagens de CD4 abaixo de 50 células/mm³. Outras opções ocorrem com CD4 mais elevado ou são menos específicas para esse limiar.", category: "Infectologia" },
  { id: 308, question: "No manejo da tuberculose pulmonar sensível aos fármacos em adultos, qual o esquema terapêutico inicial recomendado pelo Ministério da Saúde do Brasil?", options: ["Isoniazida, Rifampicina, Pirazinamida e Etambutol por 6 meses.", "Isoniazida e Rifampicina por 9 meses.", "Isoniazida, Rifampicina e Pirazinamida por 2 meses, seguido por Isoniazida e Rifampicina por 4 meses.", "Isoniazida, Rifampicina, Pirazinamida, Etambutol e Estreptomicina por 2 meses, seguido por Isoniazida e Rifampicina por 4 meses."], correctIndex: 2, explanation: "O esquema básico para tuberculose pulmonar sensível no Brasil consiste em uma fase intensiva de 2 meses com Rifampicina, Isoniazida e Pirazinamida, seguida por uma fase de manutenção de 4 meses com Rifampicina e Isoniazida.", category: "Infectologia" },
  { id: 309, question: "Um paciente retorna de uma viagem para a Amazônia e apresenta quadro de febre intermitente, calafrios, sudorese, cefaleia e mialgia. O diagnóstico mais provável é malária. Qual exame é fundamental para a confirmação diagnóstica e identificação da espécie parasita?", options: ["Hemocultura", "Teste rápido para dengue", "Gota espessa e esfregaço de sangue periférico", "Sorologia para febre amarela"], correctIndex: 2, explanation: "A gota espessa e o esfregaço de sangue periférico são os exames padrão-ouro para o diagnóstico de malária, permitindo a visualização do parasita, a identificação da espécie (Plasmodium falciparum, vivax, etc.) e a quantificação da parasitemia.", category: "Infectologia" },
  { id: 310, question: "Qual das seguintes manifestações clínicas é a mais característica da sífilis secundária?", options: ["Cancro duro indolor no local da inoculação.", "Goma sifilítica na pele ou ossos.", "Rash cutâneo maculopapular difuso, incluindo palmas das mãos e plantas dos pés.", "Aneurisma de aorta."], correctIndex: 2, explanation: "O rash cutâneo maculopapular, frequentemente descrito como não pruriginoso e envolvendo palmas das mãos e plantas dos pés, é a manifestação mais comum e característica da sífilis secundária, que ocorre semanas a meses após o cancro primário.", category: "Infectologia" },
  { id: 311, question: "Um paciente com diagnóstico recente de HIV, que reside em área endêmica de histoplasmose, apresenta febre prolongada, perda de peso, hepatoesplenomegalia e lesões cutâneas papulosas. A contagem de CD4 é de 80 células/mm³. Qual a conduta inicial mais adequada para o diagnóstico?", options: ["Início empírico de fluconazol.", "Punção e biópsia de medula óssea para pesquisa de fungos.", "Solicitar carga viral para HIV e CD4.", "Tomografia de abdome para avaliar hepatoesplenomegalia."], correctIndex: 1, explanation: "Em um paciente imunocomprometido com quadro disseminado sugestivo de histoplasmose e residência em área endêmica, a biópsia de medula óssea (ou de lesão cutânea, se presente) com cultura e histopatologia é crucial para a confirmação diagnóstica, permitindo visualizar o Histoplasma capsulatum.", category: "Infectologia" },
  { id: 312, question: "A terapêutica de escolha para a sífilis em gestantes, em qualquer estágio da doença, e que não possuem história de alergia à penicilina, é:", options: ["Azitromicina", "Doxiciclina", "Ceftriaxona", "Penicilina G Benzatina"], correctIndex: 3, explanation: "A penicilina G benzatina é a única terapêutica com eficácia comprovada na prevenção da sífilis congênita, sendo a droga de escolha para o tratamento da sífilis em gestantes, independentemente do estágio da doença.", category: "Infectologia" },
  { id: 313, question: "Em pacientes com osteomielite hematogênica em ossos longos, qual o agente etiológico mais comum?", options: ["Salmonella spp.", "Streptococcus pyogenes", "Staphylococcus aureus", "Escherichia coli"], correctIndex: 2, explanation: "O Staphylococcus aureus é o agente etiológico mais comum na maioria dos casos de osteomielite, incluindo a forma hematogênica, em todas as faixas etárias.", category: "Infectologia" },
  { id: 314, question: "Qual das seguintes medidas é mais eficaz na prevenção da transmissão vertical do HIV?", options: ["Cesariana eletiva para todas as gestantes soropositivas.", "Uso de antirretrovirais (ARV) durante a gestação, parto e para o recém-nascido.", "Aleitamento materno exclusivo sob medicação antirretroviral.", "Imunoglobulina intravenosa (IGIV) no terceiro trimestre."], correctIndex: 1, explanation: "O uso de terapia antirretroviral combinada durante a gestação, no parto e a quimioprofilaxia no recém-nascido, juntamente com a inibição do aleitamento materno, são as medidas mais eficazes para prevenir a transmissão vertical do HIV.", category: "Infectologia" },
  { id: 315, question: "Um paciente é diagnosticado com Herpes Zoster. Qual fármaco antiviral é mais utilizado para reduzir a duração e a intensidade da dor, especialmente se iniciado nas primeiras 72 horas dos sintomas?", options: ["Ribavirina", "Oseltamivir", "Aciclovir", "Lamivudina"], correctIndex: 2, explanation: "O aciclovir (e seus profármacos valaciclovir e fanciclovir) é o antiviral de primeira escolha para o tratamento do Herpes Zoster, sendo mais eficaz quando iniciado nas primeiras 72 horas para reduzir a duração da erupção e a incidência de neuralgia pós-herpética.", category: "Infectologia" },
  { id: 316, question: "Em um surto de gastroenterite em uma creche, com predominância de vômitos e diarreia aquosa em crianças, qual o agente etiológico é o mais provável?", options: ["EPEC (Escherichia coli enteropatogênica)", "Rotavírus", "Salmonella enteritidis", "Clostridium difficile"], correctIndex: 1, explanation: "O Rotavírus é a causa mais comum de gastroenterite viral grave em crianças, caracterizada por vômitos e diarreia aquosa, especialmente em ambientes como creches.", category: "Infectologia" },
  { id: 317, question: "Qual das seguintes afirmações sobre a doença de Chagas é verdadeira?", options: ["A fase aguda é sempre sintomática e grave.", "A forma crônica cardíaca é a manifestação mais comum e grave da doença.", "A transmissão ocorre exclusivamente pela picada de mosquitos Anopheles.", "O tratamento na fase crônica indeterminada não é recomendado."], correctIndex: 1, explanation: "A forma cardíaca é a manifestação mais comum e grave da doença de Chagas crônica, podendo levar a arritmias, insuficiência cardíaca e morte súbita. A transmissão é principalmente por triatomíneos (barbeiros), mas também por via oral ou transfusional.", category: "Infectologia" },
  { id: 318, question: "Qual a principal complicação neurológica da neurocisticercose, que frequentemente requer intervenção neurocirúrgica?", options: ["Epilepsia", "Hidrocefalia", "Déficit motor focal", "Meningite asséptica"], correctIndex: 1, explanation: "A hidrocefalia é uma complicação grave e comum da neurocisticercose, especialmente nas formas racemosa ou intraventricular, devido à obstrução da circulação do líquor pelos cistos ou pela reação inflamatória, frequentemente necessitando de derivação.", category: "Infectologia" },
  { id: 319, question: "Um paciente de 25 anos com febre, faringite e linfonodomegalia generalizada, incluindo esplenomegalia, tem suspeita de mononucleose infecciosa. Qual o exame mais indicado para confirmação diagnóstica?", options: ["Hemograma completo com pesquisa de células atípicas.", "Teste de Paul-Bunnell ou teste rápido para mononucleose (Monospot test).", "Dosagem de anticorpos anti-EBV (anti-VCA IgM e IgG).", "Culturas de orofaringe."], correctIndex: 2, explanation: "Embora o hemograma e o Monospot possam ser sugestivos, a dosagem de anticorpos específicos contra o vírus Epstein-Barr (EBV), como anti-VCA IgM (infecção aguda) e anti-VCA IgG (infecção passada ou recente), é o método diagnóstico confirmatório definitivo para mononucleose infecciosa.", category: "Infectologia" },
  { id: 320, question: "Um paciente com história de febre reumática apresenta um sopro cardíaco e desenvolve febre, calafrios e exantema cutâneo maculopapular. Hemoculturas revelam Streptococcus viridans. Qual o diagnóstico mais provável?", options: ["Miocardite viral", "Endocardite infecciosa", "Pericardite aguda", "Febre reumática reativada"], correctIndex: 1, explanation: "Um paciente com valvopatia preexistente (febre reumática), apresentando quadro de infecção sistêmica (febre, calafrios) e achados cutâneos compatíveis com embolia séptica, além de hemoculturas positivas para Streptococcus viridans, tem alta probabilidade de endocardite infecciosa.", category: "Infectologia" },
  { id: 321, question: "Qual a principal via de transmissão da teníase-cisticercose?", options: ["Ingestão de água contaminada com ovos de Taenia saginata.", "Ingestão de carne suína mal cozida contendo cisticercos.", "Ingestão de vegetais crus contaminados com ovos de Taenia solium.", "Picada de insetos vetores infectados."], correctIndex: 2, explanation: "A teníase é adquirida pela ingestão de carne crua ou mal cozida contendo cisticercos (larvas). A cisticercose humana é causada pela ingestão de ovos de Taenia solium, que geralmente ocorre pela ingestão de alimentos ou água contaminados com fezes humanas contendo esses ovos.", category: "Infectologia" },
  { id: 322, question: "Qual a medida mais importante para o controle da raiva em humanos, após uma exposição comprovada (mordedura por animal suspeito)?", options: ["Administração de antibióticos de amplo espectro.", "Observação do animal agressor por 10 dias se for cão ou gato.", "Vacinação antirrábica pós-exposição e, se indicado, soro antirrábico.", "Isolamento do paciente em unidade de terapia intensiva."], correctIndex: 2, explanation: "A vacinação antirrábica pós-exposição, combinada com a administração de soro antirrábico em casos de exposição de alto risco, é a medida mais crucial e eficaz para a prevenção da raiva em humanos após uma exposição.", category: "Infectologia" },
  { id: 323, question: "No tratamento empírico da meningite bacteriana aguda em adultos sem fatores de risco para germes multirresistentes, qual a combinação de antibióticos recomendada?", options: ["Ampicilina e Doxiciclina.", "Ceftriaxona e Vancomicina.", "Ciprofloxacino e Metronidazol.", "Sulfametoxazol-trimetoprim e Rifampicina."], correctIndex: 1, explanation: "A combinação de Ceftriaxona (ou Cefotaxima) com Vancomicina é o esquema empírico recomendado para a meningite bacteriana aguda em adultos, cobrindo os patógenos mais comuns como Streptococcus pneumoniae, Neisseria meningitidis e Haemophilus influenzae, incluindo cepas de pneumococo resistentes.", category: "Infectologia" },
  { id: 324, question: "Um surto de rubéola é suspeitado em uma comunidade. Qual a principal característica clínica que ajuda a diferenciá-la de outras exantemáticas?", options: ["Exantema maculopapular que começa no tronco e se espalha.", "Gânglios linfáticos retroauriculares e cervicais aumentados (linfonodomegalia).", "Manchas de Koplik na mucosa oral.", "Exantema vesiculoso com prurido intenso."], correctIndex: 1, explanation: "A linfonodomegalia generalizada, principalmente retroauricular, cervical posterior e occipital, é uma característica marcante da rubéola, ajudando a diferenciá-la de outras exantemáticas como sarampo (Koplik) ou varicela (vesículas).", category: "Infectologia" },
  { id: 325, question: "Um paciente de 65 anos, hipertenso e diabético tipo 2, apresenta-se com fadiga progressiva, edema maleolar bilateral e dispneia aos esforços. Exames laboratoriais mostram ureia de 120 mg/dL, creatinina de 4,5 mg/dL, potássio de 5,8 mEq/L, hemoglobina de 9,0 g/dL e relação albumina/creatinina urinária de 500 mg/g. Qual a classificação da Doença Renal Crônica (DRC) para este paciente, considerando a taxa de filtração glomerular estimada (TFGe) de 12 mL/min/1,73m²?", options: ["DRC estágio G3b A3", "DRC estágio G4 A3", "DRC estágio G5 A3", "DRC estágio G5 A2"], correctIndex: 2, explanation: "A TFGe de 12 mL/min/1,73m² classifica o paciente em estágio G5 (TFGe <15 mL/min/1,73m²). A relação albumina/creatinina urinária de 500 mg/g classifica o paciente em A3 (excreção de albumina >300 mg/dia).", category: "Nefrologia" },
  { id: 326, question: "No manejo da hipercalemia grave (potássio > 6,5 mEq/L ou com alterações eletrocardiográficas) em pacientes com Doença Renal Crônica, qual a conduta inicial mais urgente para estabilizar o miocárdio?", options: ["Administração intravenosa de insulina com glicose", "Administração intravenosa de gluconato de cálcio a 10%", "Administração intravenosa de bicarbonato de sódio", "Administração de furosemida intravenosa"], correctIndex: 1, explanation: "O gluconato de cálcio atua rapidamente (em minutos) estabilizando a membrana cardíaca, protegendo o coração dos efeitos da hipercalemia, sem reduzir o potássio sérico. As outras opções reduzem o potássio, mas não estabilizam o miocárdio de imediato.", category: "Nefrologia" },
  { id: 327, question: "Qual das seguintes condições é a principal causa de Doença Renal Crônica no Brasil, de acordo com inquéritos epidemiológicos recentes?", options: ["Doença renal policística autossômica dominante", "Glomerulonefrite crônica", "Nefropatia diabética", "Nefropatia hipertensiva"], correctIndex: 2, explanation: "A nefropatia diabética é a principal causa de Doença Renal Crônica no Brasil e no mundo, seguida pela nefropatia hipertensiva. O controle glicêmico é fundamental para prevenir e retardar sua progressão.", category: "Nefrologia" },
  { id: 328, question: "Um paciente de 40 anos apresenta-se com hematúria macroscópica indolor após um quadro de infecção de via aérea superior. Biópsia renal revela deposição mesangial de IgA e proliferação mesangial. Qual o diagnóstico mais provável?", options: ["Glomerulonefrite rapidly progressive", "Nefropatia por IgA", "Doença de lesão mínima", "Glomeruloesclerose segmentar e focal"], correctIndex: 1, explanation: "A nefropatia por IgA (doença de Berger) é caracterizada por hematúria macroscópica intermitente, frequentemente após infecções mucosas (respiratórias ou gastrointestinais), e a biópsia mostra deposição de IgA no mesângio.", category: "Nefrologia" },
  { id: 329, question: "Qual das seguintes classes de medicamentos é prioritária para a redução da proteinúria e da progressão da Doença Renal Crônica em pacientes diabéticos e não diabéticos com hipertensão arterial e albuminúria?", options: ["Diuréticos de alça", "Betabloqueadores", "Bloqueadores do sistema renina-angiotensina-aldosterona (IECA/BRA)", "Bloqueadores dos canais de cálcio"], correctIndex: 2, explanation: "Inibidores da enzima conversora de angiotensina (IECA) e bloqueadores dos receptores da angiotensina (BRA) são os agentes de primeira linha para reduzir a proteinúria e retardar a progressão da DRC, devido aos seus efeitos no sistema renina-angiotensina-aldosterona.", category: "Nefrologia" },
  { id: 330, question: "Um paciente com Doença Renal Crônica em estágio avançado desenvolve osteodistrofia renal. Qual é um achado laboratorial clássico nesse contexto?", options: ["Hipercalcemia e hipofosfatemia", "Hipocalcemia e hiperparatireoidismo secundário", "Níveis normais de PTH e cálcio", "Hipercalcemia e níveis de PTH suprimidos"], correctIndex: 1, explanation: "Na osteodistrofia renal, a diminuição da excreção de fosfato e a deficiência na produção de calcitriol (vitamina D ativa) levam à hipocalcemia, que estimula o hiperparatireoidismo secundário, exarcebando a reabsorção óssea.", category: "Nefrologia" },
  { id: 331, question: "Qual é a principal causa de morte em pacientes com Doença Renal Crônica em todas as fases da doença, inclusive nos pacientes em diálise?", options: ["Infecções", "Eventos cardiovasculares", "Neoplasias", "Eventos cerebrovasculares"], correctIndex: 1, explanation: "Doenças cardiovasculares (infarto agudo do miocárdio, insuficiência cardíaca, arritmias) são a principal causa de mortalidade em pacientes com DRC, um risco que aumenta à medida que a função renal declina.", category: "Nefrologia" },
  { id: 332, question: "No tratamento da anemia na Doença Renal Crônica, quando se deve considerar o início da reposição de eritropoetina (agentes estimuladores da eritropoiese - AEE)?", options: ["Quando a hemoglobina está persistentemente abaixo de 11,0 g/dL e a causa da anemia não é deficiência de ferro", "Sempre que a hemoglobina estiver abaixo de 10,0 g/dL, independentemente dos níveis de ferro", "Apenas quando a hemoglobina está abaixo de 8,0 g/dL", "Quando a hemoglobina está persistentemente abaixo de 10,0 g/dL e as reservas de ferro estão adequadas"], correctIndex: 3, explanation: "As diretrizes recomendam iniciar AEE quando a hemoglobina está abaixo de 10,0 g/dL, após exclusão ou tratamento da deficiência de ferro, e se outras causas da anemia forem abordadas.", category: "Nefrologia" },
  { id: 333, question: "Um paciente em hemodiálise apresenta hipotensão intradialítica. Qual a conduta inicial mais adequada?", options: ["Aumentar a taxa de ultrafiltração", "Administrar um vasopressor", "Administrar soro fisiológico intravenoso", "Reduzir o fluxo do dialisato"], correctIndex: 2, explanation: "A hipotensão intradialítica é uma complicação comum. A conduta inicial é interromper (ou reduzir) a ultrafiltração e administrar fluidos intravenosos (geralmente soro fisiológico) para expandir o volume intravascular e restaurar a pressão arterial.", category: "Nefrologia" },
  { id: 334, question: "Qual a principal complicação infecciosa associada ao cateter de hemodiálise de longa permanência (cateter tunelizado)?", options: ["Infecção do trato urinário", "Peritonite bacteriana espontânea", "Sepse relacionada ao cateter", "Pneumonia associada à ventilação"], correctIndex: 2, explanation: "A principal complicação infecciosa dos cateteres de hemodiálise, tanto tunelizados quanto não tunelizados, é a infecção da corrente sanguínea relacionada ao cateter, que pode levar a sepse.", category: "Nefrologia" },
  { id: 335, question: "Qual das seguintes é uma indicação absoluta para o início de terapia renal substitutiva (diálise ou transplante renal) em pacientes com Doença Renal Crônica terminal?", options: ["Creatinina sérica acima de 5,0 mg/dL", "Hipocalemia refratária", "Pericardite urêmica", "Albumina sérica abaixo de 3,0 g/dL"], correctIndex: 2, explanation: "Pericardite urêmica é uma complicação grave da uremia e constitui uma indicação absoluta de diálise de emergência, pois é um sinal de uremia severa que pode levar a tamponamento cardíaco.", category: "Nefrologia" },
  { id: 336, question: "No tratamento da Doença Renal Crônica, qual das seguintes classes de medicamentos demonstrou, além do efeito anti-hipertensivo, reduzir a progressão da doença em pacientes com albuminúria, independentemente do controle glicêmico?", options: ["Glinidas", "Inibidores da SGLT2 (iSGLT2)", "Sulfonilureias", "Biguanidas"], correctIndex: 1, explanation: "Os iSGLT2 (como dapagliflozina, empagliflozina) demonstraram em grandes ensaios clínicos reduzir a progressão da DRC e eventos cardiovasculares em pacientes com e sem diabetes tipo 2, além de seus efeitos na glicemia em diabéticos.", category: "Nefrologia" },
  { id: 337, question: "Um paciente com Síndrome Nefrótica apresenta edema generalizado, proteinúria de 5 g/dia, hipoalbuminemia e dislipidemia. Qual a principal complicação trombótica a ser prevenida nesse cenário?", options: ["Trombose venosa profunda e embolia pulmonar", "Acidente vascular cerebral isquêmico", "Trombose arterial coronariana", "Trombose de veia mesentérica"], correctIndex: 0, explanation: "A síndrome nefrótica está associada a um estado de hipercoagulabilidade devido à perda urinária de anticoagulantes naturais (como antitrombina III) e/ou aumento de fatores procoagulantes, aumentando significativamente o risco de trombose venosa profunda e embolia pulmonar.", category: "Nefrologia" },
  { id: 338, question: "Qual dos seguintes achados na análise da urina é o mais indicativo de uma lesão glomerular ativa?", options: ["Cristais de oxalato de cálcio", "Cilindros hialinos", "Hemácias dismórficas e cilindros hemáticos", "Leucocitúria e cilindros leucocitários"], correctIndex: 2, explanation: "Hemácias dismórficas (irregularidades na morfologia das hemácias) e a presença de cilindros hemáticos são patognomônicos de sangramento de origem glomerular, indicando inflamação glomerular ativa.", category: "Nefrologia" },
  { id: 339, question: "Em um paciente com doença renal crônica e anemia, qual o principal objetivo de hemoglobina a ser alcançado com o uso de agentes estimuladores de eritropoiese, conforme as diretrizes atuais?", options: ["Manter a hemoglobina acima de 13,0 g/dL para evitar fadiga", "Manter a hemoglobina entre 10,0 e 11,5 g/dL para balancear benefícios e riscos", "Atingir níveis de hemoglobina o mais próximo possível do normal (>12,0 g/dL)", "Manter a hemoglobina abaixo de 9,0 g/dL para evitar hiperviscosidade"], correctIndex: 1, explanation: "As diretrizes recomendam manter a hemoglobina entre 10,0 e 11,5 g/dL. Níveis mais altos são associados a aumento do risco de eventos cardiovasculares, AVC e trombose, sem melhora significativa na qualidade de vida.", category: "Nefrologia" },
  { id: 340, question: "Um paciente de 65 anos, hipertenso e diabético, é trazido ao pronto-socorro com queixa de hemiparesia direita e afasia de início súbito há 30 minutos. Qual a principal hipótese diagnóstica e a conduta inicial mais adequada?", options: ["Acidente Vascular Encefálico Isquêmico (AVEi); iniciar trombolítico endovenoso após exclusão de contraindicações.", "Acidente Vascular Encefálico Hemorrágico (AVEh); realizar tomografia de crânio e iniciar controle rigoroso da pressão arterial.", "Crise epiléptica focal com paralisia de Todd; observar e realizar eletroencefalograma.", "Hipoglicemia grave; verificar glicemia capilar e ofertar glicose oral ou intravenosa."], correctIndex: 0, explanation: "A descrição é clássica de AVE isquêmico, uma emergência neurológica. A janela terapêutica para trombólise endovenosa é crítica e deve ser iniciada rapidamente após exclusão de hemorragia e outras contraindicações por exame de imagem.", category: "Neurologia" },
  { id: 341, question: "Qual das seguintes condições é uma contraindicação ABSOLUTA para a trombólise endovenosa com alteplase em um paciente com Acidente Vascular Encefálico Isquêmico agudo?", options: ["Uso de anticoagulante oral (varfarina) com INR desconhecido.", "História de acidente isquêmico transitório (AIT) há 3 meses.", "Convulsão no início do AVEi, com evidência de lesão isquêmica residual significativa.", "Pressão arterial de 180/100 mmHg no momento da admissão, que respondeu à medicação anti-hipertensiva."], correctIndex: 0, explanation: "O uso de anticoagulante oral com INR desconhecido ou elevado é uma contraindicação absoluta devido ao alto risco de hemorragia intracraniana. Os demais itens são contraindicações relativas ou não o são.", category: "Neurologia" },
  { id: 342, question: "Uma paciente de 30 anos refere episódios de dor de cabeça unilateral, pulsátil, de moderada a forte intensidade, associada a náuseas, fotofobia e fonofobia, com duração de 4 a 72 horas. Os episódios são precedidos por auras visuais em zigue-zague. Qual o diagnóstico mais provável?", options: ["Cefaleia tensional crônica.", "Enxaqueca com aura.", "Cefaleia em salvas.", "Neuralgia do trigêmeo."], correctIndex: 1, explanation: "A descrição de dor unilateral, pulsátil, associada a náuseas, fotofobia/fonofobia e auras visuais é característica da enxaqueca com aura, segundo os critérios da ICHD-3.", category: "Neurologia" },
  { id: 343, question: "Em relação à Esclerose Múltipla, qual das seguintes afirmativas está CORRETA?", options: ["É uma doença infecciosa do sistema nervoso central, caracterizada por desmielinização.", "Atinge preferencialmente idosos, com quadro de demência rapidamente progressiva.", "É uma doença autoimune, inflamatória e desmielinizante do sistema nervoso central.", "O tratamento padrão ouro consiste em corticoterapia pulsada por longos períodos."], correctIndex: 2, explanation: "A Esclerose Múltipla é classicamente descrita como uma doença autoimune, inflamatória e desmielinizante que afeta o sistema nervoso central, com curso clínico variável.", category: "Neurologia" },
  { id: 344, question: "Qual das seguintes drogas é a de primeira linha para o tratamento da dor neuropática periférica, como a neuropatia diabética?", options: ["Morfina.", "Ibuprofeno.", "Amitriptilina.", "Paracetamol."], correctIndex: 2, explanation: "Antidepressivos tricíclicos, como a amitriptilina, são fármacos de primeira linha no tratamento da dor neuropática, incluindo a neuropatia diabética, devido à sua ação nos mecanismos da dor.", category: "Neurologia" },
  { id: 345, question: "Um paciente de 70 anos é levado ao pronto-socorro com história de quedas frequentes, instabilidade postural, bradicinesia e tremor de repouso na mão direita que piora ao estresse. Não apresenta alterações cognitivas significativas. Qual o diagnóstico mais provável?", options: ["Doença de Alzheimer.", "Doença de Parkinson.", "Tremor essencial.", "Ataxia cerebelar."], correctIndex: 1, explanation: "Os sintomas descritos (bradicinesia, instabilidade postural, tremor de repouso) são característicos da doença de Parkinson, uma doença neurodegenerativa que afeta o sistema motor.", category: "Neurologia" },
  { id: 346, question: "No manejo da crise epiléptica tônico-clônica generalizada em ambiente extra-hospitalar, qual a conduta INICIAL mais importante a ser adotada pelos acompanhantes?", options: ["Abrir a boca do paciente para evitar a mordedura da língua.", "Imobilizar os membros do paciente para evitar traumatismos.", "Posicionar o paciente em decúbito lateral e proteger sua cabeça.", "Administrar medicação anticonvulsivante oral imediatamente."], correctIndex: 2, explanation: "A conduta inicial mais importante é garantir a segurança do paciente, protegendo sua cabeça e garantindo a permeabilidade das vias aéreas posicionando-o em decúbito lateral para evitar aspiração.", category: "Neurologia" },
  { id: 347, question: "Um paciente com diagnóstico recente de Miastenia Gravis apresenta piora súbita da fraqueza muscular generalizada, evoluindo com dificuldade respiratória e disfagia grave. Qual a conduta IMEDIATA mais apropriada?", options: ["Aumentar a dose de piridostigmina.", "Iniciar plasmaférese ou imunoglobulina intravenosa e avaliar intubação orotraqueal.", "Administrar corticoide oral em dose de ataque.", "Realizar eletromiografia urgente para confirmar o diagnóstico."], correctIndex: 1, explanation: "A crise miastênica é uma emergência médica caracterizada por fraqueza muscular grave, que pode comprometer a respiração. O tratamento inclui suporte ventilatório (se necessário) e terapia imunomoduladora rápida como plasmaférese ou IgIV.", category: "Neurologia" },
  { id: 348, question: "Qual é a principal função do LCR (Líquor) no sistema nervoso central?", options: ["Transporte de oxigênio e nutrientes para os neurônios.", "Remoção de resíduos metabólicos e proteção mecânica do encéfalo e medula.", "Produção de neurotransmissores essenciais.", "Manutenção da temperatura cerebral constante."], correctIndex: 1, explanation: "O líquor tem papel fundamental na proteção mecânica do encéfalo e da medula espinhal, além de participar da remoção de produtos metabólicos residuais.", category: "Neurologia" },
  { id: 349, question: "Um paciente com suspeita de Síndrome de Guillain-Barré apresenta fraqueza progressiva ascendente e arreflexia. Qual achado laboratorial no líquor é mais sugestivo dessa doença?", options: ["Aumento expressivo das células com glicose baixa.", "Albumino-citológica com dissociação (aumento de proteínas com celularidade normal).", "Padrão oligoclonal de bandas.", "Presença de xantocromia."], correctIndex: 1, explanation: "A dissociação albumino-citológica (aumento de proteínas com celularidade normal ou levemente aumentada) é um achado clássico no líquor de pacientes com Síndrome de Guillain-Barré, refletindo a desmielinização.", category: "Neurologia" },
  { id: 350, question: "Qual das seguintes opções CORRETAMENTE descreve a fisiopatologia da Doença de Alzheimer?", options: ["Degeneração dos neurônios dopaminérgicos na substância negra.", "Acúmulo de corpos de Lewy no córtex cerebral.", "Depositação de placas de beta-amiloide e emaranhados neurofibrilares de proteína tau.", "Desmielinização multifocal do sistema nervoso central."], correctIndex: 2, explanation: "A Doença de Alzheimer é caracterizada patologicamente pela formação de placas senis (beta-amiloide) e emaranhados neurofibrilares (proteína tau hiperfosforilada) no cérebro.", category: "Neurologia" },
  { id: 351, question: "No tratamento agudo da neuralgia do trigêmeo idiopática, qual a medicação de primeira linha recomendada?", options: ["Baclofeno.", "Gabapentina.", "Carbamazepina.", "Pregabalina."], correctIndex: 2, explanation: "A carbamazepina é o fármaco de primeira linha para o tratamento da neuralgia do trigêmeo devido à sua eficácia comprovada no controle das crises de dor.", category: "Neurologia" },
  { id: 352, question: "Um paciente de 45 anos é internado com rebaixamento do nível de consciência, rigidez de nuca, febre e vômitos. Qual a principal suspeita diagnóstica e o exame inicial mais importante?", options: ["AVE isquêmico; angiotomografia de crânio.", "Meningite bacteriana; punção lombar (LCR) após exclusão de risco para herniação cerebral.", "Encefalite viral; ressonância magnética de crânio.", "Crise hipertensiva com encefalopatia; aferição rigorosa da pressão arterial."], correctIndex: 1, explanation: "Febre, rigidez de nuca e alteração do nível de consciência são sinais clássicos de meningite. A punção lombar é o exame diagnóstico crucial para diferenciar entre os tipos de meningite e guiar o tratamento, devendo ser realizada após assegurar a ausência de sinais de hipertensão intracraniana.", category: "Neurologia" },
  { id: 353, question: "Qual o principal efeito adverso do fenobarbital no sistema nervoso central em uso contínuo?", options: ["Insônia.", "Nervosismo e agitação.", "Sonolência e sedação.", "Cefaleia refratária."], correctIndex: 2, explanation: "O fenobarbital é um antiepiléptico com propriedades sedativas significativas, sendo a sonolência um dos seus efeitos adversos mais comuns e dose-dependentes.", category: "Neurologia" },
  { id: 354, question: "Um paciente de 60 anos apresenta ptose palpebral unilateral, miose e anidrose facial. Qual a síndrome neurológica associada a esses achados?", options: ["Síndrome de Horner.", "Síndrome de Bell.", "Síndrome de Wallenberg.", "Síndrome do túnel do carpo."], correctIndex: 0, explanation: "A tríade de ptose, miose e anidrose ipsilateral é classicamente denominada Síndrome de Horner, resultante da lesão das vias simpáticas.", category: "Neurologia" },
  { id: 355, question: "Qual dos seguintes é um fator de risco modificável mais importante para o Acidente Vascular Encefálico (AVE)?", options: ["Idade avançada.", "História familiar de AVE.", "Hipertensão arterial sistêmica não controlada.", "Sexo masculino."], correctIndex: 2, explanation: "A hipertensão arterial sistêmica não controlada é o fator de risco modificável mais prevalente e com maior impacto na ocorrência de AVE, sendo seu controle fundamental na prevenção.", category: "Neurologia" },
  { id: 356, question: "Qual a principal complicação aguda a ser monitorizada em pacientes com hemorragia subaracnoidea aneurismática?", options: ["Encefalopatia metabólica.", "Vasoespasmo cerebral.", "Crise convulsiva.", "Edema pulmonar neurogênico."], correctIndex: 1, explanation: "O vasoespasmo cerebral é uma complicação grave e comum na hemorragia subaracnoidea aneurismática, podendo levar à isquemia cerebral tardia e piora do prognóstico.", category: "Neurologia" },
  { id: 357, question: "Um paciente com hemorragia intracerebral extensa está apresentando sinais de herniação cerebral iminente. Qual a conduta de emergência mais adequada para reduzir a pressão intracraniana?", options: ["Administrar solução fisiológica a 0,9% rapidamente.", "Elevação da cabeceira a 30 graus, sedação e uso de manitol ou solução salina hipertônica.", "Iniciar transfusão de hemoderivados profilaticamente.", "Realizar cranioctomia descompressiva de rotina."], correctIndex: 1, explanation: "No contexto de hipertensão intracraniana e herniação iminente, medidas como elevação da cabeceira, sedação e o uso de agentes osmóticos (manitol ou salina hipertônica) são cruciais para reduzir a PIC e evitar danos cerebrais maiores.", category: "Neurologia" },
  { id: 358, question: "No tratamento profilático da enxaqueca, qual das seguintes classes de medicamentos é frequentemente utilizada?", options: ["Antagonistas do receptor de angiotensina II.", "Betabloqueadores como o propranolol.", "Agonistas dopaminérgicos.", "Inibidores da recaptação de serotonina (ISRS)."], correctIndex: 1, explanation: "Betabloqueadores, como o propranolol, são considerados fármacos de primeira linha para a profilaxia da enxaqueca, devido à sua eficácia e bom perfil de segurança em muitos pacientes.", category: "Neurologia" },
  { id: 359, question: "Qual a apresentação clínica mais comum da esclerose lateral amiotrófica (ELA)?", options: ["Fraqueza muscular proximal e atrofia com perda sensorial.", "Fraqueza muscular gradual e progressiva, associada a fasciculações e atrofia muscular, sem perda sensorial significativa.", "Dor neuropática intensa e parestesias em luva e bota.", "Paralisia facial unilateral de início súbito."], correctIndex: 1, explanation: "A ELA é caracterizada por degeneração dos neurônios motores superiores e inferiores, manifestando-se por fraqueza progressiva, atrofia muscular e fasciculações, sem envolvimento sensorial proeminente.", category: "Neurologia" },
  { id: 360, question: "Em um paciente com suspeita de Síndrome de Tourette, qual o sintoma característico que deve estar presente para o diagnóstico?", options: ["Apenas tiques motores complexos.", "Tiques motores e vocais múltiplos, presentes por mais de um ano.", "Tiques que aparecem apenas durante o sono.", "Tiques motores simples, com início na idade adulta."], correctIndex: 1, explanation: "A Síndrome de Tourette é definida pela presença de múltiplos tiques motores e pelo menos um tique vocal, que persistem por mais de um ano, com início antes dos 18 anos.", category: "Neurologia" },
  { id: 361, question: "Qual das seguintes condições é a causa mais comum de demência em pessoas idosas?", options: ["Demência frontotemporal.", "Doença de corpos de Lewy.", "Doença de Alzheimer.", "Demência vascular."], correctIndex: 2, explanation: "A Doença de Alzheimer é a forma mais prevalente de demência em idosos, respondendo pela maioria dos casos de comprometimento cognitivo progressivo.", category: "Neurologia" },
  { id: 362, question: "Um paciente que sofreu um traumatismo cranioencefálico grave apresenta um período de lucidez, seguido por rápida deterioração do nível de consciência, anisocoria e hemiparesia contralateral. Qual a hipótese diagnóstica mais provável?", options: ["Hematoma subdural crônico.", "Hemorragia subaracnoidea.", "Hematoma epidural.", "Contusão cerebral difusa."], correctIndex: 2, explanation: "O hematoma epidural é classicamente associado ao 'intervalo lúcido', seguido de deterioração neurológica rápida, devido ao sangramento arterial (geralmente da artéria meníngea média) entre a dura-máter e o crânio.", category: "Neurologia" },
  { id: 363, question: "Qual o principal mecanismo de ação dos agonistas do receptor de dopamina, como o pramipexol, no tratamento da Doença de Parkinson?", options: ["Inibição da degradação da acetilcolina.", "Bloqueio dos receptores de dopamina pós-sinápticos.", "Estimulação direta dos receptores de dopamina no estriado.", "Aumento da síntese de dopamina."], correctIndex: 2, explanation: "Os agonistas dopaminérgicos atuam estimulando diretamente os receptores de dopamina no estriado, mimetizando a ação da dopamina e compensando sua deficiência na Doença de Parkinson.", category: "Neurologia" },
  { id: 364, question: "Em um contexto de emergência neurológica, qual escala é comumente utilizada para avaliar e monitorar o nível de consciência de um paciente?", options: ["Escala de Rankin modificada.", "Escala de Coma de Glasgow (ECG).", "Escala NIHSS para AVE.", "Escala de Dor Visual Analógica (EVA)."], correctIndex: 1, explanation: "A Escala de Coma de Glasgow (ECG) é amplamente reconhecida e utilizada globalmente para uma avaliação rápida e padronizada do nível de consciência, especialmente em situações de emergência neurológica.", category: "Neurologia" },
  { id: 365, question: "Um paciente de 45 anos, sexo masculino, procura atendimento com queixa de fadiga progressiva, perda de peso involuntária, dor abdominal difusa e hiperpigmentação de pele e mucosas. Refere também tonturas frequentes e desejo por alimentos salgados. Exames laboratoriais mostram hiponatremia, hipercalemia e hipoglicemia. Qual das seguintes é a hipótese diagnóstica mais provável?", options: ["Hipotireoidismo primário", "Insuficiência adrenal primária (doença de Addison)", "Feocromocitoma", "Diabetes mellitus tipo 1"], correctIndex: 1, explanation: "A tríade de fadiga, perda de peso e hiperpigmentação, associada a distúrbios eletrolíticos como hiponatremia e hipercalemia, é altamente sugestiva de insuficiência adrenal primária (doença de Addison).", category: "Endocrinologia" },
  { id: 366, question: "No manejo do diabetes mellitus tipo 2, um inibidor do cotransportador de sódio-glicose 2 (iSGLT2) é particularmente benéfico em pacientes com qual das seguintes comorbidades?", options: ["Asma brônquica sem controle", "Doença renal crônica com albuminúria", "Osteoporose grave", "Hipocalemia refratária"], correctIndex: 1, explanation: "Os iSGLT2, como a dapagliflozina e empagliflozina, demonstraram benefício cardiovascular e renal, sendo recomendados em pacientes com diabetes mellitus tipo 2 e doença renal crônica, especialmente com albuminúria.", category: "Endocrinologia" },
  { id: 367, question: "Qual das seguintes características é mais consistente com tireotoxicose de Graves, em oposição a outras causas de hipertireoidismo?", options: ["Captação de iodo radioativo universalmente diminuída", "Níveis elevados de anticorpos anti-receptores de TSH (TRAb)", "Bócio multinodular palpável", "Teste de iodeto de potássio positivo"], correctIndex: 1, explanation: "A presença de anticorpos estimuladores do receptor de TSH (TRAb) é patognomônica da doença de Graves, que é a causa mais comum de hipertireoidismo com bócio difuso.", category: "Endocrinologia" },
  { id: 368, question: "Uma paciente de 30 anos apresenta amenorreia, galactorreia e cefaleia. Níveis séricos de prolactina estão elevados (150 ng/mL). A ressonância magnética da sela túrcica revela uma massa de 8 mm. Qual é a conduta inicial mais apropriada?", options: ["Cirurgia transesfenoidal imediata", "Radioterapia", "Início de agonistas dopaminérgicos", "Observação e acompanhamento anual"], correctIndex: 2, explanation: "Para prolactinomas, mesmo com macroadenomas (maiores que 10mm), os agonistas dopaminérgicos (como cabergolina ou bromocriptina) são a primeira linha de tratamento, com alta taxa de redução tumoral e normalização da prolactina.", category: "Endocrinologia" },
  { id: 369, question: "Um paciente é diagnosticado com síndrome de Cushing. Qual dos seguintes exames é o mais adequado para diferenciar entre a etiologia acth-dependente e acth-independente?", options: ["Dosagem de cortisol salivar noturno", "Teste de supressão com dexametasona em dose baixa", "Dosagem de ACTH plasmático", "Teste de corticotropina (ACTH) sintética"], correctIndex: 2, explanation: "A dosagem de ACTH plasmático é crucial para a diferenciação inicial. Níveis elevados ou inapropriadamente normais sugerem etiologia ACTH-dependente (doença de Cushing ou ACTH ectópico), enquanto níveis suprimidos indicam etiologia ACTH-independente (tumor adrenal).", category: "Endocrinologia" },
  { id: 370, question: "Qual é o principal efeito adverso que deve ser monitorado em pacientes iniciando terapia com metformina?", options: ["Hipoglicemia grave", "Ganho de peso substancial", "Acidose láctica", "Arritmias cardíacas"], correctIndex: 2, explanation: "A acidose láctica é um efeito adverso raro, porém grave, da metformina, especialmente em pacientes com insuficiência renal, insuficiência hepática ou insuficiência cardíaca descompensada. Não causa hipoglicemia grave isoladamente.", category: "Endocrinologia" },
  { id: 371, question: "Em um paciente com hiperaldosteronismo primário, qual é o exame inicial mais apropriado para rastreamento?", options: ["Dosagem de renina plasmática", "Dosagem de aldosterona plasmática", "Relação aldosterona/atividade de renina plasmática", "Tomografia computadorizada de adrenais"], correctIndex: 2, explanation: "A relação aldosterona/atividade de renina plasmática é o método de rastreamento mais sensível para hiperaldosteronismo primário. Uma relação elevada sugere o diagnóstico.", category: "Endocrinologia" },
  { id: 372, question: "Qual dos seguintes é considerado um critério diagnóstico para diabetes mellitus tipo 2, de acordo com as diretrizes da Sociedade Brasileira de Diabetes?", options: ["Glicemia de jejum < 100 mg/dL", "Hemoglobina glicada (HbA1c) ≥ 6,5%", "Teste oral de tolerância à glicose (TOTG) com glicemia de 2h < 140 mg/dL", "Glicemia casual < 200 mg/dL na ausência de sintomas"], correctIndex: 1, explanation: "Os critérios diagnósticos incluem HbA1c ≥ 6,5%, glicemia de jejum ≥ 126 mg/dL, ou glicemia de 2h no TOTG ≥ 200 mg/dL, ou glicemia casual ≥ 200 mg/dL com sintomas.", category: "Endocrinologia" },
  { id: 373, question: "Na avaliação laboratorial inicial de um nódulo tireoidiano, qual dos seguintes exames é fundamental para guiar a conduta?", options: ["Cintilografia de tireoide", "Dosagem de calcitonina", "Dosagem de TSH", "Dosagem de tireoglobulina"], correctIndex: 2, explanation: "A dosagem de TSH é o exame inicial mais importante. Níveis baixos de TSH sugerem nódulo hiperfuncionante (geralmente benigno), enquanto TSH normal ou elevado implica maior risco de malignidade, indicando PAAF guiada por ultrassom.", category: "Endocrinologia" },
  { id: 374, question: "Um paciente de 60 anos, com história de DM2 e hipertensão, apresenta-se com disfunção erétil e perda de libido. Exames revelam testosterona total baixa para a idade e LH e FSH normais/baixos. Qual é a principal hipótese diagnóstica?", options: ["Hipergonadismo primário", "Hipogonadismo primário", "Hipogonadismo hipogonadotrófico", "Hiperprolactinemia"], correctIndex: 2, explanation: "Testosterona baixa associada a LH e FSH normais ou baixos caracteriza um hipogonadismo hipogonadotrófico, ou seja, de causa central (hipofisária ou hipotalâmica).", category: "Endocrinologia" },
  { id: 375, question: "Qual dos seguintes é o manejo inicial mais apropriado para uma crise tireotóxica?", options: ["Administração de iodo radioativo", "Dose única de levotiroxina", "Terapia com propiltiouracil ou metimazol, associado a beta-bloqueador e suporte", "Cirurgia de tireoidectomia de emergência"], correctIndex: 2, explanation: "O manejo da crise tireotóxica inclui drogas antitireoidianas (propiltiouracil preferencial na gestação e lactação, metimazol nas demais), beta-bloqueadores, iodo (após as antitireoidianas), glicocorticoides e medidas de suporte.", category: "Endocrinologia" },
  { id: 376, question: "Qual a principal complicação aguda do diabetes mellitus que se caracteriza por desidratação grave, hiperglicemia acentuada (>600 mg/dL) e osmolalidade sérica elevada, sem cetoacidose significativa?", options: ["Cetoacidose diabética", "Hipoglicemia grave", "Estado hiperosmolar hiperglicêmico", "Acidose metabólica láctica"], correctIndex: 2, explanation: "O estado hiperosmolar hiperglicêmico (EHH) é caracterizado por hiperglicemia extrema, desidratação e hiperosmolaridade, geralmente sem acidose metabólica significativa, ao contrário da cetoacidose diabética.", category: "Endocrinologia" },
  { id: 377, question: "Em pacientes com osteoporose pós-menopausa, qual fármaco é a primeira linha de tratamento para reduzir o risco de fraturas vertebrais e não vertebrais?", options: ["Calcitonina", "Bifosfonatos orais", "Hormônio paratireoidiano (PTH) recombinante", "Ranelato de estrôncio"], correctIndex: 1, explanation: "Os bifosfonatos orais (ex: alendronato, risedronato) são a primeira linha de tratamento para osteoporose pós-menopausa, devido à sua eficácia comprovada na redução do risco de fraturas e boa tolerância.", category: "Endocrinologia" },
  { id: 378, question: "Um paciente em uso de levotiroxina para hipotireoidismo apresenta-se com TSH muito baixo e T4 livre elevado. Qual a conduta mais apropriada?", options: ["Aumentar a dose de levotiroxina", "Manter a dose e reavaliar em 6 meses", "Suspender a levotiroxina e iniciar terapia com propiltiouracil", "Reduzir a dose de levotiroxina"], correctIndex: 3, explanation: "TSH suprimido e T4 livre elevado indicam excesso de reposição hormonal. A conduta correta é a redução da dose de levotiroxina para evitar tireotoxicose iatrogênica.", category: "Endocrinologia" },
  { id: 379, question: "Qual é a principal manifestação clínica do feocromocitoma?", options: ["Hipotensão ortostática", "Hipoglicemia refratária", "Crises hipertensivas paroxísticas", "Bradicardia persistente"], correctIndex: 2, explanation: "O feocromocitoma é um tumor que produz catecolaminas, resultando em hipertensão, que pode ser contínua ou, mais classicamente, em crises paroxísticas acompanhadas de palpitações, cefaleia e sudorese.", category: "Endocrinologia" },
  { id: 380, question: "No rastreamento de neuropatia diabética, qual exame é recomendado anualmente a partir do diagnóstico de diabetes tipo 2?", options: ["Eletroneuromiografia", "Teste de sensibilidade térmica", "Avaliação da sensibilidade protetora com monofilamento de Semmes-Weinstein", "Dosagem de vitamina B12"], correctIndex: 2, explanation: "A avaliação da sensibilidade protetora com monofilamento de Semmes-Weinstein é o método mais prático e recomendado para rastreamento anual de neuropatia diabética periférica em atenção primária.", category: "Endocrinologia" },
  { id: 381, question: "Em um paciente com hipercalcemia grave (cálcio > 14 mg/dL), qual é a medida inicial de emergência mais importante para instituir?", options: ["Prescrição de bifosfonatos orais", "Administração de calcitonina", "Hidratação vigorosa com solução salina isotônica", "Diálise peritoneal"], correctIndex: 2, explanation: "A hidratação vigorosa com solução salina isotônica é a primeira e mais importante medida na hipercalcemia grave, visando expandir o volume e aumentar a excreção renal de cálcio.", category: "Endocrinologia" },
  { id: 382, question: "Qual dos seguintes fármacos antidiabéticos orais não causa hipoglicemia como efeito adverso principal quando utilizado em monoterapia?", options: ["Glibenclamida", "Insulina glargina", "Metformina", "Repaglinida"], correctIndex: 2, explanation: "A metformina age principalmente diminuindo a produção hepática de glicose e aumentando a sensibilidade à insulina, sem estimular diretamente a secreção de insulina pelas células beta, portanto, tem baixo risco de hipoglicemia em monoterapia.", category: "Endocrinologia" },
  { id: 383, question: "Uma paciente de 25 anos apresenta ganho de peso, intolerância ao frio, obstipação e mixedema. Exames mostram TSH elevado e T4 livre baixo. Qual o diagnóstico mais provável e a causa mais comum no Brasil?", options: ["Hipotireoidismo central, causado por adenoma hipofisário", "Hipertireoidismo subclínico, causado por nódulo tóxico", "Hipotireoidismo primário, causado por tireoidite de Hashimoto", "Tireoidite subaguda, causada por infecção viral"], correctIndex: 2, explanation: "TSH elevado e T4 livre baixo caracterizam hipotireoidismo primário. A principal causa de hipotireoidismo primário no Brasil e no mundo é a tireoidite de Hashimoto, uma doença autoimune.", category: "Endocrinologia" },
  { id: 384, question: "Qual dos seguintes fatores de risco está mais fortemente associado ao desenvolvimento de diabetes mellitus tipo 2?", options: ["Consumo excessivo de sódio", "Sedentarismo e obesidade", "Idade avançada", "Doença celíaca"], correctIndex: 1, explanation: "Sedentarismo e obesidade, especialmente obesidade visceral, são os fatores de risco modificáveis mais importantes para o desenvolvimento de resistência à insulina e diabetes mellitus tipo 2.", category: "Endocrinologia" },
  { id: 385, question: "Um paciente com acromegalia apresenta aumento das mãos, pés, macroglossia e sudorese excessiva. Qual exame hormonal é o mais útil para confirmar a atividade da doença?", options: ["Prolactina sérica", "Cortisol sérico", "Fator de crescimento semelhante à insulina tipo 1 (IGF-1)", "Hormônio tireoestimulante (TSH)"], correctIndex: 2, explanation: "O IGF-1 é o melhor marcador para rastreamento e confirmação da acromegalia, pois seus níveis refletem a secreção integrada do hormônio do crescimento (GH) e são estáveis, ao contrário do GH que tem secreção pulsátil.", category: "Endocrinologia" },
  { id: 386, question: "No tratamento do diabetes mellitus tipo 1, qual é a principal estratégia para mimetizar a secreção fisiológica de insulina?", options: ["Uso de insulina basal apenas, uma vez ao dia", "Administração de insulina regular antes das refeições", "Esquema basal-bolus com insulina de ação lenta e insulina de ação rápida antes das refeições", "Terapia com hipoglicemiantes orais"], correctIndex: 2, explanation: "O esquema basal-bolus, combinando uma insulina de longa duração (basal) para cobrir as necessidades entre as refeições e uma insulina de ação rápida (bolus) antes das refeições, é a estratégia mais fisiológica no DM1.", category: "Endocrinologia" },
  { id: 387, question: "Qual das seguintes condições endócrinas pode causar hipertensão arterial secundária?", options: ["Hipotireoidismo", "Doença de Addison", "Hipopituitarismo", "Hipertireoidismo (doença de Graves)"], correctIndex: 3, explanation: "O hipertireoidismo, especialmente a doença de Graves, pode causar hipertensão arterial, geralmente sistólica, devido ao aumento do débito cardíaco e da contratilidade miocárdica.", category: "Endocrinologia" },
  { id: 388, question: "Um paciente em uso crônico de corticoides em altas doses para uma doença autoimune desenvolve uma insuficiência adrenal secundária. Qual é a principal característica laboratorial esperada?", options: ["ACTH elevado e cortisol baixo", "ACTH baixo e cortisol baixo", "ACTH e cortisol elevados", "ACTH normal e cortisol elevado"], correctIndex: 1, explanation: "A insuficiência adrenal secundária (causada por supressão do eixo HHA por corticoides exógenos) é caracterizada por ACTH baixo, que leva à diminuição da produção de cortisol pelas adrenais.", category: "Endocrinologia" },
  { id: 389, question: "Qual é a principal manifestação do Diabetes Insipidus?", options: ["Hiponatremia e oligúria", "Hipernatremia e poliúria/polidipsia", "Hipoglicemia e polifagia", "Hipercalemia e fraqueza muscular"], correctIndex: 1, explanation: "O Diabetes Insipidus, seja central ou nefrogênico, é caracterizado por deficiência ou resistência ao ADH, resultando em poliúria (excreção de grande volume de urina diluída), polidipsia e, se a ingestão de água for restrita, hipernatremia.", category: "Endocrinologia" },
  { id: 390, question: "Um paciente de 65 anos, hipertenso e diabético, apresenta queixa de edema em membros inferiores, além de oligúria e fadiga. Exames laboratoriais revelam creatinina de 3,5 mg/dL (basal de 1,0 mg/dL), ureia de 90 mg/dL, potássio de 5,8 mEq/L, hemoglobina de 10 g/dL. Ultrassonografia renal mostra rins com tamanho normal e boa diferenciação córtico-medular. Qual a conduta inicial MAIS apropriada para este paciente?", options: ["Iniciar hemodiálise de urgência.", "Administrar infusão de soro fisiológico e aguardar diurese.", "Utilizar diurético de alça em alta dose e observar resposta.", "Solicitar biópsia renal e iniciar pulsoterapia com metilprednisolona."], correctIndex: 2, explanation: "O caso sugere lesão renal aguda (LRA) com potássio elevado e edema. Antes de indicar diálise, deve-se tentar a terapia diurética intensiva, especialmente se houver evidência de sobrecarga volêmica, para avaliar a responsividade renal e corrigir a hipercalemia por redistribuição. A biópsia não é a conduta inicial imediata.", category: "Nefrologia" },
  { id: 391, question: "Qual das seguintes condições NÃO é uma causa comum de lesão renal aguda pré-renal?", options: ["Desidratação grave.", "Insuficiência cardíaca descompensada.", "Obstrução ureteral bilateral.", "Choque séptico."], correctIndex: 2, explanation: "A obstrução ureteral bilateral causa lesão renal aguda pós-renal, devido ao impedimento do fluxo urinário. As demais opções são causas clássicas de hipoperfusão renal, levando à LRA pré-renal.", category: "Nefrologia" },
  { id: 392, question: "Um homem de 40 anos é diagnosticado com doença renal crônica (DRC) estágio 3b. Qual a conduta MAIS importante para retardar a progressão da doença?", options: ["Restrição hídrica rigorosa.", "Controle rigoroso da pressão arterial e proteinúria.", "Dieta rica em proteínas para evitar desnutrição.", "Início imediato de eritropoetina recombinante."], correctIndex: 1, explanation: "O controle da pressão arterial (geralmente <130/80 mmHg) e a redução da proteinúria (com inibidores da enzima conversora de angiotensina ou bloqueadores do receptor de angiotensina) são as medidas mais eficazes para retardar a progressão da DRC, conforme as diretrizes atuais.", category: "Nefrologia" },
  { id: 393, question: "Em relação à osteodistrofia renal, qual das seguintes alterações laboratoriais é esperada em pacientes com doença renal crônica avançada?", options: ["Aumento dos níveis séricos de cálcio e diminuição do paratormônio (PTH).", "Diminuição dos níveis séricos de fósforo e aumento da vitamina D ativada.", "Aumento dos níveis séricos de fósforo e do paratormônio (PTH).", "Níveis normais de fósforo e cálcio com PTH elevado."], correctIndex: 2, explanation: "Na DRC avançada, há redução da excreção de fósforo, levando à hiperfosfatemia. Isso, juntamente com a diminuição da síntese de vitamina D ativa, estimula a produção de PTH, resultando em hiperparatireoidismo secundário.", category: "Nefrologia" },
  { id: 394, question: "Qual a principal indicação para o início de terapia de substituição renal (diálise ou transplante) em pacientes com insuficiência renal crônica?", options: ["Creatinina sérica > 4,0 mg/dL.", "Sinais e sintomas de uremia refratários ao tratamento conservador.", "Taxa de filtração glomerular estimada (TFGe) < 30 mL/min/1,73m².", "Proteinúria persistente > 1 g/24h."], correctIndex: 1, explanation: "A principal indicação para Terapia Renal Substitutiva é a presença de sintomas urêmicos (encefalopatia, pericardite, sangramento, náuseas e vômitos refratários) ou complicações metabólicas graves (hipercalemia refratária, acidose metabólica grave, sobrecarga hídrica refratária) que não respondem ao tratamento clínico.", category: "Nefrologia" },
  { id: 395, question: "Um paciente em hemodiálise experimenta hipotensão durante a sessão. Qual a medida inicial MAIS apropriada a ser tomada pelo enfermeiro?", options: ["Aumentar a taxa de ultrafiltração (UF).", "Administrar 100 mL de soro fisiológico intravenoso e monitorar.", "Interromper imediatamente a hemodiálise.", "Administrar um vasopressor sem diluição."], correctIndex: 1, explanation: "A hipotensão é uma complicação comum da hemodiálise. A administração de volume (soro fisiológico) é a medida inicial mais segura e eficaz para restaurar a pressão arterial, seguida de redução da UF e, se necessário, outras intervenções.", category: "Nefrologia" },
  { id: 396, question: "Qual é a principal complicação infecciosa em pacientes realizando diálise peritoneal contínua ambulatorial (DPCA)?", options: ["Infecção do acesso vascular.", "Peritonite bacteriana.", "Infecção do trato urinário.", "Pneumonia por aspiração."], correctIndex: 1, explanation: "A peritonite bacteriana é a complicação infecciosa mais comum e grave na DPCA, decorrente da contaminação da cavidade peritoneal, muitas vezes relacionada à manipulação do cateter.", category: "Nefrologia" },
  { id: 397, question: "A nefropatia diabética é a principal causa de doença renal crônica terminal no Brasil e no mundo. Qual a principal característica histopatológica que a identifica?", options: ["Crescentes epiteliais.", "Depósitos de imunocomplexos no mesângio.", "Expansão mesangial e espessamento da membrana basal glomerular.", "Formação de granulomas."], correctIndex: 2, explanation: "A nefropatia diabética é caracterizada pela expansão mesangial, espessamento da membrana basal glomerular e esclerose nodular (nódulos de Kimmelstiel-Wilson), que são alterações histológicas típicas de danos microvasculares.", category: "Nefrologia" },
  { id: 398, question: "Qual dos seguintes fármacos é NEFROTÓXICO e deve ser usado com cautela em pacientes com doença renal crônica?", options: ["Amoxicilina.", "Paracetamol.", "Ibuprofeno.", "Metformina."], correctIndex: 2, explanation: "Anti-inflamatórios não esteroides (AINEs) como o ibuprofeno são nefrotóxicos, pois inibem as prostaglandinas renais, levando à vasoconstrição da arteríola aferente e redução da filtração glomerular, especialmente em pacientes com DRC.", category: "Nefrologia" },
  { id: 399, question: "Um paciente com insuficiência renal crônica em hemodiálise apresenta anemia macrocítica com níveis de folato e vitamina B12 normais. Qual a causa MAIS provável desta anemia?", options: ["Deficiência de ferro.", "Deficiência de eritropoietina.", "Perda sanguínea crônica.", "Hemólise."], correctIndex: 1, explanation: "A deficiência de eritropoietina (EPO) é a principal causa de anemia normocítica e normocrômica na DRC. Embora a questão cite anemia macrocítica, na ausência de deficiência de B12/folato, a anemia da DRC é primariamente por EPO. Considerando as opções e o contexto de hemodiálise, a deficiência de EPO é a mais direta e comum causa em pacientes renais crônicos. Ajustando a pergunta: anemia na DRC é tipicamente normocítica e normocrômica por deficiência de EPO. Se fosse macrocítica, B12/Folato, mas as opções direcionam para EPO.", category: "Nefrologia" },
  { id: 400, question: "Em qual condição clínica a principal alteração nas provas de função renal é a diminuição da taxa de filtração glomerular (TFG) sem alterações significativas na concentração de creatinina sérica nas fases iniciais?", options: ["Nefropatia por IgA.", "Glomeruloesclerose segmentar e focal.", "Nefropatia diabética incipiente.", "Síndrome de Alport."], correctIndex: 2, explanation: "Na nefropatia diabética incipiente, a TFG pode estar inicialmente normal ou até aumentada (hiperfiltração), e a principal alteração é a microalbuminúria. A creatinina começa a se elevar em estágios mais avançados, quando a TFG já está significativamente comprometida.", category: "Nefrologia" },
  { id: 401, question: "Qual dos seguintes parâmetros é o MAIS sensível para rastreamento de lesão renal em pacientes diabéticos?", options: ["Níveis séricos de creatinina.", "Taxa de filtração glomerular estimada (TFGe).", "Relação albumina/creatinina urinária (RACu).", "Ureia sérica."], correctIndex: 2, explanation: "A relação albumina/creatinina urinária (RACu) é o marcador mais precoce e sensível de lesão renal em pacientes diabéticos, identificando a microalbuminúria antes de alterações na TFGe ou creatinina.", category: "Nefrologia" },
  { id: 402, question: "No manejo da hipercalemia aguda em pacientes com LRA, qual medicação promove a estabilização da membrana cardíaca?", options: ["Insulina com glicose.", "Resinas de troca iônica.", "Gluconato de cálcio.", "Salbutamol."], correctIndex: 2, explanation: "O gluconato de cálcio estabiliza a membrana cardíaca, protegendo o miocárdio dos efeitos arritmogênicos do potássio elevado, sem reduzir os níveis séricos de potássio. É a primeira medida em casos de alterações eletrocardiográficas.", category: "Nefrologia" },
  { id: 403, question: "Um paciente com diagnóstico de cistos renais múltiplos bilaterais e história familiar positiva deve ser investigado para qual doença?", options: ["Doença de Fabry.", "Doença renal policística autossômica dominante (DRPAD).", "Síndrome de Goodpasture.", "Nefropatia por refluxo."], correctIndex: 1, explanation: "A presença de cistos renais múltiplos bilaterais com história familiar positiva é altamente sugestiva de Doença Renal Policística Autossômica Dominante (DRPAD), uma das doenças renais hereditárias mais comuns.", category: "Nefrologia" },
  { id: 404, question: "Qual a principal causa de morte em pacientes com doença renal crônica em tratamento dialítico?", options: ["Infecções.", "Eventos cardiovasculares.", "Neoplasias.", "Desnutrição."], correctIndex: 1, explanation: "Doenças cardiovasculares são a principal causa de mortalidade em pacientes com DRC em diálise, devido à alta prevalência de fatores de risco tradicionais e não tradicionais nessa população.", category: "Nefrologia" },
  { id: 405, question: "Qual classe de fármacos é considerada primeira linha para o tratamento da hipertensão arterial em pacientes com doença renal crônica e proteinúria?", options: ["Diuréticos tiazídicos.", "Bloqueadores dos canais de cálcio.", "Inibidores da enzima conversora de angiotensina (IECA).", "Betabloqueadores."], correctIndex: 2, explanation: "Inibidores da enzima conversora de angiotensina (IECA) ou bloqueadores do receptor de angiotensina (BRA) são a primeira linha em pacientes com DRC e proteinúria, devido aos seus efeitos antiproteinúricos e reno protetores, além do controle pressórico.", category: "Nefrologia" },
  { id: 406, question: "Em um paciente com síndrome nefrótica, qual achado laboratorial é esperado?", options: ["Hematúria macroscópica e hipertensão arterial.", "Proteinúria maciça (>3,5 g/dia), hipoalbuminemia e edema.", "Crescimento de creatinina e ureia acentuado.", "Complemento sérico normal ou elevado."], correctIndex: 1, explanation: "A síndrome nefrótica é caracterizada pela tríade de proteinúria maciça (>3,5 g/dia ou >3,0 g/24h/1.73m²), hipoalbuminemia (<3,0-3,5 g/dL) e edema, frequentemente acompanhada por hiperlipidemia e lipidúria.", category: "Nefrologia" },
  { id: 407, question: "Qual das seguintes condições NÃO é uma causa de proteinúria isolada, ou seja, sem outras alterações significativas no sedimento urinário?", options: ["Proteinúria ortostática.", "Proteinúria funcional (febre, exercício físico).", "Nefropatia membranosa.", "Glomerulonefrite proliferativa difusa."], correctIndex: 3, explanation: "A glomerulonefrite proliferativa difusa geralmente cursa com proteinúria e hematúria, além de sinais de inflamação glomerular. As outras opções podem causar proteinúria sem outras alterações significativas no sedimento urinário, sendo as duas primeiras benignas.", category: "Nefrologia" },
  { id: 408, question: "Qual o principal critério para o diagnóstico precoce da doença renal crônica?", options: ["Presença de edema em membros inferiores.", "Redução da taxa de filtração glomerular estimada (TFGe) abaixo de 60 mL/min/1,73m² por três meses ou mais.", "Níveis elevados de creatinina sérica.", "Anemia persistente e refratária."], correctIndex: 1, explanation: "O diagnóstico de DRC é feito pela redução da TFGe abaixo de 60 mL/min/1,73m² ou pela presença de marcadores de dano renal (proteinúria, hematúria, alterações morfológicas por imagem ou biópsia) por um período superior a 3 meses.", category: "Nefrologia" },
  { id: 409, question: "Considerando a nefrotoxicidade, qual classe de antibióticos requer monitoramento cuidadoso da função renal devido ao seu potencial de causar lesão tubular aguda?", options: ["Penicilinas.", "Cefalosporinas de primeira geração.", "Aminoglicosídeos.", "Tetraciclinas."], correctIndex: 2, explanation: "Aminoglicosídeos são conhecidos por sua nefrotoxicidade, especialmente por causarem necrose tubular aguda (NTA), e seu uso requer monitorização dos níveis séricos e da função renal do paciente.", category: "Nefrologia" },
  { id: 410, question: "Um paciente com insuficiência renal crônica em diálise peritoneal apresenta febre, dor abdominal difusa e efluente peritoneal turvo. Qual a conduta inicial MAIS adequada?", options: ["Suspender a diálise peritoneal e converter para hemodiálise.", "Coletar o efluente para cultura e iniciar antibiótico empírico intraperitoneal.", "Aumentar a concentração de glicose no dialisato para melhorar a ultrafiltração.", "Realizar tomografia computadorizada de abdome para investigar perfuração."], correctIndex: 1, explanation: "Dor abdominal, febre e efluente turvo são sinais clássicos de peritonite na DP. A conduta inicial é coletar o efluente para cultura (diagnóstico) e iniciar antibióticos de amplo espectro via intraperitoneal empírica, cobrindo gram-positivos e gram-negativos.", category: "Nefrologia" },
  { id: 411, question: "Qual a principal causa de glomerulonefrite primária em adultos jovens, frequentemente associada a episódios de hematúria macroscópica recorrente após infecções do trato respiratório superior?", options: ["Glomerulonefrite membranoproliferativa.", "Nefropatia por IgA (Doença de Berger).", "Glomerulonefrite rapidamente progressiva.", "Doença da membrana basal fina."], correctIndex: 1, explanation: "A Nefropatia por IgA (Doença de Berger) é a glomerulonefrite primária mais comum no mundo, classicamente manifestando-se com hematúria macroscópica em surtos, geralmente 24-48 horas após infecções mucosas (respiratórias ou gastrointestinais).", category: "Nefrologia" },
  { id: 412, question: "Qual é um sinal clínico importante que indica sobrecarga de volume em um paciente com doença renal crônica?", options: ["Hipotensão ortostática.", "Taquicardia sinusal.", "Crepitações pulmonares à ausculta e turgência jugular.", "Dor lombar bilateral."], correctIndex: 2, explanation: "Crepitações pulmonares e turgência jugular são sinais diretos de congestão pulmonar e aumento da pressão venosa central, respectivamente, indicando sobrecarga volêmica, comum em pacientes renais com capacidade limitada de excreção de água.", category: "Nefrologia" },
  { id: 413, question: "Qual das seguintes condições é uma complicação metabólica comum e grave da doença renal crônica, que pode ser agravada pelo uso de IECA/BRA?", options: ["Hiponatremia.", "Hipocalemia.", "Hipercalemia.", "Hipomagnesemia."], correctIndex: 2, explanation: "A hipercalemia é uma complicação metabólica comum na DRC devido à diminuição da excreção renal de potássio. O uso de IECA/BRA, embora protetor renal, pode agravar a hipercalemia por inibir a secreção de aldosterona.", category: "Nefrologia" },
  { id: 414, question: "Qual o mecanismo de ação da finerenona, um fármaco recentemente adicionado ao arsenal terapêutico da nefropatia diabética?", options: ["Inibidor seletivo do cotransportador SGLT2.", "Agonista do receptor de GLP-1.", "Antagonista não esteroide do receptor de mineralocorticoide.", "Inibidor da dipeptil peptidase-4 (DPP-4)."], correctIndex: 2, explanation: "A finerenona é um antagonista não esteroide seletivo do receptor de mineralocorticoide, aprovado para o tratamento da doença renal crônica associada ao diabetes tipo 2, agindo na redução da inflamação e fibrose.", category: "Nefrologia" },
  { id: 415, question: "Um paciente de 65 anos é trazido ao pronto-socorro com queixa de cefaleia súbita e intensa, acompanhada de rigidez de nuca e náuseas. No exame físico, apresenta Glasgow 14 e papiledema bilateral. A tomografia de crânio inicial sem contraste não mostra alterações significativas. A próxima conduta diagnóstica mais apropriada seria:", options: ["Iniciar cefalosporina de terceira geração e vancomicina por suspeita de meningite bacteriana.", "Solicitar angiotomografia de crânio para avaliação de aneurismas.", "Realizar punção lombar após a tomografia de crânio normal.", "Administrar analgésicos e observar a evolução do quadro clínico."], correctIndex: 2, explanation: "Cefaleia em trovão (súbita e intensa) com rigidez de nuca e papiledema, mesmo com TC normal, sugere hemorragia subaracnoidea. A punção lombar é essencial nesses casos para detectar xantocromia, confirmando o sangramento.", category: "Neurologia" },
  { id: 416, question: "Um homem de 30 anos apresenta crises convulsivas generalizadas tônico-clônicas desde a adolescência, bem controladas com valproato. Deseja ter filhos e pergunta sobre os riscos do tratamento. A melhor orientação em relação ao valproato é:", options: ["O valproato é o anticonvulsivante mais seguro na gravidez e não requer alterações.", "Considerar a substituição por lamotrigina ou levetiracetam, se possível, devido aos riscos teratogênicos do valproato.", "Aumentar a dose de folato para 5 mg/dia por precaução e manter o valproato.", "Interromper o valproato dois meses antes de tentar engravidar para evitar malformações."], correctIndex: 1, explanation: "O valproato está associado a altas taxas de teratogenicidade, incluindo defeitos do tubo neural. É recomendado considerar a substituição por fármacos mais seguros na gravidez, como lamotrigina ou levetiracetam, em mulheres em idade fértil.", category: "Neurologia" },
  { id: 417, question: "Em relação à doença de Parkinson, qual das seguintes afirmativas está CORRETA?", options: ["É uma doença causada pela degeneração de neurônios produtores de acetilcolina na substância negra.", "O tremor de repouso é o sintoma cardinal mais frequente e normalmente simétrico no início.", "A levodopa é a medicação mais eficaz para o controle dos sintomas motores, mas pode causar discinesias a longo prazo.", "Os sintomas não motores, como depressão e distúrbios do sono, geralmente não aparecem antes dos sintomas motores."], correctIndex: 2, explanation: "A levodopa é o tratamento mais potente para os sintomas motores da doença de Parkinson, mas seu uso prolongado está associado a complicações motoras como discinesias. A degeneração ocorre em neurônios dopaminérgicos, o tremor é geralmente unilateral no início, e sintomas não motores podem preceder os motores.", category: "Neurologia" },
  { id: 418, question: "Uma mulher de 28 anos apresenta paresia súbita do membro inferior esquerdo com alteração da sensibilidade ao toque superficial do joelho para baixo ipsilateralmente. Refere dois episódios semelhantes nos últimos 6 meses, com recuperação completa e duração de algumas semanas. A hipótese diagnóstica mais provável e a primeira investigação a ser solicitada são, respectivamente:", options: ["Mielite transversa; LCR e sorologias para doenças infecciosas.", "Esclerose múltipla; Ressonância Magnética de encéfalo e medula com contraste.", "Neuromielite óptica; Aquaporina-4 e MOG no soro.", "AVC isquêmico; Angiotomografia de vasos cervicais e encefálicos."], correctIndex: 1, explanation: "O quadro de déficits neurológicos multifocais e recorrentes (disseminação no tempo e no espaço), em uma mulher jovem, é altamente sugestivo de esclerose múltipla. A RM do encéfalo e medula é a principal ferramenta diagnóstica.", category: "Neurologia" },
  { id: 419, question: "Qual é o principal mecanismo de ação dos triptanos no tratamento da enxaqueca?", options: ["Bloqueio dos receptores dopaminérgicos centrais.", "Antagonismo dos receptores serotoninérgicos 5-HT1B/1D no sistema trigeminal, levando à vasoconstrição e redução da liberação de neuropeptídeos.", "Inibição da síntese de prostaglandinas.", "Aumento da atividade GABAérgica no córtex cerebral."], correctIndex: 1, explanation: "Os triptanos são agonistas seletivos dos receptores 5-HT1B/1D nas artérias cranianas e terminações nervosas trigeminais. Isso resulta em vasoconstrição das artérias intracranianas dilatadas e inibição da liberação de neuropeptídeos pró-inflamatórios.", category: "Neurologia" },
  { id: 420, question: "Um paciente de 70 anos com fibrilação atrial não valvular em uso de rivaroxabana é admitido com hemiparesia direita e afasia de início há 2 horas. A tomografia de crânio mostra sangramento intraparenquimatoso extenso. Qual é a conduta inicial mais apropriada para reverter o efeito do anticoagulante?", options: ["Administrar vitamina K endovenosa.", "Aplicar sulfato de protamina.", "Administrar complexo protrombínico de 4 fatores (PCC4f).", "Iniciar plasma fresco congelado."], correctIndex: 2, explanation: "Para hemorragias graves associadas a rivaroxabana (um inibidor direto do fator Xa), o PCC4f é o agente de reversão preferencial, pois repõe os fatores de coagulação inativados. Vitamina K é para antagonistas da vitamina K, e protamina para heparina.", category: "Neurologia" },
  { id: 421, question: "Um paciente apresenta fraqueza muscular simétrica e ascendente que evoluiu em 5 dias, com arreflexia e ausência de distúrbios sensitivos proeminentes. Em seu histórico, refere um quadro gastrointestinal autolimitado 2 semanas antes. O diagnóstico mais provável é:", options: ["Miastenia gravis", "Esclerose lateral amiotrófica (ELA)", "Síndrome de Guillain-Barré (SGB)", "Botulismo"], correctIndex: 2, explanation: "A Síndrome de Guillain-Barré tipicamente se apresenta com fraqueza muscular ascendente e arreflexia, muitas vezes precedida por uma infecção. A ausência de distúrbios sensitivos proeminentes não descarta, pois existem variantes. As outras condições têm apresentações distintas.", category: "Neurologia" },
  { id: 422, question: "Qual dos seguintes achados no líquor cefalorraquidiano (LCR) é mais sugestivo da Síndrome de Guillain-Barré?", options: ["Pleocitose neutrofílica.", "Xantocromia.", "Dissociação albuminocitológica (aumento de proteínas com contagem celular normal ou discretamente aumentada).", "Hipoglicorraquia."], correctIndex: 2, explanation: "A dissociação albuminocitológica, caracterizada pelo aumento significativo da concentração de proteínas no LCR com uma contagem de células normais ou discretamente elevada, é um achado clássico da Síndrome de Guillain-Barré, refletindo a inflamação e desmielinização das raízes nervosas.", category: "Neurologia" },
  { id: 423, question: "Um homem de 55 anos, tabagista e hipertenso, procura atendimento por apresentar oclusão súbita da artéria central da retina, causando perda visual unilateral. Após investigação, é diagnosticado com acidente isquêmico transitório (AIT) ocular, ou amaurose fugaz. Qual a conduta preventiva mais importante a longo prazo para este paciente?", options: ["Iniciar tratamento com prednisona oral.", "Indicar laserterapia retiniana profilática.", "Otimizar controle de fatores de risco cardiovascular e iniciar antiagregação plaquetária com ácido acetilsalicílico.", "Considerar endarterectomia de carótida independentemente do grau de estenose."], correctIndex: 2, explanation: "A amaurose fugaz é um tipo de AIT. Pacientes com AIT têm alto risco de AVC isquêmico. A prevenção secundária envolve otimização do controle de fatores de risco cardiovascular (HAS, tabagismo) e antiagregação plaquetária, geralmente com ácido acetilsalicílico.", category: "Neurologia" },
  { id: 424, question: "Em pacientes com cefaleia em salvas, qual tratamento de primeira linha é recomendado para abortar uma crise aguda?", options: ["Oxigênio suplementar a 100% por máscara não-reinalante e sumatriptano subcutâneo.", "Uso de AINEs em altas doses.", "Diazepínicos intravenosos.", "Corticosteroides orais."], correctIndex: 0, explanation: "O oxigênio a 100% por máscara e o sumatriptano subcutâneo são os tratamentos agudos de primeira linha mais eficazes para abortar uma crise de cefaleia em salvas. Os demais não são recomendados para a crise aguda.", category: "Neurologia" },
  { id: 425, question: "Qual das seguintes características é a mais indicativa de uma crise epiléptica focal com alteração da consciência?", options: ["Apresentação como movimentos tônico-clônicos bilaterais e imediata.", "Automatismos orais ou manuais, como mastigação ou apalpar roupas, e amnésia pós-ictal do evento.", "Perda súbita do tônus muscular com queda ao solo.", "Breves períodos de 'desligamento' com olhar fixo, duração de segundos, sem período pós-ictal."], correctIndex: 1, explanation: "Crises focais com alteração da consciência (anteriormente complexas parciais) frequentemente envolvem automatismos (movimentos repetitivos e sem propósito) e são seguidas por confusão mental (amnésia pós-ictal) do evento.", category: "Neurologia" },
  { id: 426, question: "Após um traumatismo cranioencefálico (TCE) em adulto, qual das seguintes indicações de tomografia de crânio é considerada de ALTO risco segundo as diretrizes?", options: ["Cefaleia leve e isolada.", "Vômito único.", "Sinais de fratura de base de crânio (otorragia, rinoliquia, sinal de Battle).", "Amnésia pós-traumática em paciente com Glasgow 15."], correctIndex: 2, explanation: "Sinais de fratura de base de crânio indicam um potencial de lesão intracraniana significativa e são considerados de alto risco, exigindo tomografia de crânio. Os outros achados, embora possam justificar TC em algumas diretrizes, geralmente são de risco intermediário ou baixo.", category: "Neurologia" },
  { id: 427, question: "A terapêutica de primeira linha para tratamento de status epilepticus na fase inicial (0-5 minutos) no ambiente pré-hospitalar ou hospitalar é:", options: ["Fenitoína intravenosa.", "Fenobarbital intravenoso.", "Benzodiazepínico intravenoso (ex: lorazepam, diazepam ou midazolam).", "Levetiracetam intravenoso."], correctIndex: 2, explanation: "Benzodiazepínicos são os fármacos de escolha na fase inicial do status epilepticus devido à sua rápida ação para cessar a convulsão. Lorazepam IV é preferível em ambiente hospitalar, enquanto diazepam retal ou midazolam IM/intranasal são opções pré-hospitalares.", category: "Neurologia" },
  { id: 428, question: "Qual a principal causa mais comum de hidrocefalia comunicante em adultos?", options: ["Estenose do aqueduto de Sylvius.", "Tumor obstrutivo intraventricular.", "Hemorragia subaracnoidea ou meningite crônica.", "Malformação de Chiari tipo I."], correctIndex: 2, explanation: "A hidrocefalia comunicante (ou não obstrutiva) em adultos é frequentemente causada por um comprometimento da reabsorção do LCR nas granulações aracnoides, que pode ocorrer após hemorragia subaracnoidea, meningite ou processos inflamatórios.", category: "Neurologia" },
  { id: 429, question: "Um paciente de 45 anos é diagnosticado com esclerose lateral amiotrófica (ELA). Qual o único fármaco atualmente aprovado no Brasil que comprovadamente retarda a progressão da doença?", options: ["Piridostigmina.", "Metilprednisolona.", "Riluzol.", "Interferon beta."], correctIndex: 2, explanation: "O riluzol é o único fármaco que comprovadamente retarda a progressão da ELA, aumentando a sobrevida dos pacientes em alguns meses, através da redução da excitotoxicidade glutamatérgica. Os outros fármacos não têm essa indicação na ELA.", category: "Neurologia" },
  { id: 430, question: "Em pacientes com miastenia gravis, qual a principal indicação para timectomia?", options: ["Todos os pacientes com miastenia gravis generalizada.", "Pacientes com miastenia ocular pura.", "Presença de timoma, independentemente da gravidade da miastenia.", "Pacientes jovens com miastenia gravis generalizada e anticorpos anti-receptor de acetilcolina positivos, mesmo sem timoma."], correctIndex: 3, explanation: "A timectomia é indicada, principalmente, para pacientes jovens (<60 anos) com miastenia gravis generalizada e anticorpos anti-receptor de acetilcolina positivos, mesmo na ausência de timoma, pois melhora os resultados a longo prazo. É mandatória em caso de timoma.", category: "Neurologia" },
  { id: 431, question: "Qual das seguintes é uma característica típica da cefaleia tensional crônica?", options: ["Pulsátil, unilateral e associada a aura visual.", "Dor em aperto ou pressão, bilateral, de intensidade leve a moderada, sem náuseas ou vômitos.", "Dor periorbital intensa, lacrimejamento e síndrome de Horner ipsilateral.", "Início súbito, dor forte e rigidez de nuca."], correctIndex: 1, explanation: "A cefaleia tensional típica é caracterizada por dor em aperto ou pressão, bilateral, de intensidade leve a moderada, que não é agravada por atividades físicas de rotina e geralmente não é acompanhada por náuseas ou vômitos.", category: "Neurologia" },
  { id: 432, question: "Um paciente de 75 anos é avaliado com história de quedas frequentes, dificuldade para iniciar a marcha ('marcha magnética'), incontinência urinária e piora da memória nos últimos anos. O exame de imagem revela ventrículos dilatados sem atrofia cortical significativa. O diagnóstico mais provável é:", options: ["Doença de Alzheimer.", "Hidrocefalia de pressão normal.", "Demência com corpos de Lewy.", "Doença de Parkinson avançada."], correctIndex: 1, explanation: "A tríade clássica de hidrocefalia de pressão normal ('demência, apraxia da marcha e incontinência urinária') com ventrículos dilatados e ausência de atrofia cortical é altamente sugestiva desta condição, que é potencialmente reversível com derivação ventricular.", category: "Neurologia" },
  { id: 433, question: "Qual é a principal indicação para o uso de corticosteroides no tratamento agudo de uma crise de esclerose múltipla?", options: ["Prevenção de futuras crises.", "Redução da frequência de surtos.", "Encurtamento da duração e aceleração da recuperação de um surto agudo, especialmente se incapacitante.", "Remissão completa da doença."], correctIndex: 2, explanation: "Corticosteroides em altas doses (como metilprednisolona IV) são utilizados no tratamento agudo dos surtos de esclerose múltipla para encurtar a duração e acelerar a recuperação funcional, principalmente em crises moderadas a graves. Não previnem futuras crises nem curam a doença.", category: "Neurologia" },
  { id: 434, question: "Em um paciente com suspeita de acidente vascular cerebral (AVC) isquêmico, qual o principal objetivo da tomografia de crânio sem contraste inicial?", options: ["Identificar a área de infarto isquêmico.", "Avaliar o grau de reperfusão tecidual.", "Excluir hemorragia intracraniana.", "Determinar o potencial de penumbra isquêmica."], correctIndex: 2, explanation: "O principal objetivo da TC de crânio sem contraste na emergência do AVC é diferenciar AVC isquêmico de hemorrágico. A exclusão de hemorragia é crucial para determinar a elegibilidade para trombólise, que seria contraindicada em caso de sangramento.", category: "Neurologia" },
  { id: 435, question: "Um paciente apresenta diplopia, ptose palpebral e fraqueza da musculatura bulbar (disfagia, disartria) que piora com o esforço e melhora com o repouso. Qual exame é mais indicado para confirmar a suspeita de Miastenia Gravis?", options: ["Eletroneuromiografia com estudo de condução nervosa.", "Dosagem de anticorpos anti-receptor de acetilcolina.", "Biópsia muscular.", "Ressonância magnética de encéfalo."], correctIndex: 1, explanation: "A Miastenia Gravis é uma doença autoimune neuromuscular caracterizada por fraqueza flutuante que piora com o esforço. A dosagem de anticorpos anti-receptor de acetilcolina é o exame mais específico para o diagnóstico, sendo positivo na maioria dos pacientes.", category: "Neurologia" },
  { id: 436, question: "Um paciente de 60 anos, sem comorbidades conhecidas, apresenta uma crise convulsiva tônico-clônica generalizada pela primeira vez na vida. Qual a investigação inicial mais importante após a estabilização do paciente?", options: ["Iniciar tratamento anticonvulsivante profilático.", "Solicitar eletroencefalograma (EEG) e ressonância magnética (RM) de encéfalo.", "Realizar dosagem sérica de fármacos e tóxicos.", "Encaminhar para avaliação psiquiátrica."], correctIndex: 1, explanation: "Em um adulto com crise epiléptica de primeira vez, é fundamental investigar a causa. O EEG pode identificar atividade epileptiforme, e a RM de encéfalo é essencial para procurar lesões estruturais (tumor, AVC, malformação) que possam ser a causa subjacente.", category: "Neurologia" },
  { id: 437, question: "Qual das seguintes é uma causa comum de neuropatia periférica crônica que pode ser prevenida com um bom controle glicêmico?", options: ["Síndrome do túnel do carpo.", "Neuropatia alcoólica.", "Neuropatia diabética.", "Neuropatia pós-herpética."], correctIndex: 2, explanation: "A neuropatia diabética é uma complicação comum do diabetes mellitus, sendo a glicemia cronicamente elevada um dos principais fatores de risco. Um bom controle glicêmico é fundamental para prevenir ou retardar sua progressão.", category: "Neurologia" },
  { id: 438, question: "A síndrome de Horner é caracterizada por qual tríade clássica de sintomas?", options: ["Ptose, miose e anidrose ipsilateral.", "Diplopia, disartria e disfagia.", "Hemiparesia, afasia e hemianopsia.", "Vertigem, náuseas e nistagmo."], correctIndex: 0, explanation: "A síndrome de Horner resulta de uma lesão na via simpática ocular e é classicamente caracterizada pela tríade de ptose palpebral (queda da pálpebra), miose (pupila contraída) e anidrose (ausência de suor) no lado ipsilateral à lesão.", category: "Neurologia" },
  { id: 439, question: "Um paciente de 45 anos, sexo masculino, procura atendimento com queixa de poliúria, polidipsia e perda ponderal de 5 kg nos últimos 2 meses. Nega comorbidades. Exames laboratoriais mostram glicemia de jejum de 220 mg/dL e HbA1c de 9,5%. Qual a conduta inicial mais apropriada?", options: ["Iniciar metformina e orientar mudanças no estilo de vida.", "Iniciar insulina NPH 2x/dia e orientar monitorização da glicemia.", "Solicitar teste de tolerância à glicose oral para confirmar o diagnóstico.", "Encaminhar para endocrinologista para investigação de diabetes secundário."], correctIndex: 0, explanation: "A elevação da glicemia de jejum e HbA1c são diagnósticas de Diabetes Mellitus tipo 2. A metformina é a terapia de primeira linha, associada a mudanças no estilo de vida, conforme as diretrizes do Ministério da Saúde e da Sociedade Brasileira de Diabetes.", category: "Endocrinologia" },
  { id: 440, question: "Em relação à tireoidite de Hashimoto, qual das seguintes afirmativas está incorreta?", options: ["É a causa mais comum de hipotireoidismo primário em áreas onde a deficiência de iodo é rara.", "Apresenta frequentemente anticorpos antitireoperoxidase (anti-TPO) e antitireoglobulina (anti-Tg) positivos.", "O tratamento geralmente se baseia na reposição hormonal com levotiroxina.", "É caracterizada por uma tireoide indolor, pequenas dimensões e consistência amolecida ao toque."], correctIndex: 3, explanation: "A tireoidite de Hashimoto classicamente apresenta uma tireoide com consistência firme, muitas vezes aumentada difusamente, e geralmente indolor. A característica de 'pequenas dimensões e consistência amolecida' não se adequa à apresentação típica.", category: "Endocrinologia" },
  { id: 441, question: "Paciente de 30 anos, sexo feminino, refere galactorreia e irregularidade menstrual (oligomenorreia). Nega uso de medicamentos. Exames laboratoriais mostram prolactina sérica de 150 ng/mL (valor de referência < 25 ng/mL) e TSH normal. Qual o próximo passo diagnóstico mais adequado?", options: ["Iniciar tratamento com cabergolina empiricamente.", "Solicitar ressonância magnética da sela túrcica com contraste.", "Realizar dosagem de hCG para excluir gravidez e repetir a prolactina.", "Solicitar campos visuais e encaminhar para neurocirurgia."], correctIndex: 1, explanation: "Com níveis de prolactina significativamente elevados e sintomas clínicos, a investigação de um prolactinoma por meio de ressonância magnética da sela túrcica é o próximo passo. A dosagem de hCG é importante, mas os níveis apresentados são altamente sugestivos de hiperprolactinemia patológica.", category: "Endocrinologia" },
  { id: 442, question: "Um paciente com suspeita de Síndrome de Cushing apresenta cortisol livre urinário de 24h elevado em duas ocasiões. Qual o teste mais adequado para diferenciar a doença de Cushing (adenoma hipofisário) da Síndrome de Cushing ectópica?", options: ["Teste de supressão com dexametasona em baixa dose.", "Teste de supressão com dexametasona em alta dose.", "Teste de estímulo com CRH (hormônio liberador de corticotrofina).", "Dosagem de ACTH plasmático."], correctIndex: 1, explanation: "Após a confirmação do hipercortisolismo, o teste de supressão com dexametasona em alta dose é utilizado para diferenciar a doença de Cushing (geralmente suprime) de outras causas de Síndrome de Cushing, como a ectópica (geralmente não suprime).", category: "Endocrinologia" },
  { id: 443, question: "Em relação ao tratamento do hipotireoidismo congênito, qual a conduta terapêutica de primeira escolha?", options: ["Iodo radioativo (131I).", "Cirurgia (tireoidectomia).", "Levotiroxina.", "Metimazol."], correctIndex: 2, explanation: "O tratamento do hipotireoidismo congênito é a reposição hormonal com levotiroxina, iniciada o mais cedo possível para prevenir deficits neurocognitivos. Trata-se de uma urgência endocrinológica.", category: "Endocrinologia" },
  { id: 444, question: "Qual das seguintes condições NÃO é uma causa comum de hipoglicemia em pacientes não diabéticos?", options: ["Insulinoma.", "Uso de sulfonilureias em pacientes com diabetes tipo 2.", "Hepatopatia grave.", "Insuficiência adrenal."], correctIndex: 1, explanation: "O uso de sulfonilureias em pacientes com diabetes tipo 2 é uma causa comum de hipoglicemia nestes pacientes, mas não em indivíduos não diabéticos. As outras opções são causas de hipoglicemia endógena ou secundária em não diabéticos.", category: "Endocrinologia" },
  { id: 445, question: "Um paciente de 60 anos, masculino, com história de diabetes mellitus tipo 2 em uso de metformina, apresenta glicemia de jejum persistentemente acima de 180 mg/dL e HbA1c de 10%. Qual a próxima droga oral a ser associada, considerando que o paciente apresenta doença renal crônica (TFG 45 mL/min/1.73m²)?", options: ["Glibenclamida.", "Sitagliptina.", "Empagliflozina.", "Pioglitazona."], correctIndex: 2, explanation: "Em pacientes com doença renal crônica e diabetes tipo 2, as gliflozinas (inibidores SGLT2), como a empagliflozina, são recomendadas por seus benefícios cardiovasculares e renais, além do controle glicêmico, conforme as diretrizes atuais, ainda que com ajuste de dose ou contraindicação em TFGs muito baixas. Glibenclamida deve ser evitada em DRC. Sitagliptina também pode ser usada com ajuste posológico, mas a empagliflozina tem evidência superior para proteção renal.", category: "Endocrinologia" },
  { id: 446, question: "Qual é a principal manifestação clínica da deficiência de hormônio do crescimento (GH) em crianças?", options: ["Aumento da circunferência abdominal e hirsutismo.", "Retardo do crescimento e baixa estatura.", "Poliúria e polidipsia.", "Puberdade precoce."], correctIndex: 1, explanation: "A principal manifestação da deficiência de GH em crianças é o retardo do crescimento e a baixa estatura desproporcional à idade, devido ao papel do GH na promoção do crescimento linear.", category: "Endocrinologia" },
  { id: 447, question: "No manejo da crise tireotóxica, qual das seguintes medidas NÃO é considerada uma conduta inicial essencial?", options: ["Administração de propiltiouracil ou metimazol.", "Uso de iodeto de potássio após o tireostático.", "Utilização de betabloqueadores para controle sintomático.", "Administração de hormônios tireoidianos para suprir a demanda."], correctIndex: 3, explanation: "A crise tireotóxica é um estado de hipertiroidismo grave, e a administração de hormônios tireoidianos seria contraindicada, podendo agravar o quadro. As outras medidas visam reduzir a síntese e liberação hormonal e controlar os sintomas.", category: "Endocrinologia" },
  { id: 448, question: "Qual o principal critério laboratorial para o diagnóstico de diabetes insipidus central?", options: ["Níveis elevados de sódio sérico e osmolaridade plasmática elevada, com osmolaridade urinária baixa após restrição hídrica.", "Níveis baixos de sódio sérico e osmolaridade plasmática baixa, com osmolaridade urinária elevada.", "Glicemia de jejum elevada e HbA1c acima de 6,5%.", "TSH baixo e T4 livre elevado."], correctIndex: 0, explanation: "O diabetes insipidus central é caracterizado pela incapacidade de se concentrar a urina devido à deficiência de ADH. Isso leva à hipernatremia, plasma hiperosmolar e urina hipotônica, especialmente após restrição hídrica, que o teste de privação hídrica elucida.", category: "Endocrinologia" },
  { id: 449, question: "A síndrome de secreção inapropriada de hormônio antidiurético (SIADH) é caracterizada por qual dos seguintes achados laboratoriais?", options: ["Hipernatremia, hipovolemia, osmolaridade urinária baixa.", "Hiponatremia, euvolemia, osmolaridade urinária elevada.", "Hipernatremia, hipervolemia, osmolaridade urinária elevada.", "Hiponatremia, hipovolemia, osmolaridade urinária baixa."], correctIndex: 1, explanation: "A SIADH leva à hiponatremia dilucional devido à retenção excessiva de água. O paciente geralmente é euvolêmico e, apesar da hiponatremia, a osmolaridade urinária é inapropriadamente alta (>100 mOsm/kg), indicando que os rins estão tentando concentrar a urina.", category: "Endocrinologia" },
  { id: 450, question: "Qual das seguintes afirmativas sobre o feocromocitoma está correta?", options: ["É um tumor da medula adrenal que produz excesso de aldosterona.", "Apresenta como sintoma cardeal a hipertensão postural.", "O diagnóstico é confirmado pela dosagem de metanefrinas plasmáticas ou urinárias.", "O tratamento definitivo é clínico com bloqueadores de canais de cálcio antes de cirurgia."], correctIndex: 2, explanation: "Feocromocitomas são tumores produtores de catecolaminas. O diagnóstico é estabelecido pela dosagem de metanefrinas (metanefrina e normetanefrina) livres plasmáticas ou urinárias. A preparação cirúrgica exige bloqueio alfa-adrenérgico, seguido por beta-bloqueio, se necessário.", category: "Endocrinologia" },
  { id: 451, question: "Um paciente de 55 anos, sexo masculino, com dislipidemia e história familiar de doença cardiovascular precoce, apresenta LDL-colesterol de 190 mg/dL. Qual a estratégia terapêutica de primeira linha para redução do LDL-colesterol neste paciente, de acordo com as diretrizes da SBC?", options: ["Fibrato.", "Ezetimiba.", "Estatinas de alta potência.", "Niacina."], correctIndex: 2, explanation: "Para redução significativa de LDL-colesterol em pacientes com alto risco cardiovascular, as estatinas de alta potência (como rosuvastatina ou atorvastatina em altas doses) são a terapia de primeira linha, conforme as diretrizes brasileiras e internacionais.", category: "Endocrinologia" },
  { id: 452, question: "Qual hormônio é o principal responsável pela regulação do cálcio sérico, aumentando sua absorção intestinal e reabsorção renal?", options: ["Calcitonina.", "Vitamina D (calcitriol).", "Hormônio paratireoidiano (PTH).", "Fosfato."], correctIndex: 2, explanation: "O PTH é o principal regulador da calcemia. Ele aumenta a reabsorção de cálcio nos rins, a reabsorção óssea e indiretamente aumenta a absorção intestinal de cálcio via ativação da vitamina D (calcitriol).", category: "Endocrinologia" },
  { id: 453, question: "Em relação à diabetes gestacional, qual das seguintes afirmativas está correta?", options: ["É diagnosticada em qualquer estágio da gravidez por meio da glicemia de jejum alterada.", "Mulheres com diabetes gestacional têm risco aumentado de desenvolver diabetes mellitus tipo 2 após a gestação.", "O tratamento inicial sempre envolve o uso de insulina.", "O rastreamento é feito universalmente com glicemia de jejum na primeira consulta pré-natal, sem necessidade de outros testes."], correctIndex: 1, explanation: "Mulheres com história de diabetes gestacional apresentam um risco significativamente elevado de desenvolver diabetes mellitus tipo 2 em até 5-10 anos após o parto. A vigilância pós-parto é fundamental.", category: "Endocrinologia" },
  { id: 454, question: "Qual é a principal indicação para o uso de iodo radioativo (131I) no tratamento do hipertireoidismo?", options: ["Gravidez e lactação.", "Pacientes com bócio volumoso e sintomas compressivos.", "Doença de Graves refratária a medicamentos antitireoidianos ou em pacientes com contraindicação cirúrgica.", "Nódulos tireoidianos suspeitos de malignidade."], correctIndex: 2, explanation: "O iodo radioativo é uma opção eficaz para o tratamento de hipertireoidismo, especialmente na Doença de Graves, quando há falha no tratamento clínico ou cirúrgico, ou quando a cirurgia é contraindicada. É contraindicado na gravidez e lactação.", category: "Endocrinologia" },
  { id: 455, question: "Paciente de 40 anos, sexo feminino, apresenta elevação de TSH (12 µIU/mL, VR: 0,4-4,0) e T4 livre normal. Refere fadiga e discreto ganho ponderal. Qual o diagnóstico e a conduta mais provável?", options: ["Hipotiroidismo franco; iniciar levotiroxina.", "Hipotiroidismo subclínico; iniciar levotiroxina.", "Hipotiroidismo subclínico; monitorar e considerar levotiroxina se sintomas piorarem ou TSH subir mais.", "Hipertiroidismo subclínico; investigar causa."], correctIndex: 2, explanation: "O quadro de TSH elevado com T4 livre normal configura hipotireoidismo subclínico. O tratamento com levotiroxina é individualizado, mas em casos como este, com TSH entre 5-10µIU/mL, pode-se optar por observação e monitoramento, especialmente se os sintomas forem brandos e inespecíficos, embora TSH >10 IU/mL geralmente indique tratamento.", category: "Endocrinologia" },
  { id: 456, question: "Qual das seguintes estratégias é a MAIS importante para prevenir a cetoacidose diabética em pacientes com diabetes mellitus tipo 1?", options: ["Monitorização regular da glicemia e ajuste adequado da dose de insulina.", "Restrição dietética rigorosa de carboidratos.", "Uso empírico de metformina, mesmo em DM tipo 1.", "Aumento da ingestão de líquidos apenas quando os sintomas de desidratação forem evidentes."], correctIndex: 0, explanation: "A cetoacidose diabética (CAD) resulta da deficiência severa de insulina. A monitorização adequada da glicemia e o ajuste preciso da dose de insulina, juntamente com a educação para o manejo em intercorrências, são cruciais para evitar a CAD em pacientes com DM1.", category: "Endocrinologia" },
  { id: 457, question: "Um paciente com diagnóstico de acromegalia após confirmação laboratorial e por imagem. Qual é a principal terapia de primeira linha para essa condição?", options: ["Radioterapia estereotáxica.", "Agonistas dopaminérgicos (ex: cabergolina).", "Análogos da somatostatina (ex: octreotida).", "Cirurgia transesfenoidal."], correctIndex: 3, explanation: "A cirurgia transesfenoidal é a terapia de primeira linha e mais eficaz para a acromegalia, visando a ressecção do adenoma hipofisário produtor de GH. As outras opções são terapias adjuvantes ou para casos específicos.", category: "Endocrinologia" },
  { id: 458, question: "Qual é o principal mecanismo de ação dos inibidores da SGLT2 (glicoflozin)?", options: ["Aumento da secreção de insulina pelas células beta do pâncreas.", "Redução da produção hepática de glicose.", "Aumento da excreção de glicose pela urina.", "Aumento da sensibilidade à insulina nos tecidos periféricos."], correctIndex: 2, explanation: "Os inibidores da SGLT2 atuam nos túbulos renais, bloqueando a reabsorção de glicose e promovendo a glicosúria, ou seja, aumentando a excreção de glicose pela urina, independentemente da secreção de insulina.", category: "Endocrinologia" },
  { id: 459, question: "Um paciente de 65 anos, hipertenso e diabético tipo 2, apresenta-se com dor torácica retroesternal irradiada para o membro superior esquerdo, sudorese fria e dispneia há 30 minutos. O eletrocardiograma (ECG) inicial mostra supradesnivelamento do segmento ST em V1-V4. Qual a conduta inicial mais adequada diante deste quadro?", options: ["Início de oxigenoterapia, ácido acetilsalicílico (AAS), nitrato sublingual e encaminhamento para angioplastia primária.", "Administração de trombolítico endovenoso e posterior encaminhamento para estudo hemodinâmico.", "AAS, nitrato sublingual e observação em unidade de emergência para nova avaliação em 6 horas.", "Morfina intravenosa para controle da dor e solicitação de troponinas cardíacas ultrassensíveis."], correctIndex: 0, explanation: "O quadro é compatível com Síndrome Coronariana Aguda com Supradesnivelamento do Segmento ST (SCASST). A conduta inicial envolve medidas de suporte (oxigenoterapia se SpO2 < 90%), AAS, nitratos (se não houver contraindicação) e a principal terapia de reperfusão, que, idealmente, é a angioplastia primária em centros com disponibilidade.", category: "Clínica Médica" },
  { id: 460, question: "Qual das seguintes alterações laboratoriais é esperada em um paciente com Doença de Addison (insuficiência adrenal primária) descompensada?", options: ["Hiponatremia, hipercalemia e hipoglicemia.", "Hipernatremia, hipocalemia e hiperglicemia.", "Hiponatremia, hipocalemia e hiperglicemia.", "Hipernatremia, hipercalemia e hipoglicemia."], correctIndex: 0, explanation: "Na Doença de Addison, há deficiência de cortisol e aldosterona. A deficiência de aldosterona leva à perda de sódio e retenção de potássio (hiponatremia e hipercalemia), enquanto a deficiência de cortisol pode causar hipoglicemia.", category: "Clínica Médica" },
  { id: 461, question: "Conforme as diretrizes atuais, qual regime terapêutico é o mais indicado para erradicação de Helicobacter pylori em pacientes com dispepsia funcional que falharam em um esquema de primeira linha com inibidor de bomba de prótons (IBP), amoxicilina e claritromicina?", options: ["Esquema quádruplo com bismuto (IBP, bismuto, tetraciclina, metronidazol).", "Esquema triplo com levofloxacino (IBP, amoxicilina, levofloxacino).", "Aumento da dose do IBP e prolongamento do esquema prévio para 14 dias.", "Substituição da claritromicina por azitromicina no esquema original."], correctIndex: 0, explanation: "Para falha de tratamento de primeira linha que incluiu claritromicina, um esquema quádruplo com bismuto ou um esquema quádruplo concomitante sem bismuto são as principais opções recomendadas, devido à alta taxa de resistência à claritromicina.", category: "Clínica Médica" },
  { id: 462, question: "Um homem de 40 anos é diagnosticado com hipertensão arterial estágio 2 (Pressão Arterial ≥ 140/90 mmHg) em múltiplas aferições. Ele possui história familiar de doença cardiovascular precoce, mas sem outras comorbidades ou lesão em órgão-alvo documentada. Qual a conduta farmacológica inicial recomendada, considerando as diretrizes brasileiras?", options: ["Monoterapia com um inibidor da enzima conversora de angiotensina (IECA) ou bloqueador do receptor de angiotensina (BRA).", "Terapia combinada com dois fármacos anti-hipertensivos, preferencialmente um IECA/BRA associado a um bloqueador dos canais de cálcio ou diurético tiazídico.", "Início com um betabloqueador e titulação da dose até o controle da pressão arterial.", "Início com diurético tiazídico e reavaliação em 3 meses para possível adição de um segundo agente."], correctIndex: 1, explanation: "De acordo com as diretrizes brasileiras e internacionais, pacientes com hipertensão estágio 2 geralmente se beneficiam do início da terapia com dois diferentes agentes anti-hipertensivos. A combinação mais comum é um IECA/BRA com um bloqueador de canal de cálcio ou um diurético tiazídico.", category: "Clínica Médica" },
  { id: 463, question: "Qual é o principal mecanismo de ação dos análogos de GLP-1 (agonistas do receptor de glucagon-like peptide-1), como a semaglutida, no tratamento do diabetes mellitus tipo 2?", options: ["Aumento da secreção de insulina dependente de glicose, supressão da secreção de glucagon e retardo do esvaziamento gástrico.", "Aumento da sensibilidade dos tecidos periféricos à insulina e redução da produção hepática de glicose.", "Inibição da reabsorção de glicose nos túbulos renais.", "Aumento da secreção de insulina independente de glicose e inibição da gliconeogênese."], correctIndex: 0, explanation: "Os agonistas do receptor de GLP-1 mimetizam o efeito das incretinas, resultando em secreção de insulina dependente de glicose, supressão do glucagon pós-prandial e retardo do esvaziamento gástrico, contribuindo para o controle glicêmico e, muitas vezes, perda de peso.", category: "Clínica Médica" },
  { id: 464, question: "Um paciente de 55 anos, etilista social, procura o pronto-socorro com queixa de dor abdominal intensa na região epigástrica, irradiação para dorso, associada a náuseas e vômitos. A dor iniciou há 6 horas. Ao exame físico, apresenta-se taquicárdico, hipotenso, abdome distendido e doloroso à palpação profunda em epigástrio, sem sinais de peritonismo. Amilase e lipase séricas elevadas. Qual a complicação mais comum a ser monitorada neste paciente nas primeiras 24-48 horas?", options: ["Pseudocisto pancreático", "Coleção líquida peripancreática aguda", "Insuficiência orgânica sistêmica", "Trombose de veia esplênica"], correctIndex: 2, explanation: "A complicação mais comum nas primeiras 24-48 horas da pancreatite aguda grave é a insuficiência orgânica sistêmica, como a insuficiência respiratória, renal ou choque, devido à resposta inflamatória sistêmica exacerbada.", category: "Gastroenterologia" },
  { id: 465, question: "Com relação à doença do refluxo gastroesofágico (DRGE), qual das seguintes afirmações sobre o tratamento é correta?", options: ["A terapia de manutenção com inibidores de bomba de prótons (IBP) deve ser evitada em todos os casos devido aos riscos a longo prazo.", "Em pacientes com sintomas típicos e resposta favorável ao IBP, a endoscopia digestiva alta não é rotineiramente indicada no diagnóstico inicial.", "A fundoplicatura cirúrgica é o tratamento de primeira linha para a DRGE em pacientes com esofagite erosiva grave.", "Antagonistas de receptores H2 são mais eficazes que IBP na cicatrização da esofagite erosiva."], correctIndex: 1, explanation: "Em pacientes com sintomas típicos de DRGE que respondem bem à terapia empírica com IBP, a endoscopia digestiva alta geralmente não é necessária para o diagnóstico inicial, sendo reservada para casos de sintomas de alarme ou refratariedade.", category: "Gastroenterologia" },
  { id: 466, question: "Uma paciente de 30 anos, sem comorbidades, refere episódios recorrentes de dor abdominal difusa, tipo cólica, associada a inchaço e alterações do hábito intestinal, alternando diarreia e constipação, há cerca de 1 ano. Os sintomas pioram em períodos de estresse. Exames laboratoriais e colonoscopia prévia foram normais. Qual o diagnóstico mais provável?", options: ["Doença de Crohn", "Colite ulcerativa", "Síndrome do intestino irritável", "Doença celíaca"], correctIndex: 2, explanation: "O quadro clínico de dor abdominal, alteração do hábito intestinal (diarreia e constipação alternadas) e inchaço, na ausência de achados estruturais ou inflamatórios, é altamente sugestivo de Síndrome do Intestino Irritável.", category: "Gastroenterologia" },
  { id: 467, question: "Qual das seguintes condições NÃO é uma indicação para cirurgia bariátrica?", options: ["Índice de Massa Corporal (IMC) ≥ 40 kg/m².", "IMC entre 35 e 39,9 kg/m² com comorbidades relacionadas à obesidade.", "IMC entre 30 e 34,9 kg/m² com diabetes tipo 2 de difícil controle, apesar de tratamento clínico otimizado.", "IMC de 28 kg/m² com esteatose hepática não alcoólica avançada."], correctIndex: 3, explanation: "As indicações para cirurgia bariátrica incluem IMC ≥ 40 kg/m², IMC 35-39,9 kg/m² com comorbidades e, em casos específicos, IMC 30-34,9 kg/m² com diabetes tipo 2 mal controlado. Um IMC de 28 kg/m² não atende aos critérios atuais, mesmo com comorbidades.", category: "Gastroenterologia" },
  { id: 468, question: "Um paciente de 60 anos, com história de cirrose hepática por hepatite C, apresenta-se com ascite volumosa. Qual das seguintes medidas é mais apropriada para alívio sintomático da ascite refratária?", options: ["Aumento da dose de diuréticos até a dose máxima tolerada.", "Paracentese de grande volume.", "Transplante hepático como primeira linha de tratamento.", "Administração de albumina intravenosa em monoterapia."], correctIndex: 1, explanation: "Para ascite refratária, a paracentese de grande volume é o tratamento de escolha para alívio sintomático. A paracentese deve ser acompanhada de reposição de albumina para prevenir disfunção circulatória pós-paracentese.", category: "Gastroenterologia" },
  { id: 469, question: "Um homem de 45 anos, tabagista e etilista, apresenta disfagia progressiva para sólidos, seguida por disfagia para líquidos, perda ponderal e odinofagia. Qual a hipótese diagnóstica mais provável?", options: ["Acalasia", "Esofagite eosinofílica", "Esôfago de Barrett", "Carcinoma epidermoide de esôfago"], correctIndex: 3, explanation: "A disfagia progressiva para sólidos e líquidos, associada a perda ponderal e odinofagia em paciente tabagista e etilista, é altamente sugestiva de carcinoma epidermoide de esôfago.", category: "Gastroenterologia" },
  { id: 470, question: "Qual é o principal fator de risco para o desenvolvimento de carcinoma hepatocelular em pacientes cirróticos?", options: ["Doença hepática gordurosa não alcoólica (DHGNA) sem cirrose documentada.", "Consumo moderado de café.", "Hepatite B ou C crônica.", "Uso crônico de anti-inflamatórios não esteroides (AINEs)."], correctIndex: 2, explanation: "A hepatite B e C crônica são os maiores fatores de risco para o desenvolvimento de cirrose hepática e, consequentemente, para o carcinoma hepatocelular. A vigilância regular é fundamental nesses pacientes.", category: "Gastroenterologia" },
  { id: 471, question: "Um paciente submetido à gastrectomia total para tratamento de câncer gástrico é encaminhado para acompanhamento. Qual vitamina necessita de suplementação parenteral regular para evitar deficiências a longo prazo?", options: ["Vitamina C", "Vitamina B12", "Vitamina D", "Vitamina K"], correctIndex: 1, explanation: "Após gastrectomia total, há uma perda do fator intrínseco, produzido pelas células parietais do estômago, essencial para a absorção da vitamina B12 no íleo terminal. A suplementação parenteral de B12 é, portanto, indispensável.", category: "Gastroenterologia" },
  { id: 472, question: "Qual das seguintes opções CORRETAMENTE descreve a fisiopatologia da úlcera duodenal em comparação com a úlcera gástrica?", options: ["Úlceras duodenais estão mais frequentemente associadas à hipossecreção ácida.", "A infecção por Helicobacter pylori é um fator etiológico menos comum em úlceras duodenais do que em úlceras gástricas.", "Úlceras duodenais geralmente ocorrem em um contexto de hipersecreção ácida e estão frequentemente associadas à infecção por Helicobacter pylori.", "O uso de anti-inflamatórios não esteroides (AINEs) é o fator etiológico predominante para úlceras duodenais."], correctIndex: 2, explanation: "Úlceras duodenais estão classicamente associadas a um ambiente de hipersecreção ácida e são fortemente ligadas à infecção por Helicobacter pylori, que afeta os mecanismos de defesa da mucosa duodenal.", category: "Gastroenterologia" },
  { id: 473, question: "No manejo da hemorragia digestiva alta varicosa em pacientes cirróticos, qual das seguintes condutas é a mais importante na fase aguda, após estabilização hemodinâmica inicial?", options: ["Instalação de balão de Sengstaken-Blakemore como medida terapêutica definitiva.", "Administração de noradrenalina para manter a pressão arterial.", "Início de antibioticoterapia profilática e uso de terlipressina/octreotida.", "Indicação de shunt portossistêmico intra-hepático transjugular (TIPS) como tratamento inicial."], correctIndex: 2, explanation: "Na hemorragia digestiva alta varicosa, após a estabilização hemodinâmica, a conduta mais importante incluem o uso de drogas vasoativas (terlipressina, octreotida) para reduzir o fluxo portal e a antibioticoterapia profilática devido ao alto risco de infecções.", category: "Gastroenterologia" },
  { id: 474, question: "Qual o principal critério diagnóstico para doença de Crohn em um paciente com sintomas compatíveis e achados endoscópicos e histopatológicos?", options: ["Colite com acometimento contínuo, começando no reto.", "Inflamação transmural com granulomas não caseosos e acometimento em saltos.", "Acometimento exclusivo do cólon esquerdo, com pseudopólipos.", "Inflamação apenas da mucosa, com ulcerações superficiais."], correctIndex: 1, explanation: "A doença de Crohn é caracterizada por inflamação transmural, acometimento 'em saltos' (áreas de doença intercaladas com áreas sadias) e a presença de granulomas não caseosos à histopatologia, embora estes não sejam obrigatórios para o diagnóstico.", category: "Gastroenterologia" },
  { id: 475, question: "Um paciente de 70 anos apresenta dor em quadrante inferior esquerdo do abdome, febre, náuseas e constipação. Tomografia computadorizada revela diverticulose com inflamação paracólica e pequena coleção líquida pericólica. Qual o tratamento inicial adequado para este caso de diverticulite aguda não complicada?", options: ["Colectomia de urgência.", "Internação hospitalar com antibioticoterapia intravenosa e dieta zero.", "Tratamento ambulatorial com dieta líquida e antibioticoterapia oral.", "Drenagem percutânea da coleção líquida."], correctIndex: 2, explanation: "A diverticulite aguda não complicada, sem sinais de peritonite generalizada ou abscesso grande, pode ser tratada ambulatorialmente com dieta líquida e antibioticoterapia oral, com estreito acompanhamento.", category: "Gastroenterologia" },
  { id: 476, question: "Com relação à hepatite autoimune, qual achado laboratorial é mais característico?", options: ["Presença de anticorpos antimúsculo liso (ASMA) e/ou anticorpos antinucleares (ANA) em títulos elevados.", "Elevação predominante da gama-glutamil transferase (GGT).", "Marcadores virais positivos para hepatite B ou C.", "Presença de anticorpos antimitocondriais (AMA)."], correctIndex: 0, explanation: "A presença de autoanticorpos como ASMA e ANA em títulos elevados é um marcador característico da hepatite autoimune, sendo um dos critérios diagnósticos.", category: "Gastroenterologia" },
  { id: 477, question: "A icterícia colestática pode ser causada por diversas condições. Qual das seguintes é uma causa comum de colestase EXTRAPática?", options: ["Colangite biliar primária.", "Cirrose biliar secundária.", "Drogas hepatotóxicas.", "Coledocolitíase."], correctIndex: 3, explanation: "A coledocolitíase, ou seja, a presença de cálculos na via biliar principal, é uma causa comum de obstrução biliar extrapática que leva à colestase.", category: "Gastroenterologia" },
  { id: 478, question: "Um paciente de 40 anos, com história de colelitíase, refere dor intensa em hipocôndrio direito, irradiando para ombro, associada a náuseas e vômitos, há 8 horas. Apresenta febre (38,5°C) e leucocitose. O ultrassom abdominal revela cálculos na vesícula biliar, espessamento da parede vesicular e sinal de Murphy ultrassonográfico positivo. Qual a conduta terapêutica inicial mais apropriada após estabilização hemodinâmica?", options: ["Colangiopancreatografia retrógrada endoscópica (CPRE).", "Colecistectomia eletiva em 3 meses.", "Internação, antibioticoterapia e colecistectomia precoce (nas primeiras 72 horas).", "Tratamento clínico ambulatorial com analgésicos e repouso."], correctIndex: 2, explanation: "O quadro é compatível com colecistite aguda. O tratamento inicial inclui internação, antibioticoterapia e, idealmente, colecistectomia precoce (nas primeiras 72 horas) para reduzir o risco de complicações e o tempo de internação.", category: "Gastroenterologia" },
  { id: 479, question: "Um paciente de 55 anos, etilista social, procura atendimento com queixa de dor abdominal epigástrica em queimação, que melhora após a alimentação e piora em jejum. Refere despertar noturno devido à dor. Qual o diagnóstico mais provável e o exame inicial recomendado para confirmação?", options: ["Gastrite aguda; Endoscopia digestiva alta.", "Úlcera duodenal; Endoscopia digestiva alta.", "Colelitíase; Ultrassonografia abdominal.", "Pancreatite crônica; Tomografia computadorizada de abdome."], correctIndex: 1, explanation: "A descrição clássica de úlcera duodenal é dor epigástrica que melhora com alimentação e piora em jejum ou à noite. A endoscopia digestiva alta é o padrão-ouro para diagnóstico e biópsia, se necessário, de lesões gastroduodenais.", category: "Gastroenterologia" },
  { id: 480, question: "Qual das seguintes condições é considerada uma indicação absoluta para o rastreamento de câncer colorretal através de colonoscopia em pacientes assintomáticos?", options: ["Idade ≥ 50 anos, sem história familiar.", "História de pólipos adenomatosos removidos previamente.", "Síndrome do Intestino Irritável.", "Doença do Refluxo Gastroesofágico crônica."], correctIndex: 1, explanation: "História prévia de pólipos adenomatosos confere maior risco de desenvolvimento de câncer colorretal e indica monitoramento endoscópico regular. O rastreamento para população geral assintomática inicia aos 45-50 anos, mas a presença de adenomas prévios é uma indicação mais forte e específica.", category: "Gastroenterologia" },
  { id: 481, question: "Um paciente de 30 anos, com história de doença de Crohn há 5 anos, apresenta dor abdominal, diarreia com sangue e febre. Exames laboratoriais mostram aumento dos marcadores inflamatórios. Qual é a classe de medicamentos mais indicada para indução de remissão em casos moderados a graves de doença de Crohn?", options: ["Inibidores da bomba de prótons.", "Sulfassalazina.", "Corticosteroides sistêmicos.", "Antagonistas do receptor H2."], correctIndex: 2, explanation: "Corticosteroides sistêmicos são eficazes na indução de remissão em casos moderados a graves de doença inflamatória intestinal, como a doença de Crohn. Apesar dos efeitos adversos, são frequentemente utilizados para controle inicial da inflamação aguda.", category: "Gastroenterologia" },
  { id: 482, question: "Qual é a principal complicação da doença do refluxo gastroesofágico (DRGE) de longa data que se caracteriza pela substituição do epitélio escamoso estratificado do esôfago distal por epitélio colunar metaplásico?", options: ["Esofagite eosinofílica.", "Estenose esofágica benigna.", "Esôfago de Barrett.", "Acalasia."], correctIndex: 2, explanation: "O Esôfago de Barrett é uma complicação da DRGE crônica onde ocorre metaplasia intestinal do epitélio esofágico, resultando na substituição do epitélio escamoso por epitélio colunar, e é uma condição pré-cancerosa para adenocarcinoma esofágico.", category: "Gastroenterologia" },
  { id: 483, question: "Um paciente é diagnosticado com colecistite aguda. Qual é o tratamento de escolha para esta condição?", options: ["Antibioticoterapia empírica e aguardar resolução espontânea.", "Analgesia e dieta leve.", "Colecistectomia (laparoscópica, preferencialmente).", "Litotripsia por ondas de choque."], correctIndex: 2, explanation: "A colecistectomia (remoção cirúrgica da vesícula biliar), preferencialmente por via laparoscópica, é o tratamento definitivo e de escolha para a colecistite aguda. Antibióticos são usados como terapia adjuvante, mas não resolvem a causa.", category: "Gastroenterologia" },
  { id: 484, question: "Qual das seguintes etiologias é a mais comum para pancreatite aguda no Brasil?", options: ["Hipertrigliceridemia.", "Alcoolismo.", "Cálculos biliares (doença biliar).", "Hiperparatireoidismo."], correctIndex: 2, explanation: "A principal causa de pancreatite aguda no Brasil, e mundialmente, são os cálculos biliares (colelitíase), responsáveis por cerca de 40-50% dos casos. O alcoolismo é a segunda causa mais comum.", category: "Gastroenterologia" },
  { id: 485, question: "Um paciente de 45 anos, com cirrose hepática por hepatite C, apresenta ascite volumosa refratária a diuréticos. Qual a próxima conduta para controle da ascite, considerando que a paracentese de alívio já foi realizada em diversas ocasiões?", options: ["Aumentar a dose dos diuréticos.", "Iniciar betabloqueadores não seletivos.", "Considerar transplante hepático ou TIPS (derivação portossistêmica intra-hepática transjugular).", "Restrição hídrica rigorosa."], correctIndex: 2, explanation: "Em casos de ascite refratária a diuréticos e após várias paracenteses, opções mais invasivas como o TIPS (para descompressão portal) ou a avaliação para transplante hepático tornam-se necessárias para controle da condição e melhora da qualidade de vida.", category: "Gastroenterologia" },
  { id: 486, question: "Qual o principal mecanismo de ação do omeprazol no tratamento da doença do refluxo gastroesofágico?", options: ["Neutralização do ácido gástrico.", "Bloqueio dos receptores H2 de histamina nas células parietais.", "Inibição irreversível da H+/K+-ATPase (bomba de prótons) nas células parietais.", "Formação de barreira protetora sobre a mucosa gástrica."], correctIndex: 2, explanation: "O omeprazol é um inibidor da bomba de prótons, atuando ao inibir irreversivelmente a H+/K+-ATPase, enzima responsável pela secreção final de ácido clorídrico pelas células parietais no estômago, reduzindo significativamente a acidez gástrica.", category: "Gastroenterologia" },
  { id: 487, question: "Um paciente de 60 anos, com história de disfagia progressiva para sólidos e posteriormente para líquidos, perda ponderal e anemia. A endoscopia digestiva alta revela uma lesão estenosante no terço médio do esôfago. Qual o diagnóstico mais provável a ser confirmado por biópsia?", options: ["Acalasia.", "Esofagite eosinofílica.", "Carcinoma esofágico.", "Estenose péptica."], correctIndex: 2, explanation: "Disfagia progressiva, principalmente com perda ponderal e anemia em paciente de 60 anos, associada a uma lesão estenosante, é altamente sugestiva de carcinoma esofágico. A confirmação histopatológica é fundamental.", category: "Gastroenterologia" },
  { id: 488, question: "A Síndrome de Mallory-Weiss é caracterizada por:", options: ["Perfuração do esôfago após vômitos excessivos.", "Úlceras gástricas múltiplas associadas a estresse fisiológico.", "Lacerações longitudinais na junção gastroesofágica, após vômitos ou ânsias intensas.", "Hemorragia digestiva alta secundária à hipertensão portal."], correctIndex: 2, explanation: "A Síndrome de Mallory-Weiss refere-se a lacerações longitudinais da mucosa na junção gastroesofágica, geralmente causadas por vômitos ou ânsias intensas, e que podem levar à hemorragia digestiva alta.", category: "Gastroenterologia" },
  { id: 489, question: "Um paciente com diagnóstico de doença celíaca deve seguir qual tipo de dieta, independentemente dos sintomas atuais?", options: ["Dieta hipocalórica.", "Dieta sem lactose.", "Dieta sem glúten.", "Dieta com baixo teor de carboidratos."], correctIndex: 2, explanation: "O tratamento da doença celíaca é estritamente a adoção de uma dieta sem glúten (exclusão de trigo, cevada e centeio) por toda a vida, o que permite a recuperação da mucosa intestinal e a resolução dos sintomas.", category: "Gastroenterologia" },
  { id: 490, question: "Qual das seguintes manifestações clínicas NÃO é um critério diagnóstico para a Síndrome do Intestino Irritável (SII)?", options: ["Dor abdominal recorrente.", "Alteração na frequência das evacuações.", "Alteração na forma das fezes.", "Perda ponderal não intencional."], correctIndex: 3, explanation: "Critérios diagnósticos para SII (critérios de Roma IV) incluem dor abdominal recorrente, relacionada com a defecação e/ou associada a alteração na frequência ou forma das fezes. Perda ponderal não é um critério e, quando presente, sugere outras causas e 'sinais de alarme'.", category: "Gastroenterologia" },
  { id: 491, question: "Na avaliação laboratorial inicial de um paciente com icterícia, qual o padrão de elevação das enzimas hepáticas e bilirrubinas sugere predominantemente uma colestase?", options: ["Aumento significativo de TGO/TGP; Bilirrubina total às custas da indireta.", "Aumento significativo de Fosfatase Alcalina e Gama-GT; Bilirrubina total às custas da direta.", "Aumento discreto de Fosfatase Alcalina; Bilirrubina total não alterada.", "Aumento significativo de TGO/TGP; Bilirrubina total às custas da direta."], correctIndex: 1, explanation: "A colestase é caracterizada laboratorialmente pela elevação desproporcional da Fosfatase Alcalina e Gama-GT, juntamente com a elevação da bilirrubina direta (conjugada), que é o tipo de bilirrubina que não consegue ser excretada na bile.", category: "Gastroenterologia" },
  { id: 492, question: "O teste respiratório da ureia com carbono-13 (C13) é utilizado para o diagnóstico de qual infecção gastrointestinal?", options: ["Giardíase.", "Clostridioides difficile.", "Helicobacter pylori.", "Salmonelose."], correctIndex: 2, explanation: "O teste respiratório da ureia com C13 é um método não invasivo e altamente sensível e específico para a detecção da infecção por Helicobacter pylori. A bactéria produz urease, que hidrolisa a ureia marcada, liberando CO2 marcado que é detectado na respiração do paciente.", category: "Gastroenterologia" },
  { id: 493, question: "Para um paciente com cirrose hepática descompensada e encefalopatia hepática, qual medicação é a de primeira linha para o tratamento da encefalopatia?", options: ["Propranolol.", "Lactulose.", "Rifamaxina.", "Neomicina."], correctIndex: 1, explanation: "A lactulose é o tratamento de primeira linha para a encefalopatia hepática. Ela atua acidificando o conteúdo intestinal, convertendo amônia em íons amônio não absorvíveis, e promovendo sua excreção.", category: "Gastroenterologia" },
  { id: 494, question: "Qual das seguintes afirmações sobre a diverticulite aguda é VERDADEIRA?", options: ["É sempre tratada cirurgicamente com colectomia de urgência.", "A maioria dos casos de diverticulite aguda não complicada pode ser manejada clinicamente com repouso intestinal e antibióticos.", "O principal sintoma é dor no quadrante superior direito do abdome.", "A colonoscopia é o exame de escolha na fase aguda para diagnóstico."], correctIndex: 1, explanation: "A maioria dos casos de diverticulite aguda não complicada responde ao tratamento clínico com repouso intestinal, dieta líquida e antibióticos. A cirurgia é reservada para complicações ou casos refratários. A dor é classicamente no quadrante inferior esquerdo.", category: "Gastroenterologia" },
  { id: 495, question: "Qual das seguintes opções é a mais indicada para o manejo inicial de uma hemorragia digestiva alta varicosa em um paciente com cirrose?", options: ["Inibidores da bomba de prótons de alta dose.", "Análogos da somatostatina (ex: octreotida) e ligadura elástica endoscópica.", "Sonda de Sengstaken-Blakemore como primeira linha.", "Coagulação com argônio endoscópica."], correctIndex: 1, explanation: "O manejo inicial da hemorragia varicosa inclui drogas vasoativas como os análogos da somatostatina (octreotida) para reduzir o fluxo portal e a endoscopia com ligadura elástica de varizes, que é o tratamento endoscópico de escolha.", category: "Gastroenterologia" },
  { id: 496, question: "Um paciente apresenta diarreia crônica, esteatorreia e perda de peso. Exames complementares revelam atrofia de vilosidades intestinais e presença de anticorpos antitransglutaminase tecidual (anti-TTG). Qual o diagnóstico mais provável?", options: ["Doença de Crohn.", "Retocolite ulcerativa.", "Doença celíaca.", "Insuficiência pancreática exócrina."], correctIndex: 2, explanation: "Diarreia crônica, esteatorreia, perda de peso, atrofia de vilosidades na biópsia intestinal e, principalmente, a positividade de anticorpos anti-TTG, são achados clássicos da doença celíaca.", category: "Gastroenterologia" },
  { id: 497, question: "Em relação à Síndrome de Gilbert, qual das seguintes afirmativas está correta?", options: ["É uma doença hepática grave que exige tratamento específico.", "Caracteriza-se pela elevação da bilirrubina direta (conjugada).", "É uma condição benigna causada pela redução da atividade da glicuroniltransferase, resultando em elevação da bilirrubina indireta (não conjugada).", "É uma condição associada ao uso crônico de álcool."], correctIndex: 2, explanation: "A Síndrome de Gilbert é uma condição genética benigna, caracterizada por uma redução na atividade da enzima uridina difosfato-glicuronosiltransferase (UGT1A1), o que leva à elevação intermitente da bilirrubina indireta (não conjugada), especialmente em situações de estresse.", category: "Gastroenterologia" },
  { id: 498, question: "Qual critério é essencial para o diagnóstico de gastroparesia diabética?", options: ["Presença de Helicobacter pylori.", "Esvaziamento gástrico lento demonstrado por cintilografia.", "Dor epigástrica intensa.", "Níveis elevados de gastrina."], correctIndex: 1, explanation: "A gastroparesia diabética é caracterizada clinicamente por sintomas dispépticos e objetivamente por um atraso no esvaziamento gástrico, sem obstrução mecânica, confirmado por exames como a cintilografia de esvaziamento gástrico.", category: "Gastroenterologia" },
  { id: 499, question: "Um paciente de 70 anos apresenta disfagia para sólidos e líquidos, regurgitação de alimentos não digeridos e halitose. A manometria esofágica revela aperistalse do corpo esofágico e relaxamento incompleto do esfíncter esofágico inferior (EEI). Qual o diagnóstico mais provável?", options: ["Doença do refluxo gastroesofágico (DRGE).", "Esôfago de Barrett.", "Acalasia.", "Espasmo esofágico difuso."], correctIndex: 2, explanation: "A tríade de disfagia para sólidos e líquidos, regurgitação, e achados manométricos de aperistalse e relaxamento incompleto do EEI são patognomônicos da acalasia, uma desordem primária da motilidade esofágica.", category: "Gastroenterologia" },
  { id: 500, question: "Qual das seguintes intervenções é a mais efetiva para prevenir a hepatite A?", options: ["Uso de antivirais de ação direta.", "Vacinação.", "Evitar o consumo de álcool.", "Uso de corticosteroides."], correctIndex: 1, explanation: "A hepatite A é uma doença viral com transmissão fecal-oral. A vacinação é a estratégia mais eficaz para a prevenção da infecção por hepatite A, oferecendo imunidade duradoura.", category: "Gastroenterologia" },
  { id: 501, question: "Um paciente com cirrose hepática apresenta piora súbita da ascite e febre. A paracentese diagnóstica revela líquido ascítico com contagem de polimorfonucleares maior que 250 células/mm³. Qual o diagnóstico e tratamento inicial de escolha?", options: ["Peritonite bacteriana secundária; cirurgia exploratória.", "Peritonite bacteriana espontânea (PBE); antibióticos de amplo espectro.", "Hemorragia intra-abdominal; transfusão sanguínea.", "Peritonite fúngica; antifúngicos endovenosos."], correctIndex: 1, explanation: "A contagem de polimorfonucleares > 250 células/mm³ no líquido ascítico, na ausência de uma fonte clara de infecção intra-abdominal, confirma o diagnóstico de Peritonite Bacteriana Espontânea (PBE), uma complicação comum e grave da cirrose. O tratamento inicial é com antibióticos de amplo espectro, como cefotaxima.", category: "Gastroenterologia" },
  { id: 502, question: "Qual das seguintes opções é uma indicação para tratamento de erradicação do Helicobacter pylori?", options: ["Dispepsia funcional sem úlcera ou histórico de úlcera.", "Úlcera péptica (gástrica ou duodenal) ativa ou com histórico de úlcera.", "Refluxo gastroesofágico sem Esofagite de Barrett.", "Constipação crônica."], correctIndex: 1, explanation: "A infecção por Helicobacter pylori é a principal causa de úlcera péptica (gástrica e duodenal). A erradicação da bactéria é fundamental para a cicatrização da úlcera e prevenção de recidivas e complicações.", category: "Gastroenterologia" },
  { id: 503, question: "Um paciente de 35 anos, sexo masculino, previamente hígido, comparece ao pronto-socorro com história de febre alta, prostração, sangramento gengival e equimoses disseminadas há 5 dias. Hemograma revela leucocitose com 80% de blastos, anemia importante e plaquetopenia grave. Qual o diagnóstico mais provável e a conduta inicial mais urgente?", options: ["Leucemia Mieloide Crônica; iniciar inibidor de tirosina-quinase.", "Anemia Aplásica Grave; transfundir hemácias e plaquetas e iniciar imunossupressão.", "Leucemia Mieloide Aguda; coletar mielograma para confirmação e iniciar quimioterapia de indução após suporte.", "Púrpura Trombocitopênica Idiopática; administrar imunoglobulina intravenosa ou corticosteroides."], correctIndex: 2, explanation: "O quadro de pancitopenia com blastose mieloide é altamente sugestivo de Leucemia Mieloide Aguda (LMA). A conduta inicial envolve confirmação diagnóstica com mielograma e biópsia de medula óssea, além de medidas de suporte transfusionais e correção de distúrbios metabólicos, preparando para quimioterapia de indução.", category: "Hematologia" },
  { id: 504, question: "Qual das seguintes condições hematológicas é caracterizada pela presença do cromossomo Philadelphia (t(9;22)) em 95% dos casos?", options: ["Leucemia Mieloide Aguda M3 (promielocítica)", "Leucemia Linfóide Aguda", "Leucemia Mieloide Crônica", "Mieloma Múltiplo"], correctIndex: 2, explanation: "A Leucemia Mieloide Crônica (LMC) é classicamente associada à presença do cromossomo Philadelphia, que resulta na formação do gene de fusão BCR-ABL1, uma tirosina-quinase oncogênica, sendo fundamental para o diagnóstico e terapêutica.", category: "Hematologia" },
  { id: 505, question: "No tratamento de uma Púrpura Trombocitopênica Imune (PTI) primária recém-diagnosticada em um adulto com plaquetas < 30.000/microL e sangramento significativo, qual a primeira linha de tratamento recomendada?", options: ["Esplenectomia.", "Agonistas do receptor de trombopoietina (TPO-RAs).", "Corticosteroides (ex: prednisona oral) ou imunoglobulina intravenosa (IVIG).", "Rituximabe."], correctIndex: 2, explanation: "Para PTI primária com plaquetas < 30.000/microL e sangramento clinicamente significativo, a primeira linha de tratamento são corticosteroides orais ou imunoglobulina intravenosa (IVIG). A escolha depende da urgência e gravidade do sangramento.", category: "Hematologia" },
  { id: 506, question: "Uma paciente de 68 anos, com histórico de fadiga progressiva e perda de peso, apresenta hemograma com hemoglobina de 8,5 g/dL, VCM de 105 fL, leucocitose com desvio à esquerda e plaquetose. Medula óssea revela hipercelularidade com displasia de três linhagens. Qual o diagnóstico provável?", options: ["Anemia Ferropriva.", "Leucemia Linfóide Crônica (LLC).", "Síndrome Mielodisplásica.", "Mielofibrose Primária."], correctIndex: 2, explanation: "A descrição de pancitopenia ou citopenias associadas a displasia de uma ou mais linhagens na medula óssea, em um paciente idoso, é característica de Síndrome Mielodisplásica (SMD). A leucocitose com desvio e plaquetose podem ser achados, mas a chave é a displasia.", category: "Hematologia" },
  { id: 507, question: "Em relação à deficiência de vitamina B12 (cobalamina), qual das seguintes manifestações clínicas é a mais grave e pode ser irreversível se não tratada precocemente?", options: ["Glossite atrófica.", "Parestesias em extremidades.", "Demência e degeneração combinada subaguda da medula espinhal.", "Icterícia leve."], correctIndex: 2, explanation: "A deficiência prolongada de vitamina B12 pode levar a manifestações neurológicas graves, como demência e a degeneração combinada subaguda da medula espinhal, que podem se tornar irreversíveis se o tratamento não for instituído precocemente.", category: "Hematologia" },
  { id: 508, question: "Qual dos seguintes parâmetros laboratoriais é essencial para o diagnóstico e classificação da Anemia Ferropriva?", options: ["Níveis de vitamina B12.", "Tempo de protrombina (TP).", "Ferro sérico, ferritina e saturação de transferrina.", "Eletroforese de hemoglobina."], correctIndex: 2, explanation: "O diagnóstico de Anemia Ferropriva é confirmado pela avaliação dos estoques de ferro, que inclui ferro sérico baixo, ferritina sérica baixa (o melhor indicador de estoques) e saturação de transferrina tipicamente reduzida. Aumenta-se também a capacidade total de ligação do ferro (TIBC).", category: "Hematologia" },
  { id: 509, question: "Um paciente de 72 anos é diagnosticado com Mieloma Múltiplo. Qual o critério principal para iniciar o tratamento, de acordo com as diretrizes atuais?", options: ["Presença de mais de 10% de plasmócitos monoclonais na medula óssea, independentemente de sintomas.", "Presença de pico M na eletroforese de proteínas séricas.", "Evidência de lesão em órgãos-alvo (CRAB: Cálcio elevado, Insuficiência Renal, Anemia, Lesões ósseas) ou biomarcadores de alto risco.", "Apenas a idade avançada do paciente."], correctIndex: 2, explanation: "O tratamento do Mieloma Múltiplo é iniciado quando há evidência de lesão em órgãos-alvo (critérios CRAB: cálcio sérico elevado, insuficiência renal, anemia, lesões ósseas líticas) ou por biomarcadores de alto risco (plasmócitos medulares ≥60%, razão de cadeias leves livres >100, >1 lesão focal em ressonância magnética).", category: "Hematologia" },
  { id: 510, question: "Qual é a principal indicação para transfusão de plaquetas em um paciente com trombocitopenia grave?", options: ["Profilaxia primária em paciente assintomático com plaquetas entre 50.000 e 100.000/microL.", "Trombocitopenia medicamentosa com plaquetas > 20.000/microL sem sangramento.", "Plaquetas < 10.000/microL em paciente afebril sem sangramento ou plaquetas < 20.000/microL na presença de febre ou sangramento.", "Em qualquer paciente com plaquetas < 100.000/microL antes de procedimento cirúrgico."], correctIndex: 2, explanation: "A principal indicação para transfusão profilática de plaquetas é em pacientes afebris com plaquetas < 10.000/microL. Em casos de febre, sepse ou sangramento, o limiar é aumentado para < 20.000/microL. Para cirurgias, os limiares variam de 50.000 a 100.000/microL dependendo do tipo da cirurgia.", category: "Hematologia" },
  { id: 511, question: "Em pacientes com Hemofilia A grave, qual tratamento é considerado a primeira linha para profilaxia e tratamento de eventos hemorrágicos?", options: ["Desmopressina (DDVAP).", "Transfusão de plasma fresco congelado.", "Concentrado de fator VIII recombinante ou derivado do plasma.", "Ácido tranexâmico."], correctIndex: 2, explanation: "A primeira linha de tratamento e profilaxia para Hemofilia A grave é a reposição do fator VIII deficiente, seja com concentrado de fator VIII recombinante ou derivado do plasma. A desmopressina é útil para casos leves, e o plasma fresco congelado não tem dose padronizada de FVIII.", category: "Hematologia" },
  { id: 512, question: "Qual das seguintes características histopatológicas é clássica no diagnóstico de Doença de Hodgkin?", options: ["Plasmócitos atípicos na medula óssea.", "Células de Reed-Sternberg.", "Infiltrado com células blásticas mieloides.", "Aumento difuso de pequenos linfócitos maduros."], correctIndex: 1, explanation: "A presença das células de Reed-Sternberg, grandes células multinucleadas derivadas de linfócitos B, é o achado patognomônico e essencial para o diagnóstico da Doença de Hodgkin.", category: "Hematologia" },
  { id: 513, question: "Um paciente de 50 anos apresenta-se com esplenomegalia maciça, linfocitose acentuada (linfócitos de aspecto maduro), anemia e trombocitopenia. A imunofenotipagem dos linfócitos revela coexpressão de CD5 e CD20, além de CD23. Qual o diagnóstico mais provável?", options: ["Leucemia Linfóide Aguda (LLA).", "Leucemia Linfóide Crônica (LLC).", "Linfoma de Hodgkin.", "Linfoma difuso de grandes células B."], correctIndex: 1, explanation: "A tríade de linfocitose crônica com linfócitos maduros, esplenomegalia, e a coexpressão de CD5 e CD20 (marcadores B) e CD23, são características altamente sugestivas e diagnósticas de Leucemia Linfóide Crônica (LLC).", category: "Hematologia" },
  { id: 514, question: "Qual o principal alvo terapêutico dos inibidores da tirosina-quinase, como o imatinibe, no tratamento da Leucemia Mieloide Crônica (LMC)?", options: ["Receptor de fator de crescimento epidérmico (EGFR).", "Proteína BCR-ABL1.", "CD20 em linfócitos B.", "Topoisomerase I."], correctIndex: 1, explanation: "Os inibidores da tirosina-quinase, como o imatinibe, são desenhados para inibir especificamente a atividade da tirosina-quinase da proteína de fusão BCR-ABL1, que é o motor molecular da Leucemia Mieloide Crônica (LMC).", category: "Hematologia" },
  { id: 515, question: "Uma gestante no terceiro trimestre apresenta anemia microcítica e hipocrômica leve, com eletrólitos e função hepática e renal normais. A investigação revela ferritina sérica baixa. Qual a conduta inicial mais apropriada?", options: ["Iniciar transfusão de concentrado de hemácias.", "Solicitar biópsia de medula óssea.", "Iniciar suplementação oral de sulfato ferroso.", "Administrar eritropoetina recombinante."], correctIndex: 2, explanation: "A anemia microcítica hipocrômica com ferritina baixa em gestante é classicamente uma Anemia Ferropriva. A suplementação oral de sulfato ferroso é a primeira linha de tratamento, sendo segura e eficaz durante a gestação.", category: "Hematologia" },
  { id: 516, question: "Em caso de Anafilaxia Transfusional, qual a primeira e mais importante medida a ser tomada?", options: ["Administrar anti-histamínicos.", "Administrar corticosteroides.", "Interromper imediatamente a transfusão e manter acesso venoso.", "Acelerar a infusão da unidade de sangue para completar o mais rápido possível."], correctIndex: 2, explanation: "Em qualquer reação transfusional, a primeira e mais crucial medida é interromper imediatamente a transfusão para evitar a infusão de mais componentes problemáticos. Manter o acesso venoso é fundamental para a administração de medicações de emergência.", category: "Hematologia" },
  { id: 517, question: "Qual das seguintes drogas é um antagonista da vitamina K e é amplamente utilizada como anticoagulante oral?", options: ["Dabigatrana.", "Rivoraxabana.", "Varfarina.", "Heparina."], correctIndex: 2, explanation: "A Varfarina é um anticoagulante oral que atua como antagonista da vitamina K, inibindo a síntese hepática de fatores da coagulação dependentes de vitamina K (II, VII, IX, X e proteínas C e S).", category: "Hematologia" },
  { id: 518, question: "Qual a principal causa de defeito primário da hemostasia em crianças, manifestada por petéquias e equimoses?", options: ["Hemofilia A.", "Doença de von Willebrand.", "Púrpura Trombocitopênica Imune (PTI) aguda.", "Deficiência de vitamina K."], correctIndex: 2, explanation: "A Púrpura Trombocitopênica Imune (PTI) aguda é a causa mais comum de trombocitopenia isolada em crianças, frequentemente após infecção viral, e se manifesta com sangramentos cutâneos e mucosos (petéquias, equimoses).", category: "Hematologia" },
  { id: 519, question: "Em um paciente com trombose venosa profunda (TVP) e contraindicações a anticoagulantes orais e parenterais, qual a alternativa terapêutica pode ser considerada?", options: ["Trombólise sistêmica imediata.", "Colocação de filtro de veia cava inferior.", "Monitoramento com ultrassonografia seriada sem intervenção.", "Angioplastia da veia trombosada."], correctIndex: 1, explanation: "Para pacientes com TVP e contraindicações absolutas à anticoagulação, a colocação de um filtro de veia cava inferior pode ser considerada para prevenir embolia pulmonar, embora não trate a trombose em si e tenha potenciais complicações.", category: "Hematologia" },
  { id: 520, question: "Qual é o principal efeito adverso da desmopressina (DDVAP) em pacientes com Doença de von Willebrand ou hemofilia leve?", options: ["Trombose.", "Hiperpotassemia.", "Hiponatremia.", "Icterícia."], correctIndex: 2, explanation: "A desmopressina (DDVAP) age como um análogo da vasopressina, e um dos seus efeitos adversos mais importantes, especialmente com uso repetido, é a hiponatremia devido à retenção de água.", category: "Hematologia" },
  { id: 521, question: "Um paciente submetido a quimioterapia para leucemia mieloide aguda desenvolve febre (temperatura oral >38,3°C ou >38,0°C por 1 hora) e neutropenia grave (neutrófilos <500/mm³). Qual a conduta inicial mais apropriada?", options: ["Aguarda resultados de culturas para iniciar antibióticos direcionados.", "Iniciar antifúngicos empíricos imediatamente.", "Iniciar antibióticos de largo espectro intravenosos imediatamente.", "Administrar fator estimulador de colônias de granulócitos (G-CSF) e observar."], correctIndex: 2, explanation: "Febre neutropênica é uma emergência oncológica. A conduta inicial é a administração imediata de antibióticos de largo espectro intravenosos após coleta de culturas, devido ao risco de sepse e alta mortalidade se o tratamento for atrasado.", category: "Hematologia" },
  { id: 522, question: "Na anemia megaloblástica por deficiência de folato, qual hemograma é tipicamente encontrado?", options: ["Hemoglobina, VCM e RDW normais.", "Anemia microcítica e hipocrômica.", "Anemia macrocítica com ou sem pancitopenia e neutrófilos hipersegmentados.", "Anemia normocítica e normocrômica com reticulocitose."], correctIndex: 2, explanation: "A anemia megaloblástica, seja por deficiência de B12 ou folato, é caracterizada por anemia macrocítica (VCM elevado), frequentemente acompanhada de pancitopenia e a presença de neutrófilos hipersegmentados no esfregaço de sangue periférico.", category: "Hematologia" },
  { id: 523, question: "Qual exame é considerado padrão-ouro para o diagnóstico de hemoglobinopatias, como anemia falciforme e talassemias?", options: ["Hemograma completo.", "Eletroforese de hemoglobina.", "Teste de Coombs direto.", "Contagem de reticulócitos."], correctIndex: 1, explanation: "A eletroforese de hemoglobina é o método padrão-ouro para o diagnóstico e quantificação das diversas variantes de hemoglobina e suas frações, sendo essencial para identificar hemoglobinopatias como a anemia falciforme e as talassemias.", category: "Hematologia" },
  { id: 524, question: "Uma das complicações graves da Leucemia Promielocítica Aguda (LMA-M3) é a coagulação intravascular disseminada (CIVD). Qual tratamento específico é crucial nessa condição, além da quimioterapia?", options: ["Transfusão massiva de concentrado de plaquetas.", "Administração de heparina de baixo peso molecular.", "Ácido transretinoico (ATRA).", "Plasma fresco congelado em grandes volumes."], correctIndex: 2, explanation: "A Leucemia Promielocítica Aguda (LMA-M3) é particularmente associada à CIVD. O ácido transretinoico (ATRA) é a terapia direcionada que induz a diferenciação dos promielócitos, reduzindo a liberação de substâncias pró-coagulantes e, assim, controlando a CIVD.", category: "Hematologia" },
  { id: 525, question: "No monitoramento da anticoagulação com varfarina, qual exame laboratorial é utilizado?", options: ["Tempo de tromboplastina parcial ativada (TTPA).", "Tempo de sangramento.", "Tempo de protrombina (TP) com o Índice de Normalização Internacional (INR).", "Dímero-D."], correctIndex: 2, explanation: "A varfarina inibe fatores da coagulação dependentes de vitamina K da via extrínseca e comum. O efeito anticoagulante é monitorado pelo Tempo de Protrombina (TP), que é padronizado e expresso como Índice de Normalização Internacional (INR) para garantir comparabilidade entre laboratórios.", category: "Hematologia" },
  { id: 526, question: "Qual das seguintes alterações é tipicamente encontrada na medula óssea de pacientes com Anemia Plástica quando submetidos a biópsia?", options: ["Hipercelularidade com blastos > 20%.", "Hipocelularidade ou aplasia medular com substituição por gordura.", "Fibrose medular extensa.", "Aumento de plasmócitos monoclonais."], correctIndex: 1, explanation: "A Anemia Aplásica é caracterizada pela falência da medula óssea, resultando em hipocelularidade (ou aplasia) da medula óssea, com redução acentuada dos elementos hematopoéticos e substituição predominante por tecido adiposo.", category: "Hematologia" },
  { id: 527, question: "Um paciente de 45 anos, com histórico de transplante renal há 5 anos, em uso de imunossupressores, apresenta anemia, leucopenia e plaquetopenia de início súbito. Os testes para vírus incluem CMV e Epstein-Barr (EBV) positivos para infecção ativa. Qual a hipótese diagnóstica hematológica mais provável?", options: ["Anemia Ferropriva.", "Leucemia Linfóide Aguda.", "Síndrome linfoproliferativa pós-transplante (PTLD).", "Mieloma Múltiplo."], correctIndex: 2, explanation: "Pacientes imunossuprimidos pós-transplante, especialmente com infecção por EBV ativa, têm risco aumentado de desenvolver doenças linfoproliferativas pós-transplante (PTLD), que podem se manifestar com citopenias (anemia, leucopenia, plaquetopenia) e linfoadenopatias. Não é uma anemia aplásica e sim doença proliferativa.", category: "Hematologia" },
  { id: 528, question: "Um paciente de 55 anos, diabético e hipertenso, procura o pronto-socorro com dor abdominal difusa, distensão e parada de eliminação de flatos há 24 horas. Ao exame físico, apresenta abdome tenso, doloroso à palpação profunda, com descompressão brusca positiva. A radiografia simples de abdome revela alças dilatadas e níveis hidroaéreos. A melhor conduta inicial para este paciente é:", options: ["Administrar analgésicos opióides, aguardar melhora e realizar exames de imagem ambulatorialmente.", "Sondagem nasogástrica (SNG), hidratação venosa, correção de distúrbios hidroeletrolíticos e preparo para laparotomia exploradora.", "Prescrever antibióticos de amplo espectro por via oral e observação em casa.", "Realizar colonoscopia de urgência para descompressão."], correctIndex: 1, explanation: "O quadro clínico sugere obstrução intestinal com sinais de peritonite. A conduta inicial deve ser estabilização do paciente e preparo para cirurgia de emergência, incluindo SNG, hidratação e correção de eletrólitos.", category: "Cirurgia" },
  { id: 529, question: "Qual das seguintes afirmações sobre a doença do refluxo gastroesofágico (DRGE) e sua abordagem cirúrgica é verdadeira?", options: ["A fundoplicatura de Nissen é o procedimento cirúrgico mais comumente realizado para DRGE, envolvendo um envoltório parcial de 180° do esôfago pelo fundo gástrico.", "A principal complicação do tratamento cirúrgico da DRGE é a recidiva dos sintomas de refluxo.", "A pHmetria esofágica de 24 horas é o exame padrão-ouro para o diagnóstico de DRGE e é essencial na indicação cirúrgica em todos os pacientes.", "A cirurgia para DRGE está indicada principalmente em pacientes com resposta inadequada ao tratamento clínico otimizado, complicações como esôfago de Barrett com displasia de alto grau ou intolerância à medicação."], correctIndex: 3, explanation: "A indicação cirúrgica para DRGE é reservada para casos selecionados, principalmente falha no tratamento clínico, complicações graves e intolerância à medicação. A fundoplicatura de Nissen é um envoltório total de 360°, não parcial.", category: "Cirurgia" },
  { id: 530, question: "Um paciente de 40 anos apresenta-se com dor súbita e intensa na fossa ilíaca direita, náuseas e febre baixa há 12 horas. Ao exame físico, há dor à palpação na fossa ilíaca direita, com sinal de Blumberg positivo. O leucograma mostra leucocitose com desvio à esquerda. A conduta mais apropriada neste cenário é:", options: ["Prescrever analgésicos e anti-inflamatórios, orientar repouso e reavaliar em 24 horas.", "Realizar ultrassonografia abdominal de urgência para confirmar o diagnóstico e, se positivo, indicar apendicectomia.", "Iniciar antibioticoterapia de amplo espectro por via endovenosa e aguardar a resolução dos sintomas.", "Indicar apendicectomia de urgência, não sendo necessária a confirmação diagnóstica por imagem se o quadro clínico for típico."], correctIndex: 3, explanation: "O quadro clínico é classicamente de apendicite aguda. Em casos típicos, o diagnóstico é clínico e a conduta é a apendicectomia de urgência, sem a necessidade mandatória de exames de imagem para confirmação, a fim de evitar atrasos no tratamento e complicações.", category: "Cirurgia" },
  { id: 531, question: "Qual das seguintes características PREDISPÕE à formação de cálculos de colesterol na vesícula biliar?", options: ["Dieta rica em fibras e pobre em colesterol.", "Uso crônico de antiácidos inibidores da bomba de prótons.", "Obesidade e rápida perda de peso.", "Consumo moderado de álcool."], correctIndex: 2, explanation: "A obesidade aumenta a secreção de colesterol biliar e a diminuição da motilidade da vesícula. A rápida perda de peso também aumenta a saturação de colesterol na bile, contribuindo para a formação de cálculos de colesterol.", category: "Cirurgia" },
  { id: 532, question: "Em um paciente politraumatizado com instabilidade hemodinâmica após trauma abdominal fechado, com FAST (Focused Assessment with Sonography for Trauma) positivo para líquido livre intra-abdominal, qual a conduta de escolha inicial?", options: ["Tomografia computadorizada de abdome com contraste para identificar a lesão específica.", "Observação clínica rigorosa com monitorização hemodinâmica.", "Laparotomia exploradora de emergência.", "Paracentese diagnóstica para avaliar a presença de sangue no líquido peritoneal."], correctIndex: 2, explanation: "Paciente politraumatizado instável hemodinamicamente com FAST positivo para líquido livre no abdome tem indicação absoluta para laparotomia exploradora de emergência. A tomografia não é indicada em pacientes instáveis.", category: "Cirurgia" },
  { id: 533, question: "Paciente, 45 anos, sexo feminino, refere dor articular em pequenas e grandes articulações, com predomínio em joelhos e punhos, há 6 meses. Apresenta rigidez matinal há 1 hora, fadiga e edema simétrico em punhos. Exames laboratoriais mostram fator reumatoide positivo e anti-CCP positivo. Qual o diagnóstico mais provável?", options: ["Lúpus Eritematoso Sistêmico", "Artrite Reumatoide", "Osteoartrite", "Artrite Psoriática"], correctIndex: 1, explanation: "A dor poliarticular simétrica, rigidez matinal prolongada, fadiga e positividade para fator reumatoide e anti-CCP são critérios diagnósticos e características clássicas da Artrite Reumatoide, conforme diretrizes do Colégio Americano de Reumatologia e EULAR.", category: "Reumatologia" },
  { id: 534, question: "Um paciente de 30 anos desenvolve monoartrite aguda no hálux. Relata ingestão recente de grande quantidade de frutos do mar e bebidas alcoólicas. Ao exame, o hálux está eritematoso, edemaciado e muito doloroso, com sinais flogísticos intensos. A aspiração da articulação revelou cristais birrefringentes negativamente. Qual a melhor conduta inicial para o alívio da dor?", options: ["Colchicina", "Alopurinol", "Prednisona em dose alta", "Anti-inflamatório não esteroide (AINE)"], correctIndex: 3, explanation: "No ataque agudo de gota, o tratamento de escolha para o alívio da dor e inflamação é o AINE em dose plena, ou colchicina se o paciente iniciar nas primeiras 12-24h após o início dos sintomas e não tiver contraindicações. Corticosteroides orais ou intrarticulares também são opções eficazes.", category: "Reumatologia" },
  { id: 535, question: "No manejo do Lúpus Eritematoso Sistêmico (LES), o uso de hidroxicloroquina é recomendado para a maioria dos pacientes. Qual o principal efeito adverso que requer monitoramento oftalmológico regular?", options: ["Hepatotoxicidade", "Mielossupressão", "Retinopatia", "Nefropatia"], correctIndex: 2, explanation: "A hidroxicloroquina pode causar retinopatia como um efeito adverso cumulativo. Diretrizes atuais recomendam triagem oftalmológica de base e, posteriormente, monitoramento anual após 5 anos de uso ou em pacientes de risco.", category: "Reumatologia" },
  { id: 536, question: "Qual das seguintes manifestações clínicas NÃO faz parte dos critérios de classificação atualizados para Esclerose Sistêmica (ACR/EULAR 2013)?", options: ["Espessamento cutâneo dos dedos de ambas as mãos, estendendo-se proximalmente às articulações metacarpofalângicas", "Acometimento pulmonar intersticial em tomografia de alta resolução ou radiografia de tórax", "Úlceras digitais ativas ou perda de polpa digital (pits)", "Níveis elevados de anticorpo anti-DNA"], correctIndex: 3, explanation: "Os critérios de classificação para Esclerose Sistêmica (ACR/EULAR 2013) incluem espessamento cutâneo típico, lesões em dedos (úlcera, perda de polpa), doença pulmonar intersticial, fenômeno de Raynaud, telangiectasias, alterações capilaroscópicas e autoanticorpos específicos (anti-topoisomerase I, anti-centrômero, anti-RNA polimerase III). O anti-DNA está associado ao LES.", category: "Reumatologia" },
  { id: 537, question: "Uma paciente de 60 anos, com história de lombalgia crônica que piora com o repouso e melhora com a atividade física, associada à rigidez matinal de 2 horas de duração. Exames de imagem mostram sacroileíte bilateral. Qual o diagnóstico mais provável?", options: ["Osteoartrite de coluna", "Artrite reumatoide", "Espondilite anquilosante", "Fibromialgia"], correctIndex: 2, explanation: "A lombalgia inflamatória (piora com repouso, melhora com atividade, rigidez matinal prolongada) associada à sacroileíte bilateral radiográfica é característica da Espondilite Anquilosante, uma espondiloartrite axial.", category: "Reumatologia" },
  { id: 538, question: "Qual é a principal indicação para o uso de metotrexato em pacientes com artrite reumatoide?", options: ["Dor em articulações isoladas", "Doença bem controlada com AINE", "Doença moderada a grave, com inflamação persistente", "Primeira linha para tratamento de osteoartrite"], correctIndex: 2, explanation: "O metotrexato é a terapia de primeira linha para a maioria dos pacientes com Artrite Reumatoide moderada a grave, sendo um DMARD sintético convencional com eficácia comprovada no controle da inflamação e prevenção de danos articulares.", category: "Reumatologia" },
  { id: 539, question: "Homem, 55 anos, apresenta dor e inchaço repentino no joelho esquerdo. O líquido sinovial aspirado é turvo e mostra inúmeros leucócitos polimorfonucleares e cristais de pirofosfato de cálcio di-hidratado, com birrefringência positiva fraca. Qual a condição reumatológica mais provável?", options: ["Artrite Gotosa", "Artrite Séptica", "Artrite Reumatoide", "Artrite por Pirofosfato de Cálcio (Pseudogota)"], correctIndex: 3, explanation: "A presença de cristais de pirofosfato de cálcio di-hidratado com birrefringência positiva fraca no líquido sinovial é patognomônica da doença por deposição de pirofosfato de cálcio, conhecida como pseudogota, que causa artrite aguda.", category: "Reumatologia" },
  { id: 540, question: "Em pacientes com osteoporose, qual é o principal achado patológico que leva ao aumento do risco de fraturas?", options: ["Aumento da densidade mineral óssea", "Inflamação crônica das articulações", "Déficit na microarquitetura óssea e redução da massa óssea", "Formação excessiva de osteófitos"], correctIndex: 2, explanation: "A osteoporose é caracterizada por comprometimento da resistência óssea, resultante de déficit na microarquitetura e da redução da massa óssea, tornando os ossos mais suscetíveis a fraturas por fragilidade.", category: "Reumatologia" },
  { id: 541, question: "Qual dos seguintes achados NÃO é um critério diagnóstico para Fibromialgia, segundo os critérios de 2010/2011 do ACR?", options: ["Índice de dor generalizada (WPI) ≥ 7 e Escala de Gravidade de Sintomas (SS) ≥ 5", "Sintomas presentes em nível semelhante por pelo menos 3 meses", "Presença de 11 de 18 pontos dolorosos (tender points)", "Ausência de outra doença que pudesse explicar a dor"], correctIndex: 2, explanation: "Os critérios de 2010/2011 e 2016 do ACR substituíram a contagem de tender points pela avaliação do índice de dor generalizada (WPI) e escala de gravidade de sintomas (SS), focando mais na generalização da dor e intensidade dos sintomas.", category: "Reumatologia" },
  { id: 542, question: "Um jovem de 25 anos apresenta dor e edema em joelho esquerdo após trauma leve. O líquido sinovial é sero-hemorrágico, com poucos leucócitos. Ele também relata manifestações cutâneas e em mucosas recorrentes e artrite em outras grandes articulações. Qual o diagnóstico diferencial deve ser considerado com maior atenção?", options: ["Artrite Reumatoide, devido ao acometimento articular", "Lúpus Eritematoso Sistêmico, pelos múltiplos acometimentos", "Artrite psoriática, devido às lesões de pele", "Doença de Behçet, pela poliartrite, manifestações em pele e mucosas"], correctIndex: 3, explanation: "A poliartrite de grandes articulações, a presença de lesões em pele e mucosas (aftas orais e genitais, lesões cutâneas como eritema nodoso ou foliculite) são características da Doença de Behçet, que pode mimetizar outras artropatias inflamatórias.", category: "Reumatologia" },
  { id: 543, question: "Qual exame laboratorial é mais específico para o diagnóstico de lúpus eritematoso sistêmico?", options: ["Fator Reumatoide (FR)", "Anticorpos Antinucleares (FAN)", "Anticorpos anti-DNA de dupla hélice (anti-dsDNA)", "Proteína C Reativa (PCR)"], correctIndex: 2, explanation: "Embora o FAN seja sensível, o anticorpo anti-DNA de dupla hélice (anti-dsDNA) é o mais específico para o LES, sendo um dos critérios imunológicos de classificação e indicador de atividade da doença, especialmente de nefrite lúpica.", category: "Reumatologia" },
  { id: 544, question: "No tratamento da osteoartrite de joelho, qual das seguintes medidas é considerada primeira linha?", options: ["Artroplastia total do joelho", "Uso de corticosteroides sistêmicos em altas doses", "Modificação do estilo de vida, incluindo exercícios de fortalecimento e perda de peso", "Uso de metotrexato"], correctIndex: 2, explanation: "As diretrizes atuais preconizam medidas não farmacológicas como primeira linha de tratamento para osteoartrite, incluindo educação do paciente, exercícios de fortalecimento muscular (especialmente quadríceps) e perda de peso, que levam à melhora da dor e função.", category: "Reumatologia" },
  { id: 545, question: "Um paciente com Síndrome de Sjögren primária, cujos sintomas predominantes são secura ocular e oral intensas, além de fadiga, deve ser monitorado por qual complicação grave?", options: ["Insuficiência renal dialítica", "Acidente vascular cerebral isquêmico", "Linfoma não-Hodgkin", "Infarto agudo do miocárdio"], correctIndex: 2, explanation: "Pacientes com Síndrome de Sjögren primária têm um risco significativamente aumentado de desenvolver linfoma não-Hodgkin, especialmente o tipo de células B. O monitoramento clínico para sintomas como aumento das glândulas salivares ou linfonodos é essencial.", category: "Reumatologia" },
  { id: 546, question: "Qual dos seguintes fármacos é um antagonista do TNF-alfa e é utilizado no tratamento de doenças reumatológicas inflamatórias?", options: ["Rituximabe", "Abatacepte", "Adalimumabe", "Tocilizumabe"], correctIndex: 2, explanation: "Adalimumabe é um anticorpo monoclonal humano que se liga especificamente ao TNF-alfa solúvel e de superfície, inibindo sua atividade biológica. É amplamente utilizado na artrite reumatoide, artrite psoriática, espondilite anquilosante e outras doenças inflamatórias.", category: "Reumatologia" },
  { id: 547, question: "Paciente, 30 anos, sexo feminino, refere fenômeno de Raynaud, disfagia, espessamento cutâneo em mãos e pés, e telangiectasias. Qual a doença a ser considerada no diagnóstico diferencial principal?", options: ["Lúpus Eritematoso Sistêmico", "Artrite Reumatoide", "Esclerose Sistêmica", "Dermatomiosite"], correctIndex: 2, explanation: "O fenômeno de Raynaud, o espessamento cutâneo, a disfagia (por dismotilidade esofágica) e as telangiectasias são manifestações cardinais da Esclerose Sistêmica, especialmente na sua forma limitada (síndrome CREST).", category: "Reumatologia" },
  { id: 548, question: "No contexto da Artrite Idiopática Juvenil (AIJ), qual subtipo é caracterizado por envolvimento de poucas articulações (até 4), geralmente grandes articulações, com início antes dos 6 anos e maior risco de uveíte?", options: ["AIJ sistêmica", "AIJ poliarticular (fator reumatoide negativo)", "AIJ oligoarticular persistente", "AIJ com entesite"], correctIndex: 2, explanation: "A AIJ oligoarticular persistente é o subtipo mais comum, acometendo até 4 articulações nos primeiros 6 meses da doença, com maior frequência em crianças pequenas e alto risco de uveíte anterior assintomática, que requer triagem oftalmológica regular.", category: "Reumatologia" },
  { id: 549, question: "Qual o principal distúrbio metabólico associado à gota?", options: ["Hipercolesterolemia", "Hipertrigliceridemia", "Hiperuricemia", "Hiperglicemia"], correctIndex: 2, explanation: "A gota é uma artrite inflamatória causada pela deposição de cristais de monourato de sódio nas articulações e tecidos moles, resultando de níveis elevados de ácido úrico no sangue, caracterizando a hiperuricemia.", category: "Reumatologia" },
  { id: 550, question: "A Síndrome de Reiter, ou Artrite Reativa, está frequentemente associada a qual tipo de infecção prévia?", options: ["Infecções virais respiratórias", "Infecções estreptocócicas", "Infecções gastrointestinais e geniturinárias", "Infecções fúngicas sistêmicas"], correctIndex: 2, explanation: "A Artrite Reativa (anteriormente Síndrome de Reiter) é um tipo de espondiloartrite que ocorre após infecções em outros sítios, sendo as mais comuns as infecções entéricas (Salmonella, Shigella, Campylobacter, Yersinia) e geniturinárias (Chlamydia trachomatis).", category: "Reumatologia" },
  { id: 551, question: "Qual o principal critério para o diagnóstico de vasculite por IgA (Púrpura de Henoch-Schönlein) em crianças?", options: ["Presença de artrite crônica e uveíte", "Rash maculopapular e febre alta", "Púrpura palpável, predominantemente em membros inferiores, sem trombocitopenia", "Anemia hemolítica e acometimento renal"], correctIndex: 2, explanation: "A púrpura palpável, não trombocitopênica, com distribuição predominante em membros inferiores, é o achado obrigatório para o diagnóstico de vasculite por IgA, sendo frequentemente acompanhada de artralgia/artrite, dor abdominal e acometimento renal.", category: "Reumatologia" },
  { id: 552, question: "No tratamento da Artrite Reumatoide, quando o metotrexato em monoterapia não é suficiente para controlar a doença, qual a próxima etapa terapêutica recomendada pelas diretrizes atuais?", options: ["Aumento da dose do metotrexato indefinidamente", "Adição de um AINE em dose alta e contínua", "Associação com outro DMARD sintético convencional ou início de um DMARD biológico/alvo específico", "Indicação de fisioterapia intensiva sem modificação medicamentosa"], correctIndex: 2, explanation: "Em caso de falha ao metotrexato em monoterapia, as diretrizes da EULAR/ACR recomendam escalonar o tratamento, adicionando outro DMARD sintético convencional (como sulfassalazina ou leflunomida) ou iniciando um DMARD biológico ou alvo específico (como inibidores de JAK).", category: "Reumatologia" },
  { id: 553, question: "Um paciente de 35 anos é admitido no pronto-socorro após trauma automobilístico com sinais de instabilidade hemodinâmica (PA 80/40 mmHg, FC 120 bpm, enchimento capilar > 4 segundos). O FAST (Focused Assessment with Sonography for Trauma) é positivo para líquido livre em abdome. Qual a conduta inicial mais apropriada neste cenário?", options: ["Realizar tomografia computadorizada abdominal com contraste para avaliar a extensão das lesões.", "Administrar, por via intravenosa, 1 litro de cristaloides aquecidos, buscando estabilização hemodinâmica antes de qualquer outra intervenção.", "Indicar laparotomia exploradora imediata.", "Aguardar a resposta à reposição volêmica inicial e reavaliar o paciente antes de definir a conduta."], correctIndex: 2, explanation: "Em pacientes vítimas de trauma com instabilidade hemodinâmica e FAST positivo para líquido livre abdominal, o tratamento de escolha é a laparotomia exploradora imediata, conforme preconizado pelo ATLS (Advanced Trauma Life Support), pois sugere hemorragia interna grave.", category: "Trauma" },
  { id: 554, question: "Em relação à tríade letal do trauma (hipotermia, acidose e coagulopatia), qual a principal razão pela qual a hipotermia agrava o quadro de coagulopatia?", options: ["A hipotermia causa vasodilatação periférica, aumentando a perda sanguínea.", "Temperaturas corporais baixas inibem a função das enzimas da cascata de coagulação.", "A hipotermia leva à hipercalcemia, que impede a cascata de coagulação.", "A hipotermia aumenta a produção de fibrinogênio, levando à trombose e consumo dos fatores."], correctIndex: 1, explanation: "A hipotermia abaixo de 35°C afeta a função plaquetária e as enzimas da cascata de coagulação, prolongando o tempo de protrombina (TP) e o tempo de tromboplastina parcial ativada (TTPA), o que agrava a coagulopatia e a hemorragia.", category: "Trauma" },
  { id: 555, question: "Um paciente de 22 anos sofreu um trauma torácico contuso e apresenta dispneia, desvio de traqueia para o lado oposto, murmúrio vesicular abolido no hemitórax direito e hipotensão. A suspeita diagnóstica mais provável e a conduta imediata são, respectivamente:", options: ["Hemotórax maciço; toracotomia de emergência.", "Pneumotórax aberto; curativo de três pontas.", "Pneumotórax hipertensivo; toracostomia com agulha no segundo espaço intercostal, linha hemiclavicular.", "Contusão pulmonar; oxigenoterapia e observação."], correctIndex: 2, explanation: "Os sinais clínicos de dispneia, desvio de traqueia, hipotensão e murmúrio vesicular abolido são classicamente descritos no pneumotórax hipertensivo, uma emergência que exige descompressão imediata por toracostomia com agulha seguida de drenagem torácica.", category: "Trauma" },
  { id: 556, question: "No manejo inicial do paciente politraumatizado, o que significa a etapa 'D' da avaliação primária (ABCDE)?", options: ["Deficiências neurológicas, ou seja, avaliação do nível de consciência e exame neurológico sumário.", "Descompressão de pneumotórax, se necessário, antes da ventilação.", "Diagnóstico por imagem, incluindo radiografias e ultrassonografia FAST.", "Dose de medicamentos, como analgésicos e antibióticos profiláticos."], correctIndex: 0, explanation: "A etapa 'D' da avaliação primária do trauma (ABCDE) refere-se à 'Disability' (incapacidade ou deficiência neurológica), que envolve a avaliação do nível de consciência através da Escala de Coma de Glasgow e a pesquisa de sinais de lateralização.", category: "Trauma" },
  { id: 557, question: "Qual das seguintes afirmações sobre o uso de ácido tranexâmico no trauma é VERDADEIRA?", options: ["Deve ser administrado em dose única de 2 gramas intravenosos o mais rápido possível após o trauma, independentemente da presença de coagulopatia.", "É recomendado para todos os pacientes com trauma e sangramento significativo, mas apenas se a estabilidade hemodinâmica for alcançada previamente.", "A maior eficácia do ácido tranexâmico na redução da mortalidade é observada quando administrado em até 3 horas após o trauma.", "Sua principal indicação é na prevenção da trombose venosa profunda em pacientes traumatizados imóveis."], correctIndex: 2, explanation: "Estudos como o CRASH-2 demonstraram que o ácido tranexâmico reduz a mortalidade por hemorragia em pacientes traumatizados com sangramento significativo se administrado precocemente, idealmente nas primeiras 3 horas após a lesão.", category: "Trauma" },
  { id: 558, question: "Um paciente de 55 anos, diabético, hipertenso e dislipidêmico, procura o pronto-socorro com dor retroesternal opressiva há 30 minutos, irradiando para o membro superior esquerdo e acompanhada de sudorese. O eletrocardiograma (ECG) inicial mostra supradesnivelamento do segmento ST em V1-V4. Qual a conduta inicial MAIS apropriada para este paciente, considerando a suspeita de Infarto Agudo do Miocárdio (IAM) com supradesnivelamento do ST?", options: ["Administrar oxigênio, monitorizar, nitrato sublingual, dupla antiagregação plaquetária (ácido acetilsalicílico + ticagrelor/prasugrel) e encaminhar para angioplastia primária.", "Administrar morfina, propranolol oral, inibidor de enzima conversora de angiotensina (IECA) e aguardar resultados de marcadores de necrose miocárdica.", "Realizar apenas angiotomografia de coronárias para confirmar oclusão e, então, considerar a terapia de reperfusão.", "Iniciar heparina de baixo peso molecular, clopidogrel e nitroprussiato de sódio intravenoso, avaliando posteriormente a necessidade de cirurgia."], correctIndex: 0, explanation: "Em casos de IAM com supradesnivelamento do ST, a reperfusão coronariana urgente é prioritária (angioplastia primária ou fibrinolítico se a angioplastia não for possível em tempo hábil). O tratamento inicial inclui oxigênio (se saturação <90%), nitrato (se sem contraindicações), dupla antiagregação e analgesia.", category: "Clínica Médica" },
  { id: 559, question: "Um paciente de 40 anos, com história de etilismo crônico, comparece ao pronto-socorro com icterícia, ascite e edema de membros inferiores. Exames laboratoriais mostram albumina sérica de 2,5 g/dL, tempo de protrombina (TP) com INR de 2,0 e creatinina sérica de 1,8 mg/dL. Qual a classificação de Child-Pugh para este paciente?", options: ["Child A", "Child B", "Child C", "Não é possível classificar com os dados fornecidos."], correctIndex: 2, explanation: "Para Child-Pugh, ascite e encefalopatia são de 1-3 pontos, bilirrubina (>3mg/dL = 3 pontos), albumina (<2.8g/dL = 3 pontos), e INR (>2.3 = 3 pontos). Este paciente se encaixa em Child C devido à ascite (1 ponto), bilirrubina provavelmente alta (não informada, mas contribuindo para icterícia), albumina baixa (3 pontos), INR elevado (2 pontos) e possivelmente encefalopatia (não informada, mas comum), totalizando >10 pontos.", category: "Clínica Médica" },
  { id: 560, question: "Em um paciente asmático, qual das seguintes classes de medicamentos é indicada no tratamento de manutenção para controle da inflamação brônquica, conforme as diretrizes da GINA?", options: ["Beta-2 agonistas de ação curta (SABA) isolados", "Corticosteroides inalatórios (CI) em baixa dose", "Beta-2 agonistas de ação prolongada (LABA) isolados", "Antagonistas de leucotrienos como primeira linha exclusiva"], correctIndex: 1, explanation: "Os corticosteroides inalatórios (CI) são a base do tratamento de manutenção da asma para controle da inflamação. A GINA recomenda CI como a pedra angular do tratamento da asma em todos os estágios para controle contínuo, geralmente em combinação com LABA para asma moderada a grave.", category: "Clínica Médica" },
  { id: 561, question: "Qual é o principal mecanismo de ação dos inibidores da bomba de prótons (IBPs) no tratamento da doença do refluxo gastroesofágico (DRGE)?", options: ["Neutralização do ácido gástrico", "Formação de barreira protetora na mucosa esofágica", "Inibição irreversível da H+/K+-ATPase nas células parietais", "Aumento da motilidade esofágica"], correctIndex: 2, explanation: "Os IBPs atuam inibindo irreversivelmente a bomba de prótons (H+/K+-ATPase) nas células parietais do estômago. Isso resulta em uma redução potente e duradoura da secreção de ácido gástrico, sendo o tratamento mais eficaz para DRGE.", category: "Clínica Médica" },
  { id: 562, question: "Conforme as diretrizes mais recentes para o manejo da hipertensão arterial, qual é o valor de pressão arterial considerado limítrofe para iniciar mudanças no estilo de vida em um adulto sem fatores de risco adicionais, antes de considerar terapia farmacológica?", options: ["PA sistólica ≥ 120 mmHg e/ou PA diastólica ≥ 80 mmHg", "PA sistólica ≥ 130 mmHg e/ou PA diastólica ≥ 85 mmHg", "PA sistólica ≥ 140 mmHg e/ou PA diastólica ≥ 90 mmHg", "PA sistólica ≥ 160 mmHg e/ou PA diastólica ≥ 100 mmHg"], correctIndex: 1, explanation: "As diretrizes recentes sugerem que mudanças no estilo de vida são recomendadas para indivíduos com PA sistólica ≥ 130 mmHg e/ou PA diastólica ≥ 85 mmHg (pré-hipertensão estágio 2 ou hipertensão estágio 1, dependendo da classificação), mesmo antes da terapia farmacológica em alguns cenários.", category: "Clínica Médica" },
  { id: 563, question: "Um paciente de 68 anos apresenta perda de peso não intencional, fadiga crônica, dor abdominal difusa e alteração do hábito intestinal (diarreia e constipação alternadas) há 6 meses. Exames revelam anemia microcítica e hipocrômica, e sangue oculto nas fezes positivo. Qual a principal hipótese diagnóstica e conduta inicial?", options: ["Doença de Crohn; iniciar terapia imunossupressora.", "Síndrome do intestino irritável; recomendar dieta específica e probióticos.", "Neoplasia colorretal; indicar colonoscopia com biópsia.", "Diverticulite aguda; prescrever antibióticos e dieta líquida."], correctIndex: 2, explanation: "A descrição do quadro clínico (idade, perda de peso, anemia, sangramento oculto nas fezes, alteração do hábito intestinal) é altamente sugestiva de neoplasia colorretal. A colonoscopia com biópsia é o exame padrão-ouro para confirmar o diagnóstico.", category: "Clínica Médica" },
  { id: 564, question: "Qual das seguintes condições é uma contraindicação ABSOLUTA para o uso de betabloqueadores em pacientes com insuficiência cardíaca?", options: ["Diabetes mellitus tipo 2", "Doença pulmonar obstrutiva crônica (DPOC) grave com broncoespasmo ativo", "Doença arterial periférica branda", "Bradicardia sinusal assintomática (FC 55 bpm)"], correctIndex: 1, explanation: "Embora betabloqueadores sejam importantes na IC, a DPOC grave com broncoespasmo ativo é uma contraindicação absoluta devido ao risco de piora da broncoconstrição. As outras condições são contraindicações relativas ou não contraindicações.", category: "Clínica Médica" },
  { id: 565, question: "Uma paciente de 35 anos, com histórico de múltiplos abortos espontâneos, trombose venosa profunda e trombocitopenia, apresenta resultado positivo para anticorpo anticardiolipina e anticoagulante lúpico em duas ocasiões, com 12 semanas de diferença. Qual o diagnóstico MAIS provável?", options: ["Lúpus Eritematoso Sistêmico (LES)", "Trombofilia hereditária", "Síndrome do Anticorpo Antifosfolípide (SAF)", "Púrpura Trombocitopênica Idiopática (PTI)"], correctIndex: 2, explanation: "A Síndrome do Anticorpo Antifosfolípide (SAF) é caracterizada por tromboses (arteriais ou venosas), morbidade gestacional (abortos de repetição) e presença de anticorpos antifosfolípides (anticardiolipina, anticoagulante lúpico, anti-beta2-glicoproteína I).", category: "Clínica Médica" },
  { id: 566, question: "Qual é a principal indicação para o uso de metformina no tratamento do diabetes mellitus tipo 2?", options: ["Prevenção de hipoglicemia em pacientes idosos.", "Redução da resistência à insulina e diminuição da produção hepática de glicose.", "Estimulação direta da secreção de insulina pelas células beta pancreáticas.", "Aumento da excreção urinária de glicose."], correctIndex: 1, explanation: "A metformina é um sensibilizador de insulina que atua principalmente reduzindo a produção hepática de glicose (gliconeogênese) e melhorando a sensibilidade à insulina nos tecidos periféricos, sendo a primeira linha na maioria dos pacientes com DM2.", category: "Clínica Médica" },
  { id: 567, question: "Um paciente de 70 anos é admitido com pneumonia comunitária grave. Após 48 horas de internação, desenvolve hipotensão refratária a fluidos, necessitando de vasopressores, e apresenta lactato elevado. Exames laboratoriais indicam leucocitose acentuada, PCR aumentado e disfunção de múltiplos órgãos. Qual o diagnóstico MAIS provável?", options: ["Síndrome da Resposta Inflamatória Sistêmica (SIRS)", "Choque hipovolêmico", "Sepse com choque séptico", "Reação anafilática"], correctIndex: 2, explanation: "A combinação de infecção (pneumonia) com disfunção orgânica progressiva (hipotensão refratária, lactato elevado) caracteriza sepse e, quando há necessidade de vasopressores para manter pressão arterial média ≥ 65 mmHg e lactato > 2 mmol/L, configura choque séptico.", category: "Clínica Médica" },
  { id: 568, question: "Qual a principal complicação renal do diabetes mellitus, sendo a principal causa de doença renal crônica terminal?", options: ["Glomerulonefrite aguda", "Pielonefrite crônica", "Nefropatia diabética", "Hipertensão renovascular"], correctIndex: 2, explanation: "A nefropatia diabética é a complicação renal mais comum do diabetes mellitus e a principal causa de doença renal crônica em estágio terminal, caracterizada por proteinúria progressiva e declínio da função renal.", category: "Clínica Médica" },
  { id: 569, question: "Um paciente de 45 anos apresenta febre, calafrios, cefaleia intensa e rigidez de nuca. O líquido cefalorraquidiano (LCR) obtido por punção lombar revela pleocitose com predomínio de neutrófilos, glicorraquia baixa e proteinorraquia elevada. Qual o diagnóstico MAIS provável?", options: ["Meningite viral", "Meningite tuberculosa", "Meningite bacteriana", "Hemorragia subaracnoidea"], correctIndex: 2, explanation: "Os achados do LCR (pleocitose neutrofílica, glicose baixa, proteína alta) são característicos de meningite bacteriana aguda, uma emergência médica que requer tratamento antibiótico imediato.", category: "Clínica Médica" },
  { id: 570, question: "Qual das seguintes opções é um fator de risco MODIFICÁVEL para o desenvolvimento de doença aterosclerótica?", options: ["Idade avançada", "Gênero masculino", "História familiar de doença cardíaca precoce", "Hipercolesterolemia"], correctIndex: 3, explanation: "A hipercolesterolemia é um fator de risco modificável, pois pode ser controlada através de mudanças no estilo de vida (dieta, exercícios) e uso de medicamentos (estatinas). Os outros são fatores de risco não modificáveis.", category: "Clínica Médica" },
  { id: 571, question: "Em um paciente com doença renal crônica (DRC) em estádio 3 (TFG 30-59 mL/min/1.73m²), qual das seguintes condutas é fundamental para o manejo da progressão da doença?", options: ["Restrição hídrica rigorosa", "Administração intravenosa de diuréticos de alça diariamente", "Controle rigoroso da pressão arterial e da proteinúria, geralmente com inibidores do sistema renina-angiotensina-aldosterona (SRAA).", "Início de diálise peritoneal."], correctIndex: 2, explanation: "O controle da pressão arterial e da proteinúria, frequentemente com IECA/BRA, é a medida mais eficaz para desacelerar a progressão da DRC, reduzindo a lesão glomerular e renal. Diálise só é iniciada em estágios mais avançados.", category: "Clínica Médica" },
  { id: 572, question: "Qual o principal critério diagnóstico para Síndrome Coronariana Aguda sem Supradesnivelamento do Segmento ST (SCASSST) em um paciente com dor torácica aguda?", options: ["Dor torácica tipo pleurítica e dispneia", "Alterações dinâmicas do segmento ST ou onda T no ECG e/ou elevação de marcadores de necrose miocárdica.", "Supradesnivelamento do segmento ST em duas derivações contíguas.", "Presença de tosse persistente e expectoração."], correctIndex: 1, explanation: "A SCASSST é definida pela presença de isquemia miocárdica (sintomas), mas sem elevação persistente do ST no ECG, e é confirmada por alterações do ST/T ou elevação dos marcadores de necrose miocárdica (troponina).", category: "Clínica Médica" },
  { id: 573, question: "Um paciente de 50 anos tabagista, apresenta tosse crônica com expectoração mucoide, dispneia progressiva nos esforços e sibilância intermitente há vários anos. As provas de função pulmonar mostram relação VEF1/CVF < 0,7 pós-broncodilatador. Qual o diagnóstico MAIS provável?", options: ["Asma brônquica", "Fibrose pulmonar idiopática", "Doença Pulmonar Obstrutiva Crônica (DPOC)", "Bronquiectasias"], correctIndex: 2, explanation: "O histórico de tabagismo, tosse crônica, dispneia progressiva e o padrão obstrutivo irreversível na espirometria (VEF1/CVF < 0,7 pós-broncodilatador) são critérios diagnósticos para DPOC.", category: "Clínica Médica" },
  { id: 574, question: "Qual a principal causa de hemorragia digestiva alta em pacientes com cirrose hepática e hipertensão portal?", options: ["Úlcera péptica", "Esofagite de refluxo", "Varizes esofágicas", "Angiodisplasia"], correctIndex: 2, explanation: "As varizes esofágicas, decorrentes da hipertensão portal em pacientes cirróticos, são a causa mais comum e grave de hemorragia digestiva alta neste grupo, com alta morbidade e mortalidade.", category: "Clínica Médica" },
  { id: 575, question: "Conforme o Sistema Único de Saúde (SUS), qual é a vacina contra influenza mais indicada para a população geral em campanha anual?", options: ["Vacina Inativada Trivalente (Fragmentada)", "Vacina Atenuada Trivalente", "Vacina Tetravalente Recombinante", "Vacina Adjuvada Trivalente"], correctIndex: 0, explanation: "O SUS tradicionalmente utiliza a vacina influenza inativada trivalente (fragmentada) para a campanha anual de vacinação da população geral, abrangendo as cepas H1N1, H3N2 e um tipo B.", category: "Clínica Médica" },
  { id: 576, question: "Um paciente com diagnóstico recente de embolia pulmonar estável hemodinamicamente deve iniciar qual tipo de terapia ANITICOAGULANTE?", options: ["Varfarina isolada", "Heparina de baixo peso molecular (HBPM) ou fondaparinux, seguido por um anticoagulante oral (Vitamina K antagonistas ou DOACs).", "Apenas ácido acetilsalicílico", "Estreptocinase intravenosa"], correctIndex: 1, explanation: "O tratamento inicial da embolia pulmonar estável envolve anticoagulação parenteral (HBPM ou fondaparinux) seguido de terapia oral (antagonistas da vitamina K ou DOACs) para prevenção de recorrência a longo prazo.", category: "Clínica Médica" },
  { id: 577, question: "Qual a principal causa de pancreatite aguda no Brasil e no mundo ocidental?", options: ["Hipertrigliceridemia", "Alcoolismo e litíase biliar", "Medicamentos (ex: tiazídicos)", "Trauma abdominal"], correctIndex: 1, explanation: "A litíase biliar (cálculos na vesícula) e o etilismo são as duas principais causas de pancreatite aguda, respondendo pela vasta maioria dos casos tanto no Brasil quanto no ocidente.", category: "Clínica Médica" },
  { id: 578, question: "Um paciente em uso crônico de corticoide devido a uma doença autoimune apresenta-se com febre, tosse e infiltrados pulmonares difusos. A pesquisa de fungos revela a presença de Pneumocystis jirovecii. Qual profilaxia deveria ter sido instituída para prevenir esta infecção?", options: ["Profilaxia com isoniazida", "Profilaxia com aciclovir", "Profilaxia com sulfametoxazol-trimetoprim (SMX-TMP)", "Profilaxia com fluconazol"], correctIndex: 2, explanation: "Pacientes imunossuprimidos, especialmente em uso crônico de corticosteroides ou com outras condições como HIV/AIDS, devem receber profilaxia para Pneumocystis jirovecii (PCP) com sulfametoxazol-trimetoprim (SMX-TMP).", category: "Clínica Médica" },
  { id: 579, question: "Qual é a abordagem inicial MAIS adequada para o manejo de um paciente com crise tireotóxica (tempestade tireoidiana)?", options: ["Administrar levotiroxina intravenosa em altas doses.", "Prescrever um betabloqueador oral e aguardar a estabilização.", "Iniciar propiltiouracil (PTU) ou metimazol, iodo inorgânico, betabloqueador, corticosteroides e medidas de suporte intensivo.", "Apenas realizar tireoidectomia de emergência."], correctIndex: 2, explanation: "A crise tireotóxica é uma emergência e requer tratamento agressivo que inclui bloqueio da síntese hormonal (PTU/metimazol), bloqueio da liberação (iodo), controle dos sintomas adrenérgicos (betabloqueador), redução da conversão periférica de T4 para T3 (corticosteroides) e suporte geral.", category: "Clínica Médica" },
  { id: 580, question: "Qual das seguintes características é a MAIS indicativa de uma causa secundária de hipertensão arterial?", options: ["História familiar de hipertensão", "Diagnóstico de hipertensão em paciente idoso", "Hipertensão resistente a três ou mais anti-hipertensivos, incluindo um diurético, em doses máximas", "Hipertensão controlada com um único medicamento"], correctIndex: 2, explanation: "A hipertensão resistente (hipertensão não controlada apesar do uso de 3 anti-hipertensivos, um deles diurético, em doses máximas) é um forte indicador para investigação de causas secundárias de hipertensão.", category: "Clínica Médica" },
  { id: 581, question: "Um paciente de 25 anos apresenta anemia microcítica e hipocrômica, ferritina sérica baixa (<30 ng/mL) e saturação de transferrina reduzida. Qual o diagnóstico MAIS provável?", options: ["Anemia de doença crônica", "Talassemia minor", "Anemia ferropriva", "Anemia megaloblástica"], correctIndex: 2, explanation: "Os achados de anemia microcítica e hipocrômica, associados a ferritina baixa e saturação de transferrina reduzida, são clássicos da anemia ferropriva, que reflete a deficiência de ferro no organismo.", category: "Clínica Médica" },
  { id: 582, question: "Qual das seguintes vacinas é recomendada para adultos portadores de Diabetes Mellitus tipo 1 ou tipo 2, independentemente da idade?", options: ["Vacina contra HPV", "Vacina contra sarampo, caxumba e rubéola (SCR) em todas as idades", "Vacina antipneumocócica (PCV13 e PPSV23) e vacina contra influenza anualmente", "Apenas as vacinas de rotina da infância"], correctIndex: 2, explanation: "Pacientes com diabetes mellitus, devido ao risco aumentado de infecções e suas complicações, têm indicação prioritária para vacinação contra influenza anualmente e vacinas antipneumocócicas (PCV13 e PPSV23 em esquema sequencial), conforme as diretrizes do Ministério da Saúde.", category: "Clínica Médica" },
  { id: 583, question: "Um paciente de 55 anos, diabético tipo 2, hipertenso e dislipidêmico, é trazido ao pronto-socorro com dor torácica retroesternal opressiva há 30 minutos, irradiando para o braço esquerdo, acompanhada de sudorese e náuseas. O eletrocardiograma (ECG) inicial mostra supradesnivelamento do segmento ST em V1-V4. Qual a conduta inicial MAIS apropriada para este paciente no pronto-socorro, após o reconhecimento do IAMCSST?", options: ["Administração de oxigênio suplementar, vasodilatadores e beta-bloqueadores por via oral.", "AAS, clopidogrel (ou inibidor P2Y12 potente), heparina e encaminhamento para angioplastia primária.", "Morfina, nitratos sublinguais e avaliação para trombólise farmacológica.", "Apenas monitorização intensiva, aguardando exames laboratoriais como troponina para confirmação."], correctIndex: 1, explanation: "Em casos de IAMCSST, a conduta inicial deve incluir antiagregação plaquetária dupla (AAS + inibidor P2Y12), anticoagulação e o mais rápido encaminhamento para reperfusão, preferencialmente angioplastia primária. A reperfusão é tempo-dependente e essencial para minimizar o dano miocárdico.", category: "Clínica Médica" },
  { id: 584, question: "Uma mulher de 68 anos, com fibrilação atrial permanente e escore CHA2DS2-VASc de 4, apresenta-se com um INR de 0,9 em uso de varfarina. Refere alguns episódios recentes de tontura e dispneia leve. Qual a conduta MAIS adequada em relação à anticoagulação?", options: ["Aumentar a dose de varfarina e solicitar novo INR em 24h.", "Manter a dose de varfarina e reavaliar o paciente em uma semana.", "Suspender a varfarina e iniciar um anticoagulante oral direto (DOAC).", "Administrar heparina de baixo peso molecular, ajustar a varfarina e monitorar o INR."], correctIndex: 3, explanation: "Com um INR sub-terapêutico em paciente de alto risco para AVC isquêmico devido à FA, é fundamental ajustar a varfarina para um INR alvo entre 2-3 e considerar a ponte com heparina de baixo peso molecular enquanto o INR não atinge o alvo terapêutico.", category: "Clínica Médica" },
  { id: 585, question: "Paciente de 45 anos, sexo masculino, previamente hígido, procura o pronto-socorro com tosse seca persistente há 3 semanas, perda ponderal de 5kg e febre vespertina. A radiografia de tórax revela infiltrado parenquimatoso em lobo superior direito com provável cavitação. A principal hipótese diagnóstica e a conduta inicial são, respectivamente:", options: ["Pneumonia bacteriana comunitária; iniciar amoxicilina-clavulanato oral.", "Bronquiectasia infectada; solicitar tomografia de tórax de alta resolução.", "Tuberculose pulmonar; coletar escarro para baciloscopia e cultura, iniciar esquema RIPE.", "Neoplasia pulmonar; solicitar broncoscopia com biópsia."], correctIndex: 2, explanation: "A tríade de sintomas (tosse, febre vespertina, perda ponderal) e o achado radiográfico (infiltrado com cavitação em lobo superior) são altamente sugestivos de tuberculose pulmonar. A confirmação é feita pela baciloscopia ou cultura de escarro, e o tratamento padrão é o esquema RIPE.", category: "Clínica Médica" },
  { id: 586, question: "Um paciente de 70 anos é internado com exacerbação de DPOC. Apresenta dispneia intensa, uso de musculatura acessória, frequência respiratória de 30 irpm e SpO2 de 88% em ar ambiente. O paciente está consciente e cooperativo. Qual a conduta ventilatória INICIAL MAIS apropriada para este paciente?", options: ["Intubação orotraqueal e ventilação mecânica invasiva.", "Oxigenoterapia de alto fluxo por cateter nasal.", "Ventilação não invasiva (VNI) com pressão positiva.", "Oxigenoterapia com máscara simples e reavaliação em 30 minutos."], correctIndex: 2, explanation: "Em pacientes com exacerbação grave de DPOC, a ventilação não invasiva (VNI) com pressão positiva é a modalidade preferencial. Reduz a necessidade de intubação, mortalidade e tempo de internação, desde que o paciente esteja consciente e hemodinamicamente estável.", category: "Clínica Médica" },
  { id: 587, question: "Um paciente de 35 anos, previamente hígido, apresenta quadro de poliúria, polidipsia e polifagia há 2 meses, com perda ponderal significativa. Exames laboratoriais revelam glicemia de jejum de 280 mg/dL e HbA1c de 11%. Nega história familiar de diabetes. Qual o diagnóstico MAIS provável e a conduta inicial?", options: ["Diabetes Mellitus tipo 2; iniciar metformina.", "Diabetes Mellitus tipo 1; iniciar insulinoterapia.", "Diabetes LADA (Latent Autoimmune Diabetes in Adults); iniciar insulinoterapia.", "Diabetes Mellitus tipo MODY (Maturity Onset Diabetes of the Young); exames genéticos e observação."], correctIndex: 1, explanation: "Nesse cenário, a apresentação clássica (poliúria, polidipsia, polifagia, perda ponderal em paciente jovem e sem história familiar) sugere Diabetes Mellitus tipo 1. A insulinoterapia é o tratamento inicial indispensável para controlar a hiperglicemia e prevenir cetoacidose diabética.", category: "Clínica Médica" },
  { id: 588, question: "Qual dos seguintes achados eletrocardiográficos é considerado um critério maior para o diagnóstico de Hipertrofia Ventricular Esquerda (HVE) pelos critérios de Sokolow-Lyon em adultos?", options: ["S em V1 + R em V5 ou V6 ≥ 35 mm.", "R em aVL ≥ 11 mm.", "Onda T invertida em V5-V6.", "Duração do QRS > 0,12 segundos."], correctIndex: 0, explanation: "O critério de Sokolow-Lyon para Hipertrofia Ventricular Esquerda define HVE quando a soma da amplitude da onda S em V1 com a amplitude da onda R em V5 ou V6 é maior ou igual a 35 mm.", category: "Clínica Médica" },
  { id: 589, question: "Um paciente de 60 anos, com história de etilismo crônico, é admitido com icterícia, dor abdominal em hipocôndrio direito, febre e alteração do nível de consciência. Os exames laboratoriais revelam bilirrubinas elevadas (direta predominantemente), FA/GGT altas e leucocitose. Qual a principal hipótese diagnóstica?", options: ["Hepatite alcoólica.", "Colangite aguda.", "Pancreatite aguda.", "Hepatocarcinoma."], correctIndex: 1, explanation: "A tríade de Charcot (icterícia, dor em hipocôndrio direito, febre) associada à hipotensão e alteração do nível de consciência (Pêntade de Reynolds) é característica de colangite aguda grave, uma infecção das vias biliares.", category: "Clínica Médica" },
  { id: 590, question: "Em relação ao diagnóstico e tratamento da doença de Addison (insuficiência adrenal primária), qual das seguintes afirmações é CORRETA?", options: ["O teste de estímulo com ACTH (Cortrosina) demonstra níveis de cortisol normais ou elevados após a administração de ACTH.", "A principal causa é a adrenalite autoimune, levando à destruição bilateral do córtex adrenal.", "O tratamento baseia-se exclusivamente na reposição de glicocorticoides (ex: prednisona).", "A hiponatremia e hipercalemia são achados incomuns na doença de Addison."], correctIndex: 1, explanation: "A adrenalite autoimune é a causa mais comum de insuficiência adrenal primária. No teste com ACTH, espera-se uma resposta de cortisol baixa ou ausente. A hiponatremia e hipercalemia são achados esperados devido à deficiência de mineralocorticoides. O tratamento exige reposição de glico e mineralocorticoides.", category: "Clínica Médica" },
  { id: 591, question: "Paciente de 40 anos, sexo feminino, apresenta história de dor articular migratória em grandes articulações, lesões cutâneas eritematosas em face (rash malar), fadiga e febre ocasional. Exames laboratoriais mostram anemia, leucopenia e títulos elevados de anticorpos antinucleares (FAN) com padrão homogêneo. Qual a conduta inicial e o principal diagnóstico a ser considerado?", options: ["Artrite reumatoide; iniciar metotrexato.", "Lúpus Eritematoso Sistêmico (LES); encaminhar para reumatologista e considerar hidroxicloroquina.", "Fibromialgia; iniciar analgésicos e exercícios físicos.", "Gota; iniciar colchicina e alopurinol."], correctIndex: 1, explanation: "Os múltiplos sistemas envolvidos (articular, cutâneo, hematológico) e a presença de FAN positivo são altamente sugestivos de Lúpus Eritematoso Sistêmico. A hidroxicloroquina é a medicação de primeira linha para muitos casos de LES.", category: "Clínica Médica" },
  { id: 592, question: "Qual dos seguintes distúrbios hidroeletrolíticos é a complicação MAIS comum e grave da síndrome de lise tumoral espontânea ou induzida por quimioterapia?", options: ["Hipocalemia.", "Hipofosfatemia.", "Hipercalcemia.", "Hiperuricemia."], correctIndex: 3, explanation: "A lise tumoral libera grandes quantidades de componentes intracelulares, incluindo potássio, fosfato, e nucleotídeos. A quebra dos nucleotídeos resulta em aumento significativo dos níveis de ácido úrico (hiperuricemia), que pode levar à insuficiência renal aguda por formação de cristais.", category: "Clínica Médica" },
  { id: 593, question: "Um paciente de 72 anos apresenta dispneia progressiva, sibilos e tosse produtiva noturna há vários meses, com piora aos esforços. Tem história de tabagismo pesado por mais de 50 anos. A espirometria revela VEF1/CVF < 0,7 pós-broncodilatador e VEF1 < 50% do previsto. Qual o diagnóstico e a classificação de gravidade da DPOC (GOLD 2024)?", options: ["Asma; moderada.", "DPOC; muito grave.", "Bronquiectasias; grave.", "DPOC; grave."], correctIndex: 3, explanation: "A história de tabagismo e a espirometria com VEF1/CVF < 0,7 pós-broncodilatador confirmam o diagnóstico de DPOC. Com VEF1 < 50% do previsto, a classificação GOLD para gravidade da obstrução do fluxo aéreo é 'Grave'.", category: "Clínica Médica" },
  { id: 594, question: "Em um paciente com pneumonia adquirida na comunidade (PAC) sem fatores de risco para microrganismos resistentes, tratado ambulatorialmente, qual a terapia antibiótica de primeira linha RECOMENDADA pelas diretrizes brasileiras?", options: ["Ceftriaxona intravenosa.", "Azitromicina oral.", "Amoxicilina oral.", "Ciprofloxacino oral."], correctIndex: 2, explanation: "Para PAC em pacientes ambulatoriais sem comorbidades ou fatores de risco para resistência, a amoxicilina oral é a droga de escolha e a mais recomendada pelas diretrizes brasileiras, devido à sua eficácia e baixo custo.", category: "Clínica Médica" },
  { id: 595, question: "Qual a principal complicação cardiovascular da doença renal crônica?", options: ["Miocardite infecciosa.", "Pericardite constritiva.", "Aterosclerose e doença arterial coronariana acelerada.", "Cardiomiopatia restritiva."], correctIndex: 2, explanation: "Pacientes com doença renal crônica apresentam risco significativamente aumentado de aterosclerose acelerada e doença cardiovascular, sendo a principal causa de morbimortalidade nesta população. Fatores como inflamação, estresse oxidativo e distúrbios do metabolismo mineral contribuem para essa condição.", category: "Clínica Médica" },
  { id: 596, question: "Um paciente de 48 anos apresenta cefaleia súbita e intensa, seguida de perda de consciência em casa. Ao chegar ao pronto-socorro, está com Glasgow 8, hemiparesia à direita e rigidez de nuca. Qual o exame de imagem INICIAL essencial para guiar a conduta?", options: ["Ressonância Magnética encefálica com angio-RM.", "Tomografia Computadorizada de crânio sem contraste.", "Angiografia cerebral digital.", "Tomografia Computadorizada de crânio com contraste."], correctIndex: 1, explanation: "A história (cefaleia súbita, perda de consciência, rigidez de nuca) sugere hemorragia subaracnoidea. A TC de crânio sem contraste é o método de imagem inicial mais rápido para detectar sangramento e é crucial para o diagnóstico e manejo emergencial.", category: "Clínica Médica" },
  { id: 597, question: "Qual o principal efeito adverso que limita o uso da estatina em altas doses?", options: ["Hipertensão arterial.", "Insuficiência renal aguda.", "Miálgia e rabdomiólise.", "Hipoglicemia."], correctIndex: 2, explanation: "As miopatias, que variam de mialgia leve a rabdomiólise grave (com elevação de CK e potencial para IRA), são o efeito adverso mais frequente e preocupante das estatinas, especialmente em altas doses.", category: "Clínica Médica" },
  { id: 598, question: "Um paciente de 65 anos é diagnosticado com câncer de cólon metastático. Apresenta perda de peso progressiva, astenia e dor abdominal. Qual abordagem terapêutica, além do tratamento específico do câncer, é fundamental para melhorar a qualidade de vida e o bem-estar do paciente?", options: ["Apenas tratamento paliativo com opioides.", "Quimioterapia em altas doses para retardar a progressão.", "Cuidados paliativos integrados, incluindo controle de sintomas e suporte psicossocial.", "Dietas restritivas para evitar a progressão tumoral."], correctIndex: 2, explanation: "Em pacientes com câncer avançado, os cuidados paliativos têm um papel crucial no manejo dos sintomas, suporte psicossocial e planejamento de cuidados, visando a melhoria da qualidade de vida, independentemente da terapia oncológica específica.", category: "Clínica Médica" },
  { id: 599, question: "Qual a medida terapêutica de escolha para o tratamento da doença do refluxo gastroesofágico (DRGE) leve a moderada, sem esofagite erosiva grave?", options: ["Bloqueadores de receptores H2 (ex: ranitidina).", "Antiácidos de venda livre.", "Inibidores de bomba de prótons (IBP) (ex: omeprazol).", "Procinéticos (ex: domperidona)."], correctIndex: 2, explanation: "Os IBPs são a terapia mais eficaz para o tratamento da DRGE, proporcionando alívio dos sintomas e cicatrização da esofagite, mesmo em casos de doença leve a moderada. Eles são superiores aos bloqueadores H2 e antiácidos na supressão ácida.", category: "Clínica Médica" },
  { id: 600, question: "Um paciente de 50 anos desenvolve edema de membros inferiores, ascite, icterícia e encefalopatia hepática. Exames revelam albumina sérica de 2,0 g/dL, INR de 1,8, bilirrubina total de 4,5 mg/dL. Qual escore prognóstico é mais adequado para classificar a gravidade da disfunção hepática, e qual a provável classificação?", options: ["Child-Pugh; C.", "MELD; <10.", "Glasgow; 15.", "NYHA; IV."], correctIndex: 0, explanation: "O escore de Child-Pugh avalia a gravidade da cirrose hepática com base em bilirrubina, albumina, INR, ascite e encefalopatia. A presença de ascite, encefalopatia e alteração dos exames sugere um Child-Pugh C (cirrose descompensada grave).", category: "Clínica Médica" },
  { id: 601, question: "Qual é a principal indicação para o uso de betabloqueadores em pacientes com insuficiência cardíaca com fração de ejeção reduzida (ICFEr)?", options: ["Aumentar a contratilidade miocárdica.", "Reduzir a frequência cardíaca para controlar a dispneia.", "Bloquear a atividade do sistema nervoso simpático, melhorando a sobrevida e reduzindo hospitalizações.", "Tratar arritmias ventriculares agudas."], correctIndex: 2, explanation: "Betabloqueadores, como carvedilol, metoprolol succinato e bisoprolol, são fundamentais no tratamento da ICFEr pois, ao bloquear a hiperativação simpática crônica, melhoram a função ventricular, reduzem a progressão da doença, hospitalizações e mortalidade.", category: "Clínica Médica" },
  { id: 602, question: "Um paciente de 28 anos, previamente hígido, apresenta quadro de diarreia aquosa e mucossanguinolenta há mais de 6 semanas, acompanhada de dor abdominal tipo cólica, febre e perda ponderal. A colonoscopia revela inflamação contínua e ulcerada da mucosa do cólon, iniciando no reto. Qual o diagnóstico MAIS provável?", options: ["Doença de Crohn.", "Retocolite Ulcerativa (RCU).", "Síndrome do Intestino Irritável.", "Colite infecciosa por Clostridioides difficile."], correctIndex: 1, explanation: "A apresentação clínica (diarreia mucossanguinolenta, dor, perda de peso) e os achados endoscópicos (inflamação contínua, ulcerada e iniciando no reto) são clássicos da retocolite ulcerativa. A doença de Crohn geralmente afeta qualquer parte do TGI e tem distribuição segmentar.", category: "Clínica Médica" },
  { id: 603, question: "Qual das seguintes condições representa uma contraindicação ABSOLUTA ao uso de estreptoquinase para fibrinólise em um paciente com infarto agudo do miocárdio com supradesnivelamento do segmento ST (IAMCSST)?", options: ["Idade avançada (>75 anos).", "História prévia de acidente vascular cerebral isquêmico há mais de 3 meses.", "Trauma craniano ou AVC hemorrágico prévio (a qualquer momento).", "Hipertensão arterial sistêmica não controlada (PA > 180/110 mmHg) na chegada."], correctIndex: 2, explanation: "Qualquer histórico de AVC hemorrágico ou trauma craniano grave é uma contraindicação absoluta à terapia fibrinolítica devido ao risco inaceitável de hemorragia intracraniana. A HAS não controlada é uma contraindicação relativa.", category: "Clínica Médica" },
  { id: 604, question: "Um paciente de 60 anos, tabagista e etilista crônico, com histórico de síncopes recorrentes, apresenta eletrólitos séricos: Sódio 125 mEq/L, Potássio 3,0 mEq/L, Glicemia 110 mg/dL. O paciente está normovolêmico no exame físico. Qual a principal causa da hiponatremia neste contexto?", options: ["Insuficiência adrenal.", "Síndrome de Secreção Inapropriada de Hormônio Antidiurético (SIADH).", "Diabetes insipidus.", "Insuficiência cardíaca descompensada."], correctIndex: 1, explanation: "Diante de um paciente normovolêmico com hiponatremia e hipocalemia, especialmente com histórico de síncopes (que podem ser convulsivas, indicando uma doença neurológica de base), a SIADH é a causa mais provável, muitas vezes associada a distúrbios pulmonares ou neoplasias.", category: "Clínica Médica" },
  { id: 605, question: "Qual é a principal manifestação clínica que diferencia um paciente com doença de Graves (hipertireoidismo autoimune) de outras causas de tireotoxicose?", options: ["Perda de peso.", "Nervosismo e taquicardia.", "Oftalmopatia e mixedema pré-tibial.", "Intolerância ao calor e sudorese."], correctIndex: 2, explanation: "A oftalmopatia (exoftalmia, retração palpebral) e o mixedema pré-tibial são manifestações infiltrativas autoimunes específicas da Doença de Graves, não presentes em outras causas de hipertireoidismo.", category: "Clínica Médica" },
  { id: 606, question: "Qual medicação é a primeira linha para o tratamento da hipertensão arterial em pacientes diabéticos tipo 2 com albuminúria, devido aos seus efeitos reno e cardioprotetores?", options: ["Diuréticos tiazídicos (ex: hidroclorotiazida).", "Bloqueadores dos canais de cálcio (ex: anlodipino).", "Inibidores da enzima conversora de angiotensina (IECA) ou Bloqueadores de Receptores de Angiotensina (BRA).", "Betabloqueadores (ex: atenolol)."], correctIndex: 2, explanation: "IECA e BRA são as classes de medicamentos de primeira escolha para o tratamento da hipertensão em pacientes diabéticos com albuminúria. Eles demonstram não apenas controle da pressão arterial, mas também proteção renal e cardiovascular, retardando a progressão da nefropatia diabética.", category: "Clínica Médica" },
  { id: 607, question: "Um paciente de 75 anos, em investigação de anemia, apresenta hemoglobina de 8,5 g/dL, VCM 72 fL (microcítica), RDW elevado e ferro sérico baixo, com ferritina sérica de 12 ng/mL (baixo). Qual a principal hipótese diagnóstica para esta anemia?", options: ["Anemia de doença crônica.", "Anemia ferropriva.", "Talassemias.", "Anemia sideroblástica."], correctIndex: 1, explanation: "O padrão de anemia microcítica e hipocrômica (VCM baixo), associado a ferro sérico e ferritina baixos, que é o principal marcador dos estoques de ferro, é diagnóstico de anemia ferropriva. O RDW elevado é um achado comum neste tipo de anemia.", category: "Clínica Médica" },
  { id: 608, question: "Um paciente de 45 anos, previamente hígido, comparece ao pronto-socorro com dor abdominal periumbilical que migrou para a fossa ilíaca direita (FID) há 12 horas. Apresenta náuseas e um episódio de vômito. Ao exame físico, temperatura de 37,8°C, dor à palpação profunda em FID com descompressão brusca dolorosa positiva. Qual o diagnóstico mais provável e a conduta inicial mais adequada?", options: ["Apendicite aguda; Laparotomia exploradora.", "Diverticulite aguda; Tomografia computadorizada (TC) de abdome com contraste.", "Apendicite aguda; Laparoscopia exploradora.", "Urolitíase; Analgesia e ultrassonografia de vias urinárias."], correctIndex: 2, explanation: "O quadro clínico é classicamente de apendicite aguda. A laparoscopia exploradora é o tratamento de escolha, sendo diagnóstica e terapêutica, especialmente em casos duvidosos ou em mulheres em idade fértil.", category: "Cirurgia" },
  { id: 609, question: "Em um paciente vítima de trauma abdominal fechado que chega ao pronto-socorro instável hemodinamicamente (PAS < 90 mmHg), qual o exame complementar preferencial a ser realizado na sala de emergência, após a estabilização inicial com reposição volêmica?", options: ["Tomografia computadorizada (TC) de abdome com contraste.", "Ultrassonografia abdominal (FAST - Focused Assessment with Sonography for Trauma).", "Laparoscopia exploradora.", "Radiografia de abdome em pé."], correctIndex: 1, explanation: "O FAST é o exame inicial de escolha para pacientes traumatizados instáveis, permitindo identificar rapidamente a presença de líquido livre na cavidade abdominal (indicativo de hemorragia), direcionando para a laparotomia exploradora.", category: "Cirurgia" },
  { id: 610, question: "Qual das seguintes condições representa uma contraindicação ABSOLUTA para a realização de colecistectomia laparoscópica?", options: ["Coagulopatia grave não corrigível.", "Gravidez no primeiro trimestre.", "Cirurgias abdominais prévias com múltiplas aderências.", "Obesidade mórbida."], correctIndex: 0, explanation: "Coagulopatias graves não corrigíveis aumentam significativamente o risco de sangramento e complicações hemorrágicas durante e após a cirurgia, tornando a abordagem laparoscópica contraindicada em favor de uma correção prévia ou, se necessário, cirurgia aberta.", category: "Cirurgia" },
  { id: 611, question: "Uma paciente de 60 anos, com história de colelitíase, apresenta dor em hipocôndrio direito, icterícia e febre. O ultrassom de abdome revela dilatação de vias biliares e coledocolitíase. Qual a conduta mais apropriada para esta paciente?", options: ["Colecistectomia laparoscópica eletiva após melhora dos sintomas.", "Colangiopancreatografia retrógrada endoscópica (CPRE) de urgência seguida ou não de colecistectomia.", "Antibioticoterapia e observação, com avaliação cirúrgica posterior.", "Realizar ressonância magnética de vias biliares (CPRM) e, se confirmar coledocolitíase, colecistectomia."], correctIndex: 1, explanation: "O quadro é sugestivo de colangite aguda, uma emergência cirúrgica biliar que requer drenagem urgente da via biliar principal. A CPRE é o método de escolha para desobstrução e drenagem, seguida da colecistectomia após controle da infecção.", category: "Cirurgia" },
  { id: 612, question: "Qual o principal agente etiológico associado à peritonite terciária?", options: ["Escherichia coli.", "Staphylococcus aureus resistente à meticilina (MRSA).", "Candida albicans.", "Streptococcus pyogenes."], correctIndex: 2, explanation: "A peritonite terciária é a persistência ou recorrência da infecção peritoneal após tratamento adequado da peritonite secundária, sendo frequentemente causada por patógenos nosocomiais, como fungos (principalmente Candida albicans) e bactérias multirresistentes.", category: "Cirurgia" },
  { id: 613, question: "Um paciente de 70 anos, com histórico de doença diverticular dos cólons, chega ao pronto-socorro com dor em fossa ilíaca esquerda, febre e leucocitose. A tomografia computadorizada de abdome evidencia diverticulite aguda não complicada. Qual a conduta inicial mais adequada?", options: ["Antibioticoterapia intravenosa e internação hospitalar.", "Colectomia de urgência.", "Dieta zero e observação domiciliar.", "Antibioticoterapia oral e tratamento ambulatorial."], correctIndex: 3, explanation: "Para diverticulite aguda não complicada, em pacientes sem sinais de sepse ou imunocomprometimento, o tratamento pode ser ambulatorial com dieta líquida (ou conforme tolerância), analgesia e antibioticoterapia oral.", category: "Cirurgia" },
  { id: 614, question: "Qual a principal causa de hemorragia digestiva alta varicosa?", options: ["Úlcera péptica gástrica.", "Varizes esofágicas por hipertensão portal.", "Síndrome de Mallory-Weiss.", "Angiodisplasia."], correctIndex: 1, explanation: "A principal causa de hemorragia digestiva alta varicosa são as varizes esofágicas, que são uma complicação grave da hipertensão portal, frequentemente decorrente de cirrose hepática.", category: "Cirurgia" },
  { id: 615, question: "No manejo do choque hipovolêmico em um paciente adulto vítima de trauma grave, qual a principal indicação para a transfusão de hemoderivados (concentrado de hemácias)?", options: ["Pressão arterial sistólica (PAS) < 120 mmHg.", "Nível de hemoglobina < 10 g/dL.", "Sinais de hipoperfusão tecidual (acidose metabólica, lactato elevado).", "Débito urinário > 0,5 mL/kg/h."], correctIndex: 2, explanation: "A transfusão de concentrado de hemácias é indicada quando há sinais de hipoperfusão tecidual associados à hemorragia significativa, independentemente de um valor absoluto de hemoglobina inicial, visando restaurar a capacidade de transporte de oxigênio.", category: "Cirurgia" },
  { id: 616, question: "Qual técnica cirúrgica é mais comumente utilizada para o tratamento definitivo da hérnia inguinal, com menor taxa de recorrência, em adultos?", options: ["Técnica de Bassini.", "Técnica de Shouldice.", "Técnica de Lichtenstein com tela.", "Técnica de McVay."], correctIndex: 2, explanation: "A herniorrafia de Lichtenstein com tela é a técnica mais utilizada mundialmente para reparo de hérnias inguinais em adultos, devido à sua simplicidade, eficácia e baixa taxa de recorrência.", category: "Cirurgia" },
  { id: 617, question: "Um paciente com diagnóstico de câncer gástrico é submetido a uma gastrectomia total e linfadenectomia D2. Qual a principal complicação nutricional a longo prazo que deve ser monitorada rigorosamente neste paciente?", options: ["Hiponatremia.", "Deficiência de vitamina B12.", "Hipercalemia.", "Deficiência de vitamina D."], correctIndex: 1, explanation: "A gastrectomia total remove as células parietais que produzem o fator intrínseco, essencial para a absorção da vitamina B12. A deficiência desta vitamina leva a anemia megaloblástica e neuropatias, necessitando de suplementação vitalícia.", category: "Cirurgia" },
  { id: 618, question: "No contexto da síndrome de Fournier, qual a principal abordagem terapêutica, além da antibioticoterapia de amplo espectro?", options: ["Drenagem percutânea de coleções.", "Debridamento cirúrgico agressivo e precoce.", "Oxigenoterapia hiperbárica isolada.", "Colostomia de proteção exclusivamente."], correctIndex: 1, explanation: "A síndrome de Fournier é uma fasciíte necrosante do períneo, uma emergência cirúrgica que exige debridamento cirúrgico agressivo e precoce de todo o tecido necrosado, além da antibioticoterapia, para controlar a infecção fulminante.", category: "Cirurgia" },
  { id: 619, question: "Qual a principal complicação precoce e mais temida da esofagectomia trans-hiatal ou transtorácica?", options: ["Estenose da anastomose.", "Fístula da anastomose esofágica.", "Refluxo gastroesofágico.", "Infecção do sítio cirúrgico."], correctIndex: 1, explanation: "A fístula da anastomose esofágica é a complicação mais grave e temida da esofagectomia, associada a alta morbidade e mortalidade devido à mediastinite e sepse que pode causar.", category: "Cirurgia" },
  { id: 620, question: "Um paciente de 55 anos apresenta dor abdominal difusa, distensão, ausência de eliminação de flatos e fezes há 3 dias. Radiografia de abdome mostra alças de delgado e cólon dilatadas com múltiplos níveis hidroaéreos. Qual a provável etiologia em um paciente com cirurgia abdominal prévia (apendicectomia)?", options: ["Volvulo de sigmoide.", "Íleo paralítico.", "Obstrução intestinal por bridas aderenciais.", "Doença de Crohn em atividade."], correctIndex: 2, explanation: "Em pacientes com história de cirurgias abdominais prévias, a obstrução intestinal por bridas aderenciais é a causa mais comum de oclusão do intestino delgado, levando ao quadro descrito.", category: "Cirurgia" },
  { id: 621, question: "Em pacientes com pancreatite aguda grave com necrose infectada, qual a principal indicação para intervenção cirúrgica?", options: ["Drenagem de pseudocisto pancreático assintomático.", "Colecistectomia profilática para prevenir novas crises.", "Sinais de síndrome da resposta inflamatória sistêmica (SIRS) persistente.", "Confirmação de infecção da necrose por cultura de material obtido por punção percutânea."], correctIndex: 3, explanation: "A intervenção cirúrgica (necrosectomia) em pancreatite aguda grave é indicada principalmente na presença de necrose infectada, confirmada por cultura, e deve ser postergada o máximo possível para permitir a demarcação da necrose.", category: "Cirurgia" },
  { id: 622, question: "Qual das seguintes afirmações sobre a dor em cólica biliar (colelitíase sintomática) está INCORRETA?", options: ["É geralmente desencadeada por refeições gordurosas.", "É uma dor contínua e constante que dura várias horas.", "Pode irradiar para o ombro direito ou dorso.", "É causada pela contração da vesícula biliar contra um cálculo impactado no ducto cístico."], correctIndex: 1, explanation: "A dor em cólica biliar, embora intensa, apresenta um caráter de flutuação na intensidade (cólica) e geralmente dura de 30 minutos a poucas horas, não sendo contínua e constante por várias horas como a dor inflamatória.", category: "Cirurgia" },
  { id: 623, question: "A Síndrome de Whipple é uma condição que afeta principalmente qual parte do trato gastrointestinal?", options: ["Estômago.", "Intestino delgado.", "Cólon.", "Esôfago."], correctIndex: 1, explanation: "A Síndrome de Whipple é uma doença rara causada pela bactéria Tropheryma whipplei, que afeta principalmente o intestino delgado, levando à má absorção e sintomas sistêmicos.", category: "Cirurgia" },
  { id: 624, question: "Qual a principal indicação para o uso de octreotide no tratamento da fístula pancreática?", options: ["Estimular a secreção de enzimas pancreáticas.", "Reduzir o débito da fístula por inibição da secreção pancreática.", "Promover a cicatrização do trajeto fistuloso.", "Prevenir a infecção do fluido da fístula."], correctIndex: 1, explanation: "O octreotide, um análogo da somatostatina, inibe a secreção pancreática de fluidos e enzimas, o que pode ajudar a reduzir o débito de fístulas pancreáticas, facilitando seu fechamento espontâneo.", category: "Cirurgia" },
  { id: 625, question: "Um paciente é submetido a uma tireoidectomia total por carcinoma papilífero de tireoide. Qual a principal complicação pós-operatória que deve ser monitorada nos primeiros dias?", options: ["Hipertireoidismo.", "Hipocalcemia sintomática.", "Hipernatremia.", "Paralisia de prega vocal por lesão de nervo laríngeo superior."], correctIndex: 1, explanation: "A complicação mais comum e importante após tireoidectomia total é a hipocalcemia, devido a lesão ou ressecção acidental das glândulas paratireoides, que regulam o metabolismo do cálcio.", category: "Cirurgia" },
  { id: 626, question: "No tratamento de queimaduras de segundo grau profundo e terceiro grau extensas, qual a principal indicação para a realização de enxertos de pele?", options: ["Prevenir a desidratação primária da ferida.", "Acelerar a reepitelização e fechar a ferida de forma permanente.", "Reduzir a dor e o desconforto do paciente.", "Minimizar o risco de edema e compartimento."], correctIndex: 1, explanation: "Os enxertos de pele são essenciais para fechar permanentemente as feridas de queimaduras profundas que não cicatrizarão espontaneamente, prevenindo infecções, reduzindo a dor e acelerando a recuperação funcional.", category: "Cirurgia" },
  { id: 627, question: "Qual o principal critério para se considerar um paciente com traumatismo cranioencefálico (TCE) como 'grave'?", options: ["Contusão cerebral ao exame de imagem.", "Escala de Coma de Glasgow (ECG) entre 9 e 12.", "Escala de Coma de Glasgow (ECG) menor ou igual a 8.", "Fratura de crânio linear sem rebaixamento de nível de consciência."], correctIndex: 2, explanation: "O TCE é classificado como grave quando a Escala de Coma de Glasgow (ECG) é menor ou igual a 8, indicando um alto risco de lesão cerebral significativa e desfechos desfavoráveis.", category: "Cirurgia" },
  { id: 628, question: "Um paciente de 40 anos apresenta um nódulo tireoidiano palpável. A ultrassonografia mostra um nódulo sólido, hipoecoico, com microcalcificações e margens irregulares. A punção aspirativa por agulha fina (PAAF) resultou em Bethesda V. Qual a conduta cirúrgica mais recomendada?", options: ["Lobectomia unilateral da tireoide.", "Tireoidectomia total.", "Acompanhamento e nova PAAF em 6 meses.", "Terapia com iodo radioativo isolada."], correctIndex: 1, explanation: "A categoria Bethesda V indica suspeita de malignidade, e os achados ultrassonográficos são de alto risco. Nesses casos, especialmente para nódulos acima de 1 cm ou multifocais, a tireoidectomia total é frequentemente indicada para o tratamento do carcinoma papilífero.", category: "Cirurgia" },
  { id: 629, question: "No tratamento da úlcera péptica perfurada, qual a principal conduta cirúrgica, em um paciente estável hemodinamicamente?", options: ["Vagotomia e piloroplastia.", "Ressecção gástrica a Billroth I.", "Rafia da perfuração com omento.", "Gastrectomia total."], correctIndex: 2, explanation: "A rafia simples da perfuração com omento (Manobra de Graham) é a técnica mais comum e segura para úlcera péptica perfurada em pacientes estáveis, com o objetivo de selar a perfuração e controlar a peritonite.", category: "Cirurgia" },
  { id: 630, question: "Qual dos seguintes parâmetros é o MAIS importante para indicar uma reanimação volêmica agressiva em um paciente queimado?", options: ["Peso corporal do paciente.", "Área de superfície corporal queimada (ABSC) em porcentagem.", "Profundidade das queimaduras.", "Presença de lesões associadas."], correctIndex: 1, explanation: "A porcentagem da Área de Superfície Corporal Queimada (ABSC) é o parâmetro mais importante para guiar a reanimação volêmica inicial em pacientes queimados, pois determina a quantidade de fluido a ser administrada (fórmula de Parkland).", category: "Cirurgia" },
  { id: 631, question: "A principal indicação para cirurgia no tratamento da doença do refluxo gastroesofágico (DRGE) é:", options: ["Falha do tratamento clínico com inibidores da bomba de prótons (IBP) em dose dupla.", "Presença de esôfago de Barrett em biópsia.", "Episódios frequentes de regurgitação noturna.", "Uso de IBP por mais de 6 meses."], correctIndex: 0, explanation: "A falha do tratamento clínico otimizado (IBP em dose adequada, ajustes de estilo de vida) é a principal indicação para a cirurgia antirrefluxo (fundoplicatura) na DRGE, visando controlar os sintomas e prevenir complicações.", category: "Cirurgia" },
  { id: 632, question: "Um paciente politraumatizado, após estabilização inicial, apresenta dor intensa em crônica abdominal, distensão, sinais de irritação peritoneal e hipotensão persistente. A laparotomia exploradora revela mais de 1000 mL de sangue livre na cavidade. Qual órgão tem maior probabilidade de ser a fonte desse sangramento em um trauma abdominal fechado?", options: ["Pâncreas.", "Intestino delgado.", "Baço.", "Rim."], correctIndex: 2, explanation: "Em traumas abdominais fechados, o baço é o órgão mais frequentemente lesado e a principal fonte de sangramento significativo, dada sua localização e vascularização, levando a grande quantidade de hemoperitônio.", category: "Cirurgia" },
  { id: 633, question: "Em relação à colecistite aguda, assinale a alternativa CORRETA:", options: ["A colecistectomia deve ser postergada para após a resolução do quadro inflamatório agudo.", "A dor típica é em hipocôndrio esquerdo com irradiação para o ombro esquerdo.", "O sinal de Murphy é patognomônico, mas sua ausência exclui o diagnóstico.", "A colecistectomia laparoscópica precoce (nas primeiras 72 horas) é a conduta de escolha para a maioria dos pacientes."], correctIndex: 3, explanation: "A colecistectomia laparoscópica precoce (geralmente dentro de 72 horas do início dos sintomas) é a conduta de escolha para a colecistite aguda, apresentando melhores resultados e menores taxas de complicação.", category: "Cirurgia" },
  { id: 634, question: "Um homem de 70 anos, com história de diverticulite aguda prévia, apresenta-se no pronto-socorro com dor em quadrante inferior esquerdo, febre (38,5°C) e leucocitose. A tomografia computadorizada abdominal revela diverticulite aguda com um abscesso pericólico de 3 cm. Qual a conduta mais adequada neste caso?", options: ["Drenagem percutânea do abscesso e antibioticoterapia.", "Colectomia segmentar de urgência.", "Antibioticoterapia oral e acompanhamento ambulatorial.", "Observação clínica e analgesia apenas."], correctIndex: 0, explanation: "Diverticulite aguda com abscesso < 4-5 cm, sem sinais de peritonite difusa, é geralmente tratada com drenagem percutânea (se tecnicamente viável) e antibioticoterapia intravenosa, evitando cirurgia de urgência.", category: "Cirurgia" },
  { id: 635, question: "Qual das seguintes condições é uma indicação absoluta para cirurgia imediata em pacientes com doença inflamatória intestinal (Doença de Crohn ou Retocolite Ulcerativa)?", options: ["Proctite leve refratária ao tratamento tópico.", "Estenose assintomática em íleo terminal.", "Megacólon tóxico.", "Atividade inflamatória moderada em exame endoscópico."], correctIndex: 2, explanation: "O megacólon tóxico é uma complicação grave da doença inflamatória intestinal, representando uma emergência cirúrgica devido ao alto risco de perfuração e sepse.", category: "Cirurgia" },
  { id: 636, question: "Em relação à hérnia inguinal indireta, qual das seguintes afirmações está CORRETA?", options: ["É mais comum em mulheres.", "Sua formação está relacionada a uma fraqueza adquirida da parede abdominal posterior.", "O saco herniário medializa-se aos vasos epigástricos inferiores.", "É congênita e resulta da persistência do processo vaginal."], correctIndex: 3, explanation: "A hérnia inguinal indireta é congênita e resulta da persistência do processo vaginal, que é uma evaginação do peritônio que acompanha o testículo em sua descida.", category: "Cirurgia" },
  { id: 637, question: "Um paciente de 60 anos com história de cirurgia prévia por apendicite há 20 anos apresenta dor abdominal tipo cólica, distensão abdominal progressiva e vômitos biliosos. Ao exame, abdome distendido, timpânico, com ruídos hidroaéreos aumentados e de tonalidade metálica. A radiografia de abdome revela alças delgadas dilatadas com níveis hidroaéreos. Qual é o diagnóstico mais provável?", options: ["Isquemia mesentérica aguda.", "Íleo paralítico.", "Obstrução intestinal por bridas.", "Perfuração de víscera oca."], correctIndex: 2, explanation: "O quadro clínico de dor tipo cólica, distensão, vômitos e ruídos hidroaéreos aumentados, em paciente com cirurgia abdominal prévia, é altamente sugestivo de obstrução intestinal por bridas.", category: "Cirurgia" },
  { id: 638, question: "No manejo inicial do paciente politraumatizado, o que deve ser priorizado conforme o protocolo ATLS?", options: ["Realização de tomografia computadorizada de corpo inteiro.", "Controle definitivo das fraturas de fêmur e pelve.", "Avaliação e tratamento de lesões com risco imediato de vida, seguindo a sequência ABCDE.", "Coleta de exames laboratoriais completos."], correctIndex: 2, explanation: "O protocolo ATLS prioriza a avaliação e tratamento das lesões que representam risco imediato para a vida do paciente, seguindo a sequência padronizada de A (via aérea), B (respiração), C (circulação), D (disfunção neurológica) e E (exposição/controle do ambiente).", category: "Cirurgia" },
  { id: 639, question: "Qual dos seguintes achados na ultrassonografia de abdome é mais sugestivo de apendicite aguda?", options: ["Coleção líquida na fossa ilíaca direita.", "Diâmetro do apêndice cecal superior a 6 mm, não compressível, com parede espessada e presença de apendicolito.", "Presença de líquido livre na cavidade abdominal.", "Espessamento difuso da parede do íleo terminal."], correctIndex: 1, explanation: "O critério ultrassonográfico mais confiável para apendicite aguda é um apêndice não compressível, com diâmetro maior que 6 mm, parede espessada, e frequentemente com presença de apendicolito.", category: "Cirurgia" },
  { id: 640, question: "Em pacientes com choque hipovolêmico por hemorragia aguda, qual o tipo de fluido preferencial para a ressuscitação inicial?", options: ["Solução de glicose a 5%.", "Plasma fresco congelado.", "Cristaloides isotônicos (ex: Ringer Lactato ou soro fisiológico 0,9%).", "Albumina."], correctIndex: 2, explanation: "As diretrizes atuais preconizam o uso de cristaloides isotônicos (Ringer Lactato ou soro fisiológico) como primeira escolha para a ressuscitação volêmica inicial em choque hipovolêmico hemorrágico.", category: "Cirurgia" },
  { id: 641, question: "Um paciente submetido a gastrectomia total para tratamento de adenocarcinoma gástrico deve receber, no pós-operatório tardio, suplementação contínua de qual vitamina?", options: ["Vitamina C.", "Vitamina D.", "Vitamina B12.", "Vitamina K."], correctIndex: 2, explanation: "Após gastrectomia total, há uma deficiência de fator intrínseco, essencial para a absorção da vitamina B12, tornando sua suplementação contínua indispensável para prevenir anemia megaloblástica e déficits neurológicos.", category: "Cirurgia" },
  { id: 642, question: "Qual a principal causa de colelitíase (cálculos biliares) na população geral?", options: ["Cálculos de bilirrubinato de cálcio.", "Cálculos de pigmento puro.", "Cálculos mistos (predominantemente de colesterol).", "Cálculos de carbonato de cálcio."], correctIndex: 2, explanation: "A maioria dos cálculos biliares (aproximadamente 80%) é composta predominantemente por colesterol, sendo classificados como cálculos mistos ou de colesterol.", category: "Cirurgia" },
  { id: 643, question: "A icterícia obstrutiva geralmente cursa com qual característica laboratorial?", options: ["Aumento predomínante da bilirrubina indireta.", "Enzimas hepáticas (ALT/AST) marcadamente elevadas.", "Fosfatase alcalina e Gama-glutamiltransferase (GGT) elevadas.", "Teste de Coombs direto positivo."], correctIndex: 2, explanation: "Na icterícia obstrutiva, há uma elevação das enzimas de colestase, como a fosfatase alcalina e a GGT, devido ao acúmulo de bile e hepatotoxicidade.", category: "Cirurgia" },
  { id: 644, question: "Qual a principal indicação cirúrgica para refluxo gastroesofágico (DRGE) refratário ao tratamento clínico?", options: ["Esôfago de Barrett sem displasia.", "Presença de hérnia de hiato tipo I (deslizamento) sintomática.", "Falha no tratamento clínico otimizado (inibidores de bomba de prótons) e documentação de refluxo patológico.", "Ulcerações esofágicas leves."], correctIndex: 2, explanation: "A cirurgia antirrefluxo (fundoplicatura) é indicada principalmente em pacientes com DRGE refratária ao tratamento clínico otimizado com IBP, com evidência objetiva de refluxo ácido patológico.", category: "Cirurgia" },
  { id: 645, question: "Em pacientes com choque séptico, qual o objetivo principal da antibioticoterapia?", options: ["Reduzir a inflamação sistêmica.", "Erradicar a flora bacteriana normal do paciente.", "Cobrir o maior número de bactérias possível para evitar resistência.", "Iniciar precocemente, com antibióticos de amplo espectro, após coleta de culturas, visando ao foco infeccioso."], correctIndex: 3, explanation: "A antibioticoterapia no choque séptico deve ser iniciada de forma precoce, geralmente com agentes de amplo espectro, após coleta de culturas, e posteriormente ajustada com base nos resultados e na identificação do foco infeccioso.", category: "Cirurgia" },
  { id: 646, question: "Qual das seguintes cirurgias é mais associada à síndrome de dumping?", options: ["Apendicectomia.", "Colecistectomia.", "Gastrectomia subtotal com reconstrução a Billroth II.", "Hérniorrafia inguinal."], correctIndex: 2, explanation: "A síndrome de dumping é uma complicação comum de cirurgias gástricas que alteram a velocidade do esvaziamento gástrico, como a gastrectomia subtotal com Billroth II, onde o alimento chega rapidamente ao intestino delgado.", category: "Cirurgia" },
  { id: 647, question: "Um paciente apresenta-se com um nódulo tireoidiano palpável. Qual das seguintes características sugere maior risco de malignidade?", options: ["Nódulo com múltiplos focos císticos à ultrassonografia.", "Nódulo único, duro, fixo e de crescimento rápido.", "Nódulo predominantemente hipoecoico com microcalcificações.", "Nódulo com bordas regulares e halo hipoecoico completo."], correctIndex: 2, explanation: "Nódulos tireoidianos com microcalcificações, hipoecogenicidade e bordas irregulares à ultrassonografia são características altamente sugestivas de malignidade e indicam a necessidade de punção aspirativa por agulha fina (PAAF).", category: "Cirurgia" },
  { id: 648, question: "Qual a principal causa de perfuração de úlcera péptica duodenal?", options: ["Infecção por Helicobacter pylori.", "Uso crônico de anti-inflamatórios não esteroides (AINEs).", "Síndrome de Zollinger-Ellison.", "Estresse fisiológico em pacientes internados."], correctIndex: 1, explanation: "Embora a H. pylori seja a principal causa de úlcera péptica, o uso crônico de AINEs é a principal causa evitável de úlceras complicadas, incluindo perfuração, devido à inibição da cicloxigenase (COX) e redução da proteção da mucosa gástrica e duodenal.", category: "Cirurgia" },
  { id: 649, question: "No diagnóstico e manejo de pneumotórax hipertensivo, qual a conduta de emergência inicial mais apropriada?", options: ["Intubação orotraqueal e ventilação mecânica com pressão positiva.", "Toracostomia de alívio por agulha no 2º espaço intercostal, linha hemiclavicular.", "Drenagem torácica com selo d'água imediata.", "Radiografia de tórax para confirmação diagnóstica."], correctIndex: 1, explanation: "O pneumotórax hipertensivo é uma emergência médica que requer descompressão imediata. A toracostomia de alívio por agulha é a medida inicial para descompressão, antes da drenagem torácica definitiva, pois o diagnóstico é clínico.", category: "Cirurgia" },
  { id: 650, question: "Qual das seguintes opções é uma complicação tardia comum da cirurgia bariátrica (especialmente bypass gástrico em Y de Roux)?", options: ["Deiscência de anastomose.", "Fístula anastomótica.", "Obstrução intestinal por hérnia interna.", "Trombose venosa profunda."], correctIndex: 2, explanation: "Hérnias internas são uma complicação tardia significativa após bypass gástrico em Y de Roux, ocorrendo devido à criação de espaços virtuais por onde alças intestinais podem se herniar.", category: "Cirurgia" },
  { id: 651, question: "Um paciente idoso apresenta-se com quadro de dor abdominal difusa, distensão, ausência de eliminação de flatos e fezes, e imagem de grande dilatação colônica no enema opaco. O diagnóstico provável é de volvo de sigmoide. Qual a conduta inicial mais adequada na ausência de sinais de peritonite?", options: ["Colectomia de urgência.", "Redução endoscópica (desimpactação) com colonoscopia e colocação de sonda retal.", "Laparotomia exploradora imediata.", "Antibioticoterapia intravenosa de amplo espectro por 7 dias."], correctIndex: 1, explanation: "Em casos de volvo de sigmoide sem sinais de complicação (perfuração, isquemia), a conduta inicial de escolha é a desimpactação colonoscópica, que pode resolver a torção e desobstruir o intestino.", category: "Cirurgia" },
  { id: 652, question: "Qual das seguintes opções NÃO é uma característica da síndrome de Fournier?", options: ["Fasciite necrotizante de etiologia polimicrobiana.", "Afeta predominantemente a região perineal e genital.", "Geralmente associada a diabetes mellitus e imunossupressão.", "Evolução lenta e indolente, geralmente autolimitada."], correctIndex: 3, explanation: "A síndrome de Fournier é uma infecção grave e progressiva, de rápida evolução, caracterizada por fasciite necrotizante que afeta a região perineal, genital e perianal. Não é lenta nem autolimitada.", category: "Cirurgia" },
  { id: 653, question: "Em um paciente com doença diverticular do cólon, qual a indicação primária para cirurgia eletiva após um episódio de diverticulite aguda não complicada?", options: ["Primeiro episódio de diverticulite aguda.", "Presença de divertículos múltiplos e assintomáticos.", "Episódios recorrentes de diverticulite aguda complicada ou não, ou falha no tratamento clínico.", "Idade avançada do paciente."], correctIndex: 2, explanation: "A indicação primária de cirurgia eletiva para diverticulite é a ocorrência de episódios recorrentes, especialmente se forem complicados, ou refratariedade ao tratamento clínico, impactando a qualidade de vida do paciente.", category: "Cirurgia" },
  { id: 654, question: "Qual o principal critério para indicação de cirurgia de urgência em paciente com abdome agudo por obstrução intestinal?", options: ["Aumento da distensão abdominal progressiva.", "Presença de febre.", "Sinais de estrangulamento ou isquemia intestinal (peritonite, leucocitose com desvio, dor desproporcional).", "Vômitos persistentes."], correctIndex: 2, explanation: "A presença de sinais de estrangulamento ou isquemia intestinal, como peritonite, dor desproporcional, leucocitose marcada, é a principal indicação para cirurgia de urgência em obstrução intestinal, devido ao risco de necrose e perfuração.", category: "Cirurgia" },
  { id: 655, question: "Em relação à cirurgia de reparo de hérnias da parede abdominal (herniorrafia), qual o princípio fundamental para a prevenção de recorrência?", options: ["Utilização exclusiva de sutura, sem tela prostética.", "Reparo sem tensão (tension-free) com uso de tela.", "Limitação do tamanho da incisão cirúrgica.", "Repouso absoluto prolongado no pós-operatório."], correctIndex: 1, explanation: "O princípio fundamental para a prevenção de recorrência em herniorrafias é o reparo sem tensão, que é geralmente alcançado com o uso de tela prostética para reforçar a parede abdominal, em vez de apenas suturar os tecidos sob tensão.", category: "Cirurgia" },
  { id: 656, question: "A principal abordagem terapêutica para um paciente com um cisto hidático hepático complicado (ex: roto em vias biliares ou infectado) é:", options: ["Tratamento clínico com albendazol e observação.", "Drenagem percutânea guiada por imagem sem cirurgia.", "Cirurgia (pericystectomia total ou parcial) associada a tratamento medicamentoso.", "Transplante hepático."], correctIndex: 2, explanation: "Cistos hidáticos hepáticos complicados geralmente requerem tratamento cirúrgico (pericystectomia total ou parcial) para remover o cisto e prevenir recorrências, associado à terapêutica antiparasitária com albendazol.", category: "Cirurgia" },
  { id: 657, question: "Primigesta, 28 anos, comparece ao pronto-socorro com queixa de dor súbita e intensa em hipogástrio, sangramento vaginal discreto e hipotensão arterial. Ao exame físico, útero hiper-tônico, doloroso e feto com bradicardia acentuada. Qual o diagnóstico mais provável?", options: ["Descolamento prematuro de placenta (DPP)", "Placenta prévia total", "Rotura uterina", "Vasa prévia"], correctIndex: 0, explanation: "O quadro clássico de dor súbita intensa, sangramento, hiper-tonia uterina e sofrimento fetal agudo é sugestivo de descolamento prematuro de placenta. A hipotensão reflete a perda sanguínea oculta no útero.", category: "Ginecologia e Obstetrícia" },
  { id: 658, question: "Uma paciente de 35 anos, nulípara, busca atendimento por irregularidade menstrual e sangramento uterino anormal. O ultrassom revela útero aumentado de volume, contornos irregulares e múltiplos nódulos com características sugestivas de miomas. Qual a conduta inicial mais apropriada para esta paciente com miomas sintomáticos?", options: ["Indicação de histerectomia imediata", "Prescrição de análogos do GnRH", "Observação e acompanhamento sem intervenção", "Embolização de artérias uterinas"], correctIndex: 1, explanation: "Análogos do GnRH são frequentemente utilizados no tratamento de miomas sintomáticos para reduzir seu volume e controlar o sangramento, especialmente antes de uma cirurgia ou para mulheres que desejam preservar o útero.", category: "Ginecologia e Obstetrícia" },
  { id: 659, question: "Qual das seguintes infecções sexualmente transmissíveis (IST) é causada por um protozoário e tem como principal sintoma corrimento vaginal amarelado-esverdeado, bolhoso e com odor fétido?", options: ["Vaginose bacteriana", "Candidíase vulvovaginal", "Tricomoníase", "Clamídia"], correctIndex: 2, explanation: "A tricomoníase é causada pelo protozoário Trichomonas vaginalis e classicamente se manifesta com corrimento vaginal amarelado-esverdeado, bolhoso, pruriginoso e com odor fétido ('cheiro de peixe').", category: "Ginecologia e Obstetrícia" },
  { id: 660, question: "Puérpera, 24 anos, no 5º dia pós-parto, com história de febre, dor abdominal e sangramento vaginal fétido. Ao exame físico, útero doloroso à palpação e subinvoluído. Qual a principal hipótese diagnóstica?", options: ["Mastite", "Endometrite puerperal", "Trombose venosa profunda", "Cistite"], correctIndex: 1, explanation: "A endometrite puerperal é a principal causa de febre no pós-parto, associada a dor abdominal, útero subinvoluído e lóquios fétidos. É uma infecção do endométrio após o parto.", category: "Ginecologia e Obstetrícia" },
  { id: 661, question: "Qual é a principal indicação para o uso de sulfato de magnésio na gestação?", options: ["Aceleração da maturidade pulmonar fetal", "Tratamento da infecção urinária", "Neuroproteção fetal em prematuros e prevenção/tratamento de convulsões na pré-eclâmpsia grave/eclâmpsia", "Indução do trabalho de parto"], correctIndex: 2, explanation: "O sulfato de magnésio é amplamente utilizado em obstetrícia para neuroproteção fetal em partos prematuros (abaixo de 32 semanas) e como anticonvulsivante na pré-eclâmpsia grave e eclâmpsia.", category: "Ginecologia e Obstetrícia" },
  { id: 662, question: "Mulher de 52 anos, menopausada há 3 anos, apresenta sangramento vaginal. O que deve ser investigado prioritariamente?", options: ["Atrofia vaginal", "Pólipo endometrial", "Câncer de endométrio", "Miomas uterinos"], correctIndex: 2, explanation: "Em mulheres menopausadas, qualquer sangramento vaginal deve ser considerado câncer de endométrio até prova em contrário, exigindo investigação diagnóstica imediata (geralmente biópsia endometrial).", category: "Ginecologia e Obstetrícia" },
  { id: 663, question: "Qual é o principal fator de risco para o câncer de colo de útero?", options: ["Tabagismo", "Obesidade", "Infecção persistente por Papilomavírus Humano (HPV) de alto risco", "Múltiplas gestações"], correctIndex: 2, explanation: "A infecção persistente por tipos oncogênicos do Papilomavírus Humano (HPV) é o fator de risco mais importante e necessário para o desenvolvimento do câncer de colo uterino.", category: "Ginecologia e Obstetrícia" },
  { id: 664, question: "Gestante, 32 semanas, é diagnosticada com diabetes gestacional após curva glicêmica. Qual a principal conduta inicial para o manejo desta condição?", options: ["Início imediato de insulina", "Internação hospitalar para monitoramento", "Dieta e atividade física orientadas", "Indução do parto nas próximas semanas"], correctIndex: 2, explanation: "A primeira linha de tratamento para diabetes gestacional é a terapia nutricional e a prática de atividade física regular. Se as metas glicêmicas não forem atingidas, a insulinoterapia é iniciada.", category: "Ginecologia e Obstetrícia" },
  { id: 665, question: "Qual método contraceptivo possui maior eficácia na prevenção da gravidez?", options: ["Preservativo masculino", "Pílula anticoncepcional oral combinada", "Dispositivo intrauterino (DIU) de cobre", "Diafragma"], correctIndex: 2, explanation: "Os métodos contraceptivos mais eficazes são os de longa duração e reversíveis (LARC), como o DIU de cobre e o DIU hormonal, devido às suas altas taxas de continuidade e baixa variação de eficácia ligada ao uso habitual.", category: "Ginecologia e Obstetrícia" },
  { id: 666, question: "Paciente de 25 anos, com ciclos menstruais irregulares, acne, hirsutismo e obesidade. Qual a principal hipótese diagnóstica?", options: ["Endometriose", "Síndrome dos Ovários Policísticos (SOP)", "Insuficiência ovariana prematura", "Hiperprolactinemia"], correctIndex: 1, explanation: "A Síndrome dos Ovários Policísticos (SOP) se caracteriza por hiperandrogenismo (clínico ou laboratorial), disfunção ovulatória (oligo ou anovulação) e ovários de aspecto policístico ao ultrassom, explicando os sintomas apresentados.", category: "Ginecologia e Obstetrícia" },
  { id: 667, question: "Qual a principal causa de hemorragia pós-parto imediata (nas primeiras 24 horas)?", options: ["Atonia uterina", "Retenção de restos placentários", "Lacerações do trato genital", "Coagulopatias"], correctIndex: 0, explanation: "A atonia uterina é a principal causa de hemorragia pós-parto imediata, sendo responsável por aproximadamente 80% dos casos de sangramento excessivo nas primeiras 24 horas após o parto.", category: "Ginecologia e Obstetrícia" },
  { id: 668, question: "Em relação à dor pélvica crônica, qual das seguintes condições é caracterizada pela presença de tecido endometrial fora da cavidade uterina?", options: ["Adenomiose", "Miomatose uterina", "Endometriose", "Doença inflamatória pélvica (DIP)"], correctIndex: 2, explanation: "Endometriose é a doença ginecológica caracterizada pela presença de glândulas e estroma endometriais fora da cavidade uterina, causando dor pélvica crônica, dismenorreia e infertilidade.", category: "Ginecologia e Obstetrícia" },
  { id: 669, question: "Uma gestante de 39 semanas, com diagnóstico de ruptura prematura de membranas prolongada (mais de 18 horas), e febre. Qual a complicação mais provável e conduta indicada?", options: ["Corioamnionite - Iniciar antibióticos e induzir o parto", "Infeccção urinária - Tratar com antibióticos orais e observar", "Descolamento prematuro de placenta - Realizar histerectomia", "Pré-eclâmpsia - Monitorar pressão arterial e proteína na urina"], correctIndex: 0, explanation: "Ruptura prematura de membranas prolongada, associada à febre, é forte indicativo de corioamnionite. A conduta é antibioticoterapia de largo espectro e interrupção da gestação para evitar sepse materno-fetal.", category: "Ginecologia e Obstetrícia" },
  { id: 670, question: "Qual o principal critério para o diagnóstico de trabalho de parto ativo?", options: ["Contração uterina a cada 10 minutos", "Dilatação cervical de 2 cm", "Dilatação cervical de 6 cm ou mais", "Bolsa amniótica rota"], correctIndex: 2, explanation: "O trabalho de parto ativo é definido pela presença de contrações uterinas regulares e modificações cervicais, sendo a dilatação cervical de 6 cm ou mais o marco para sua definição, conforme as diretrizes atuais.", category: "Ginecologia e Obstetrícia" },
  { id: 671, question: "Paciente de 40 anos, com história de três abortamentos espontâneos consecutivos no primeiro trimestre. Qual alteração etiológica deve ser investigada prioritariamente?", options: ["Diabetes mellitus descompensado", "Miomas uterinos", "Síndrome dos anticorpos antifosfolípides (SAAF)", "Cervicite crônica"], correctIndex: 2, explanation: "Abortamentos de repetição, especialmente no primeiro trimestre, devem levantar a suspeita de Síndrome dos Anticorpos Antifosfolípides (SAAF), uma causa importante de trombofilias e perdas gestacionais.", category: "Ginecologia e Obstetrícia" },
  { id: 672, question: "Qual a principal complicação do uso prolongado de terapia hormonal na menopausa (estrogênio+progestagênio)?", options: ["Osteoporose", "Câncer de colo de útero", "Eventos tromboembólicos e aumento do risco de câncer de mama", "Atrofia vaginal"], correctIndex: 2, explanation: "O uso prolongado da terapia hormonal combinada na menopausa está associado a um aumento do risco de eventos tromboembólicos (TEV) e um risco ligeiramente maior de câncer de mama.", category: "Ginecologia e Obstetrícia" },
  { id: 673, question: "Qual o principal critério para diferenciar hemorragia uterina anormal (HUA) PALM de COEIN?", options: ["A presença ou ausência de dor", "A faixa etária da paciente", "A etiologia estrutural ou não estrutural", "A intensidade do sangramento"], correctIndex: 2, explanation: "A classificação PALM-COEIN divide as causas de HUA em estruturais (PALM: Pólipo, Adenomiose, Leiomioma, Malignidade e Hiperplasia) e não estruturais (COEIN: Coagulopatia, Ovulatória, Endometrial, Iatrogênica e Não classificada).", category: "Ginecologia e Obstetrícia" },
  { id: 674, question: "Gestante com 36 semanas, apresentando queixa de cefaleia intensa, epigastralgia, escotomas cintilantes e pressão arterial 160/110 mmHg. O exame de urina revela proteinúria ++. Qual a conduta urgente adequada?", options: ["Repouso absoluto e acompanhamento ambulatorial semanal", "Internação hospitalar, uso de sulfato de magnésio e avaliação para interrupção da gravidez", "Prescrição de analgésicos e anti-hipertensivos orais", "Realização de ultrassonografia com Doppler fetal"], correctIndex: 1, explanation: "O quadro é de pré-eclâmpsia grave, que exige internação imediata, administração de sulfato de magnésio para prevenção de convulsões (eclâmpsia) e avaliação da interrupção da gravidez, dada a idade gestacional.", category: "Ginecologia e Obstetrícia" },
  { id: 675, question: "Em um exame de Papanicolau, o resultado 'ASC-US' indica qual conduta inicial mais apropriada?", options: ["Repetir o Papanicolau após 3 anos", "Colposcopia imediata", "Repetição do exame em 6 a 12 meses ou teste de HPV", "Conização cervical"], correctIndex: 2, explanation: "ASC-US (Células Escamosas Atípicas de Significado Indeterminado) exige uma conduta mais próxima: repetição do exame em 6 a 12 meses ou realização do teste de HPV como forma de triagem e acompanhamento.", category: "Ginecologia e Obstetrícia" },
  { id: 676, question: "Qual o principal agente infeccioso associado à doença inflamatória pélvica (DIP)?", options: ["Vírus Herpes Simplex (HSV)", "Treponema pallidum", "Neisseria gonorrhoeae e Chlamydia trachomatis", "Gardnerella vaginalis"], correctIndex: 2, explanation: "Os principais agentes etiológicos da doença inflamatória pélvica (DIP) são as bactérias Neisseria gonorrhoeae e Chlamydia trachomatis, embora outras bactérias também possam estar envolvidas.", category: "Ginecologia e Obstetrícia" },
  { id: 677, question: "Primigesta, 32 anos, com gestação de 36 semanas e 2 dias, em consulta pré-natal. Refere cefaleia de forte intensidade, visão turva e epigastralgia há 2 dias. Apresenta pressão arterial de 160/110 mmHg, proteinúria de +3 na fita. Exames laboratoriais mostram plaquetas de 90.000/mm³, TGP 120 U/L, TGO 180 U/L. Qual a conduta obstétrica mais adequada para este caso?", options: ["Iniciar sulfato de magnésio, anti-hipertensivos e induzir o parto após estabilização materna.", "Internar para monitoramento e aguardar o tempo completo de 40 semanas para o parto.", "Realizar cesariana de emergência imediatamente, sem outra intervenção prévia.", "Administrar corticosteroides para maturação pulmonar fetal e reavaliar em 24 horas."], correctIndex: 0, explanation: "O quadro é de pré-eclâmpsia grave com sinais de iminência de eclâmpsia e síndrome HELLP. A conduta é estabilização materna com sulfato de magnésio (neuroproteção) e anti-hipertensivos, seguida da interrupção da gestação devido à gravidade.", category: "Ginecologia e Obstetrícia" },
  { id: 678, question: "Paciente, 28 anos, comparece ao pronto-socorro com dor em baixo ventre, sangramento vaginal discreto e amenorreia de 8 semanas. Beta-hCG positivo elevado. Ao exame físico, colo fechado, útero de tamanho um pouco aumentado, dor à mobilização do colo uterino. Ultrassonografia transvaginal revela útero vazio e massa anexial direita heterogênea. Qual o diagnóstico mais provável?", options: ["Gravidez ectópica rota.", "Abortamento incompleto.", "Cisto ovariano hemorrágico.", "Mola hidatiforme."], correctIndex: 0, explanation: "A tríade clássica de amenorreia, dor abdominal e sangramento vaginal, associada a útero vazio e massa anexial ao ultrassom, é altamente sugestiva de gravidez ectópica. A dor à mobilização do colo indica irritação peritoneal, e a massa heterogênea sugere sangramento.", category: "Ginecologia e Obstetrícia" },
  { id: 679, question: "Uma puérpera, 30 anos, no 5º dia pós-parto vaginal, apresenta febre de 38,5°C, dor em baixo ventre, útero subinvoluído e doloroso à palpação, e lóquios fétidos. Qual a causa provável e o tratamento inicial mais adequado?", options: ["Endometrite puerperal; iniciar antibioticoterapia empírica com clindamicina e gentamicina.", "Infecção urinária; solicitar urinocultura e iniciar ciprofloxacino oral.", "Mastite puerperal; orientar amamentação e iniciar dicloxacilina.", "Tromboflebite pélvica séptica; anticoagulação e antibioticoterapia ampla."], correctIndex: 0, explanation: "Os sintomas (febre, dor abdominal, útero subinvoluído e lóquios fétidos no pós-parto) são característicos de endometrite puerperal. O tratamento de escolha é antibioticoterapia intravenosa de amplo espectro, sendo clindamicina e gentamicina a combinação mais comum.", category: "Ginecologia e Obstetrícia" },
  { id: 680, question: "Paciente, 45 anos, G3P3, refere sangramento uterino anormal há 6 meses, com ciclos menstruais irregulares e intensos. Nega uso de anticoncepcionais. Ultrassonografia transvaginal mostra útero de dimensões normais, endométrio espessado (15 mm) e cisto ovariano simples de 3 cm. Biópsia de endométrio é indicada para excluir qual condição?", options: ["Hiperplasia endometrial com atipias ou câncer de endométrio.", "Miomatose uterina submucosa.", "Pólipo endometrial.", "Adenomiose."], correctIndex: 0, explanation: "Em mulheres acima dos 40 anos com sangramento uterino anormal e espessamento endometrial (especialmente > 12 mm), a principal preocupação é a hiperplasia endometrial com atipias ou o câncer de endométrio, indicando biópsia para diagnóstico histopatológico.", category: "Ginecologia e Obstetrícia" },
  { id: 681, question: "Qual a principal complicação aguda mais temida e de maior risco de vida associada ao uso de DIU de cobre?", options: ["Perfuração uterina durante a inserção.", "Doença inflamatória pélvica.", "Gestação ectópica.", "Expulsão do DIU."], correctIndex: 0, explanation: "A perfuração uterina é a complicação aguda mais grave e de maior risco durante a inserção do DIU, podendo levar a danos viscerais e hemorragia. As demais são complicações importantes, mas geralmente com menor risco de vida imediato.", category: "Ginecologia e Obstetrícia" },
  { id: 682, question: "Paciente, 25 anos, com ciclos menstruais irregulares, obesidade, hirsutismo e acne. Exames hormonais revelam testosterona elevada e LH/FSH > 2:1. Ultrassonografia pélvica mostra ovários com múltiplos cistos periféricos. Qual o diagnóstico mais provável?", options: ["Síndrome dos Ovários Policísticos (SOP).", "Hiperprolactinemia.", "Insuficiência ovariana prematura.", "Tumor produtor de androgênios."], correctIndex: 0, explanation: "O quadro clínico e laboratorial (anovulação crônica, hiperandrogenismo clínico/laboratorial, ovários policísticos ao ultrassom) preenche os critérios de Rotterdam para o diagnóstico da Síndrome dos Ovários Policísticos (SOP).", category: "Ginecologia e Obstetrícia" },
  { id: 683, question: "Qual a principal vantagem da amamentação materna exclusiva nos primeiros seis meses de vida para a saúde do recém-nascido?", options: ["Proteção contra infecções gastrointestinais e respiratórias.", "Diminuição do risco de alergias alimentares na fase adulta.", "Desenvolvimento cognitivo superior em comparação com fórmula láctea.", "Redução da incidência de diabetes tipo 2."], correctIndex: 0, explanation: "O leite materno contém anticorpos, células imunológicas e outros fatores que conferem proteção importante contra infecções, especialmente as gastrointestinais e respiratórias, sendo a principal vantagem da amamentação.", category: "Ginecologia e Obstetrícia" },
  { id: 684, question: "Gestante, 38 semanas, apresenta bolsa rota há duas horas, líquido amniótico claro. Não apresenta contrações. Qual a conduta inicial mais apropriada?", options: ["Internar, monitorar vitalidade fetal e avaliar indução do parto.", "Realizar cesariana de emergência para evitar infecção.", "Aguarda-se o início espontâneo do trabalho de parto em ambiente domiciliar.", "Administrar tocolíticos para prolongar a gestação."], correctIndex: 0, explanation: "Em gestação a termo com bolsa rota e feto a termo, a conduta é a internação, monitoramento fetal e avaliação para indução do trabalho de parto, geralmente aguardando um período para o início espontâneo, ou induzindo se necessário, para prevenir infecções.", category: "Ginecologia e Obstetrícia" },
  { id: 685, question: "Em relação ao rastreamento do câncer de colo uterino no Brasil, qual a recomendação do Ministério da Saúde para mulheres na faixa etária de 25 a 64 anos, após dois exames citopatológicos negativos consecutivos com intervalo de um ano?", options: ["Repetição do exame citopatológico a cada três anos.", "Repetição anual do exame citopatológico.", "Interrupção do rastreamento se a mulher for monogâmica.", "Realização de teste de HPV como método primário."], correctIndex: 0, explanation: "A recomendação atual do Ministério da Saúde para rastreamento do câncer de colo uterino em mulheres de 25-64 anos é realizar o exame citopatológico a cada 3 anos, após dois exames negativos consecutivos com intervalo de um ano.", category: "Ginecologia e Obstetrícia" },
  { id: 686, question: "Qual dos seguintes métodos contraceptivos possui menor índice de falha (Índice de Pearl) no uso típico?", options: ["Implante subdérmico de etonogestrel.", "Pílula anticoncepcional oral combinada.", "Preservativo masculino.", "Método do calendário (tabelinha)."], correctIndex: 0, explanation: "Os métodos contraceptivos de longa ação reversível (LARCs), como o implante subdérmico, DIU hormonal e DIU de cobre, apresentam os menores índices de falha no uso típico, independentes da usuária.", category: "Ginecologia e Obstetrícia" },
  { id: 687, question: "Paciente, 35 anos, com queixa de dor pélvica crônica, dismenorreia intensa e dispareunia profunda. Ao exame físico, útero em retroversodesvio fixo e dor à palpação de ligamentos uterossacros. Ultrassonografia pélvica transvaginal com preparo intestinal mostra nódulos hipoecogênicos no septo retovaginal e ovário esquerdo. Qual o diagnóstico mais provável?", options: ["Endometriose profunda.", "Doença inflamatória pélvica crônica.", "Câncer de ovário avançado.", "Adenomiose."], correctIndex: 0, explanation: "A tríade de dismenorreia, dispareunia profunda e dor pélvica crônica, associada a achados de fixação uterina e nódulos no septo retovaginal, é altamente sugestiva de endometriose profunda.", category: "Ginecologia e Obstetrícia" },
  { id: 688, question: "Qual a principal indicação para o uso de misoprostol na Obstetrícia?", options: ["Indução do parto e tratamento de abortamento incompleto.", "Prevenção de pré-eclâmpsia em alto risco.", "Tratamento de infecção urinária na gestação.", "Uso como anticoncepcional de emergência."], correctIndex: 0, explanation: "O misoprostol é uma prostaglandina sintética amplamente utilizada em obstetrícia para indução do trabalho de parto e para o manejo de abortamento (incompleto, retido) e óbito fetal, devido à sua capacidade de amadurecer o colo e induzir contrações uterinas.", category: "Ginecologia e Obstetrícia" },
  { id: 689, question: "Em relação à cardiotocografia (CTG), qual achado é considerado mais preocupante e exige intervenção imediata?", options: ["Bradicardia fetal persistente e desacelerações tardias repetitivas.", "Linha de base de 130 bpm com variabilidade moderada e acelerações.", "Desacelerações variáveis ocasionais, sem relação com as contrações.", "Ausência de acelerações em 20 minutos de monitorização."], correctIndex: 0, explanation: "A bradicardia fetal persistente e as desacelerações tardias repetitivas são sinais de sofrimento fetal agudo e hipóxia, indicando a necessidade de intervenção rápida para evitar resultados adversos.", category: "Ginecologia e Obstetrícia" },
  { id: 690, question: "Qual o principal agente etiológico da sífilis congênita?", options: ["Treponema pallidum.", "Chlamydia trachomatis.", "Neisseria gonorrhoeae.", "Toxoplasma gondii."], correctIndex: 0, explanation: "A sífilis congênita é causada pela transmissão vertical do Treponema pallidum, a bactéria responsável pela sífilis, da mãe para o feto durante a gestação.", category: "Ginecologia e Obstetrícia" },
  { id: 691, question: "Qual a principal recomendação para o rastreamento do diabetes gestacional no Brasil?", options: ["Realização de teste de tolerância à glicose oral (TTGO 75g) entre 24 e 28 semanas de gestação para todas as gestantes.", "Rastreamento apenas em gestantes com fatores de risco (obesidade, histórico familiar).", "Medida apenas da glicemia de jejum no início do pré-natal.", "Realização de hemoglobina glicada (HbA1c) em todas as gestantes."], correctIndex: 0, explanation: "As diretrizes brasileiras recomendam o rastreamento universal do diabetes gestacional através do TTGO com 75g de glicose entre 24 e 28 semanas de gestação, independentemente dos fatores de risco.", category: "Ginecologia e Obstetrícia" },
  { id: 692, question: "Uma paciente, 62 anos, menopausada, apresenta sangramento vaginal. Nega uso de terapia hormonal. Qual a primeira linha de investigação a ser realizada para determinar a causa?", options: ["Ultrassonografia transvaginal e biópsia endometrial.", "Colposcopia com biópsia do colo uterino.", "Teste de gravidez e dosagem de beta-hCG.", "Exame de Papanicolau e dosagem de FSH."], correctIndex: 0, explanation: "Qualquer sangramento vaginal na pós-menopausa deve ser investigado agressivamente para excluir câncer de endométrio. A investigação inicial envolve ultrassonografia transvaginal para avaliar o endométrio e, se espessado, biópsia endometrial.", category: "Ginecologia e Obstetrícia" },
  { id: 693, question: "Qual medicamento é mais indicado para o manejo da náusea e vômitos da gravidez (hiperemese gravídica) que não respondem a medidas dietéticas e de estilo de vida?", options: ["Piridoxina (vitamina B6) isolada ou associada à doxilamina.", "Ondansetrona.", "Metoclopramida.", "Prometazina."], correctIndex: 0, explanation: "A piridoxina (vitamina B6) é a primeira linha de tratamento farmacológico para náuseas e vômitos na gravidez, frequentemente associada à doxilamina para maior eficácia, conforme diretrizes internacionais.", category: "Ginecologia e Obstetrícia" },
  { id: 694, question: "Em relação à mastite puerperal, qual a medida principal para o tratamento e prevenção de complicações, além da antibioticoterapia?", options: ["Continuação da amamentação ou esvaziamento da mama afetada.", "Interrupção total da amamentação.", "Compressas frias e repouso absoluto.", "Drenagem cirúrgica imediata da mama."], correctIndex: 0, explanation: "A continuação da amamentação ou o esvaziamento eficaz da mama afetada é crucial para desobstruir os ductos e acelerar a recuperação, além de prevenir a formação de abscesso, em conjunto com a antibioticoterapia.", category: "Ginecologia e Obstetrícia" },
  { id: 695, question: "Qual a principal causa de hemorragia pós-parto imediata?", options: ["Atonia uterina.", "Lacerações de trajeto.", "Retenção de restos placentários.", "Coagulopatias."], correctIndex: 0, explanation: "A atonia uterina é a causa mais comum (aproximadamente 70-80%) da hemorragia pós-parto imediata, devido à falha do útero em contrair adequadamente após a dequitação placentária.", category: "Ginecologia e Obstetrícia" },
  { id: 696, question: "Paciente, 22 anos, nuligesta, com relato de dispareunia superficial e hipertonia do assoalho pélvico. Ao exame ginecológico, apresenta dor intensa à tentativa de introdução do espéculo e contração involuntária da musculatura vaginal. Nega infecções ou alterações anatômicas. Qual o diagnóstico mais provável?", options: ["Vaginismo.", "Endometriose.", "Vestibulodinia provocada.", "Doença inflamatória pélvica."], correctIndex: 0, explanation: "O vaginismo é caracterizado por espasmos involuntários e recorrentes da musculatura vaginal circundante ao introito, interferindo na relação sexual ou exame ginecológico, causando dor e dificuldade de penetração.", category: "Ginecologia e Obstetrícia" },
  { id: 697, question: "Primigesta, 39 semanas, com diagnóstico de diabetes gestacional em uso de insulina, com feto em apresentação pélvica detectado no pré-natal. Qual a via de parto mais indicada neste caso?", options: ["Cesariana eletiva.", "Parto vaginal induzido.", "Parto vaginal espontâneo.", "Tentativa de versão cefálica externa."], correctIndex: 0, explanation: "A apresentação pélvica do feto a termo, especialmente em primigestas e com comorbidades maternas como diabetes gestacional, é uma indicação para cesariana eletiva devido ao maior risco de complicações no parto vaginal.", category: "Ginecologia e Obstetrícia" },
  { id: 698, question: "Em uma paciente com sangramento uterino anormal, a ultrassonografia transvaginal revela um pólipo endometrial. Qual a principal conduta terapêutica para resolver o sangramento e avaliar microscopicamente a lesão?", options: ["Histeroscopia com polipectomia.", "Tratamento hormonal com progestagênios.", "Ablação endometrial.", "Histerectomia."], correctIndex: 0, explanation: "A histeroscopia com polipectomia é o método de escolha para o tratamento dos pólipos endometriais sintomáticos, pois permite a visualização direta, remoção da lesão e envio para análise histopatológica.", category: "Ginecologia e Obstetrícia" },
  { id: 699, question: "Qual a principal função do hormônio Gonadotrofina Coriônica Humana (hCG) na gestação inicial?", options: ["Manter o corpo lúteo para produzir progesterona, essencial para a gravidez.", "Estimular o desenvolvimento dos folículos ovarianos.", "Induzir as contrações uterinas para o parto.", "Promover a maturação pulmonar fetal."], correctIndex: 0, explanation: "O hCG é produzido pelo trofoblasto e tem como principal função resgatar e manter o corpo lúteo gravídico, que por sua vez produz progesterona, hormônio fundamental para a manutenção da gestação até que a placenta assuma essa função.", category: "Ginecologia e Obstetrícia" },
  { id: 700, question: "Qual a classificação de Papanicolau que indica a presença de células escamosas atípicas de significado indeterminado, não sendo possível afastar lesão de alto grau (ASC-H)?", options: ["ASC-H.", "ASC-US.", "LSIL.", "HSIL."], correctIndex: 0, explanation: "ASC-H (Atypical Squamous Cells - Cannot Exclude HSIL) indica atipias celulares que não permitem afastar lesão intraepitelial de alto grau, necessitando de investigação mais aprofundada, como a colposcopia.", category: "Ginecologia e Obstetrícia" },
  { id: 701, question: "Qual das seguintes condições é uma contraindicação absoluta para o parto vaginal?", options: ["Placenta prévia total.", "Diabetes gestacional controlada com dieta.", "Gestação gemelar dicoriônica e diamniótica.", "Miomatose uterina sem obstrução do canal de parto."], correctIndex: 0, explanation: "A placenta prévia total (quando a placenta cobre completamente o orifício interno do colo uterino) é uma contraindicação absoluta ao parto vaginal devido ao risco de hemorragia maciça e incontrolável.", category: "Ginecologia e Obstetrícia" },
  { id: 702, question: "Primigesta, 32 anos, 38 semanas de idade gestacional, é admitida na maternidade com queixa de perda de líquido via vaginal há 4 horas. Apresenta contrações uterinas regulares e dolorosas a cada 5 minutos. Ao exame físico: dinâmica uterina 3 contrações em 10 minutos, colo uterino com 4 cm de dilatação, 80% de apagamento, bolsa rota com saída de líquido claro, apresentação cefálica -2 de DeLee. A conduta inicial mais apropriada é:", options: ["Iniciar ocitocina intravenosa para acelerar o trabalho de parto.", "Realizar cardiotocografia contínua para avaliação da vitalidade fetal.", "Administrar antibiótico profilático para evitar infecção intra-amniótica.", "Preparar para cesariana imediata devido à rotura prematura de membranas."], correctIndex: 1, explanation: "Em caso de trabalho de parto ativo com bolsa rota, a cardiotocografia contínua é essencial para monitorar a vitalidade fetal e identificar sofrimento, guiando as próximas condutas. A profilaxia antibiótica não é indicada de rotina na bolsa rota no termo.", category: "Ginecologia e Obstetrícia" },
  { id: 703, question: "Paciente, 65 anos, menopausa há 15 anos, procura atendimento ginecológico com queixa de sangramento vaginal intermitente, indolor. Relata não fazer terapia de reposição hormonal. Ao exame especular, observa-se atrofia vaginal e pequena quantidade de sangue no fundo de saco. O exame de Papanicolau recente foi negativo para malignidade. Qual o próximo passo na investigação para essa paciente?", options: ["Biópsia de endométrio por curetagem semiótica ou histeroscopia.", "Início de terapia de reposição hormonal para controle do sangramento.", "Ultrassonografia transvaginal para avaliar espessura endometrial.", "Repetição do Papanicolau em 6 meses."], correctIndex: 2, explanation: "Sangramento uterino pós-menopausa, mesmo com Papanicolau normal, deve ser investigado para neoplasia endometrial. A ultrassonografia transvaginal é o método de triagem inicial para avaliar a espessura endometrial, que guiará a necessidade de biópsia.", category: "Ginecologia e Obstetrícia" },
  { id: 704, question: "Uma gestante com diagnóstico de diabetes gestacional, controlada com dieta e exercícios, atinge 39 semanas de gestação. O índice de líquido amniótico é de 12 cm, e a biometria fetal está dentro da normalidade para a idade gestacional. Não há outras comorbidades. Qual a conduta obstétrica mais indicada neste momento?", options: ["Indução do trabalho de parto, pois o risco de macrossomia e complicações aumenta após 39 semanas.", "Monitoramento fetal intensivo e programação da cesariana para 40 semanas.", "Acompanhamento semanal com cardiotocografia e ultrassonografia, aguardando o início espontâneo do trabalho de parto.", "Início de insulinoterapia para otimizar o controle glicêmico antes do parto."], correctIndex: 0, explanation: "Gestantes com diabetes gestacional controladas sem uso de insulina devem ter o parto induzido entre 39 semanas e 39 semanas e 6 dias, devido ao risco aumentado de macrossomia e outras complicações, mesmo na ausência de achados adversos.", category: "Ginecologia e Obstetrícia" },
  { id: 705, question: "Qual das seguintes características histopatológicas é mais sugestiva de adenomiose?", options: ["Células endometriais atípicas infiltrando o endométrio.", "Presença de glândulas e estroma endometrial no miométrio, com hipertrofia do músculo liso adjacente.", "Focos de endométrio ectópico no peritônio pélvico.", "Proliferação de células do estroma endometrial sem glândulas atípicas."], correctIndex: 1, explanation: "Adenomiose é caracterizada pela presença de glândulas e estroma endometrial dentro do miométrio, penetrando a camada muscular pelo menos 2,5 mm, frequentemente associada à hipertrofia do músculo liso adjacente.", category: "Ginecologia e Obstetrícia" },
  { id: 706, question: "Jovem, 22 anos, busca atendimento com queixa de amenorreia primária. Apresenta desenvolvimento de caracteres sexuais secundários (mamas e pelos pubianos). Ao exame físico, observa-se genitália externa feminina normal e ausência de útero e porção superior da vagina. Cariótipo 46,XX. A hipótese diagnóstica mais provável é:", options: ["Síndrome de Turner.", "Síndrome de insensibilidade androgênica completa.", "Agenesia mülleriana (Síndrome de Mayer-Rokitansky-Küster-Hauser).", "Hipotireoidismo congênito."], correctIndex: 2, explanation: "A Síndrome de Mayer-Rokitansky-Küster-Hauser é caracterizada por anomalias do desenvolvimento mülleriano, resultando em agenesia vaginal e uterina na presença de ovários funcionantes e cariótipo 46,XX, com desenvolvimento normal dos caracteres sexuais secundários.", category: "Ginecologia e Obstetrícia" },
  { id: 707, question: "Qual é a principal contraindicação para o uso de DIU hormonal (levonorgestrel) como método contraceptivo?", options: ["Antecedente de gestação ectópica.", "Miomatose uterina com útero aumentado de volume.", "Sangramento uterino anormal sem diagnóstico.", "História familiar de câncer de mama."], correctIndex: 2, explanation: "O sangramento uterino anormal de causa desconhecida é uma contraindicação formal para o DIU hormonal, pois pode mascarar uma condição patológica grave, como câncer de endométrio ou outras malignidades, que necessitam de investigação prévia.", category: "Ginecologia e Obstetrícia" },
  { id: 708, question: "Primigesta, 28 anos, tem diagnóstico de pré-eclâmpsia sem sinais de gravidade, em 36 semanas de gestação. A cardiotocografia está reativa e o ultrassom com perfil biofísico fetal 8/8. Qual a conduta obstétrica mais adequada neste momento?", options: ["Internação hospitalar e programação de indução de parto em 24-48 horas.", "Expectação e acompanhamento ambulatorial com monitoramento rigoroso até 40 semanas.", "Administração de sulfato de magnésio para neuroproteção fetal e prevenção de eclâmpsia.", "Solicitar perfil de vitalidade fetal a cada 48 horas e aguardar início espontâneo do trabalho de parto."], correctIndex: 0, explanation: "Na pré-eclâmpsia sem sinais de gravidade, a indução do parto é recomendada a partir das 37 semanas. Em 36 semanas, a recomendação é uma conduta mais ativa, visando a resolução da gestação dentro de um curto período após a estabilização, em geral entre 36 e 37 semanas.", category: "Ginecologia e Obstetrícia" },
  { id: 709, question: "Qual das seguintes intervenções é a mais eficaz na prevenção da transmissão vertical do HIV durante a gestação?", options: ["Aleitamento artificial exclusivo e uso de antirretrovirais para a gestante.", "Cesariana eletiva em todas as gestantes soropositivas.", "Uso de antirretrovirais para a gestante, independentemente da carga viral, e profilaxia antirretroviral para o recém-nascido.", "Apenas rastreamento da carga viral e supressão da mesma antes do parto."], correctIndex: 2, explanation: "A estratégia mais eficaz para prevenir a transmissão vertical do HIV envolve a terapia antirretroviral para a gestante durante toda a gravidez e parto, profilaxia antirretroviral para o recém-nascido e a supressão do aleitamento materno, independentemente da carga viral. A cesariana é indicada com carga viral detectável próximo ao parto.", category: "Ginecologia e Obstetrícia" },
  { id: 710, question: "Uma paciente, 45 anos, com ciclos menstruais regulares, queixa-se de sangramentos uterinos anormais intermenstruais e dor pélvica de forte intensidade durante a menstruação. A ultrassonografia transvaginal revela endométrio espessado e heterogêneo, com múltiplos cistos de Naboth no colo uterino e ovários de aspecto normal. A principal hipótese diagnóstica, considerando o quadro, seria:", options: ["Endometriose.", "Miomatose uterina.", "Pólipo endometrial.", "Adenomiose."], correctIndex: 0, explanation: "A descrição de dor pélvica intensa (dismenorreia) e sangramento uterino anormal, especialmente intermenstrual, com achados de endométrio espessado e heterogêneo, deve levantar a suspeita de endometriose, que frequentemente causa esses sintomas e pode ser associada a inflamação e congestão pélvica.", category: "Ginecologia e Obstetrícia" },
  { id: 711, question: "Em relação à fisiologia do trabalho de parto, qual hormônio é o principal responsável pelas contrações uterinas e dilatação cervical?", options: ["Progesterona.", "Ocitocina.", "Estrogênio.", "Relaxina."], correctIndex: 1, explanation: "A ocitocina é o principal hormônio responsável pelas contrações uterinas potentes e coordenadas que promovem a dilatação do colo e a expulsão do feto. Sua liberação é aumentada no trabalho de parto por um feedback positivo (reflexo de Ferguson).", category: "Ginecologia e Obstetrícia" },
  { id: 712, question: "Durante o acompanhamento pré-natal, uma gestante de 30 semanas G2P1 com um parto normal anterior, apresenta pressão arterial de 145/95 mmHg em duas ocasiões, com 4 horas de intervalo. Refere edema de membros inferiores e rosto. Exames laboratoriais revelam proteinúria de 24 horas de 0,4 g. Qual o diagnóstico e a conduta inicial mais adequada?", options: ["Hipertensão gestacional e iniciar acompanhamento ambulatorial rigoroso.", "Pré-eclâmpsia e hospitalizar para avaliação e possível indução do parto.", "Eclâmpsia e iniciar sulfato de magnésio e programação de cesariana.", "Hipertensão crônica e ajuste da medicação anti-hipertensiva."], correctIndex: 1, explanation: "Com nova hipertensão após 20 semanas e proteinúria, o diagnóstico é de pré-eclâmpsia. Mesmo que sem sinais de gravidade, a internação para monitoramento materno-fetal e planejamento do parto é a conduta inicial. A eclâmpsia é pré-eclâmpsia com convulsões.", category: "Ginecologia e Obstetrícia" },
  { id: 713, question: "Paciente, 25 anos, primigesta, 16 semanas de gestação, com ultrassonografia morfológica revelando anencefalia fetal. Qual a conduta obstétrica mais indicada, considerando a legislação brasileira?", options: ["Manutenção da gestação até o termo, com parto vaginal programado.", "Interrupção da gestação mediante autorização judicial, após laudo médico conclusivo.", "Indução do trabalho de parto imediata, sem necessidade de autorização judicial.", "Acompanhamento pré-natal e cesariana eletiva para preservar a vida materna."], correctIndex: 2, explanation: "No Brasil, a interrupção da gestação em casos de anencefalia fetal é permitida por lei desde 2012, sem necessidade de autorização judicial, bastando o laudo médico conclusivo da malformação incompatível com a vida extrauterina.", category: "Ginecologia e Obstetrícia" },
  { id: 714, question: "Qual das seguintes opções CORRETAMENTE descreve o mecanismo de ação dos contraceptivos orais combinados?", options: ["Inibição da ovulação e alteração do muco cervical.", "Alteração da motilidade tubária e adelgaçamento do endométrio.", "Impedimento da nidação e bloqueio da espermatogênese.", "Aumento da viscosidade do muco cervical e estímulo à ovulação."], correctIndex: 0, explanation: "Os contraceptivos orais combinados atuam principalmente inibindo a ovulação através do feedback negativo no eixo hipotálamo-hipófise-ovariano e alteram o muco cervical, tornando-o hostil à passagem de espermatozoides.", category: "Ginecologia e Obstetrícia" },
  { id: 715, question: "Uma puérpera, 3 dias pós-parto vaginal, apresenta febre de 38,5°C, dor em baixo ventre, útero subinvoluído e dor à palpação. O sangramento vaginal é sanguinolento e com odor fétido. Qual o diagnóstico mais provável?", options: ["Mastite puerperal.", "Infecção do trato urinário.", "Endometrite puerperal.", "Tromboflebite pélvica séptica."], correctIndex: 2, explanation: "A febre puerperal, dor em baixo ventre, involução uterina atrasada, dor à palpação uterina e lóquios fétidos são classicamente indicativos de endometrite puerperal, uma infecção do revestimento uterino após o parto.", category: "Ginecologia e Obstetrícia" },
  { id: 716, question: "Qual a principal indicação para o uso de cardiotocografia anteparto no pré-natal de alto risco?", options: ["Rastreamento de distúrbios da tireoide fetal.", "Avaliação do bem-estar fetal em gestações de risco.", "Diagnóstico de malformações congênitas.", "Prevenção de parto prematuro."], correctIndex: 1, explanation: "A cardiotocografia anteparto é um método de avaliação da vitalidade fetal, indicado principalmente para monitorar o bem-estar de fetos em gestações de alto risco, detectando alterações na sua oxigenação e estado geral.", category: "Ginecologia e Obstetrícia" },
  { id: 717, question: "Paciente, 60 anos, pós-menopausa, apresenta sangramento vaginal há 2 meses. Ultrassonografia transvaginal revela espessura endometrial de 8 mm. Qual a conduta mais apropriada?", options: ["Acompanhamento clínico e repetição da ultrassonografia em 6 meses.", "Início de terapia de reposição hormonal para controle do sangramento.", "Histeroscopia com biópsia endometrial.", "Tratamento com progesterona oral."], correctIndex: 2, explanation: "Qualquer sangramento pós-menopausa com espessura endometrial maior que 4 mm (ou 5 mm, a depender da diretriz) requer investigação para afastar patologia endometrial, incluindo neoplasia. A histeroscopia com biópsia é o padrão-ouro para o diagnóstico.", category: "Ginecologia e Obstetrícia" },
  { id: 718, question: "Qual o limite de idade gestacional para a realização do parto em gestações gemelares dicoriônicas e diamnióticas sem complicações?", options: ["34 semanas.", "36 semanas.", "38 semanas.", "40 semanas."], correctIndex: 2, explanation: "Para gestações gemelares dicoriônicas e diamnióticas não complicadas, recomenda-se a indução ou parto entre 37 semanas e 0 dias e 38 semanas e 6 dias, devido ao aumento de riscos perinatais após este período.", category: "Ginecologia e Obstetrícia" },
  { id: 719, question: "Primigesta, 25 anos, com resultado de teste de triagem para sífilis (VDRL positivo 1:16 e FTA-Abs reagente). Não tem história de tratamento prévio. Qual a conduta terapêutica para esta paciente?", options: ["Benzilpenicilina benzatina, dose única, intramuscular.", "Benzilpenicilina benzatina, 3 doses, intramuscular, com intervalo de 1 semana.", "Doxiciclina por 14 dias, via oral.", "Ampicilina intravenosa por 7 dias."], correctIndex: 1, explanation: "O esquema terapêutico para sífilis gestacional em estágios iniciais, como a sífilis primária, secundária ou latente recente, é benzilpenicilina benzatina, 2,4 milhões de unidades, em 3 doses, com intervalo de 1 semana. A dose única é para sífilis latente precoce ou adquirida há menos de 1 ano.", category: "Ginecologia e Obstetrícia" },
  { id: 720, question: "Qual o principal efeito colateral metabólico dos contraceptivos orais combinados de alta dose que deve ser monitorado?", options: ["Aumento da densidade óssea.", "Melhora do perfil lipídico.", "Risco aumentado de trombose venosa profunda.", "Diminuição da pressão arterial."], correctIndex: 2, explanation: "Contraceptivos orais combinados, especialmente os de alta dose de estrogênio, aumentam o risco de trombose venosa profunda e tromboembolismo pulmonar, devido aos efeitos do estrogênio nos fatores de coagulação. Este é um efeito colateral metabólico importante a ser monitorado.", category: "Ginecologia e Obstetrícia" },
  { id: 721, question: "Paciente, 35 anos, com história de um parto prematuro anterior, busca aconselhamento sobre prevenção de recorrência na gestação atual. Qual das seguintes intervenções é a mais indicada para reduzir o risco de parto prematuro recorrente?", options: ["Uso de tocolíticos orais desde o início da gestação.", "Repouso absoluto e abstinência sexual durante toda a gestação.", "Suplementação de progesterona desde o segundo trimestre.", "Cerclagem cervical de rotina em todas as pacientes com história de parto prematuro."], correctIndex: 2, explanation: "A suplementação de progesterona (via vaginal ou intramuscular) no segundo trimestre é uma das intervenções mais eficazes para a prevenção de parto prematuro recorrente em pacientes com história prévia. A cerclagem é para casos de insuficiência istmocervical.", category: "Ginecologia e Obstetrícia" },
  { id: 722, question: "Uma mulher de 28 anos, sexualmente ativa, apresenta dor pélvica intensa, febre (39°C), corrimento vaginal purulento e dor à mobilização do colo uterino ao exame ginecológico. A contagem de leucócitos está elevada. Qual o diagnóstico mais provável?", options: ["Vaginose bacteriana.", "Cervicite.", "Doença Inflamatória Pélvica (DIP).", "Gravidez ectópica rota."], correctIndex: 2, explanation: "A tríade de dor pélvica, febre e dor à mobilização do colo uterino, juntamente com o corrimento purulento e leucocitose, são achados clássicos da Doença Inflamatória Pélvica (DIP), que envolve a infecção do trato genital superior.", category: "Ginecologia e Obstetrícia" },
  { id: 723, question: "A principal causa de hemorragia pós-parto imediato é:", options: ["Lacerações de trajeto.", "Retenção de restos placentários.", "Útero de Couvelaire.", "Atonia uterina."], correctIndex: 3, explanation: "A atonia uterina é a causa mais comum de hemorragia pós-parto imediato, respondendo por aproximadamente 80% dos casos. É caracterizada pela falha do útero em se contrair adequadamente após a expulsão da placenta, levando à perda sanguínea excessiva.", category: "Ginecologia e Obstetrícia" },
  { id: 724, question: "Qual dos seguintes é um fator de risco primário para o desenvolvimento de câncer de colo uterino?", options: ["Uso prolongado de contraceptivos orais.", "Infecção persistente pelo Papilomavírus Humano (HPV) de alto risco.", "Tabagismo.", "Múltiplos parceiros sexuais."], correctIndex: 1, explanation: "A infecção persistente por tipos de alto risco do Papilomavírus Humano (HPV) é considerada a causa necessária, embora não suficiente, para o desenvolvimento de câncer de colo uterino. Os outros fatores são importantes, mas secundários à presença do HPV.", category: "Ginecologia e Obstetrícia" },
  { id: 725, question: "Gestante, 30 semanas, apresenta sangramento vaginal indolor, vermelho vivo, em pequena quantidade. A ultrassonografia de rotina realizada em 20 semanas não revelou alterações. Qual a principal hipótese diagnóstica a ser investigada?", options: ["Descolamento prematuro de placenta.", "Vasa prévia.", "Placenta prévia.", "Rotura de seio marginal."], correctIndex: 2, explanation: "O sangramento vaginal indolor, vermelho vivo, no terceiro trimestre, sem outras causas aparentes, é o sinal clássico de placenta prévia. Embora a ultrassonografia de 20 semanas fosse normal, a placenta pode migrar ou surgir em uma nova avaliação.", category: "Ginecologia e Obstetrícia" },
  { id: 726, question: "Uma paciente de 40 anos, com história de câncer de mama recente, é candidata a método contraceptivo. Qual das opções a seguir é a mais segura e indicada para essa paciente?", options: ["Contraceptivo oral combinado (estrogênio e progesterona).", "Implante de etonogestrel.", "DIU de cobre.", "Injeção trimestral de progestagênio."], correctIndex: 2, explanation: "Para pacientes com histórico de câncer de mama, métodos contraceptivos hormonais, especialmente os que contêm estrogênio, são contraindicados. O DIU de cobre é uma opção segura e eficaz por ser um método não hormonal, não interferindo na patologia pré-existente.", category: "Ginecologia e Obstetrícia" },
  { id: 727, question: "Lactente de 3 meses, previamente hígido, é trazido à emergência com história de febre alta (39,5°C) há 6 horas e irritabilidade. Ao exame, apresenta-se consciente, reativo, com fontanela normotensa, sem sinais de irritação meníngea evidentes. Qual a principal preocupação e a conduta inicial mais adequada?", options: ["Infecção do trato urinário; aguardar resultado de urocultura e iniciar antibiótico somente se positivo.", "Sepse; realizar punção lombar e coletar culturas de sangue e urina antes de iniciar antibiótico empírico.", "Otite média aguda; prescrever amoxicilina e reavaliar em 24 horas.", "Bronquiolite; realizar lavagem nasal e inalação com soro fisiológico."], correctIndex: 1, explanation: "Em lactentes jovens com febre alta sem foco aparente, a preocupação principal é sepse oculta. A investigação deve ser agressiva, incluindo punção lombar, hemocultura e urocultura, com início de antibiótico empírico de amplo espectro imediatamente após a coleta dos exames.", category: "Pediatria" },
  { id: 728, question: "Criança de 5 anos é diagnosticada com asma após vários episódios de sibilância e tosse, pior à noite e após exercícios. Qual o tratamento de manutenção inicial recomendado para asma persistente leve, de acordo com as diretrizes atuais?", options: ["Salbutamol (formoterol) em todas as crises asma.", "Corticoide inalatório em baixa dose diariamente.", "Montelucaste via oral diariamente.", "Corticoide inalatório em baixa dose com broncodilatador de longa duração."], correctIndex: 1, explanation: "O corticoide inalatório em baixa dose diária é o tratamento de primeira linha para o controle da asma persistente leve em crianças, reduzindo a inflamação das vias aéreas e prevenindo exacerbações.", category: "Pediatria" },
  { id: 729, question: "Qual a principal causa de diarreia grave com desidratação em crianças menores de 5 anos no Brasil, antes da introdução da vacina universal e que atualmente ainda é um agente etiológico importante?", options: ["Shigella spp.", "Escherichia coli enterotoxigênica (ETEC)", "Rotavírus", "Giardia lamblia"], correctIndex: 2, explanation: "O Rotavírus é a principal causa de diarreia grave com desidratação em crianças menores de 5 anos. Apesar da vacinação, ainda representa um importante desafio de saúde, especialmente em áreas com baixa cobertura vacinal ou para sorotipos não cobertos.", category: "Pediatria" },
  { id: 730, question: "Um recém-nascido (RN) de 38 semanas, com peso de 3200g, apresentou-se ao nascimento com boa vitalidade. No segundo dia de vida, evoluiu com icterícia, com bilirrubina total de 12 mg/dL e fração indireta predominante. A mãe tem tipagem sanguínea O+. O RN é A+. Qual a conduta inicial mais adequada?", options: ["Início de fototerapia intensiva e monitorização da bilirrubina.", "Repetir a bilirrubina em 24 horas e aguardar.", "Transfusão de troca imediata.", "Administração de imunoglobulina intravenosa."], correctIndex: 0, explanation: "Com base na idade gestacional, peso e níveis de bilirrubina, além da incompatibilidade ABO (mãe O+, RN A+), a fototerapia é a conduta inicial para hiperbilirrubinemia indireta que ultrapassa o limiar para o início do tratamento, visando prevenir a kernicterus.", category: "Pediatria" },
  { id: 731, question: "Criança de 8 anos é admitida no pronto-socorro com história de dor abdominal periumbilical que migrou para a fossa ilíaca direita, associada a náuseas e vômitos. Ao exame, apresenta dor à descompressão brusca na fossa ilíaca direita e febre de 38,5°C. Qual o diagnóstico mais provável?", options: ["Gastroenterite viral.", "Infecção do trato urinário.", "Apudice aguda.", "Linfadenite mesentérica."], correctIndex: 2, explanation: "A descrição clássica da dor abdominal migratória (periumbilical para fossa ilíaca direita), associada a náuseas, vômitos e febre, é altamente sugestiva de apendicite aguda, uma emergência cirúrgica em pediatria.", category: "Pediatria" },
  { id: 732, question: "Qual a principal complicação aguda e grave da cetoacidose diabética (CAD) em crianças, que exige monitoramento e manejo cuidadosos para ser evitada?", options: ["Hipoglicemia.", "Edema cerebral.", "Insuficiência renal aguda.", "Arritmia cardíaca."], correctIndex: 1, explanation: "O edema cerebral é a complicação mais grave e potencialmente fatal da cetoacidose diabética em crianças, ocorrendo principalmente durante a infusão de fluidos e insulina. Seu manejo exige reposição volêmica e correção gradual da glicemia e eletrólitos.", category: "Pediatria" },
  { id: 733, question: "Um RN pré-termo de 32 semanas, no terceiro dia de vida, apresenta distensão abdominal, resíduos gástricos biliosos e letargia. Ao exame, abdome tenso, com eritema na parede. Qual a hipótese diagnóstica mais provável?", options: ["Sepse neonatal precoce.", "Síndrome do desconforto respiratório.", "Enterocolite necrosante (ECN).", "Atresia intestinal."], correctIndex: 2, explanation: "As manifestações clínicas de distensão abdominal, resíduos biliosos, letargia e achados no exame físico (abdome tenso, eritema) em um RN pré-termo são altamente sugestivas de enterocolite necrosante (ECN), uma condição grave que requer intervenção imediata.", category: "Pediatria" },
  { id: 734, question: "Em relação à profilaxia da doença hemorrágica do recém-nascido, qual o fármaco e a via de administração recomendados?", options: ["Vitamina B12 intramuscular.", "Vitamina K intramuscular.", "Vitamina D via oral.", "Soro glicosado intravenoso."], correctIndex: 1, explanation: "A profilaxia da doença hemorrágica do recém-nascido é realizada pela administração de Vitamina K (fitomenadiona) por via intramuscular, logo após o nascimento, para prevenir sangramentos causados pela deficiência de fatores de coagulação dependentes de vitamina K.", category: "Pediatria" },
  { id: 735, question: "Criança de 10 anos, com história de faringoamigdalite há 2 semanas, evolui com edema periorbital e nos membros inferiores, oligúria e urina com coloração de 'coca-cola'. A pressão arterial está elevada. Qual o diagnóstico mais provável?", options: ["Síndrome nefrótica.", "Glomerulonefrite difusa aguda pós-estreptocócica.", "Pielonefrite aguda.", "Lúpus eritematoso sistêmico."], correctIndex: 1, explanation: "A tríade de edema, oligúria/hematúria (urina 'coca-cola') e hipertensão após uma infecção de vias aéreas superiores, especialmente por estreptococo, é classicamente descritiva da Glomerulonefrite Difusa Aguda Pós-estreptocócica.", category: "Pediatria" },
  { id: 736, question: "Qual a principal intervenção para prevenir a transmissão vertical do HIV da mãe para o filho durante a gestação e o puerpério?", options: ["Vacinação materna e fetal.", "Corte do cordão umbilical após 3 minutos.", "Terapia antirretroviral (TARV) para a gestante e RN, e inibição da amamentação.", "Suplementação de ferro durante a gestação."], correctIndex: 2, explanation: "A prevenção da transmissão vertical do HIV é multifacetada, incluindo terapia antirretroviral para a gestante e o recém-nascido e, fundamentalmente, a inibição da amamentação para evitar a transmissão pelo leite materno.", category: "Pediatria" },
  { id: 737, question: "Um adolescente de 14 anos é trazido ao pronto-socorro com queixas de febre, dor faríngea intensa, adenomegalia cervical e exantema maculopapular. O hemograma revela linfocitose atípica. Qual a principal suspeita diagnóstica?", options: ["Amigdalite bacteriana por Streptococcus pyogenes.", "Mononucleose infecciosa.", "Escarlatina.", "Gripe."], correctIndex: 1, explanation: "A tríade de febre, dor faríngea e adenomegalia cervical, juntamente com a presença de linfócitos atípicos no hemograma, é altamente sugestiva de mononucleose infecciosa, geralmente causada pelo vírus Epstein-Barr (EBV).", category: "Pediatria" },
  { id: 738, question: "Qual é a principal contraindicação à amamentação, de acordo com as diretrizes do Ministério da Saúde do Brasil?", options: ["Mastite materna.", "Uso de antidepressivos pela mãe.", "Mãe soropositiva para HIV.", "Icterícia neonatal."], correctIndex: 2, explanation: "A amamentação está contraindicada quando a mãe é soropositiva para HIV devido ao risco de transmissão vertical do vírus através do leite materno. Outras condições geralmente não contraindicam a amamentação.", category: "Pediatria" },
  { id: 739, question: "Criança de 2 anos é atendida com quadro de febre há 3 dias, coriza e tosse. Hoje, apresenta exantema eritematoso maculopapular cefalocaudal, que coalesceu em algumas áreas. Apresenta conjuntivite, coriza e manchas de Koplik na mucosa jugal. Qual o diagnóstico mais provável?", options: ["Rubéola.", "Sarampo.", "Catapora (Varicela).", "Exantema súbito (roséola)."], correctIndex: 1, explanation: "A sequência de febre, sintomas catarrais (coriza, tosse, conjuntivite), o exantema maculopapular cefalocaudal coalescente e, principalmente, a presença das manchas de Koplik, são achados clássicos do sarampo.", category: "Pediatria" },
  { id: 740, question: "Qual a principal causa de morte por injúria não intencional em crianças menores de 1 ano no Brasil?", options: ["Quedas.", "Queimaduras.", "Afogamento.", "Obstrução de vias aéreas por corpo estranho (asfixia)."], correctIndex: 3, explanation: "A obstrução de vias aéreas por corpo estranho é a principal causa de morte por injúria não intencional em lactentes, ressaltando a importância das medidas de prevenção e primeiros socorros.", category: "Pediatria" },
  { id: 741, question: "Um recém-nascido de termo, com 48 horas de vida, apresenta distensão abdominal e ausência de eliminação de mecônio. Ao toque retal, observa-se ampola retal vazia e saída de grande quantidade de fezes e gases após a retirada do dedo. Qual a hipótese diagnóstica mais provável?", options: ["Íleo paralítico.", "Atresia anal.", "Doença de Hirschsprung.", "Fibrose cística."], correctIndex: 2, explanation: "A ausência de eliminação de mecônio, distensão abdominal e a característica 'explosão' de fezes e gases após o toque retal (relação com o espasmo do segmento agangliônico) são achados clássicos da doença de Hirschsprung.", category: "Pediatria" },
  { id: 742, question: "Qual a principal complicação da doença falciforme em crianças, que se manifesta com dor intensa e pode levar a hospitalizações frequentes?", options: ["Acidente vascular cerebral.", "Síndrome torácica aguda.", "Crise álgica vaso-oclusiva.", "Seqüestração esplênica."], correctIndex: 2, explanation: "A crise álgica vaso-oclusiva é a manifestação mais comum e a principal causa de hospitalização em crianças com doença falciforme, caracterizada por dor intensa devido à oclusão de pequenos vasos sanguíneos.", category: "Pediatria" },
  { id: 743, question: "Em um paciente pediátrico com choque séptico, qual a medida inicial mais importante e priorizado no manejo hemodinâmico, após assegurada a via aérea e a ventilação?", options: ["Administração de dopamina em dose vasopressora.", "Expansão volêmica agressiva com cristaloides.", "Início de antibióticos de amplo espectro.", "Correção de distúrbios eletrolíticos."], correctIndex: 1, explanation: "Após garantir a via aérea e a ventilação, a expansão volêmica agressiva e precoce com cristaloides é a medida inicial mais crítica no manejo do choque séptico em crianças, visando restaurar a perfusão tisular.", category: "Pediatria" },
  { id: 744, question: "Quais vacinas são recomendadas no Calendário Nacional de Vacinação para crianças no primeiro ano de vida?", options: ["Somente BCG e Hepatite B.", "Somente Rotavírus, Meningocócica C e Pneumocócica 10.", "BCG, Hepatite B, Rotavírus, Meningocócica C, Pneumocócica 10, VIP (poliomielite inativada), DTP, Haemophilus influenzae b, Gripe.", "DTP, Sarampo, Caxumba, Rubéola (SCR)."], correctIndex: 2, explanation: "O Calendário Nacional de Vacinação para o primeiro ano de vida é abrangente, incluindo BCG, Hepatite B, Rotavírus, Meningocócica C, Pneumocócica 10, VIP, DTP, Haemophilus influenzae b e Gripe, para proteger contra diversas doenças infecciosas.", category: "Pediatria" },
  { id: 745, question: "Qual a principal causa de hipoglicemia neonatal em recém-nascidos de mães diabéticas?", options: ["Deficiência de hormônio do crescimento.", "Hiperinsulinismo fetal transitório.", "Resistência à insulina.", "Deficiência de glicose-6-fosfatase."], correctIndex: 1, explanation: "Recém-nascidos de mães diabéticas frequentemente apresentam hiperinsulinismo fetal transitório devido à exposição crônica à hiperglicemia materna, resultando em produção excessiva de insulina e, consequentemente, hipoglicemia após o nascimento.", category: "Pediatria" },
  { id: 746, question: "Qual o tratamento de primeira linha para escabiose (sarna) em crianças?", options: ["Permetrina tópica a 5%.", "Ivermectina oral.", "Tiabendazol tópico.", "Creme de hidrocortisona a 1%."], correctIndex: 0, explanation: "A permetrina tópica a 5% é o tratamento de primeira linha recomendado para escabiose em crianças, demonstrando alta eficácia e bom perfil de segurança quando aplicada corretamente.", category: "Pediatria" },
  { id: 747, question: "Um recém-nascido pré-termo tardio, 35 semanas de idade gestacional, apresenta icterícia no terceiro dia de vida. Bilirrubina total de 12 mg/dL e direta de 0.8 mg/dL. Qual a conduta inicial mais apropriada?", options: ["Iniciar fototerapia intensiva imediatamente.", "Solicitar dosagem de bilirrubina transcutânea a cada 6 horas.", "Considerar exsanguinotransfusão devido à prematuridade.", "Monitorar a bilirrubina e reavaliar em 12-24 horas, conforme curva de tratamento."], correctIndex: 0, explanation: "Para recém-nascidos pré-termo (mesmo tardios), os níveis para fototerapia são mais baixos devido ao maior risco de encefalopatia bilirrubínica. Um RN de 35 semanas com 12 mg/dL no 3º dia de vida já está na faixa de tratamento.", category: "Pediatria" },
  { id: 748, question: "Lactente de 6 meses é levado à emergência com febre alta (39,5°C) há 2 dias, irritabilidade e convulsão tônico-clônica generalizada com duração de 3 minutos. Após a convulsão, o exame neurológico é normal. Qual o diagnóstico mais provável?", options: ["Meningite bacteriana.", "Convulsão febril simples.", "Epilepsia mioclônica da infância.", "Encefalite viral."], correctIndex: 1, explanation: "A convulsão febril simples ocorre em crianças de 6 meses a 5 anos, é generalizada, tem curta duração (<15 min), associada à febre e não se repete nas próximas 24h, com recuperação neurológica completa.", category: "Pediatria" },
  { id: 749, question: "Menina de 7 anos apresenta quadro de tosse produtiva há 3 semanas, com expectoração purulenta e alguns episódios de sibilância. Relata episódios semelhantes desde a primeira infância. Ao exame físico, apresenta crepitações inspiratórias em bases pulmonares. Qual a principal hipótese diagnóstica?", options: ["Asma brônquica.", "Fibrose cística.", "Bronquiolite viral aguda.", "Refluxo gastroesofágico."], correctIndex: 1, explanation: "A história de tosse crônica produtiva, expectoração purulenta e crepitações em bases, associada a quadros de repetição desde a infância, sugere fortemente fibrose cística, uma doença genética que afeta múltiplos órgãos, principalmente o trato respiratório e gastrointestinal.", category: "Pediatria" },
  { id: 750, question: "Um escolar de 8 anos apresenta dor abdominal periumbilical de início agudo, que migrou posteriormente para fossa ilíaca direita, associada a febre baixa, náuseas e um episódio de vômito. À palpação abdominal, dor intensa em fossa ilíaca direita. Qual o exame complementar inicial de escolha para auxiliar no diagnóstico?", options: ["Ultrassonografia abdominal.", "Tomografia computadorizada abdominal com contraste.", "Radiografia simples de abdome em pé e deitado.", "Hemograma completo e proteína C reativa."], correctIndex: 0, explanation: "Em crianças, a ultrassonografia abdominal é o exame complementar inicial de escolha para diagnóstico de apendicite aguda devido à sua sensibilidade, especificidade e ausência de radiação ionizante.", category: "Pediatria" },
  { id: 751, question: "Lactente de 3 meses, previamente hígido, é trazido à urgência com quadro de tosse e sibilância progressivas há 3 dias. Ao exame físico, apresenta taquipneia, tiragem subcostal e intercostal, e sibilância difusa à ausculta pulmonar. Não há febre. Qual o diagnóstico mais provável?", options: ["Asma brônquica.", "Bronquiolite viral aguda.", "Pneumonia bacteriana.", "Coqueluche."], correctIndex: 1, explanation: "A bronquiolite viral aguda é comum em lactentes menores de 6 meses, manifestando-se com tosse, taquipneia, tiragem e sibilância, geralmente precedida por sintomas de vias aéreas superiores, sendo o vírus sincicial respiratório o principal agente etiológico.", category: "Pediatria" },
  { id: 752, question: "Com relação à introdução alimentar em lactentes, qual é a recomendação atual do Ministério da Saúde do Brasil?", options: ["Iniciar aos 4 meses de idade com papinhas salgadas.", "Iniciar aos 6 meses de idade, mantendo o aleitamento materno e oferecendo alimentos complementares variados.", "Restringir a oferta de ovos e peixes até os 12 meses para evitar alergias.", "Introduzir apenas frutas e cereais sem glúten até os 9 meses."], correctIndex: 1, explanation: "As diretrizes atuais do Ministério da Saúde e da Sociedade Brasileira de Pediatria recomendam o aleitamento materno exclusivo até os 6 meses, e a partir de então, a introdução de alimentos complementares, mantendo o aleitamento materno até os 2 anos ou mais.", category: "Pediatria" },
  { id: 753, question: "Um bebê de 10 dias de vida, nascido a termo, apresenta regressão da perda de peso fisiológica e hoje pesa 10% a mais que o peso de nascimento. Qual é essa condição?", options: ["Perda de peso fisiológica normal.", "Ganho de peso adequado.", "Ganho de peso excessivo.", "Atraso no crescimento fetal."], correctIndex: 1, explanation: "O ganho de peso adequado em um recém-nascido a termo geralmente ocorre a partir do 7º-10º dia de vida, com recuperação do peso de nascimento e posterior ganho. Um bebê com 10% a mais que o peso de nascimento aos 10 dias está com ganho de peso adequado.", category: "Pediatria" },
  { id: 754, question: "Qual o principal critério para o diagnóstico de febre reumática?", options: ["Presença de PCR e VHS elevados.", "Critérios de Jones modificados da American Heart Association.", "Diagnóstico baseado apenas em cultura de orofaringe positiva para Streptococcus pyogenes.", "Dor articular isolada e febre."], correctIndex: 1, explanation: "O diagnóstico de febre reumática é feito com base nos Critérios de Jones modificados da American Heart Association, que incluem evidência de infecção estreptocócica recente (cultura positiva, teste rápido para estreptococo positivo ou aumento da ASLO) e a presença de dois critérios maiores ou um critério maior e dois menores.", category: "Pediatria" },
  { id: 755, question: "Qual a principal complicação do refluxo gastroesofágico fisiológico em lactentes?", options: ["Doença do refluxo gastroesofágico.", "Esofagite erosiva.", "Pneumonia aspirativa recorrente.", "Nenhuma, pois é uma condição fisiológica e autolimitada."], correctIndex: 3, explanation: "O refluxo gastroesofágico fisiológico é uma condição comum e autolimitada em lactentes, geralmente sem consequências CLÍNICAS significativas. A maioria se resolve espontaneamente até os 12-18 meses de idade.", category: "Pediatria" },
  { id: 756, question: "Em um caso de crise asmática moderada em criança, qual o tratamento de primeira linha no pronto atendimento?", options: ["Corticosteroide sistêmico e broncodilatador inalatório (bet agonista de curta ação).", "Oxigênio suplementar e antibiótico parenteral.", "Broncodilatador de longa ação e fisioterapia respiratória.", "Antihistamínico e descongestionante nasal."], correctIndex: 0, explanation: "O tratamento de primeira linha para crise asmática moderada em crianças inclui a administração de corticosteroides sistêmicos (orais ou intravenosos) e broncodilatadores inalatórios de curta ação (salbutamol) para aliviar a broncoconstrição e a inflamação.", category: "Pediatria" },
  { id: 757, question: "Qual a principal recomendação para a prevenção da Síndrome da Morte Súbita do Lactente (SMSL)?", options: ["Colocar o bebê para dormir de bruços.", "Compartilhar a cama com os pais.", "Colocar o bebê para dormir de barriga para cima (decúbito dorsal).", "Utilizar travesseiros e cobertores pesados no berço."], correctIndex: 2, explanation: "A principal recomendação para a prevenção da SMSL é a posição supina (barriga para cima) para dormir, em um berço seguro, sem objetos fofos, travesseiros ou cobertores soltos.", category: "Pediatria" },
  { id: 758, question: "Criança de 2 anos é levada à emergência com febre alta e irritabilidade. Presença de petéquias e púrpura em membros inferiores. Suspeita inicial de sepse. Qual exame microbiológico é fundamental para o diagnóstico e direcionamento terapêutico?", options: ["Hemograma completo.", "Coagulograma.", "Hemocultura e cultura de líquor.", "Teste rápido para dengue."], correctIndex: 2, explanation: "Em casos de sepse em crianças, especialmente com suspeita de infecção invasiva (meningite), hemocultura e cultura de líquor (após exclusão de contraindicações) são exames essenciais para identificar o agente etiológico e guiar o tratamento antibiótico específico.", category: "Pediatria" },
  { id: 759, question: "Qual a condição que deve ser sempre rastreada no teste do pezinho ampliado no Brasil?", options: ["Síndrome de Down.", "Fenilcetonúria.", "Anemia falciforme.", "Diabetes mellitus tipo 1."], correctIndex: 1, explanation: "A fenilcetonúria é uma das condições metabólicas hereditárias rastreadas de forma universal no teste do pezinho (triagem neonatal) no Brasil, juntamente com o hipotireoidismo congênito, fibrose cística, hiperplasia adrenal congênita, deficiência de biotinidase e anemia falciforme.", category: "Pediatria" },
  { id: 760, question: "Em relação à osteomielite aguda em crianças, qual o agente etiológico mais comum?", options: ["Mycobacterium tuberculosis.", "Staphylococcus aureus.", "Streptococcus pyogenes.", "Escherichia coli."], correctIndex: 1, explanation: "Staphylococcus aureus é o agente etiológico mais comum de osteomielite aguda na maioria das faixas etárias pediátricas, tanto em infecções hematogênicas quanto após traumas ou cirurgias.", category: "Pediatria" },
  { id: 761, question: "Escolar de 9 anos é atendido com puberdade precoce. Qual a conduta inicial mais apropriada para investigar a etiologia?", options: ["Início de tratamento com antiandrogênios.", "Medida apenas de idade óssea.", "Dosagem hormonal (LH, FSH, estradiol ou testosterona) e ultrassonografia pélvica/testicular.", "Ressonância magnética da sela túrcica de rotina."], correctIndex: 2, explanation: "A investigação inicial da puberdade precoce (central ou periférica) requer dosagem hormonal para avaliar o eixo hipotálamo-hipófise-gonadal e ultrassonografia para avaliar estruturas gonadais, com idade óssea também sendo fundamental.", category: "Pediatria" },
  { id: 762, question: "Qual a principal causa de parada cardiorrespiratória em crianças?", options: ["Arritmias cardíacas primárias.", "Trauma cranioencefálico grave.", "Insuficiência respiratória e choque.", "Infarto agudo do miocárdio."], correctIndex: 2, explanation: "Em crianças, a parada cardiorrespiratória é mais frequentemente secundária a insuficiência respiratória progressiva e/ou choque não tratado, que levam à bradicardia e assistolia, diferentemente de adultos, onde as causas primárias são cardíacas.", category: "Pediatria" },
  { id: 763, question: "Um menino de 4 anos é diagnosticado com diabetes mellitus tipo 1. Qual a base do tratamento e o prognóstico em relação à remissão?", options: ["Dieta rigorosa e exercícios físicos, com chance de remissão espontânea em 50% dos casos.", "Insulinoterapia contínua por toda a vida, sem chance de remissão.", "Uso de hipoglicemiantes orais inicialmente, com possível progressão para insulina.", "Insulinoterapia, mas pode haver uma 'lua de mel' com necessidade reduzida de insulina."], correctIndex: 3, explanation: "O diabetes mellitus tipo 1 é uma doença autoimune com destruição das células beta pancreáticas, exigindo insulinoterapia por toda a vida. No entanto, muitos pacientes experimentam um período de 'lua de mel' logo após o diagnóstico, com necessidade reduzida de insulina devido à preservação parcial da função pancreática.", category: "Pediatria" },
  { id: 764, question: "Lactente de 8 meses apresenta choro intenso de início súbito, intermitente, associado a vômitos e fezes em geleia de framboesa. Apalpa-se massa em forma de salsicha no abdome. Qual a hipótese diagnóstica e a conduta inicial?", options: ["Apendicite aguda; cirurgia de urgência.", "Invaginação intestinal; enema com contraste ou ar.", "Gastroenterite aguda; hidratação oral.", "Corpo estranho intestinal; expectação."], correctIndex: 1, explanation: "Trata-se de um quadro clássico de invaginação intestinal, uma emergência pediátrica. O enema com contraste ou ar é a conduta inicial preferencial, sendo diagnóstico e terapêutico na maioria dos casos não complicados.", category: "Pediatria" },
  { id: 765, question: "Qual a principal indicação para o uso de ribavirina em crianças com infecção por vírus sincicial respiratório (VSR)?", options: ["Todos os casos de bronquiolite viral aguda.", "Apenas em pacientes com doença cardíaca congênita grave ou imunodeficiência.", "Crianças internadas em UTI com necessidade de ventilação mecânica.", "Uso profilático em todos os prematuros."], correctIndex: 1, explanation: "O uso de ribavirina para infecção por VSR é restrito a casos específicos e graves, como pacientes imunocomprometidos, com doença cardiopulmonar crônica significativa ou prematuros extremos, devido aos potenciais efeitos adversos e benefício limitado em pacientes previamente sadios.", category: "Pediatria" },
  { id: 766, question: "Em relação à profilaxia da meningite meningocócica, qual a principal recomendação para contatos próximos de um caso confirmado?", options: ["Vacinação imediata de todos os contatos.", "Antibioticoterapia profilática com rifampicina ou ciprofloxacino.", "Observação e monitoramento de sintomas por 14 dias.", "Realização de cultura de orofaringe em todos os contatos."], correctIndex: 1, explanation: "Contatos próximos de casos confirmados de doença meningocócica devem receber quimioprofilaxia com antibióticos (como rifampicina, ciprofloxacino ou ceftriaxona), que é mais eficaz na eliminação da colonização e prevenção da infecção secundária.", category: "Pediatria" },
  { id: 767, question: "Qual a característica clínica mais útil para diferenciar a laringite viral (crupe) da epiglotite aguda em uma criança?", options: ["Febre alta.", "Tosse ladrante.", "Sialorreia e disfagia.", "Estridor inspiratório."], correctIndex: 2, explanation: "A epiglotite aguda, embora rara devido à vacinação, é uma emergência e caracteriza-se por início súbito, febre alta, prostração, disfagia, sialorreia (baba excessiva) e voz abafada. A laringite viral (crupe) geralmente apresenta tosse ladrante e voz rouca.", category: "Pediatria" },
  { id: 768, question: "Em caso de anafilaxia em uma criança, qual a conduta imediata mais importante?", options: ["Administrar anti-histamínico oral.", "Aplicar epinefrina intramuscular na face lateral da coxa.", "Iniciar nebulização com broncodilatador.", "Monitorar e aguardar melhora."], correctIndex: 1, explanation: "A epinefrina (adrenalina) intramuscular é o tratamento de primeira linha e mais importante para a anafilaxia, devendo ser administrada prontamente na face lateral da coxa para reverter a broncoconstrição e o choque.", category: "Pediatria" },
  { id: 769, question: "Qual a principal causa de cegueira prevenível na infância globalmente?", options: ["Glaucoma congênito.", "Retinopatia da prematuridade.", "Deficiência de vitamina A.", "Catarata congênita."], correctIndex: 2, explanation: "A deficiência de vitamina A (Xeroftalmia) é a principal causa de cegueira prevenível na infância em regiões em desenvolvimento, afetando milhões de crianças anualmente.", category: "Pediatria" },
  { id: 770, question: "Quais são as alterações laboratoriais mais esperadas em um paciente com síndrome nefrótica em crianças?", options: ["Proteinúria maciça, hipoalbuminemia, hiperlipidemia e edema.", "Hematúria macroscópica, hipertensão, oligúria.", "Hipoproteinemia, hipercoagulabilidade e anemia.", "Creatinina elevada, potássio baixo e hipoglicemia."], correctIndex: 0, explanation: "A síndrome nefrótica é caracterizada pela tétrade de proteinúria maciça (>3,5g/1,73m2/dia ou >50 mg/kg/dia em crianças), hipoalbuminemia (<2,5 g/dL), edema (geralmente generalizado) e hiperlipidemia.", category: "Pediatria" },
  { id: 771, question: "Um recém-nascido pré-termo de 32 semanas de idade gestacional, internado na UTI Neo, em ventilação mecânica, apresenta apneias frequentes, bradicardia e dessaturação. Após otimização do suporte ventilatório e descarte de outras causas, qual é a principal medida farmacológica recomendada para o tratamento da apneia da prematuridade de acordo com as diretrizes atuais?", options: ["Sildenafila", "Cafeína", "Dexametasona", "Furosemida"], correctIndex: 1, explanation: "A cafeína é o principal fármaco utilizado no tratamento da apneia da prematuridade, comprovadamente eficaz na redução da frequência das apneias e na melhora do prognóstico neurológico a longo prazo.", category: "Pediatria" },
  { id: 772, question: "Lactente de 6 meses de idade, previamente hígido, é trazido à emergência com história de febre alta (39,5°C) há 3 dias, irritabilidade e prostração. Ao exame, apresenta fontanela abaulada, rigidez de nuca e manchas petequiais e purpúricas em tronco e membros. Qual é a conduta inicial mais adequada diante deste quadro suspeito?", options: ["Administrar ceftriaxona endovenosa após punção liquórica", "Administrar ceftriaxona endovenosa imediatamente antes da punção liquórica", "Coletar punção liquórica e aguardar resultados para iniciar antibioticoterapia", "Administrar paracetamol e iniciar investigação etiológica ambulatorial"], correctIndex: 1, explanation: "Diante da suspeita de sepse/meningite bacteriana com sinais de choque séptico e doença meningocócica (petéquias/púrpuras), a antibioticoterapia deve ser iniciada imediatamente, antes mesmo da punção liquórica, para evitar maior morbimortalidade.", category: "Pediatria" },
  { id: 773, question: "Escolar de 8 anos, previamente hígida, apresenta dor súbita e intensa em fossa ilíaca direita, acompanhada de febre e vômitos. Ao exame físico, observa-se dor à palpação profunda em FID e descompressão brusca dolorosa positiva. O ultrassom abdominal é inconclusivo. Qual é o diagnóstico mais provável e a conduta imediata?", options: ["Gastroenterite aguda; hidratação e sintomáticos", "Adenite mesentérica; observação e analgesia", "Apendicite aguda; laparotomia exploradora (ou videolaparoscopia)", "Infecção do trato urinário; urinálise e antibioticoterapia empírica"], correctIndex: 2, explanation: "Os sintomas clássicos e os sinais ao exame físico são altamente sugestivos de apendicite aguda. Nesses casos, mesmo com ultrassom inconclusivo, a conduta é cirúrgica, devido ao risco de perfuração.", category: "Pediatria" },
  { id: 774, question: "Em relação à nutrição do lactente, qual das seguintes afirmativas sobre a introdução alimentar complementar é correta, segundo as recomendações da Sociedade Brasileira de Pediatria (SBP)?", options: ["A introdução de alimentos sólidos deve ocorrer a partir do 4º mês de vida para estimular o desenvolvimento.", "Frutas e vegetais devem ser introduzidos, preferencialmente, após os 8 meses de idade.", "Não é recomendado oferecer água, chás ou sucos ao lactente antes dos 6 meses de idade, mesmo em climas quentes.", "Alimentos alergênicos, como ovo, amendoim e peixe, devem ser evitados até os 12 meses de idade para prevenir alergias."], correctIndex: 2, explanation: "As diretrizes da SBP e do MS recomendam aleitamento materno exclusivo até os 6 meses, sem oferta de água, chás ou sucos. A introdução alimentar complementar deve ocorrer a partir dos 6 meses, com oferta de diversos grupos alimentares, incluindo alimentos potencialmente alergênicos, para induzir tolerância.", category: "Pediatria" },
  { id: 775, question: "Recém-nascido a termo, com 48 horas de vida, apresenta icterícia. Bilirrubina total sérica é de 15 mg/dL, com fração indireta predominante. O bebê está mamando bem, sem sinais de doença. Qual é a conduta inicial mais apropriada de acordo com os nomogramas de Bhutani?", options: ["Iniciar fototerapia intensiva imediatamente", "Apenas observar e repetir bilirrubina em 24 horas", "Realizar exsanguineotransfusão", "Investigar causas patológicas de icterícia (ex: Coombs, tipagem sanguínea) e considerar fototerapia se nos limites superiores para a idade"], correctIndex: 0, explanation: "Para recém-nascidos a termo com 48 horas de vida, uma bilirrubina total de 15 mg/dL geralmente está acima do percentil 95 no nomograma, indicando a necessidade de fototerapia intensiva para prevenir Kernicterus.", category: "Pediatria" },
  { id: 776, question: "Qual das seguintes condições é a contraindicação ABSOLUTA para o aleitamento materno?", options: ["Mastite materna", "Uso materno de antidepressivos", "Infecção materna por HIV", "Lábio leporino no lactente"], correctIndex: 2, explanation: "A infecção materna por HIV é uma contraindicação absoluta para o aleitamento materno em países onde a substituição do leite materno é segura e factível, devido ao risco de transmissão vertical viral.", category: "Pediatria" },
  { id: 777, question: "Um menino de 2 anos é trazido ao pronto-socorro com história de início súbito de tosse, dispneia e estridor inspiratório após brincar com peças pequenas. Ao exame, apresenta cianose perioral e esforço respiratório acentuado. Qual é o diagnóstico e a conduta imediata mais prováveis?", options: ["Epiglotite; intubação orotraqueal e ceftriaxona", "Laringite viral; nebulização com adrenalina e corticoide oral", "Corpo estranho em via aérea; manobras de desobstrução (Heimlich) ou broncoscopia rígida", "Crise asmática; broncodilatador inalatório e corticoide sistêmico"], correctIndex: 2, explanation: "O quadro súbito de tosse, dispneia e estridor em uma criança brincando com objetos pequenos é altamente sugestivo de aspiração de corpo estranho em via aérea. A conduta imediata envolve manobras de desobstrução ou remoção via broncoscopia rígida.", category: "Pediatria" },
  { id: 778, question: "De acordo com as recomendações atuais do Ministério da Saúde para o Calendário de Vacinação da Criança, qual vacina é administrada ao nascimento?", options: ["Pneumocócica 10-valente e VIP (Poliomielite Inativada)", "BCG e Hepatite B", "Rotavírus e Pentavalente", "Meningocócica C (Conjugada) e Febre Amarela"], correctIndex: 1, explanation: "Ao nascimento, o calendário de vacinação do MS prevê a aplicação da vacina BCG (intradérmica) e da primeira dose da vacina Hepatite B (intramuscular).", category: "Pediatria" },
  { id: 779, question: "Adolescente de 14 anos, com histórico de asma brônquica, chega à emergência com dispneia intensa, sibilos expiratórios difusos e pico de fluxo expiratório de 40% do previsto. Qual é a conduta farmacológica inicial mais apropriada?", options: ["Salbutamol inalatório em aerossol dosimetrado (spray) 2 puffs", "Brometo de ipratrópio inalatório e corticoide oral", "Oxigênio suplementar, salbutamol inalatório (nebulização contínua ou doses repetidas) e corticoide sistêmico (oral ou endovenoso)", "Antibiótico sistêmico e antialérgico"], correctIndex: 2, explanation: "Em uma crise asmática grave, a conduta inicial inclui oxigênio suplementar, broncodilatador de curta ação (salbutamol) em doses elevadas ou contínuas, e corticoide sistêmico para controlar a inflamação.", category: "Pediatria" },
  { id: 780, question: "Qual das seguintes características é mais sugestiva de uma cardiopatia congênita cianótica?", options: ["Sopros cardíacos intensos audíveis em todas as áreas precordiais", "Atraso no desenvolvimento ponderoestatural e infecções respiratórias de repetição", "Cianose central, baqueteamento digital e policitemia", "Presença de tosse crônica e dispneia aos esforços leves"], correctIndex: 2, explanation: "Cianose central (lábios, língua, leitos ungueais), baqueteamento digital (acropaquia) e policitemia compensatória são achados clássicos de cardiopatias congênitas cianóticas, indicando hipoxemia crônica.", category: "Pediatria" },
  { id: 781, question: "Um lactente de 10 meses é trazido à consulta com história de diarreia aquosa há 4 dias, com 6-8 evacuações por dia, sem sangue ou muco. A mãe relata que ele está mais prostrado e com diminuição da diurese. Ao exame, apresenta olhos encovados, turgor da pele diminuído e tempo de enchimento capilar de 4 segundos. Qual o grau de desidratação e a conduta inicial mais adequada?", options: ["Desidratação leve; oferecer SRO em casa", "Desidratação moderada; iniciar SRO oral supervisionado na unidade de saúde", "Desidratação grave; iniciar hidratação endovenosa com solução salina isotônica", "Ausência de desidratação; observar e orientar sobre sinais de alerta"], correctIndex: 2, explanation: "Olhos encovados, turgor diminuído e enchimento capilar > 3 segundos são critérios para desidratação grave no lactente, indicando a necessidade de hidratação endovenosa imediata para correção do déficit.", category: "Pediatria" },
  { id: 782, question: "Qual o principal agente etiológico de bronquiolite aguda em lactentes?", options: ["Rinovírus", "Vírus Sincicial Respiratório (VSR)", "Influenza A", "Adenovírus"], correctIndex: 1, explanation: "O Vírus Sincicial Respiratório (VSR) é, de longe, o agente etiológico mais comum da bronquiolite aguda, responsável por até 70% dos casos, especialmente nos meses de inverno e primavera.", category: "Pediatria" },
  { id: 783, question: "Menina de 5 anos de idade chega ao pronto-socorro com febre de 39°C, dor de garganta intensa, disfagia e salivação. Ao exame, observa-se amígdalas hiperemiadas e edemaciadas com exsudato purulento, linfonodos cervicais anteriores aumentados e dolorosos. Qual o tratamento mais indicado, considerando o agente etiológico mais provável neste cenário?", options: ["Amoxicilina por 10 dias", "Aciclovir por 7 dias", "Prednisolona por 5 dias", "Observação e sintomáticos"], correctIndex: 0, explanation: "O quadro clínico é altamente sugestivo de faringoamigdalite estreptocócica, sendo a amoxicilina por 10 dias o tratamento de escolha para prevenir complicações como a febre reumática.", category: "Pediatria" },
  { id: 784, question: "Em relação ao desenvolvimento neuropsicomotor (DNPM), qual o marco esperado que uma criança atinge por volta dos 12 meses de idade?", options: ["Andar sem apoio", "Falar frases com duas palavras", "Apontar objetos e dar tchau", "Sentar sem apoio e rolar"], correctIndex: 2, explanation: "Por volta dos 12 meses, é esperado que a criança aponte objetos e dê tchau. Andar sem apoio e falar frases são marcos posteriores.", category: "Pediatria" },
  { id: 785, question: "Um adolescente de 15 anos é trazido ao pronto-socorro após uma queda. Ele está consciente, mas queixa-se de dor intensa na perna esquerda e não consegue apoiar o pé no chão. Há deformidade visível na região tibial. Qual é a conduta inicial prioritária?", options: ["Administrar analgésicos potentes e aguardar avaliação ortopédica", "Realizar tomografia computadorizada da perna para avaliar extensão da fratura", "Imobilizar o membro afetado, avaliar pulsos e sensibilidade, e administrar analgésicos", "Iniciar mobilização passiva para verificar a amplitude de movimento"], correctIndex: 2, explanation: "Em casos de suspeita de fratura, a conduta inicial prioritária é a imobilização do membro para evitar piora da lesão, a avaliação neurovascular distal (pulsos e sensibilidade) e o controle da dor com analgésicos.", category: "Pediatria" },
  { id: 786, question: "Qual é a principal indicação para a administração da Imunoglobulina Humana Anti-Ro (Rh) em Pediatria?", options: ["Tratamento de púrpura trombocitopênica idiopática (PTI)", "Prevenção da doença hemolítica perinatal em gestantes Rh negativo", "Profilaxia da infecção por Vírus Sincicial Respiratório (VSR) em prematuros", "Tratamento da doença de Kawasaki"], correctIndex: 1, explanation: "A Imunoglobulina Humana Anti-Rho (Rh) é utilizada na Pediatria, mas principalmente em Ginecologia/Obstetrícia, para prevenir a isoimunização Rh em gestantes Rh negativo, evitando a doença hemolítica perinatal em gestações futuras.", category: "Pediatria" },
  { id: 787, question: "Um escolar de 7 anos apresenta febre alta, cefaleia intensa, dor abdominal e exantema maculopapular avermelhado que se iniciou em face e se disseminou para tronco e membros. No 5º dia de doença, a febre cede, mas o exantema descama. Qual o diagnóstico mais provável?", options: ["Exantema súbito (roseola infantil)", "Eritema infeccioso (quinta doença)", "Sarampo", "Varicela"], correctIndex: 2, explanation: "O sarampo é caracterizado por febre alta, cefaleia, prostração, exantema maculopapular com progressão cefalo-caudal, e descamação após o fim da febre. Os outros exantemas têm características e evolução diferentes.", category: "Pediatria" },
  { id: 788, question: "Qual das seguintes afirmativas sobre a febre reumática é INCORRETA?", options: ["É uma doença inflamatória autoimune que ocorre após infecção estreptocócica do trato respiratório superior.", "A coreia de Sydenham é uma manifestação tardia e frequentemente isolada da doença.", "A cardite reumática é a manifestação mais grave e pode levar a sequelas cardíacas permanentes.", "O diagnóstico é realizado com base nos critérios de Jones e pela cultura de orofaringe."], correctIndex: 3, explanation: "O diagnóstico de febre reumática é clínico, baseado nos critérios de Jones (maiores e menores), e na evidência de uma infecção estreptocócica prévia, que não é necessariamente confirmada pela cultura de orofaringe no momento do diagnóstico da febre reumática, mas por outros exames como o ASLO ou teste rápido.", category: "Pediatria" },
  { id: 789, question: "Lactente de 3 meses, com baixo peso ao nascer, em acompanhamento em puericultura, apresenta baixa adesão alimentar e ganho de peso insuficiente. Qual a primeira medida a ser investigada e corrigida antes de considerar diagnósticos mais complexos?", options: ["Erros alimentares e técnicas de amamentação/oferta de fórmula", "Deficiências enzimáticas congênitas (ex: fenilcetonúria)", "Cardiopatias congênitas graves", "Infecções urinárias de repetição"], correctIndex: 0, explanation: "Na maioria dos casos de baixo ganho de peso em lactentes, a causa mais comum e, portanto, a primeira a ser investigada e corrigida, são os erros alimentares ou problemas com a técnica de amamentação/oferta de fórmula.", category: "Pediatria" },
  { id: 790, question: "Qual o principal mecanismo de ação do palivizumabe, indicado para profilaxia da infecção grave por VSR em grupos de risco?", options: ["Estímulo à produção de anticorpos maternos", "Indução de imunidade celular específica contra VSR", "Anticorpo monoclonal que neutraliza o VSR", "Vacina atenuada contra o VSR"], correctIndex: 2, explanation: "O palivizumabe é um anticorpo monoclonal humanizado específico para um epítopo da proteína de fusão (F) do Vírus Sincicial Respiratório (VSR). Atua como imunização passiva, neutralizando o vírus e prevenindo infecções graves.", category: "Pediatria" },
  { id: 791, question: "Menina de 2 anos é trazida ao pronto-socorro com história de vômitos biliosos intermitentes e evacuações com sangue e muco ('geleia de framboesa'). A mãe relata que a criança estava irritada e com dor abdominal em cólica. Ao exame, palpa-se uma massa em forma de salsicha no quadrante superior direito do abdome. Qual o diagnóstico mais provável?", options: ["Apensdite aguda", "Hernia inguinal encarcerada", "Intussuscepção", "Gastroenterite aguda"], correctIndex: 2, explanation: "O quadro de vômitos biliosos, dor abdominal em cólica, fezes em 'geleia de framboesa' e a palpação de massa abdominal em forma de salsicha são achados clássicos de intussuscepção.", category: "Pediatria" },
  { id: 792, question: "Em relação à sepse neonatal, qual das seguintes afirmativas está correta?", options: ["Sinais e sintomas são sempre específicos, facilitando o diagnóstico precoce.", "O hemograma é o exame mais sensível e específico para o diagnóstico.", "A proteína C reativa (PCR) é um marcador inflamatório útil, mas deve ser interpretada no contexto clínico.", "A antibioticoterapia empírica inicial deve ser restrita para evitar resistência antimicrobiana."], correctIndex: 2, explanation: "A PCR é um marcador inflamatório útil para auxiliar no diagnóstico e no acompanhamento da sepse neonatal. No entanto, sua elevação não é exclusiva da sepse e pode ocorrer em outras condições, exigindo interpretação cautelosa e em conjunto com os dados clínicos.", category: "Pediatria" },
  { id: 793, question: "Qual a medida mais eficaz na prevenção da Síndrome da Morte Súbita do Lactente (SMSL)?", options: ["Colocar o lactente para dormir de bruços (decúbito ventral).", "Oferecer brinquedos macios no berço para conforto.", "Compartilhar a cama com os pais (co-leito).", "Colocar o lactente para dormir de costas (decúbito dorsal) em um berço seguro."], correctIndex: 3, explanation: "A principal recomendação para a prevenção da SMSL é sempre colocar o lactente para dormir de costas (decúbito dorsal), em berço seguro, sem objetos que possam obstruir as vias aéreas.", category: "Pediatria" },
  { id: 794, question: "Um adolescente de 13 anos é diagnosticado com diabetes mellitus tipo 1. Qual o tratamento prioritário e fundamental para este paciente?", options: ["Dieta rigorosa com restrição de carboidratos e uso de metformina oral.", "Insulinoterapia, monitorização da glicemia e educação nutricional.", "Uso de sulfonilureias e exercícios físicos intensos.", "Internação hospitalar prolongada para controle glicêmico e alta com acompanhamento nutricional."], correctIndex: 1, explanation: "O tratamento do diabetes mellitus tipo 1 é baseado na insulinoterapia (substituição da insulina que o pâncreas não produz), monitorização glicêmica domiciliar e educação nutricional para controle da doença.", category: "Pediatria" },
  { id: 795, question: "Qual o principal critério para definir sucesso da hidratação oral em uma criança com diarreia e desidratação leve a moderada?", options: ["O desaparecimento completo da diarreia.", "A ausência de sede e a melhora do estado geral, com diurese presente.", "A normalização dos eletrólitos séricos.", "O retorno imediato à dieta habitual."], correctIndex: 1, explanation: "O sucesso da hidratação oral é determinado pela melhora clínica do paciente, incluindo o desaparecimento da sede, melhora do estado geral (criança mais ativa e sorridente) e presença de diurese, indicando reidratação eficaz.", category: "Pediatria" },
  { id: 796, question: "Um paciente de 60 anos é encontrado inconsciente. A equipe inicia as manobras de reanimação cardiopulmonar (RCP). Qual a frequência de compressões torácicas recomendada pelas diretrizes atuais para adultos?", options: ["60-80 compressões por minuto", "80-100 compressões por minuto", "100-120 compressões por minuto", "120-140 compressões por minuto"], correctIndex: 2, explanation: "As diretrizes atuais (AHA 2020-2025, incorporadas pelas diretrizes brasileiras) recomendam uma frequência de 100 a 120 compressões por minuto para adultos em RCP, visando maximizar o fluxo sanguíneo cerebral e coronariano.", category: "PCR" },
  { id: 797, question: "Durante a RCP em um adulto, qual a profundidade de compressão torácica recomendada?", options: ["Pelo menos 3 cm", "Pelo menos 4 cm", "Pelo menos 5 cm e não mais que 6 cm", "Pelo menos 7 cm"], correctIndex: 2, explanation: "A profundidade de compressão torácica em adultos deve ser de pelo menos 5 cm, mas não exceder 6 cm. Compressões muito rasas ou muito profundas podem ser ineficazes ou causar lesões.", category: "PCR" },
  { id: 798, question: "Qual a proporção compressão-ventilação recomendada para RCP em adulto com via aérea não avançada?", options: ["15:2", "30:2", "5:1", "10:1"], correctIndex: 1, explanation: "Para RCP em adulto com via aérea não avançada, a proporção recomendada é de 30 compressões para cada 2 ventilações. Essa proporção equilibra a oferta de oxigênio com a perfusão cerebral e coronariana.", category: "PCR" },
  { id: 799, question: "Em um cenário de PCR em ritmo chocável (fibrilação ventricular ou taquicardia ventricular sem pulso), qual a conduta imediata após a identificação do ritmo e a aplicação das compressões iniciais?", options: ["Administrar adrenalina endovenosa", "Administrar amiodarona endovenosa", "Realizar desfibrilação assim que o desfibrilador estiver disponível", "Aguardar 2 minutos de RCP e então desfibrilar"], correctIndex: 2, explanation: "Em ritmos chocáveis, a desfibrilação precoce é a intervenção mais crítica para reverter a PCR. Deve ser realizada assim que o desfibrilador estiver disponível e carregado, minimizando as interrupções nas compressões.", category: "PCR" },
  { id: 800, question: "Um paciente em PCR com assistolia é monitorizado. Qual a principal conduta farmacológica a ser considerada neste ritmo?", options: ["Amiodarona", "Lidocaína", "Adenosina", "Adrenalina"], correctIndex: 3, explanation: "Para ritmos não chocáveis, como assistolia e atividade elétrica sem pulso (AESP), a adrenalina é o principal fármaco recomendado. Atua como vasopressor e visa aumentar a pressão de perfusão coronariana e cerebral.", category: "PCR" },
  { id: 801, question: "Qual a dose de adrenalina recomendada para uso em PCR em adultos, via endovenosa ou intraóssea?", options: ["0,1 mg a cada 5 minutos", "0,5 mg a cada 3-5 minutos", "1 mg a cada 3-5 minutos", "2 mg a cada 2-3 minutos"], correctIndex: 2, explanation: "A dose padrão de adrenalina para PCR em adultos é de 1 mg IV/IO a cada 3-5 minutos. Essa dosagem tem sido estabelecida para otimizar os efeitos alfa-adrenérgicos desejados na PCR.", category: "PCR" },
  { id: 802, question: "Em um paciente com PCR pediátrica, qual a dose inicial de adrenalina recomendada?", options: ["0,001 mg/kg", "0,01 mg/kg", "0,1 mg/kg", "1 mg/kg"], correctIndex: 1, explanation: "Para PCR pediátrica, a dose inicial de adrenalina é de 0,01 mg/kg IV/IO. É crucial o cálculo preciso da dose baseada no peso para evitar erros de medicação em crianças.", category: "PCR" },
  { id: 803, question: "Qual das seguintes 'H's é uma causa reversível de PCR?", options: ["Hipertensão", "Hipertermia", "Hipocalcemia", "Hipovolemia"], correctIndex: 3, explanation: "A hipovolemia é uma das causas reversíveis ('H's e 'T's) de PCR. A identificação e correção rápidas, muitas vezes com volume, são cruciais para o prognóstico.", category: "PCR" },
  { id: 804, question: "Qual das seguintes 'T's é uma causa reversível de PCR?", options: ["Taquicardia supraventricular", "Trombose coronariana", "Trauma craniano isolado", "Toxicidade por opióides"], correctIndex: 1, explanation: "A trombose coronariana (infarto agudo do miocárdio) é uma das causas reversíveis ('T's) de PCR. O tratamento específico, como a reperfusão, pode reverter a PCR.", category: "PCR" },
  { id: 805, question: "Na PCR em gestantes, qual a principal adaptação na técnica de RCP, a partir de qual idade gestacional, é recomendada?", options: ["Elevação dos membros inferiores em todas as gestantes", "Deslocamento manual do útero para a esquerda, a partir de 20 semanas de gestação ou altura uterina compatível", "Compressões torácicas mais profundas devido ao aumento do volume sanguíneo", "Realizar ventilação com pressão positiva intermitente em todas as gestantes em PCR"], correctIndex: 1, explanation: "Em gestantes a partir de 20 semanas de gestação (ou altura uterina compatível), é recomendado o deslocamento manual do útero para a esquerda para aliviar a compressão da veia cava inferior e aorta pelo útero grávido, otimizando o retorno venoso e o débito cardíaco.", category: "PCR" },
  { id: 806, question: "Após o retorno da circulação espontânea (RCE) em um paciente com PCR, qual é um objetivo primordial do manejo pós-PCR?", options: ["Administrar diuréticos para prevenir edema cerebral", "Manter a temperatura corporal acima de 38°C para otimizar o metabolismo", "Otimizar a ventilação e oxigenação para evitar hipóxia e hipercapnia", "Iniciar antiarrítmicos profiláticos em todos os pacientes"], correctIndex: 2, explanation: "Após o RCE, a otimização da ventilação e oxigenação é crucial para prevenir lesão cerebral secundária. Hipóxia e hipercapnia devem ser evitadas, mantendo PaO2 e PaCO2 em níveis fisiológicos.", category: "PCR" },
  { id: 807, question: "Qual a principal indicação para o uso de amiodarona na PCR?", options: ["Assistolia", "Atividade elétrica sem pulso (AESP)", "Fibrilação ventricular (FV) ou taquicardia ventricular sem pulso (TVSP) refratária à desfibrilação inicial", "Bradicardia sintomática"], correctIndex: 2, explanation: "A amiodarona é um antiarrítmico de classe III indicado para FV ou TVSP que persiste ou recorre após múltiplas desfibrilações e adrenalina. Não é usada em assistolia ou AESP.", category: "PCR" },
  { id: 808, question: "Um paciente jovem, previamente hígido, apresenta-se no pronto-socorro com palpitações rápidas e regulares, tontura e mal-estar. O ECG de 12 derivações mostra taquicardia com QRS estreito (0,08s), regular, frequência de 180 bpm, sem ondas P visíveis antes de cada QRS. Qual a provável arritmia e a conduta inicial mais apropriada se o paciente estiver estável hemodynamicamente?", options: ["Fibrilação atrial; betabloqueador oral ou diltiazem.", "Taquicardia ventricular; cardioversão elétrica sincronizada.", "Taquicardia supraventricular paroxística (TSVP); manobras vagais e, se ineficazes, adenosina IV.", "Flutter atrial; amiodarona IV."], correctIndex: 2, explanation: "Taquicardia com QRS estreito, regular, sem ondas P visíveis e frequência elevada é sugestiva de TSVP. Em pacientes hemodinamicamente estáveis, as manobras vagais são a primeira linha de tratamento, seguidas pela adenosina intravenosa se as manobras forem ineficazes.", category: "Emergência" },
  { id: 809, question: "No manejo inicial do choque séptico em adultos, após a estabilização da via aérea e ventilação, qual a etapa mais prioritária, de acordo com as diretrizes atuais?", options: ["Início de antibioticoterapia de amplo espectro após coleta de culturas sanguíneas.", "Administração de corticoides intravenosos em dose de estresse.", "Uso de noradrenalina para manter a pressão arterial média (PAM) acima de 65 mmHg.", "Reposição volêmica com cristaloides, 30 mL/kg, nas primeiras 3 horas."], correctIndex: 3, explanation: "As diretrizes do Surviving Sepsis Campaign priorizam a reposição volêmica com 30 mL/kg de cristaloides nas primeiras 3 horas como medida inicial para o choque séptico, após a estabilização da via aérea e ventilação, objetivando otimizar a perfusão tecidual.", category: "Emergência" },
  { id: 810, question: "Um paciente de 40 anos é trazido ao pronto-socorro após um acidente automobilístico. Apresenta dispneia intensa, dor torácica pleurítica, hipotensão (PA 80/50 mmHg), taquicardia (FC 130 bpm) e desvio da traqueia para a direita. À ausculta pulmonar, há abolição do murmúrio vesicular à esquerda e hipertimpanismo à percussão do mesmo hemitórax. Qual a conduta imediata mais apropriada?", options: ["Solicitar raio-X de tórax para confirmar o diagnóstico.", "Realizar intubação orotraqueal e iniciar ventilação mecânica.", "Punção de alívio com agulha no segundo ou terceiro espaço intercostal na linha hemiclavicular esquerda.", "Infundir volume rapidamente para estabilizar a pressão arterial."], correctIndex: 2, explanation: "O quadro clínico é compatível com pneumotórax hipertensivo, uma emergência médica que exige descompressão imediata. A punção de alívio com agulha no 2º ou 3º espaço intercostal, na linha hemiclavicular, no lado afetado, é a conduta salvadora de vida, mesmo antes da confirmação radiológica.", category: "Emergência" },
  { id: 811, question: "Um paciente com insuficiência cardíaca crônica descompensada, em classe funcional IV, é admitido com dispneia progressiva, ortopneia, crepitações pulmonares bilaterais e edema de membros inferiores 3+/4+. Qual a terapia medicamentosa intravenosa inicial mais recomendada para alívio dos sintomas?", options: ["Enalaprilide e espironolactona.", "Digoxina e dobutamina.", "Furosemida e nitraglicerina.", "Anlodipino e carvedilol."], correctIndex: 2, explanation: "Na descompensação aguda da insuficiência cardíaca com congestão pulmonar, a furosemida (diurético de alça) é fundamental para reduzir a pré-carga e a nitraglicerina (vasodilatador venoso e arterial) para diminuir a pré-carga e a pós-carga, promovendo rápido alívio sintomático.", category: "Emergência" },
  { id: 812, question: "Qual das seguintes condições NÃO é uma causa comum de parada cardiorrespiratória (PCR) reversível (reconhecida como um dos 'Hs e Ts')?", options: ["Hipotermia.", "Hipocalcemia grave.", "Tromboembolismo pulmonar.", "Tóxicos (intoxicações)."], correctIndex: 1, explanation: "As causas reversíveis da PCR (4 Hs e 4 Ts) incluem: Hipóxia, Hipovolemia, Hipo/Hipercalemia, Hipotermia, Toxinas, Tamponamento cardíaco, Tensão (pneumotórax hipertensivo) e Trombose (coronariana ou pulmonar). Hipocalcemia grave, embora possa causar arritmias, não é classicamente listada entre os 4Hs e 4Ts principais.", category: "Emergência" },
  { id: 813, question: "No caso de uma crise asmática grave, qual das seguintes condutas NÃO faz parte do manejo inicial recomendado?", options: ["Corticosteroide sistêmico (oral ou intravenoso).", "Oxigenoterapia para manter saturação > 92%.", "Broncodilatador de curta ação (agonista beta-2) inalatório de forma contínua ou seriada.", "Antibiótico empírico para cobrir uma possível infecção bacteriana."], correctIndex: 3, explanation: "O tratamento inicial da crise asmática grave foca em oxigenoterapia, broncodilatadores de curta ação e corticosteroides sistêmicos. Antibióticos são indicados apenas se houver evidência clara de infecção bacteriana, não devendo ser administrados empiricamente.", category: "Emergência" },
  { id: 814, question: "Um paciente de 50 anos desenvolve crise convulsiva tônico-clônica generalizada que não cede após 5 minutos. Ele não tem história prévia de epilepsia. Qual o fármaco de primeira linha para cessar a convulsão neste cenário?", options: ["Fenitoína intravenosa.", "Ácido valproico intravenoso.", "Diazepam intravenoso.", "Levetiracetam intravenoso."], correctIndex: 2, explanation: "Para o status epilepticus (crise convulsiva contínua por mais de 5 minutos ou múltiplas crises sem recuperação da consciência), as benzodiazepinas (diazepam IV, lorazepam IV ou midazolam IM/IV) são os fármacos de primeira linha para cessar a crise rapidamente.", category: "Emergência" },
  { id: 815, question: "Qual a principal complicação associada à administração de fluidos intravenosos em grande volume durante o manejo do choque hemorrágico em pacientes traumatizados antes do controle definitivo da hemorragia?", options: ["Hipotermia.", "Coagulopatia dilucional.", "Hipernatremia.", "Arritmias cardíacas."], correctIndex: 1, explanation: "A reposição volêmica agressiva com cristaloides antes do controle cirúrgico da hemorragia em choque hemorrágico pode levar à coagulopatia dilucional, hipotermia e acidose, piorando o quadro do paciente e aumentando a mortalidade.", category: "Emergência" },
  { id: 816, question: "No contexto de trauma cranioencefálico (TCE) grave, qual das seguintes medidas é fundamental para prevenir lesão cerebral secundária?", options: ["Manter a pressão arterial média (PAM) < 60 mmHg para evitar hipertensão intracraniana.", "Administrar glicose intravenosa de rotina para todos os pacientes.", "Garantir ventilação adequada para evitar hipóxia e hipercapnia.", "Realizar craniotomia descompressiva de forma profilática em todos os TCEs graves."], correctIndex: 2, explanation: "A hipóxia e a hipercapnia são fatores críticos que pioram o prognóstico no TCE grave. Manter a via aérea pérvia e assegurar ventilação adequada, controlando PCO2 e PaO2, é essencial para evitar lesão secundária.", category: "Emergência" },
  { id: 817, question: "Um paciente de 70 anos, com história de fibrilação atrial não anticoagulada, apresenta-se com início súbito de afasia e hemiparesia à direita. A tomografia de crânio realizada 1 hora após o início dos sintomas não mostra sangramento. Qual a conduta mais indicada para este paciente?", options: ["Iniciar heparina de baixo peso molecular imediatamente.", "Administrar ácido acetilsalicílico (AAS) e clopidogrel.", "Considerar trombólise endovenosa com alteplase, se preencher critérios.", "Internar para investigação e iniciar anticoagulação oral após 24 horas."], correctIndex: 2, explanation: "O quadro é compatível com acidente vascular cerebral isquêmico (AVCI) agudo cardioembólico. Se o paciente se apresentar dentro da janela terapêutica (geralmente até 4,5 horas) e preencher os demais critérios, a trombólise endovenosa com alteplase é a principal terapia de reperfusão.", category: "Emergência" },
  { id: 818, question: "Qual é o principal marcador laboratorial utilizado para diagnóstico e monitorização da insuficiência cardíaca aguda?", options: ["Dímero D.", "Troponina I de alta sensibilidade.", "Peptídeo natriurético tipo B (BNP) ou N-terminal pro-BNP (NT-proBNP).", "Creatinoquinase MB (CK-MB)."], correctIndex: 2, explanation: "O BNP e o NT-proBNP são peptídeos liberados pelos cardiomiócitos em resposta ao estiramento ventricular e são marcadores sensíveis e específicos de sobrecarga de fluidos e disfunção ventricular, sendo amplamente utilizados no diagnóstico e prognóstico da insuficiência cardíaca.", category: "Emergência" },
  { id: 819, question: "No manejo da crise hipertensiva, qual a classe de medicamentos que deve ser evitada em pacientes com suspeita de acidente vascular cerebral isquêmico agudo?", options: ["Inibidores da enzima conversora de angiotensina (IECAs).", "Bloqueadores dos canais de cálcio (BCCs).", "Vasodilatadores diretos (ex: hidralazina).", "Betabloqueadores."], correctIndex: 0, explanation: "IECA e BCC podem causar queda abrupta da pressão arterial, o que, em pacientes com AVCI agudo, pode comprometer a perfusão cerebral em zonas de penumbra, piorando o desfecho neurológico. A pressão arterial deve ser abaixada gradualmente e com cautela nesses casos (não mais que 15% nas primeiras 24 horas).", category: "Emergência" },
  { id: 820, question: "Um paciente com suspeita de embolia pulmonar apresenta dispneia súbita, dor torácica pleurítica, taquicardia e hipoxemia. Ele está hemodinamicamente instável (hipotenso). Qual o exame diagnóstico de escolha neste paciente?", options: ["Angiotomografia de tórax (Angio-TC de tórax).", "Cintilografia pulmonar de ventilação/perfusão.", "Eco transtorácico.", "Início de tratamento empírico e aguardar estabilização para exames."], correctIndex: 0, explanation: "A angiotomografia de tórax (Angio-TC) é o exame padrão-ouro para o diagnóstico de embolia pulmonar. Em pacientes hemodinamicamente instáveis, o uso do eco transtorácico pode auxiliar no diagnóstico rápido de cor pulmonale agudo, mas a Angio-TC ainda é a escolha diagnóstica definitiva se o paciente puder ser transportado com segurança para o exame.", category: "Emergência" },
  { id: 821, question: "Em relação à dor abdominal aguda no pronto-socorro, qual das seguintes afirmativas é verdadeira?", options: ["Pacientes com dor abdominal aguda devem sempre receber analgésicos antes do exame físico para maior conforto.", "A apendicite aguda é mais comum em idosos e geralmente se apresenta com dor epigástrica que migra para o quadrante inferior esquerdo.", "A diverticulite aguda é frequentemente diagnosticada através de ultrassonografia abdominal.", "A perforação de víscera oca geralmente apresenta-se com dor abdominal intensa, súbita, difusa, e pode levar a irritação peritoneal."], correctIndex: 3, explanation: "A perfuração de víscera oca é uma emergência cirúrgica que tipicamente cursa com dor abdominal intensa e difusa, seguida de sinais de peritonite. A analgesia não deve atrasar a avaliação clínica.", category: "Emergência" },
  { id: 822, question: "Um paciente comparece ao pronto-socorro com queixa de cefaleia súbita e intensa ('thunderclap headache'), associada a náuseas, vômitos e rigidez de nuca. Qual a principal suspeita diagnóstica?", options: ["Enxaqueca com aura.", "Meningite viral.", "Hemorragia subaracnoidea.", "Cefaleia tensional."], correctIndex: 2, explanation: "Cefaleia 'thunderclap', súbita e excruciante, com ou sem sinais meníngeos, sugere fortemente hemorragia subaracnoidea e exige investigação imediata, geralmente com tomografia de crânio e, se negativa, punção lombar.", category: "Emergência" },
  { id: 823, question: "A principal indicação para o uso de naloxona em emergência é o tratamento de:", options: ["Intoxicação por benzodiazepínicos.", "Reações anafiláticas graves.", "Depressão respiratória por opioides.", "Hipoglicemia grave em pacientes diabéticos."], correctIndex: 2, explanation: "A naloxona é um antagonista de receptores opioides e está indicada para reverter a depressão respiratória e outros efeitos de intoxicação por opioides (naturais ou sintéticos).", category: "Emergência" },
  { id: 824, question: "Qual das seguintes ações NÃO faz parte do protocolo de atendimento inicial a um paciente queimado grave?", options: ["Estabelecimento de via aérea e ventilação.", "Cálculo da superfície corporal queimada (SCQ) e início da reposição volêmica segundo a fórmula de Parkland.", "Remoção de roupas e joias.", "Administração intramuscular de opioides para analgesia."], correctIndex: 3, explanation: "A analgesia no paciente queimado geralmente é administrada por via intravenosa, pois a absorção intramuscular pode ser errática e ineficaz em grandes queimaduras, além de potencialmente causar acúmulo de medicamento quando a perfusão melhora.", category: "Emergência" },
  { id: 825, question: "Um paciente chega ao pronto-socorro com queimaduras circulares de terceiro grau em membro superior direito. Qual a principal complicação imediata a ser monitorizada e prevenida?", options: ["Infecção da ferida.", "Síndrome compartimental.", "Hipotermia grave.", "Desidratação."], correctIndex: 1, explanation: "Queimaduras circulares de terceiro grau podem levar à formação de escara rígida, que impede a expansão dos tecidos em casos de edema, resultando em síndrome compartimental, com comprometimento vascular e neurológico. Pode ser necessária escarotomia de urgência.", category: "Emergência" },
  { id: 826, question: "Em pacientes com crise tireotóxica (tempestade tireoidiana), qual das seguintes condutas é contraindicada?", options: ["Administração de propiltiouracil.", "Administração de iodo inorgânico.", "Uso de corticosteroides.", "Administração de ácido acetilsalicílico (AAS) para controle da febre."], correctIndex: 3, explanation: "O ácido acetilsalicílico (AAS) deve ser evitado na crise tireotóxica, pois pode deslocar os hormônios tireoidianos de suas proteínas de ligação, aumentando os níveis de hormônio tireoidiano livre e piorando o quadro.", category: "Emergência" },
  { id: 827, question: "Qual a principal causa de morte evitável em pacientes traumatizados?", options: ["Lesão cerebral traumática.", "Choque hipovolêmico não controlado.", "Tromboembolismo pulmonar.", "Sepse tardia."], correctIndex: 1, explanation: "A hemorragia não controlada levando a choque hipovolêmico é a principal causa de morte evitável em pacientes traumatizados, o que ressalta a importância do controle rápido da perda sanguínea.", category: "Emergência" },
  { id: 828, question: "Um paciente com insuficiência renal crônica em hemodiálise comparece ao pronto-socorro com dor torácica atípica, dispneia e alterações no ECG como ondas T apiculadas e QRS alargado. Qual alteração eletrolítica deve ser imediatamente investigada?", options: ["Hipocalcemia.", "Hiponatremia.", "Hiperpotassemia.", "Hipomagnesemia."], correctIndex: 2, explanation: "O quadro clínico e as alterações eletrocardiográficas (ondas T apiculadas, QRS alargado, BRD/BRE, onda P achatada/ausente) são altamente sugestivos de hiperpotassemia, uma emergência médica que pode levar a arritmias fatais, comum em pacientes renais em hemodiálise.", category: "Emergência" },
  { id: 829, question: "A principal indicação para uso de bicarbonato de sódio intravenoso na urgência é:", options: ["Cetoacidose diabética grave.", "Sepse grave com acidose metabólica.", "Parada cardiorrespiratória.", "Acidose metabólica grave com pH < 7,1 e comprometimento hemodinâmico, após correção da causa subjacente e adequada ventilação."], correctIndex: 3, explanation: "O uso de bicarbonato na acidose metabólica deve ser criterioso. É geralmente reservado para acidose grave (pH < 7,1 ou 7,0, dependendo da diretriz) com comprometimento hemodinâmico, após otimização da ventilação e correção da causa subjacente, para evitar a piora paradoxal da acidose intracelular e sobrecarga de volume.", category: "Emergência" },
  { id: 830, question: "Qual das seguintes características clínicas é mais indicativa de uma hemorragia digestiva alta em comparação com uma baixa?", options: ["Eliminação de fezes com raias de sangue vivo.", "Melena (fezes escuras, pastosas e fétidas).", "Presença de hematoquezia (sangue vermelho vivo nas fezes).", "Dor abdominal em cólica e diarreia sanguinolenta."], correctIndex: 1, explanation: "Melena é o resultado da digestão do sangue pelo ácido gástrico e enzimas intestinais, sendo um forte indicativo de hemorragia digestiva alta. Fezes com sangue vivo ou hematoquezia são mais comuns em sangramentos da parte inferior do trato gastrointestinal.", category: "Emergência" },
  { id: 831, question: "Em um paciente com suspeita de aneurisma de aorta abdominal roto, qual o exame diagnóstico de escolha para confirmação, desde que o paciente esteja hemodinamicamente estável para realizá-lo?", options: ["Radiografia simples de abdome.", "Ultrassonografia abdominal.", "Tomografia computadorizada de abdome com contraste.", "Ressonância magnética de abdome."], correctIndex: 2, explanation: "A tomografia computadorizada de abdome com contraste é o exame padrão-ouro para o diagnóstico de aneurisma de aorta abdominal roto ou ameaçado, fornecendo detalhes precisos sobre o tamanho, localização e extravasamento.", category: "Emergência" },
  { id: 832, question: "Paciente masculino, 65 anos, hipertenso e diabético, é admitido com dor torácica retroesternal intensa, irradiando para membro superior esquerdo, com 3 horas de duração. Ao eletrocardiograma, observa-se supradesnivelamento do segmento ST em parede inferior (DII, DIII, aVF). Qual a conduta inicial mais apropriada para este paciente?", options: ["Administração de oxigênio suplementar, heparina não fracionada, nitratos sublinguais e aguardar cateterismo cardíaco eletivo.", "Administração de aspirina, ticagrelor, atorvastatina, oxigênio suplementar e encaminhamento imediato para angioplastia primária.", "Administração de morfina, heparina de baixo peso molecular, clopidogrel e realização de trombolítico em sala de emergência.", "Administração de fentanil, propranolol, heparina não fracionada e ressonância magnética cardíaca de urgência."], correctIndex: 1, explanation: "Diante de um IAM com supradesnivelamento do segmento ST (IAMCSST), a terapia de reperfusão é prioritária. A angioplastia primária é preferível se realizada em tempo hábil. A conduta inicial inclui terapia antiplaquetária dupla (aspirina e um inibidor P2Y12, como ticagrelor), estatina de alta potência e oxigênio se hipoxemia.", category: "IAM" },
  { id: 833, question: "Qual das seguintes alterações eletrocardiográficas é mais sugestiva de uma isquemia miocárdica que requer avaliação imediata para síndrome coronariana aguda?", options: ["Inversão da onda T simétrica e profunda em precordiais laterais (V5-V6).", "Elevação do segmento ST difusa com concavidade para cima.", "Ondas Q patológicas isoladas em DIII e aVF.", "Supradesnivelamento do segmento ST de 1,5 mm em V2 em paciente do sexo feminino."], correctIndex: 3, explanation: "O supradesnivelamento do segmento ST é o principal critério eletrocardiográfico para IAMCSST, com valores de corte dependendo da idade, sexo e derivação. Em mulheres, o supradesnivelamento ≥ 1,5 mm em V2-V3 é patológico, enquanto em homens, esse valor é geralmente ≥ 2,5 mm (< 40 anos) ou ≥ 2,0 mm (≥ 40 anos).", category: "IAM" },
  { id: 834, question: "Em um paciente com IAM sem supradesnivelamento do segmento ST (IAMSST) de alto risco, qual o tempo máximo recomendado para a realização de estratificação invasiva (coronariografia) após a admissão?", options: ["Até 2 horas.", "Até 24 horas.", "Até 72 horas.", "Até 7 dias."], correctIndex: 1, explanation: "Para pacientes com IAMSST de alto risco (escalas GRACE ou TIMI elevadas, marcadores de necrose miocárdica continuamente elevados, alterações dinâmicas do ST-T), a estratificação invasiva precoce, preferencialmente nas primeiras 24 horas, é recomendada pelas diretrizes para melhorar o prognóstico.", category: "IAM" },
  { id: 835, question: "Um paciente em uso de dupla antiagregação plaquetária com aspirina e clopidogrel pós-IAM apresenta sangramento gastrointestinal moderado. Qual a conduta mais adequada em relação à terapia antiplaquetária?", options: ["Suspender imediatamente ambos os antiagregantes e iniciar inibidor de bomba de prótons.", "Manter aspirina, suspender clopidogrel e avaliar substituição por prasugrel.", "Manter aspirina, suspender clopidogrel e associar inibidor de bomba de prótons.", "Suspender aspirina, manter clopidogrel e realizar endoscopia digestiva alta."], correctIndex: 2, explanation: "Em caso de sangramento moderado, a diretriz recomenda manter a aspirina (se possível) e suspender o segundo antiagregante (clopidogrel nesse caso), associando um inibidor de bomba de prótons para proteção gástrica. A interrupção precoce de ambos os fármacos aumenta o risco de trombose de stent.", category: "IAM" },
  { id: 836, question: "Qual dos seguintes mecanismos farmacológicos é o principal objetivo da administração de nitratos em pacientes com síndromes coronarianas agudas?", options: ["Redução da frequência cardíaca e do consumo de oxigênio pelo miocárdio.", "Inibição da agregação plaquetária e prevenção de trombose.", "Vasodilatação periférica e coronariana, reduzindo a pré-carga e a dor.", "Estabilização da placa aterosclerótica e redução da inflamação vascular."], correctIndex: 2, explanation: "Os nitratos atuam como vasodilatadores, principalmente venosos, reduzindo assim o retorno venoso (pré-carga) e a demanda de oxigênio miocárdico. Também promovem alguma vasodilatação coronariana, aliviando a isquemia e a dor torácica.", category: "IAM" },
  { id: 837, question: "Em um paciente que apresenta IAMCSST na parede anterior (V1-V4), qual complicação mecânica aguda é mais provável de ocorrer?", options: ["Insuficiência mitral aguda por ruptura de músculo papilar.", "Comunicação interventricular por ruptura do septo.", "Taponamento cardíaco por ruptura de parede livre.", "Pseudoaneurisma de ventrículo esquerdo."], correctIndex: 1, explanation: "A ruptura do septo interventricular é uma complicação mecânica grave do IAM e é mais comum após infarto de parede anterior, devido à irrigação do septo por ramos da artéria descendente anterior. Manifesta-se geralmente com novo sopro holossistólico e deterioração hemodinâmica.", category: "IAM" },
  { id: 838, question: "Qual marcador bioquímico é considerado o padrão-ouro para diagnóstico de necrose miocárdica em síndromes coronarianas agudas?", options: ["CK-MB massa.", "Mioglobina.", "Troponina de alta sensibilidade.", "Lactato desidrogenase (LDH)."], correctIndex: 2, explanation: "As troponinas cardíacas (troponina I e troponina T), especialmente as de alta sensibilidade, são os biomarcadores mais sensíveis e específicos para detecção de necrose miocárdica, permitindo diagnóstico precoce e preciso de infarto agudo do miocárdio.", category: "IAM" },
  { id: 839, question: "Paciente com IAMCSST é submetido a angioplastia primária. Qual a droga antiplaquetária inibidora do receptor P2Y12 é preferencialmente utilizada, se não houver contraindicação?", options: ["Clopidogrel.", "Ticagrelor.", "Prasugrel.", "Cangrelor."], correctIndex: 2, explanation: "Em pacientes com IAMCSST submetidos à angioplastia coronariana primária, prasugrel ou ticagrelor são preferíveis ao clopidogrel devido à sua potência e onset de ação mais rápidos, resultando em menor taxa de eventos isquêmicos, desde que não haja contraindicações como alto risco de sangramento ou histórico de AVC.", category: "IAM" },
  { id: 840, question: "Em relação ao manejo da dor em pacientes com IAM, qual medicação deve ser utilizada com cautela devido ao risco de vasoconstrição e potencial impacto negativo no prognóstico?", options: ["Morfina.", "Nitroglicerina.", "Oxigênio.", "Anti-inflamatórios não esteroides (AINEs)."], correctIndex: 3, explanation: "Anti-inflamatórios não esteroides (AINEs) devem ser evitados em pacientes com IAM devido ao risco de aumento de eventos cardiovasculares (incluindo infarto, insuficiência cardíaca e hipertensão) e sangramento, especialmente em longo prazo. Opioides como a morfina são utilizados para alívio da dor, mas também requerem cautela.", category: "IAM" },
  { id: 841, question: "A principal causa fisiopatológica do infarto agudo do miocárdio com supradesnivelamento do segmento ST (IAMCSST) é:", options: ["Espasmo coronariano prolongado.", "Vasoespasmo difuso das artérias coronárias.", "Rotura de placa aterosclerótica com trombose oclusiva.", "Aumento da demanda miocárdica de oxigênio em coronárias sadias."], correctIndex: 2, explanation: "O IAMCSST é tipicamente causado pela ruptura de uma placa aterosclerótica vulnerável em uma artéria coronária, resultando na formação de um trombo que oclui completamente o lúmen vascular, levando à isquemia transmural e necrose.", category: "IAM" },
  { id: 842, question: "Um paciente de 65 anos é admitido no pronto-socorro com dor torácica de forte intensidade, sudorese, náuseas e dispneia. O eletrocardiograma inicial (ECG) revela supradesnivelamento do segmento ST em parede inferior (II, III e aVF). Os exames laboratoriais confirmam elevação de troponina. Qual a conduta inicial mais adequada para este paciente?", options: ["Administrar propranolol endovenoso e iniciar amiodarona oral.", "Realizar trombólise farmacológica imediatamente com alteplase.", "Preparar para encaminhamento para angiografia coronária primária (ICP primária).", "Administrar furosemida e aguardar resultado da troponina de alta sensibilidade."], correctIndex: 2, explanation: "Em casos de infarto agudo do miocárdio com supradesnivelamento do segmento ST (IAMCSST), a reperfusão coronariana é a prioridade. A ICP primária é o tratamento de escolha quando disponível em tempo hábil (preferencialmente em até 90-120 minutos do primeiro contato médico).", category: "Emergência" },
  { id: 843, question: "No manejo inicial do choque séptico em adultos, de acordo com as diretrizes atuais, qual dos seguintes é um alvo terapêutico prioritário nas primeiras 3 horas?", options: ["Pressão venosa central (PVC) entre 12-15 mmHg.", "Saturação venosa central de oxigênio (ScvO2) acima de 80%.", "Lactato sérico menor que 2 mmol/L ou queda de pelo menos 20% do valor inicial.", "Diurese horária superior a 1 mL/kg/h."], correctIndex: 2, explanation: "As diretrizes recentes para choque séptico e sepse priorizam a rápida ressuscitação volêmica guiada pela resposta e a busca por eliminação da fonte infecciosa, tendo como um dos alvos a redução do lactato sérico, indicativo de hipoperfusão.", category: "Emergência" },
  { id: 844, question: "Um paciente de 40 anos apresenta crises convulsivas generalizadas tônico-clônicas repetidas, sem recuperação da consciência entre elas, perdurando por mais de 5 minutos. Qual a primeira linha de tratamento farmacológico a ser administrada por via endovenosa?", options: ["Fenitoína.", "Fenobarbital.", "Midazolam.", "Diazepam."], correctIndex: 3, explanation: "No tratamento do estado de mal epiléptico, as benzodiazepinas são a primeira linha de tratamento devido ao seu rápido início de ação. O diazepam e o lorazepam são as opções classicamente recomendadas por via endovenosa.", category: "Emergência" },
  { id: 845, question: "Qual é a principal indicação para o uso de dobutamina na insuficiência cardíaca descompensada e choque cardiogênico?", options: ["Aumentar a frequência cardíaca em bradicardias sintomáticas.", "Reduzir rapidamente a pressão arterial em crises hipertensivas.", "Melhorar a contratilidade miocárdica e o débito cardíaco sem aumento significativo da resistência vascular sistêmica.", "Diminuir a pré-carga em pacientes com edema agudo de pulmão."], correctIndex: 2, explanation: "A dobutamina é um agente inotrópico positivo, utilizado para melhorar a contratilidade miocárdica e, consequentemente, o débito cardíaco, em pacientes com disfunção sistólica grave e hipoperfusão, como no choque cardiogênico.", category: "Emergência" },
  { id: 846, question: "Uma gestante de 32 semanas chega ao pronto-socorro com queixa de sangramento vaginal vermelho vivo, indolor e de grande volume. O abdome está flácido, e o feto apresenta batimentos cardíacos fetais reduzidos. Qual a hipótese diagnóstica mais provável?", options: ["Descolamento prematuro de placenta (DPP).", "Placenta prévia total.", "Ruptura de vasa prévia.", "Rotura uterina."], correctIndex: 1, explanation: "A placenta prévia total se manifesta tipicamente com sangramento vaginal indolor, vermelho vivo, recorrente e, por vezes, volumoso após a 20ª semana de gestação. O útero geralmente permanece relaxado.", category: "Emergência" },
  { id: 847, question: "Um paciente de 70 anos em uso de varfarina para fibrilação atrial chega ao pronto-socorro com cefaleia intensa e alteração súbita do nível de consciência. A tomografia de crânio revela hemorragia intracraniana. Qual é a medida mais urgente para reverter o efeito anticoagulante da varfarina?", options: ["Administrar plasma fresco congelado (PFC) e protamina.", "Administrar complexo protrombínico de quatro fatores (CPT4F) e vitamina K.", "Suspender a varfarina e aguardar a normalização do INR.", "Realizar diálise de urgência para remover a varfarina."], correctIndex: 1, explanation: "Na hemorragia intracraniana associada ao uso de antagonistas da vitamina K como a varfarina, a reversão rápida da anticoagulação é crucial. O CPT4F é a opção preferencial por seu rápido início de ação e por conter os fatores dependentes de vitamina K. A vitamina K atua como coadjuvante, mas tem ação mais lenta.", category: "Emergência" },
  { id: 848, question: "Na avaliação inicial de um politraumatizado, qual a primeira prioridade no atendimento, de acordo com o ATLS?", options: ["Avaliação do estado neurológico.", "Controle de hemorragias externas.", "Garantia de via aérea pérvia com proteção da coluna cervical.", "Exposição do paciente e prevenção de hipotermia."], correctIndex: 2, explanation: "A, B, C, D, E são as etapas sequenciais do atendimento primário no ATLS. A via aérea (A - Airway) com proteção da coluna cervical é a prioridade número um para garantir a oxigenação cerebral adequada.", category: "Emergência" },
  { id: 849, question: "Qual das seguintes condições é uma contraindicação absoluta para o uso de trombólise endovenosa em um paciente com AVC isquêmico agudo?", options: ["Pressão arterial > 185/110 mmHg não responsiva a medicação.", "História de AVC prévio há 3 meses.", "Melhora rápida e espontânea dos sintomas neurológicos.", "Tempo de início dos sintomas há 3,5 horas."], correctIndex: 0, explanation: "Pressão arterial persistentemente > 185/110 mmHg é uma contraindicação absoluta para a trombólise endovenosa devido ao risco aumentado de transformação hemorrágica. As outras são contraindicações relativas ou não são contraindicações absolutas no contexto de janelas terapêuticas específicas.", category: "Emergência" },
  { id: 850, question: "Um paciente de 25 anos é trazido ao pronto-socorro após tentativa de suicídio por ingestão de cáustico. Ele apresenta dor intensa, sialorreia e dispneia. Qual o procedimento diagnóstico imediato e fundamental para avaliar a extensão da lesão?", options: ["Endoscopia digestiva alta de urgência.", "Radiografia de tórax e abdome.", "Tomografia computadorizada de tórax e abdome.", "Laparoscopia exploratória."], correctIndex: 0, explanation: "A endoscopia digestiva alta é o método diagnóstico padrão-ouro para avaliar a extensão e profundidade das lesões esofágicas e gástricas por ingestão de cáusticos, devendo ser realizada nas primeiras 12-24 horas, se o paciente estiver estável hemodinamicamente.", category: "Emergência" },
  { id: 851, question: "Um paciente de 45 anos com histórico de asma grave mal controlada chega ao pronto-socorro com sibilância intensa, dispneia acentuada e uso da musculatura acessória, sem melhora significativa após inaloterapia inicial com beta-2 agonista de curta duração. Qual a próxima etapa na conduta?", options: ["Iniciar oxigenoterapia e aguardar melhora.", "Administrar antibiótico endovenoso profilático.", "Administrar corticoide sistêmico e considerar sulfato de magnésio.", "Realizar intubação orotraqueal de emergência."], correctIndex: 2, explanation: "Em exacerbações graves da asma, além da broncodilatação, é fundamental a administração de corticoides sistêmicos para reduzir a inflamação. O sulfato de magnésio pode ser considerado em casos refratários ou graves devido ao seu efeito broncodilatador.", category: "Emergência" },
  { id: 852, question: "No atendimento pré-hospitalar, a manobra de compressões torácicas eficazes em uma parada cardiorrespiratória (PCR) em adultos deve ser realizada com qual frequência e profundidade?", options: ["80-100 compressões por minuto, com profundidade de 3-4 cm.", "100-120 compressões por minuto, com profundidade de 5-6 cm.", "120-140 compressões por minuto, com profundidade de 4-5 cm.", "60-80 compressões por minuto, com profundidade de 6-7 cm."], correctIndex: 1, explanation: "As diretrizes atuais de RCP (AHA 2020) recomendam compressões torácicas numa frequência de 100 a 120 por minuto e com uma profundidade de 5 a 6 cm para adultos, a fim de garantir um fluxo sanguíneo cerebral e coronariano adequados.", category: "Emergência" },
  { id: 853, question: "Qual é a principal complicação do uso excessivo e prolongado de oxigênio em pacientes com doença pulmonar obstrutiva crônica (DPOC) e hipercapnia crônica?", options: ["Pneumonia aspirativa.", "Atelectasia pulmonar.", "Retenção de gás carbônico e narcose.", "Hipertensão pulmonar."], correctIndex: 2, explanation: "Em pacientes com DPOC e hipercapnia crônica, o estímulo hipóxico é o principal impulsionador respiratório. A administração excessiva de oxigênio pode deprimir ainda mais o drive respiratório, levando à retenção de CO2 e narcose por CO2.", category: "Emergência" },
  { id: 854, question: "No tratamento do edema agudo de pulmão cardiogênico, qual das seguintes classes de medicamentos é indicada para reduzir rapidamente a pré-carga e a pós-carga?", options: ["Betabloqueadores.", "Diuréticos de alça e nitratos.", "Inibidores da enzima conversora de angiotensina (IECA).", "Glicosídeos cardíacos (digitálicos)."], correctIndex: 1, explanation: "Diuréticos de alça (como a furosemida) reduzem a pré-carga por diurese rápida. Nitratos (como o dinitrato de isossorbida ou nitroglicerina) promovem venodilatação (redução de pré-carga) e, em doses mais altas, arteriodilatação (redução de pós-carga), sendo fundamentais no manejo agudo.", category: "Emergência" },
  { id: 855, question: "Uma paciente de 30 anos com histórico de doença inflamatória intestinal apresenta dor abdominal difusa intensa, febre, taquicardia e distensão abdominal. A radiografia de abdome revela sinais de megacólon. Qual a conduta inicial mais adequada?", options: ["Início de terapia com agentes imunossupressores.", "Administração de loperamida para controle da diarreia.", "Internação hospitalar para hidratação venosa, antibióticos e descompressão.", "Realização de colonoscopia diagnóstica com biópsia."], correctIndex: 2, explanation: "A paciente apresenta um quadro sugestivo de megacólon tóxico, uma complicação grave da doença inflamatória intestinal. O tratamento inicial é conservador, com suporte intensivo, correção hidroeletrolítica, antibióticos e descompressão, com monitorização rigorosa para indicação cirúrgica.", category: "Emergência" },
  { id: 856, question: "Qual a principal via de administração para o glucagon em crises hipoglicêmicas graves, especialmente em pacientes inconscientes e sem acesso venoso?", options: ["Intravenosa.", "Intramuscular.", "Subcutânea.", "Oral."], correctIndex: 1, explanation: "Em casos de hipoglicemia grave com perda de consciência e sem acesso venoso, a administração intramuscular de glucagon é a via de escolha, pois é rapidamente absorvida e promove a elevação dos níveis de glicose pela liberação hepática.", category: "Emergência" },
  { id: 857, question: "No choque anafilático, após a administração de epinefrina, qual o próximo passo mais importante se o paciente permanece hipotenso?", options: ["Administrar difenidramina endovenosa.", "Iniciar infusão de norepinefrina.", "Administrar fludrocortisona oral.", "Realizar intubação orotraqueal profilática."], correctIndex: 1, explanation: "A epinefrina é o tratamento de primeira linha para anafilaxia. Se a hipotensão persistir apesar da epinefrina, a reposição volêmica vigorosa e a infusão de vasopressores como a norepinefrina são cruciais para manter a perfusão de órgãos vitais.", category: "Emergência" },
  { id: 858, question: "Qual dos seguintes achados eletrocardiográficos é sugestivo de hipercalemia grave?", options: ["Onda U proeminente e inversão da onda T.", "Intervalo PR curto e onda delta.", "Ondas T apiculadas e estreitamento do QRS.", "Depressão do segmento ST e presença de onda Q patológica."], correctIndex: 2, explanation: "A hipercalemia grave pode causar ondas T apiculadas e estreitas, prolongamento do intervalo PR, alargamento do complexo QRS (devido a lentificação da condução) e, em casos mais graves, perda da onda P e padrão sinusoidal.", category: "Emergência" },
  { id: 859, question: "Um paciente vítima de trauma cranioencefálico grave apresenta pupilas anisocóricas e reativas à luz um pouco lentas. A tomografia de crânio revela coleção extradural. Qual conduta é fundamental para evitar a herniação cerebral?", options: ["Administração de manitol e neurocirurgia de urgência.", "Cabeceira elevada a 30 graus e solicitação de nova TC em 24h.", "Monitorização da pressão intracraniana (PIC) invasiva e hipotermia terapêutica.", "Hiperventilação controlada e uso de betabloqueadores."], correctIndex: 0, explanation: "Apesar do manitol ajudar a reduzir o edema cerebral associado, a coleção extradural geralmente requer intervenção cirúrgica de emergência (craniectomia) para drenagem e alívio da compressão, sendo esta a medida definitiva para evitar a herniação.", category: "Emergência" },
  { id: 860, question: "No tratamento inicial da crise tireotóxica em sala de emergência, qual dos seguintes medicamentos tem como principal objetivo bloquear a síntese de novos hormônios tireoidianos?", options: ["Propranolol.", "Iodeto de potássio.", "Dexametasona.", "Propiltiouracil (PTU) ou metimazol."], correctIndex: 3, explanation: "Os antitireoidianos (propiltiouracil ou metimazol) são a primeira linha para bloquear a síntese de novos hormônios tireoidianos na crise tireotóxica. O propranolol controla os sintomas adrenérgicos, o iodeto bloqueia a liberação e os corticoides são para suporte geral e efeitos anti-inflamatórios.", category: "Emergência" },
  { id: 861, question: "A principal indicação para o uso de naloxona na emergência é:", options: ["Reversão de overdose de benzodiazepínicos.", "Antídoto para intoxicação por paracetamol.", "Reversão de depressão respiratória induzida por opioides.", "Tratamento de arritmias cardíacas por betabloqueadores."], correctIndex: 2, explanation: "A naloxona é um antagonista de receptores opioides e é o antídoto de escolha para reverter a depressão respiratória e coma causados por overdose de opioides.", category: "Emergência" },
  { id: 862, question: "Em pacientes com pancreatite aguda grave, qual a principal complicação que pode levar a um desfecho fatal na fase precoce (primeira semana)?", options: ["Pseudocisto pancreático.", "Disfunção e falência de múltiplos órgãos.", "Formação de fístula pancreática.", "Diabetes mellitus pós-pancreatite."], correctIndex: 1, explanation: "A falência de múltiplos órgãos é a principal causa de mortalidade na fase precoce da pancreatite aguda grave, resultante da resposta inflamatória sistêmica exacerbada. As outras são complicações tardias ou menos letais no início.", category: "Emergência" },
  { id: 863, question: "Qual a principal alteração do balanço acidobásico esperada em um paciente com cetoacidose diabética (CAD)?", options: ["Alcalose metabólica com hiato aniônico normal.", "Acidose respiratória com hipercapnia.", "Acidose metabólica com hiato aniônico elevado.", "Alcalose respiratória compensatória."], correctIndex: 2, explanation: "A cetoacidose diabética é caracterizada pela produção excessiva de corpos cetônicos (ácidos), resultando em acidose metabólica com consumo de bicarbonato e, consequentemente, um hiato aniônico elevado. A acidose respiratória compensatória é esperada, mas a acidose metabólica é a alteração primária.", category: "Emergência" },
  { id: 864, question: "No escore de Cincinatti para AVC (pré-hospitalar), qual dos seguintes achados indica um possível acidente vascular cerebral?", options: ["Assimetria pupilar.", "Distorção facial.", "Deficit de força em membros inferiores.", "Afasia de condução."], correctIndex: 1, explanation: "O escore de Cincinatti avalia três alterações principais: distorção facial (incluindo desvio de rima), queda de um braço ao estender ambos por 10 segundos e fala anômala (disartria ou afasia). A presença de qualquer um desses indica alta probabilidade de AVC.", category: "Emergência" },
  { id: 865, question: "Qual a abordagem inicial mais adequada para um paciente com taquicardia supraventricular (TSV) com sinais de instabilidade hemodinâmica (hipotensão, alteração do nível de consciência, dor torácica isquêmica)?", options: ["Manobras vagais e adenosina endovenosa.", "Cardioversão elétrica sincronizada de urgência.", "Administração de verapamil ou diltiazem endovenoso.", "Amiodarona endovenosa e observação."], correctIndex: 1, explanation: "Em qualquer taquiarritmia (incluindo TSV) com sinais de instabilidade hemodinâmica, a cardioversão elétrica sincronizada é a terapia de escolha e deve ser realizada o mais rapidamente possível para restaurar o ritmo sinusal e estabilizar o paciente.", category: "Emergência" },
  { id: 866, question: "Um paciente com apendicite aguda é encaminhado para cirurgia. O que é o mais importante a ser feito para reduzir o risco de infecção cirúrgica, além da antibioticoprofilaxia?", options: ["Jejum prolongado pré-operatório.", "Preparo intestinal com laxativos.", "Hidratação venosa e correção de distúrbios eletrolíticos.", "Utilização de drenos profiláticos na ferida operatória."], correctIndex: 2, explanation: "O paciente com apendicite aguda frequentemente está desidratado e pode apresentar distúrbios eletrolíticos. A otimização do estado volêmico e eletrolítico é crucial no pré-operatório para melhorar a perfusão tecidual e a resposta imune, reduzindo o risco de complicações infecciosas.", category: "Emergência" },
  { id: 867, question: "Um paciente de 72 anos, hipertenso e diabético, é internado com quadro súbito de hemiparesia direita e afasia global. A tomografia computadorizada de crânio inicial revela ausência de sangramento. Qual a conduta inicial mais adequada para este paciente, considerando que os sintomas iniciaram há 2 horas?", options: ["Início imediato de ácido acetilsalicílico e clopidogrel.", "Realizar angiotomografia cerebral e, se houver oclusão de grande vaso, considerar trombectomia mecânica.", "Administrar alteplase intravenosa imediatamente, após exclusão de contraindicações.", "Observação clínica e aguardar evolução para decidir conduta."], correctIndex: 2, explanation: "Considerando a ausência de sangramento na TC e o início dos sintomas dentro da janela terapêutica da trombólise (4,5 horas), a administração de alteplase intravenosa é a conduta inicial mais prioritária, após exclusão de contraindicações e preenchimento dos critérios de indicação para o tratamento.", category: "AVC" },
  { id: 868, question: "Qual dos seguintes fatores de risco é considerado NÃO MODIFICÁVEL para o acidente vascular cerebral isquêmico?", options: ["Fibrilação atrial.", "Hipertensão arterial sistêmica.", "Idade avançada.", "Tabagismo."], correctIndex: 2, explanation: "A idade avançada é um fator de risco não modificável para o AVC isquêmico, enquanto fibrilação atrial, hipertensão e tabagismo são fatores de risco modificáveis que podem ser controlados para reduzir o risco de AVC.", category: "AVC" },
  { id: 869, question: "Um paciente com diagnóstico de acidente vascular cerebral isquêmico agudo apresenta pressão arterial de 190/110 mmHg. Ele foi submetido a trombólise intravenosa há 30 minutos. Qual a meta de pressão arterial a ser alcançada nas primeiras 24 horas pós-trombólise?", options: ["Manter pressão arterial sistólica inferior a 220 mmHg e diastólica inferior a 120 mmHg.", "Manter pressão arterial sistólica inferior a 140 mmHg e diastólica inferior a 90 mmHg.", "Manter pressão arterial sistólica inferior a 185 mmHg e diastólica inferior a 110 mmHg.", "Manter pressão arterial sistólica inferior a 160 mmHg e diastólica inferior a 100 mmHg."], correctIndex: 2, explanation: "Em pacientes que receberam trombólise intravenosa, a meta é manter a pressão arterial sistólica abaixo de 185 mmHg e a diastólica abaixo de 110 mmHg nas primeiras 24 horas para minimizar o risco de transformação hemorrágica e edema cerebral.", category: "AVC" },
  { id: 870, question: "Qual das seguintes escalas é mais utilizada para avaliar a gravidade do acidente vascular cerebral e predizer o prognóstico funcional subsequente?", options: ["Escala de Coma de Glasgow (ECG).", "Escala de Rankin Modificada (mRS).", "National Institutes of Health Stroke Scale (NIHSS).", "Escala de Hunt-Hess."], correctIndex: 2, explanation: "A NIHSS é uma escala padronizada e amplamente utilizada para quantificar o déficit neurológico agudo em pacientes com AVC, correlacionando-se bem com o tamanho da lesão e o prognóstico, especialmente em fase aguda. A mRS avalia incapacidade funcional após o evento.", category: "AVC" },
  { id: 871, question: "Um paciente de 60 anos apresenta súbita perda de sensibilidade no hemicorpo esquerdo e desvio de rima labial para a direita. A suspeita clínica é de AVC isquêmico. Qual o exame de imagem de escolha para confirmar o diagnóstico e excluir sangramento?", options: ["Ressonância magnética de crânio com sequência de difusão.", "Tomografia computadorizada de crânio sem contraste.", "Angiografia cerebral.", "Tomografia computadorizada de crânio com contraste."], correctIndex: 1, explanation: "A tomografia computadorizada de crânio sem contraste é o exame de imagem de escolha inicial no AVC agudo, pois é rápida, amplamente disponível e eficaz para excluir hemorragia intracraniana antes de considerar a trombólise.", category: "AVC" },
  { id: 872, question: "Após um AVC isquêmico, qual a principal indicação para o uso de terapia antitrombótica oral em longo prazo para prevenção secundária?", options: ["Estenose carotídea sintomática.", "Fibrilação atrial.", "Aterosclerose de grandes vasos intracranianos.", "Hipercolesterolemia."], correctIndex: 1, explanation: "A fibrilação atrial é a principal indicação para anticoagulação oral (com antagonistas da vitamina K ou anticoagulantes orais diretos) em longo prazo para prevenção secundária de AVC, devido ao alto risco de formação de trombos e embolia cerebrais.", category: "AVC" },
  { id: 873, question: "Qual o principal efeito adverso da trombólise intravenosa com alteplase no tratamento do AVC isquêmico agudo?", options: ["Reações anafiláticas.", "Angioedema.", "Hemorragia intracraniana sintomática.", "Hipotensão grave."], correctIndex: 2, explanation: "A complicação mais grave e temida da trombólise com alteplase é a hemorragia intracraniana sintomática, que pode piorar significativamente o prognóstico do paciente. O manejo rigoroso das contraindicações e da pressão arterial é fundamental para minimizar este risco.", category: "AVC" },
  { id: 874, question: "Um paciente de 55 anos, tabagista, apresenta-se com amaurose fugaz. Qual a investigação mais apropriada para identificar a etiologia e planejar a prevenção secundária de AVC?", options: ["Eletrocardiograma de 12 derivações e ecocardiograma transesofágico.", "Ultrassonografia com Doppler de carótidas e vertebrais.", "Angiografia por ressonância magnética do crânio.", "Monitorização cardíaca contínua por 24 horas."], correctIndex: 1, explanation: "A amaurose fugaz é frequentemente causada por embolia originada de placas ateroscleróticas na artéria carótida. A ultrassonografia com Doppler de carótidas e vertebrais é crucial para identificar estenoses e determinar a conduta terapêutica, como endarterectomia ou angioplastia.", category: "AVC" },
  { id: 875, question: "Qual das seguintes medicações deve ser evitada nas primeiras 24 horas após um AVC isquêmico, caso o paciente não preencha os critérios para trombólise?", options: ["Estatinas.", "Anti-hipertensivos.", "Ácido acetilsalicílico.", "Hipoglicemiantes orais."], correctIndex: 2, explanation: "Nas primeiras 24 horas de um AVC isquêmico, em pacientes que não receberam trombólise, a administração de ácido acetilsalicílico deve ser postergada por 24 horas após a exclusão de hemorragia com exame de imagem, para evitar o risco de transformação hemorrágica. Se não houver trombólise e a TC for negativa para sangramento pode ser iniciada após poucas horas.", category: "AVC" },
  { id: 876, question: "Em relação à reabilitação pós-AVC, qual o principal objetivo das intervenções precoces?", options: ["Total recuperação da função neurológica pré-AVC.", "Prevenir complicações secundárias e otimizar a recuperação funcional.", "Minimizar a dependência de cuidadores.", "Integrar o paciente ao programa de atividades físicas em grupo."], correctIndex: 1, explanation: "A reabilitação precoce pós-AVC visa prevenir complicações como broncopneumonia, trombose venosa profunda, úlceras de pressão e contraturas, além de otimizar a recuperação funcional através de terapia física, ocupacional e fonoaudiológica, melhorando o prognóstico a longo prazo.", category: "AVC" },
  { id: 877, question: "Um paciente de 35 anos, previamente hígido, começa a apresentar humor deprimido, perda de interesse em atividades prazerosas, insônia inicial, fadiga e dificuldade de concentração há 3 meses. Nega ideação suicida. O diagnóstico mais provável é:", options: ["Transtorno de Adaptação", "Transtorno Depressivo Maior, episódio único, moderado", "Transtorno Bipolar, episódio depressivo", "Transtorno Distímico (Transtorno Depressivo Persistente)"], correctIndex: 1, explanation: "A sintomatologia e o tempo de duração (há 3 meses) são consistentes com um Transtorno Depressivo Maior. A ausência de sintomas maníacos ou hipomaníacos exclui transtorno bipolar neste momento.", category: "Psiquiatria" },
  { id: 878, question: "Um homem de 50 anos, com história de etilismo crônico, é internado após convulsão. No terceiro dia de internação, apresenta agitação psicomotora, desorientação temporal-espacial, alucinações visuais vívidas (animais pequenos), tremores e sudorese intensa. Qual o diagnóstico mais provável?", options: ["Psicose induzida por substância", "Demência alcoólica", "Delirium tremens", "Encefalopatia de Wernicke"], correctIndex: 2, explanation: "Os sintomas descritos são clássicos do Delirium Tremens, uma síndrome de abstinência alcoólica grave, caracterizada por hiperatividade autonômica, delírio, alucinações e tremores, com início 48-96h após o último copo.", category: "Psiquiatria" },
  { id: 879, question: "Em relação ao tratamento farmacológico do Transtorno de Pânico, qual das seguintes classes de medicamentos é considerada de primeira linha para o tratamento a longo prazo?", options: ["Benzodiazepínicos", "Antipsicóticos atípicos", "Antidepressivos tricíclicos", "Inibidores Seletivos da Recaptação de Serotonina (ISRS)"], correctIndex: 3, explanation: "Os ISRS são a primeira linha de tratamento farmacológico para o Transtorno de Pânico devido à sua eficácia, perfil de efeitos colaterais mais favorável e menor risco de dependência em comparação com os benzodiazepínicos.", category: "Psiquiatria" },
  { id: 880, question: "Sobre o manejo de pacientes com agitação psicomotora aguda em pronto-socorro, qual das seguintes opções representa a primeira escolha para contenção farmacológica em ambiente não psicótico?", options: ["Haloperidol intramuscular", "Clorpromazina intravenosa", "Lorazepam oral ou intramuscular", "Risperidona oral"], correctIndex: 2, explanation: "Em pacientes não psicóticos, os benzodiazepínicos, como o lorazepam, são a primeira escolha para contenção farmacológica da agitação aguda, devido ao seu rápido início de ação, eficácia ansiolítica e sedativa.", category: "Psiquiatria" },
  { id: 881, question: "Uma paciente de 22 anos procura atendimento referindo preocupação excessiva e incontrolável com diversos aspectos da vida diária (trabalho, finanças, saúde dos familiares) há mais de 6 meses. Apresenta também tensão muscular, irritabilidade, insônia e fadiga. Qual o diagnóstico mais provável?", options: ["Transtorno de Ansiedade Social", "Transtorno Obsessivo-Compulsivo", "Transtorno de Ansiedade Generalizada", "Transtorno do Pânico"], correctIndex: 2, explanation: "A preocupação excessiva e generalizada, juntamente com sintomas físicos de ansiedade e duração superior a 6 meses, são critérios diagnósticos para o Transtorno de Ansiedade Generalizada (TAG).", category: "Psiquiatria" },
  { id: 882, question: "Em pacientes com Transtorno Bipolar, qual dos seguintes medicamentos é considerado um estabilizador de humor de primeira linha, eficaz tanto para episódios maníacos quanto depressivos?", options: ["Sertralina", "Amitriptilina", "Lítio", "Haloperidol"], correctIndex: 2, explanation: "O lítio é um estabilizador de humor clássico e de primeira linha para o Transtorno Bipolar, com eficácia comprovada tanto na melhora e prevenção de episódios maníacos quanto depressivos.", category: "Psiquiatria" },
  { id: 883, question: "Um paciente de 40 anos é diagnosticado com esquizofrenia. Qual dos seguintes antipsicóticos atípicos apresenta maior risco de ganho de peso e alteração metabólica?", options: ["Aripiprazol", "Ziprasidona", "Olanzapina", "Lurasidona"], correctIndex: 2, explanation: "A olanzapina está associada a um risco significativamente maior de ganho de peso e dislipidemia, sendo um dos antipsicóticos atípicos com pior perfil metabólico.", category: "Psiquiatria" },
  { id: 884, question: "Qual é a principal indicação para eletroconvulsoterapia (ECT) em Psiquiatria de acordo com as diretrizes atuais?", options: ["Transtorno de Ansiedade Generalizada refratário", "Transtorno do Pânico com agorafobia", "Depressão Maior grave e refratária ou com sintomas psicóticos", "Transtorno Obssessivo-Compulsivo leve"], correctIndex: 2, explanation: "A ECT é indicada para casos de Depressão Maior grave, refratária a tratamentos farmacológicos, ou associada a sintomas psicóticos, alto risco de suicídio ou catatonia, devido à sua eficácia e rápido início de ação.", category: "Psiquiatria" },
  { id: 885, question: "Uma paciente de 28 anos relata episódios recorrentes de compulsão alimentar, seguidos por comportamentos compensatórios inadequados, como vômitos autoinduzidos, uso de laxantes e exercícios físicos excessivos. Esses episódios ocorrem há 3 meses, em média duas vezes por semana. O diagnóstico mais provável é:", options: ["Anorexia Nervosa", "Transtorno da Compulsão Alimentar", "Bulimia Nervosa", "Transtorno Alimentar Restritivo Evitativo"], correctIndex: 2, explanation: "A descrição de episódios de compulsão alimentar seguidos por comportamentos compensatórios inadequados é característica da Bulimia Nervosa. Na Anorexia Nervosa, há restrição alimentar extrema e baixo peso significativo.", category: "Psiquiatria" },
  { id: 886, question: "A Síndrome da Serotonina, comumente associada ao uso concomitante ou sequencial de determinadas classes de psicofármacos, manifesta-se tipicamente por:", options: ["Hipotensão ortostática, boca seca e constipação", "Bradicardia, sudorese, miose e sialorreia", "Hipertermia, agitação, tremores, rigidez muscular e mioclonias", "Sedação excessiva, hipotonia e depressão respiratória"], correctIndex: 2, explanation: "A Síndrome da Serotonina é caracterizada pelo excesso de atividade serotoninérgica, resultando em hipertermia, sintomas autonômicos (sudorese), neuromusculares (tremores, rigidez, mioclonias) e alterações do estado mental (agitação).", category: "Psiquiatria" },
  { id: 887, question: "Em pacientes idosos com depressão, antes de iniciar o tratamento farmacológico, é fundamental realizar uma investigação para excluir qual das seguintes condições que podem mimetizar os sintomas depressivos?", options: ["Transtorno de Ansiedade Generalizada", "Transtorno Bipolar", "Demência em estágio inicial", "Transtorno de Personalidade Borderline"], correctIndex: 2, explanation: "Em idosos, a depressão pode ser um sintoma inicial ou precursor de demência. É crucial investigar e descartar causas orgânicas ou neurológicas, como demência, que podem se apresentar com sintomas depressivos (pseudodemência depressiva).", category: "Psiquiatria" },
  { id: 888, question: "Qual dos seguintes fármacos é especialmente indicado para o tratamento da insônia de manutenção, devido à sua meia-vida mais longa e menor risco de despertar precoce?", options: ["Zolpidem de liberação imediata", "Zopiclona", "Eszopiclona", "Ramelteon"], correctIndex: 2, explanation: "A eszopiclona possui uma meia-vida mais longa (cerca de 6 horas) entre os hipnóticos não benzodiazepínicos, sendo eficaz para a manutenção do sono e redução dos despertares noturnos/matinais.", category: "Psiquiatria" },
  { id: 889, question: "A característica principal do Transtorno de Personalidade Borderline é:", options: ["Desrespeito e violação dos direitos dos outros", "Excentricidade e isolamento social", "Instabilidade nos relacionamentos interpessoais, autoimagem, afetos e impulsividade acentuada", "Padrão difuso de grandiosidade, necessidade de admiração e falta de empatia"], correctIndex: 2, explanation: "A instabilidade afetiva, dos relacionamentos, da autoimagem e a impulsividade são traços centrais do Transtorno de Personalidade Borderline, levando a comportamentos autodestrutivos e crises emocionais.", category: "Psiquiatria" },
  { id: 890, question: "Um paciente de 60 anos, com história de Parkinson, é avaliado devido a alucinações visuais complexas e bem formadas, flutuações cognitivas e distúrbios do sono REM. Qual o diagnóstico mais provável?", options: ["Doença de Alzheimer", "Demência com Corpos de Lewy", "Demência Frontotemporal", "Demência Vascular"], correctIndex: 1, explanation: "As alucinações visuais complexas, flutuações cognitivas e o distúrbio do sono REM são características clínicas da Demência com Corpos de Lewy, frequentemente sobrepondo-se ou coexistindo com parkinsonismo.", category: "Psiquiatria" },
  { id: 891, question: "Qual das seguintes condições representa uma contraindicação ABSOLUTA para o uso de bupropiona?", options: ["Epilepsia ou histórico de convulsões", "Obesidade mórbida", "Hipertensão arterial controlada", "Transtorno de Ansiedade Generalizada"], correctIndex: 0, explanation: "A bupropiona tem um potencial de reduzir o limiar convulsivo e é contraindicada em pacientes com histórico de epilepsia ou convulsões, bulimia nervosa e anorexia nervosa devido ao risco aumentado de crises epilépticas.", category: "Psiquiatria" },
  { id: 892, question: "O mecanismo de ação primário dos Inibidores Seletivos da Recaptação de Serotonina (ISRS) é:", options: ["Bloqueio dos receptores dopaminérgicos D2", "Inibição da monoaminoxidase (MAO)", "Aumento da disponibilidade de serotonina na fenda sináptica", "Bloqueio da recaptação de noradrenalina e dopamina"], correctIndex: 2, explanation: "Os ISRS atuam inibindo seletivamente a recaptação de serotonina pelos neurônios pré-sinápticos, aumentando assim a concentração de serotonina na fenda sináptica e prolongando sua ação.", category: "Psiquiatria" },
  { id: 893, question: "Sobre o manejo do luto normal, qual das seguintes afirmativas está correta?", options: ["O luto normal invariavelmente requer intervenção farmacológica com antidepressivos.", "Em luto normal, a disforia tende a diminuir ao longo do tempo, e o indivíduo é capaz de experimentar momentos de prazer.", "A incapacidade de funcionar em atividades diárias por mais de 2 semanas após uma perda indica luto complicado.", "O luto normal não se associa a sintomas físicos ou alterações do sono."], correctIndex: 1, explanation: "No luto normal, mesmo com a dor e a tristeza, há capacidade de experimentar momentos de prazer e a intensidade da disforia tende a flutuar e diminuir. Intervenção farmacológica não é rotina; sintomas físicos e alterações do sono podem ocorrer.", category: "Psiquiatria" },
  { id: 894, question: "Qual dos seguintes é um sintoma negativo proeminente da esquizofrenia?", options: ["Alucinações auditivas", "Delírios persecutórios", "Pobreza da fala (alogia)", "Comportamento desorganizado"], correctIndex: 2, explanation: "Alogia (pobreza da fala) é um exemplo de sintoma negativo da esquizofrenia, que representa uma diminuição ou perda das funções normais, em contraste com os sintomas positivos como alucinações e delírios.", category: "Psiquiatria" },
  { id: 895, question: "Um paciente de 82 anos, previamente hígido, é trazido ao pronto-socorro com confusão mental aguda e quedas frequentes há 2 dias. A filha relata que ele estava ativo e independente até então. Ao exame físico, apresenta desidratação leve, ausência de sinais de focalização neurológica aparente e taquicardia. Qual a conduta inicial mais adequada para este paciente?", options: ["Iniciar imediatamente a investigação para doença de Alzheimer, considerando o déficit cognitivo agudo.", "Solicitar tomografia de crânio urgente para descartar acidente vascular cerebral.", "Avaliar medicamentos em uso e buscar causas reversíveis para o delírio, como infecções e alterações metabólicas.", "Prescrever um benzodiazepínico de curta ação para controle da agitação e reorientação."], correctIndex: 2, explanation: "A apresentação de confusão mental aguda em idosos, com alteração súbita do nível de consciência e atenção, é característica de delírio (estado confusional agudo). É fundamental buscar e tratar as causas reversíveis, sendo as mais comuns infecções (urinária, pneumonia), desidratação, alterações metabólicas e efeitos adversos de medicamentos.", category: "Geriatria" },
  { id: 896, question: "Em relação à síndrome da fragilidade no idoso, qual das seguintes afirmativas está correta?", options: ["A fragilidade é sinônimo de comorbidade e não possui critérios diagnósticos próprios.", "O principal determinante da fragilidade é a idade avançada, sendo inevitável a sua ocorrência em idosos muito velhos.", "A perda de peso não intencional, a fadiga e a baixa velocidade de marcha são critérios para o diagnóstico de fragilidade.", "Idosos frágeis devem ser incentivados a reduzir suas atividades físicas para evitar quedas e lesões."], correctIndex: 2, explanation: "A síndrome da fragilidade é caracterizada por critérios como perda de peso não intencional (>4,5 kg ou 5% do peso corporal em 1 ano), fadiga autorreferida, baixa força de preensão, baixa velocidade de marcha e baixo nível de atividade física. É uma condição dinâmica e potencialmente reversível, distinta de comorbidade ou deficiência.", category: "Geriatria" },
  { id: 897, question: "Os inibidores da bomba de prótons (IBP) são frequentemente prescritos para idosos. A queixa de anemia ferropriva refratária ao tratamento e osteoporose avançada em um paciente idoso em uso crônico de IBP deve levantar a suspeita de qual interação ou efeito adverso?", options: ["Diminuição da absorção de vitamina B12 e cálcio.", "Aumento do risco de insuficiência cardíaca e arritmias.", "Elevação dos níveis de glicose no sangue e piora do diabetes.", "Aumento da eliminação renal de potássio e hipocalemia."], correctIndex: 0, explanation: "O uso crônico de IBP pode levar à hipocloridria, que prejudica a absorção de certos nutrientes como a vitamina B12, cálcio e ferro. Isso pode resultar em anemia perniciosa por deficiência de B12 e anemia ferropriva, além de aumentar o risco de osteoporose e fraturas devido à menor absorção de cálcio.", category: "Geriatria" },
  { id: 898, question: "Um paciente de 75 anos, hipertenso e diabético, apresenta queixa de perda de memória recente e dificuldade em realizar tarefas complexas, como preencher formulários bancários, que antes fazia com facilidade. A família nota que ele está mais lento e apático. Qual o diagnóstico diferencial mais provável neste caso?", options: ["Neurose de ansiedade.", "Depressão maior.", "Delírio agudo.", "Transtorno neurocognitivo maior (demência)."], correctIndex: 3, explanation: "A perda de memória progressiva e a dificuldade em atividades instrumentais da vida diária, em um idoso com comorbidades vasculares, sugerem um quadro de demência. A apatia e lentidão também são sintomas comuns. É importante diferenciar de delírio (início agudo e flutuante) e depressão (em que o humor deprimido é central e costuma haver queixa de alteração de memória, mas com pouca repercussão funcional).", category: "Geriatria" },
  { id: 899, question: "Qual das seguintes estratégias é a mais eficaz para a prevenção primária de quedas em idosos na comunidade, segundo as diretrizes atuais?", options: ["Uso rotineiro de suplementos de cálcio e vitamina D em todos os idosos.", "Aconselhamento sobre ajuste de medicações e exercícios terapêuticos de equilíbrio e força.", "Instalação de barras de apoio e remoção de tapetes em todas as residências de idosos.", "Uso profilático de calçados ortopédicos para todos os idosos acima de 70 anos."], correctIndex: 1, explanation: "A prevenção de quedas em idosos na comunidade deve ser multifacetada. No entanto, a revisão e ajuste de medicamentos potencialmente inadequados (reduzindo polifarmácia e sedativos) e a prática de exercícios que melhorem o equilíbrio e a força muscular (como tai chi ou programas de exercícios supervisionados) são as intervenções mais fundamentadas por evidências para reduzir o risco de quedas.", category: "Geriatria" },
  { id: 900, question: "Sobre a polifarmácia em geriatria, assinale a alternativa correta:", options: ["É definida pelo uso de apenas dois ou mais medicamentos concomitantemente.", "Está associada unicamente ao aumento do custo do tratamento, sem impacto na segurança do paciente.", "Aumenta o risco de interações medicamentosas, reações adversas e não aderência ao tratamento.", "É sempre benéfica, pois garante que todas as condições de saúde do idoso sejam tratadas."], correctIndex: 2, explanation: "Polifarmácia é o uso de múltiplos medicamentos (geralmente cinco ou mais), sendo um desafio comum em geriatria. Ela aumenta significativamente o risco de interações medicamentosas adversas, reações indesejadas, síndromes geriátricas (como quedas e delírio) e piora da aderência ao tratamento complexo.", category: "Geriatria" },
  { id: 901, question: "Qual é a principal recomendação para o manejo da hipertensão arterial em idosos frágeis, acima de 80 anos, segundo as diretrizes de 2024?", options: ["Manter a pressão arterial sistólica abaixo de 120 mmHg para evitar eventos cardiovasculares.", "Avaliar a tolerância ao tratamento e evitar hipotensão ortostática, com meta de pressão arterial sistólica mais flexível (e.g., 130-149 mmHg).", "Iniciar doses máximas de anti-hipertensivos para controle rápido da pressão arterial.", "Descontinuar todos os anti-hipertensivos devido ao risco de quedas."], correctIndex: 1, explanation: "Em idosos frágeis e muito idosos (acima de 80 anos), a individualização do tratamento anti-hipertensivo é crucial. A meta de pressão arterial sistólica precisa ser mais flexível (geralmente entre 130-149 mmHg) para evitar hipotensão ortostática, quedas e hipoperfusão de órgãos vitais, priorizando a segurança e a qualidade de vida do paciente.", category: "Geriatria" },
  { id: 902, question: "Um paciente de 90 anos, acamado, com doença de Parkinson avançada, desenvolve uma úlcera por pressão em região sacral, estágio III. Qual o principal fator de risco modificável para o desenvolvimento desta úlcera?", options: ["Idade avançada.", "Doença de Parkinson.", "Desnutrição e baixa ingestão proteica.", "Incontinência urinária e fecal."], correctIndex: 2, explanation: "Embora idade avançada, Parkinson, imobilidade e incontinência sejam fatores de risco importantes para úlceras por pressão, a desnutrição e a baixa ingestão proteica são fatores de risco modificáveis cruciais. A deficiência de proteínas compromete a integridade da pele, retarda a cicatrização e enfraquece a resposta imune, aumentando a vulnerabilidade.", category: "Geriatria" },
  { id: 903, question: "Em relação à incontinência urinária de esforço na mulher idosa, qual tratamento não farmacológico deve ser a primeira linha de abordagem?", options: ["Estimulação elétrica funcional.", "Implante de pessário vaginal.", "Treinamento dos músculos do assoalho pélvico (exercícios de Kegel).", "Dieta rigorosa para perda de peso."], correctIndex: 2, explanation: "O treinamento dos músculos do assoalho pélvico (exercícios de Kegel), muitas vezes com a orientação de um fisioterapeuta, é a primeira linha de tratamento não farmacológico para a incontinência urinária de esforço em mulheres, independentemente da idade. Seu objetivo é fortalecer a musculatura que suporta a uretra e a bexiga, melhorando o controle esfincteriano.", category: "Geriatria" },
  { id: 904, question: "Qual das seguintes intervenções tem maior impacto na melhora da capacidade funcional e redução da mortalidade em idosos com insuficiência cardíaca com fração de ejeção reduzida (ICFEr)?", options: ["Restrição hídrica rigorosa (1 litro/dia).", "Suplementação de vitamina D e cálcio.", "Terapia com betabloqueadores e inibidores da enzima conversora de angiotensina (IECA) ou bloqueadores do receptor de angiotensina (BRA).", "Uso de digoxina em doses elevadas para controle sintomático."], correctIndex: 2, explanation: "Em idosos com ICFEr, assim como em adultos mais jovens, a terapia medicamentosa otimizada com betabloqueadores, IECA/BRA, antagonistas dos receptores mineralocorticóides e, em casos selecionados, inibidores do SGLT2, constitui a base do tratamento e tem o maior impacto na melhora da capacidade funcional e redução da morbimortalidade, conforme as diretrizes atuais.", category: "Geriatria" },
  { id: 905, question: "Um paciente de 88 anos é avaliado para vacinação. Ele não possui cartão de vacinação e mora sozinho. Qual vacina, dentre as opções abaixo, é mais relevante para este idoso e deve ser priorizada, considerando as diretrizes do Ministério da Saúde para o ano de 2024?", options: ["Vacina contra HPV (papilomavírus humano).", "Vacina tríplice bacteriana (Difteria, Tétano e Coqueluche - dTpa).", "Vacina contra varicela (catapora).", "Vacina contra febre amarela, se morar em área de risco."], correctIndex: 1, explanation: "Para idosos, a vacina tríplice bacteriana (dTpa) é recomendada com um reforço a cada 10 anos. A proteção contra tétano e difteria é fundamental, e o componente contra coqueluche (pertussis) é importante para evitar a transmissão a contatos próximos, especialmente bebês. As outras vacinas listadas não são prioritárias ou recomendadas para a maioria dos idosos não expostos, exceto em situações específicas.", category: "Geriatria" },
  { id: 906, question: "Qual princípio ético é fundamental ao abordar a autonomia de um paciente idoso com declínio cognitivo leve, mas capaz de tomar decisões sobre seu cuidado de saúde?", options: ["Beneficência: o que é melhor para o paciente é decidido pela equipe médica.", "Não maleficência: evitar danos, mesmo que isso signifique não oferecer tratamento.", "Autonomia: o paciente tem o direito de tomar decisões sobre seu corpo e tratamento, desde que tenha capacidade de discernimento.", "Justiça: garantir que todos os pacientes recebam o mesmo tratamento, independentemente de sua capacidade."], correctIndex: 2, explanation: "O princípio da autonomia visa respeitar a capacidade do paciente de tomar decisões informadas sobre seu próprio corpo e tratamento. Mesmo com declínio cognitivo leve, muitos idosos mantêm a capacidade decisória para aspectos específicos de seu cuidado, e essa autonomia deve ser respeitada e promovida, com apoio e informações claras.", category: "Geriatria" },
  { id: 907, question: "Paciente de 65 anos, diabético tipo 2 há 15 anos com controle glicêmico irregular, queixa-se de baixa acuidade visual progressiva em ambos os olhos nos últimos 2 anos. Relata visão embaçada e halos ao redor das luzes à noite. Ao exame oftalmológico, apresenta turvação do cristalino bilateralmente. Qual o diagnóstico mais provável?", options: ["Catarata senil associada ao diabetes", "Retinopatia diabética proliferativa", "Glaucoma agudo de ângulo fechado", "Neuropatia óptica isquêmica anterior"], correctIndex: 0, explanation: "A catarata é uma complicação comum do diabetes mellitus, caracterizada por turvação do cristalino. A baixa acuidade visual progressiva e halos noturnos são sintomas clássicos de catarata.", category: "Oftalmologia" },
  { id: 908, question: "Um paciente de 40 anos apresenta dor ocular intensa súbita, olho vermelho, pupila em midríase média e fixa, e baixa acuidade visual. A pressão intraocular está elevada. Qual a conduta inicial mais adequada para este caso, considerando a urgência?", options: ["Administração de acetazolamida oral e pilocarpina tópica", "Colírio de corticosteroide e antibiótico de amplo espectro", "Realização de ultrassonografia ocular para avaliar descolamento de retina", "Aplicação de compresses frias e analgésicos sistêmicos"], correctIndex: 0, explanation: "Os sintomas são compatíveis com glaucoma agudo de ângulo fechado. O tratamento inicial visa reduzir a pressão intraocular rapidamente com acetazolamida (diminui produção de humor aquoso) e pilocarpina (miótico que promove a abertura do ângulo).", category: "Oftalmologia" },
  { id: 909, question: "Em relação à retinopatia diabética, qual das seguintes afirmativas está correta?", options: ["A retinopatia diabética proliferativa (RDP) é a forma mais grave, caracterizada pela presença de neovasos.", "A retinopatia diabética não proliferativa (RDNP) leve é tratada com fotocoagulação a laser.", "O edema macular diabético só ocorre em estágios avançados da retinopatia diabética proliferativa.", "O controle rigoroso da glicemia é o único fator preventivo para a progressão da retinopatia diabética."], correctIndex: 0, explanation: "A RDP é definida pela presença de neovascularização, que pode levar a sangramentos, descolamento de retina e cegueira. A fotocoagulação é indicada em estágios mais avançados, e não apenas o controle glicêmico previne a progressão.", category: "Oftalmologia" },
  { id: 910, question: "Qual das seguintes condições representa uma emergência oftalmológica que requer encaminhamento imediato para tratamento cirúrgico?", options: ["Descolamento de retina regmatogênico macula on", "Pinguécula com inflamação moderada", "Conjuntivite alérgica com secreção mucoide", "Blefarite anterior estafilocócica"], correctIndex: 0, explanation: "Descolamento de retina regmatogênico com mácula 'on' (não descolada) é uma emergência cirúrgica para preservar a visão central. As outras condições não são emergências cirúrgicas.", category: "Oftalmologia" },
  { id: 911, question: "Um paciente refere perda súbita e indolor da visão em um olho, com mancha escura que escurece conforme os minutos passam. Ao exame fundoscópico, observa-se o sinal da 'mancha vermelho-cereja' na mácula. Qual o diagnóstico mais provável?", options: ["Oclusão da artéria central da retina", "Oclusão da veia central da retina", "Hemovítreo massivo", "Neurite óptica aguda"], correctIndex: 0, explanation: "A oclusão da artéria central da retina causa perda súbita e indolor da visão, com o sinal patognomônico da 'mancha vermelho-cereja' devido à isquemia retiniana.", category: "Oftalmologia" },
  { id: 912, question: "Qual é a principal função do humor aquoso no olho?", options: ["Nutrição da córnea e do cristalino e manutenção da pressão intraocular", "Proteção contra raios ultravioleta", "Foco da imagem na retina", "Lubrificação da superfície ocular"], correctIndex: 0, explanation: "O humor aquoso nutre estruturas avasculares como a córnea e o cristalino, e sua produção e drenagem são essenciais para a manutenção da pressão intraocular.", category: "Oftalmologia" },
  { id: 913, question: "Um recém-nascido pré-termo, com 28 semanas de idade gestacional e peso de nascimento de 1000g, é submetido a exame oftalmológico. Qual a principal condição ocular que deve ser ativamente pesquisada neste grupo de pacientes?", options: ["Retinopatia da prematuridade", "Catarata congênita", "Glaucoma congênito", "Conjuntivite neonatal"], correctIndex: 0, explanation: "A retinopatia da prematuridade (ROP) é a principal causa evitável de cegueira em bebês prematuros, especialmente aqueles com menor idade gestacional e peso ao nascer. O rastreamento é essencial.", category: "Oftalmologia" },
  { id: 914, question: "Qual o principal agente etiológico da conjuntivite bacteriana aguda em crianças e adultos?", options: ["Staphylococcus aureus e Streptococcus pneumoniae", "Adenovírus", "Chlamydia trachomatis", "Herpes simplex vírus"], correctIndex: 0, explanation: "Staphylococcus aureus e Streptococcus pneumoniae são as bactérias mais frequentemente isoladas em casos de conjuntivite bacteriana aguda, tanto em crianças quanto em adultos.", category: "Oftalmologia" },
  { id: 915, question: "Um paciente de 70 anos apresenta drusas moles e confluentes na região macular, com atrofia geográfica do epitélio pigmentar da retina. A acuidade visual central está comprometida. Qual o diagnóstico mais provável?", options: ["Degeneração macular relacionada à idade (DMRI) seca", "Degeneração macular relacionada à idade (DMRI) úmida", "Retinocoroidite por toxoplasmose", "Retinopatia hipertensiva"], correctIndex: 0, explanation: "Drusas moles e confluentes com atrofia geográfica da retina são características da DMRI seca (atrófica), a forma mais comum da doença, que leva à perda progressiva da visão central.", category: "Oftalmologia" },
  { id: 916, question: "Qual dos seguintes fármacos é um antagonista beta-adrenérgico utilizado no tratamento do glaucoma para reduzir a produção de humor aquoso?", options: ["Timolol", "Latanoprosta", "Acetazolamida", "Brimonidina"], correctIndex: 0, explanation: "O timolol é um betabloqueador frequentemente utilizado topicamente no tratamento do glaucoma para diminuir a produção de humor aquoso, reduzindo assim a pressão intraocular.", category: "Oftalmologia" },
  { id: 917, question: "Um paciente de 35 anos, pescador, procura atendimento com lesão ulcerada no dorso da mão direita há 3 meses, com bordos elevados, indolor e com linfangite ascendente nodular. Ele relata contato frequente com vegetação aquática. Qual o diagnóstico mais provável?", options: ["Esporotricose", "Leishmaniose cutânea", "Criptococose cutânea", "Nocardiose"], correctIndex: 0, explanation: "A esporotricose é uma micose subcutânea causada por fungos do gênero Sporothrix, frequentemente associada ao contato com solo, plantas e vegetação aquática, com a forma linfocutânea sendo a apresentação mais comum, caracterizada por lesão primária e nódulos satélites ao longo dos vasos linfáticos.", category: "Dermatologia" },
  { id: 918, question: "Paciente de 60 anos, com história de transplante renal há 5 anos e em uso de imunossupressores, apresenta múltiplas lesões hiperpigmentadas, verrucosas, em áreas expostas ao sol. A histopatologia revela atipia celular em todas as camadas da epiderme. Qual dos diagnósticos abaixo é o mais provável?", options: ["Carcinoma espinocelular in situ (Doença de Bowen)", "Melanoma in situ", "Ceratose seborreica", "Ceratoacantoma"], correctIndex: 0, explanation: "Pacientes imunossuprimidos, especialmente transplantados renais, têm alto risco de desenvolver lesões pré-malignas e malignas na pele, com o carcinoma espinocelular e seus precursores (incluindo a Doença de Bowen) sendo particularmente comuns em áreas fotoexpostas. A histopatologia descrita é compatível com carcinoma espinocelular in situ.", category: "Dermatologia" },
  { id: 919, question: "Qual das seguintes características histopatológicas é mais fortemente associada ao diagnóstico de psoríase?", options: ["Acanthose regular com alongamento das cristas epidérmicas e neutrófilos na camada córnea (microabscessos de Munro)", "Atrofia epidérmica e vacuolização da camada basal", "Infiltrado inflamatório perivascular em formato de cunha na derme superficial e média", "Linfócitos atípicos com epidermotropismo na ausência de espongiose"], correctIndex: 0, explanation: "A psoríase é caracterizada histologicamente por acantose regular, com alongamento das cristas epidérmicas, paraqueratose, adelgaçamento da camada granulosa e a presença de microabscessos de Munro (neutrófilos na camada córnea).", category: "Dermatologia" },
  { id: 920, question: "Um paciente de 45 anos apresenta quadro de lesões eritematosas, pruriginosas, em forma de anel, com bordas elevadas e centro claro, que migram e se espalham pelo tronco e membros. Essas lesões surgem e desaparecem em horas. Qual o diagnóstico mais provável?", options: ["Urticária crônica", "Eritema multiforme", "Pitiríase rósea", "Micose fungoide"], correctIndex: 0, explanation: "A descrição de lesões eritematosas pruriginosas, em forma de anel, com bordas elevadas e centro claro, que são transitórias e migratórias, é clássica da urticária. O surgimento e desaparecimento em horas é uma característica chave da urticária.", category: "Dermatologia" },
  { id: 921, question: "No tratamento de um caso grave de herpes zoster oftálmico em paciente imunocompetente, qual das seguintes condutas é a mais adequada?", options: ["Início imediato de aciclovir oral em dose plena, preferencialmente nas primeiras 72 horas do início das lesões.", "Tratamento tópico com antivirais somente, devido ao risco de efeitos sistêmicos.", "Observação clínica e analgesia, pois a doença é autolimitada na maioria dos casos.", "Corticosteroides orais em altas doses para prevenir neuralgia pós-herpética."], correctIndex: 0, explanation: "O tratamento do herpes zoster, especialmente em casos graves ou localizações especiais como o oftálmico, deve ser feito com antivirais sistêmicos (aciclovir, fanciclovir ou valaciclovir) iniciados o mais precocemente possível, idealmente nas primeiras 72 horas, para reduzir a gravidade e a duração da doença, e diminuir o risco de complicações como a neuralgia pós-herpética.", category: "Dermatologia" },
  { id: 922, question: "Qual o principal critério para o diagnóstico de lúpus eritematoso sistêmico (LES) com acometimento cutâneo, segundo os critérios mais recentes?", options: ["Lesões de lúpus cutâneo agudo (rash malar, lúpus bolhoso) ou subagudo ou crônico (lúpus discoide).", "Presença de anticorpo antinuclear (FAN) positivo em título alto.", "Artrite não erosiva envolvendo duas ou mais articulações periféricas.", "Pneumonia, pleurite ou pericardite de origem inexplicada."], correctIndex: 0, explanation: "Os critérios de classificação do LES de 2019 (ACR/EULAR) consideram as lesões cutâneas lúpicas agudas, subagudas e crônicas como critérios importantes. O rash malar, descrito como lúpus cutâneo agudo, é um critério clínico essencial.", category: "Dermatologia" },
  { id: 923, question: "Em relação ao tratamento da escabiose (sarna) em adultos, qual das seguintes opções terapêuticas é a MAIS recomendada pela maioria das diretrizes atuais?", options: ["Permetrina creme a 5% aplicada em todo o corpo, do pescoço para baixo, por 8 a 14 horas, repetida após 7 dias.", "Ivermectina oral em dose única diária por 3 dias consecutivos.", "Enxofre precipitado a 10% em vaselina diariamente por 21 dias.", "Malathion loção a 0,5% aplicado por 24 horas, semanalmente."], correctIndex: 0, explanation: "A permetrina creme a 5% é o tratamento tópico de primeira linha para escabiose devido à sua alta eficácia e bom perfil de segurança. É essencial aplicá-la em todo o corpo, do pescoço para baixo, e repetir a aplicação após 7 dias para combater as larvas eclodidas dos ovos resistentes ao primeiro tratamento.", category: "Dermatologia" },
  { id: 924, question: "Um paciente de 28 anos apresenta múltiplas pápulas e nódulos, alguns com umbilicação central, distribuídos pelo tronco e genitais. O histopatológico revela corpos de Henderson-Paterson. Qual o diagnóstico e tratamento de escolha?", options: ["Molusco contagioso; curetagem ou crioterapia.", "Verrugas virais; ácido salicílico ou eletrocauterização.", "Herpes simples; aciclovir oral.", "Sífilis secundária; penicilina benzatina."], correctIndex: 0, explanation: "A descrição das lesões (pápulas e nódulos umbilicados) e a presença dos corpos de Henderson-Paterson (corpúsculos de inclusão virais) são patognomônicos de molusco contagioso, uma infecção viral autolimitada, mas que pode ser tratada com métodos destrutivos como curetagem ou crioterapia.", category: "Dermatologia" },
  { id: 925, question: "Qual das seguintes manifestações cutâneas caracteriza o eritema nodoso?", options: ["Nódulos subcutâneos eritematosos e dolorosos em áreas extensoras das pernas, com resolução sem deixar cicatrizes.", "Placas eritematosas anulares, migratórias, que duram por horas e desaparecem sem sequelas.", "Pápulas violáceas, poligonais, pruriginosas, na superfície flexora dos punhos e antebraços.", "Lesões bolhosas tensas sobre pele eritematosa ou urticariforme em pacientes idosos."], correctIndex: 0, explanation: "O eritema nodoso é uma paniculite aguda caracterizada por nódulos subcutâneos, eritematosos e dolorosos, geralmente nas faces extensoras das pernas. A resolução das lesões ocorre sem ulceração ou cicatrizes, podendo deixar hiperpigmentação residual.", category: "Dermatologia" },
  { id: 926, question: "Em relação à dermatofitose, qual das opções abaixo NÃO é um fator predisponente comum?", options: ["Uso de sapatos fechados e úmidos por longos períodos.", "Imunodeficiência (ex: diabetes mellitus, HIV).", "Exposição frequente à luz solar intensa.", "Hiperidrose e trauma cutâneo."], correctIndex: 2, explanation: "A exposição à luz solar intensa não é um fator predisponente para dermatofitoses; na verdade, a umidade, o calor, a oclusão e a imunodeficiência são fatores de risco mais relevantes para o crescimento fúngico.", category: "Dermatologia" },
  { id: 927, question: "Um paciente de 70 anos, previamente hígido, desenvolve um quadro de bolhas tensas e pruriginosas, que não se rompem facilmente, em pele aparentemente sã ou eritematosa, predominantemente em tronco e superfícies flexoras. O sinal de Nikolsky é negativo. Qual é o diagnóstico mais provável?", options: ["Penfigoide bolhoso", "Pênfigo vulgar", "Dermatite herpetiforme", "Eritema multiforme bolhoso"], correctIndex: 0, explanation: "O penfigoide bolhoso é uma dermatose bolhosa autoimune que afeta principalmente idosos, caracterizada por bolhas tensas subcutâneas em pele eritematosa ou normal. O sinal de Nikolsky é negativo, diferentemente do pênfigo vulgar.", category: "Dermatologia" },
  { id: 928, question: "Qual das seguintes afirmativas sobre o carcinoma basocelular (CBC) é verdadeira?", options: ["É a neoplasia maligna cutânea mais comum e raramente metastatiza.", "Apresenta um alto índice de metástase linfática regional.", "É predominantemente causado por infecção viral persistente.", "O subtipo nodular é o menos frequente, com pior prognóstico."], correctIndex: 0, explanation: "O carcinoma basocelular é o câncer de pele mais comum, responsável por cerca de 80% dos casos. Embora seja localmente invasivo, a capacidade de metástase é extremamente rara, conferindo a ele um bom prognóstico quando tratado adequadamente.", category: "Dermatologia" },
  { id: 929, question: "Um paciente de 35 anos procura o pronto-socorro com queixa de dor intensa em ouvido direito, plenitude auricular e otorréia purulenta há 3 dias. Refere ter nadado em piscina recentemente. Ao exame otoscópico, observa-se edema e hiperemia do conduto auditivo externo, com presença de secreção. A membrana timpânica não é visibilizada devido ao edema. Qual é a conduta inicial mais apropriada para este caso?", options: ["Prescrição de corticoide oral e analgésico.", "Limpeza do conduto auditivo, antibioticoterapia tópica (gotas) e analgésico.", "Miringotomia para drenagem e antibioticoterapia oral.", "Encaminhamento para audiometria tonal e impedanciometria urgente."], correctIndex: 1, explanation: "O quadro clínico é sugestivo de otite externa difusa aguda. A conduta inicial inclui limpeza do conduto para facilitar a ação medicamentosa, antibioticoterapia tópica com cobertura para Pseudomonas e Staphylococcus, e analgesia para controle da dor intensa.", category: "Otorrinolaringologia" },
  { id: 930, question: "Qual das seguintes estruturas anatômicas é responsável por equalizar a pressão entre o ouvido médio e a nasofaringe?", options: ["Janela redonda", "Cóclea", "Tuba auditiva (Trompa de Eustáquio)", "Meato acústico externo"], correctIndex: 2, explanation: "A tuba auditiva, ou trompa de Eustáquio, conecta a cavidade do ouvido médio à nasofaringe, sendo fundamental para a ventilação e equalização da pressão do ouvido médio com a pressão atmosférica.", category: "Otorrinolaringologia" },
  { id: 931, question: "Um lactente de 6 meses é levado ao pediatra com irritabilidade, febre e puxões frequentes na orelha. Ao exame otoscópico, a membrana timpânica esquerda está abaulada, hiperemiada e sem reflexo luminoso. O diagnóstico mais provável e a conduta inicial recomendada são:", options: ["Otite externa, prescrever gotas otológicas de antibiótico.", "Otite média aguda, prescrever amoxicilina via oral.", "Cerúmen impactado, realizar lavagem auricular.", "Corpo estranho no ouvido, tentar remoção imediata."], correctIndex: 1, explanation: "O quadro é clássico de otite média aguda em lactente. A amoxicilina é o antibiótico de primeira escolha para crianças sem fatores de risco para germes resistentes, devendo ser administrada por via oral.", category: "Otorrinolaringologia" },
  { id: 932, question: "Após um trauma cranioencefálico, um paciente apresenta hemotímpano e paralisia facial periférica ipsilateral. Qual o diagnóstico mais provável para a paralisia facial neste contexto?", options: ["Paralisia de Bell.", "Secção do nervo facial em sua porção intra-auricular.", "Fratura de osso temporal com acometimento do canal do nervo facial.", "Mielite transversa."], correctIndex: 2, explanation: "A paralisia facial periférica associada a trauma cranioencefálico, especialmente com hemotímpano, sugere fratura do osso temporal que pode lesar o nervo facial em seu trajeto no canal de Faloppio.", category: "Otorrinolaringologia" },
  { id: 933, question: "Qual é a principal manifestação clínica da Síndrome de Ménière?", options: ["Dor em ouvido, secreção e febre.", "Otorragia, vertigem posicional e zumbido.", "Vertigem rotatória episódica, plenitude auricular, zumbido e perda auditiva flutuante.", "Paralisia facial súbita e perda auditiva neurossensorial."], correctIndex: 2, explanation: "A Síndrome de Ménière é caracterizada pela tétrade de sintomas: episódios de vertigem rotatória, plenitude auricular, zumbido e perda auditiva neurossensorial flutuante, geralmente unilateral.", category: "Otorrinolaringologia" },
  { id: 934, question: "Um paciente de 45 anos refere obstrução nasal crônica, rinorreia posterior, cefaleia frontal e perda do olfato há 6 meses. Ao exame, observa-se massa polipoide em fossa nasal direita. Qual o diagnóstico diferencial mais importante a ser considerado?", options: ["Rinite alérgica crônica.", "Sinusite fúngica invasiva.", "Pólipo antrocoanal.", "Neoplasia maligna de seios paranasais."], correctIndex: 3, explanation: "Sintomas unilaterais, progressivos e a presença de massa em fossa nasal em adulto de meia-idade sempre levantam a suspeita de neoplasia maligna, diferenciando-se de condições inflamatórias benignas.", category: "Otorrinolaringologia" },
  { id: 935, question: "Qual das seguintes afirmativas sobre o carcinoma espinocelular de laringe é INCORRETA?", options: ["O tabagismo e o etilismo são os principais fatores de risco.", "A disfonia persistente é o sintoma mais comum no câncer glótico.", "O tratamento pode envolver cirurgia, radioterapia e quimioterapia.", "Tumores supraglóticos geralmente apresentam prognóstico melhor que os glóticos."], correctIndex: 3, explanation: "Tumores glóticos, devido à sua localização e ao fato de causarem disfonia precoce, tendem a ser diagnosticados em estágios iniciais e apresentam prognóstico relativamente melhor que os supraglóticos ou subglóticos.", category: "Otorrinolaringologia" },
  { id: 936, question: "Em relação à epistaxe, qual a conduta inicial mais adequada em um caso de sangramento nasal anterior leve a moderado em um paciente sem coagulopatia?", options: ["Sondagem nasogástrica para controle do sangramento.", "Compressão digital da asa do nariz contra o septo por 5 a 10 minutos com o paciente inclinado para frente.", "Cauterização química imediata sem compressão prévia.", "Administração de vitamina K endovenosa."], correctIndex: 1, explanation: "A conduta inicial para a maioria dos casos de epistaxe anterior é a compressão digital bimanual da asa do nariz contra o septo, por 5 a 10 minutos, com o paciente ligeiramente inclinado para frente para evitar deglutição de sangue.", category: "Otorrinolaringologia" },
  { id: 937, question: "A triagem auditiva neonatal (teste da orelhinha) tem como objetivo principal identificar precocemente qual tipo de deficiência auditiva?", options: ["Perda auditiva condutiva isolada.", "Deficiências auditivas neurossensoriais e condutivas permanentes e significativas.", "Otite média com efusão.", "Zumbido transitório do recém-nascido."], correctIndex: 1, explanation: "O teste da orelhinha busca identificar perdas auditivas significativas, tanto neurossensoriais quanto condutivas, que possam impactar o desenvolvimento da linguagem e comunicação, permitindo intervenção precoce.", category: "Otorrinolaringologia" },
  { id: 938, question: "Qual fármaco é considerado a primeira escolha no tratamento da rinite alérgica moderada a grave, conforme as diretrizes atuais?", options: ["Anti-histamínicos orais de primeira geração.", "Descongestionantes nasais tópicos.", "Corticosteroides nasais tópicos.", "Antagonistas dos receptores de leucotrienos."], correctIndex: 2, explanation: "Os corticosteroides nasais tópicos são a terapia de primeira linha e mais eficaz para o tratamento da rinite alérgica moderada a grave, agindo sobre os múltiplos sintomas (obstrução, rinorreia, espirros, prurido).", category: "Otorrinolaringologia" },
  { id: 939, question: "Um paciente de 55 anos, diabético tipo 2 e hipertenso, procura a Unidade Básica de Saúde (UBS) para avaliação de rotina. Nega tabagismo ou etilismo. Apresenta IMC de 32 kg/m². Na última consulta, há 6 meses, a glicemia de jejum foi 135 mg/dL e a HbA1c 7,8%. Em relação ao controle glicêmico, qual a meta de HbA1c para este paciente, conforme as diretrizes atuais para DM2?", options: ["Inferior a 6,0%", "Inferior a 6,5%", "Inferior a 7,0%", "Inferior a 8,0%"], correctIndex: 2, explanation: "Para a maioria dos adultos não idosos com diabetes tipo 2, a meta de HbA1c é inferior a 7,0%. Metas mais rígidas (inferior a 6,5%) podem ser consideradas para pacientes jovens sem comorbidades significativas e com baixo risco de hipoglicemia, enquanto metas mais flexíveis (inferior ou igual a 8,0%) são indicadas para idosos frágeis, com muitas comorbidades ou alta expectativa de vida limitada, o que não é o caso do paciente.", category: "Medicina de Família" },
  { id: 940, question: "Mulher de 35 anos busca a UBS para planejamento familiar. Relata histórico de enxaqueca com aura desde a adolescência. É não tabagista e não tem comorbidades. Qual o método contraceptivo que deve ser evitado nesta paciente devido ao risco aumentado de eventos tromboembólicos?", options: ["Dispositivo intrauterino (DIU) de cobre", "Dispositivo intrauterino (DIU) hormonal", "Anticoncepcionais orais combinados", "Progestagênio injetável trimestral"], correctIndex: 2, explanation: "A enxaqueca com aura é uma contraindicação absoluta para o uso de métodos contraceptivos que contêm estrogênio, como os anticoncepcionais orais combinados, devido ao risco aumentado de acidente vascular cerebral isquêmico.", category: "Medicina de Família" },
  { id: 941, question: "Em relação à triagem do câncer de colo de útero no Brasil, qual a idade de início e a periodicidade recomendada para o rastreamento em mulheres assintomáticas de baixo risco, conforme as diretrizes do Ministério da Saúde?", options: ["Início aos 20 anos, anual", "Início aos 25 anos, a cada 3 anos após dois exames normais consecutivos", "Início aos 30 anos, bienal", "Início aos 35 anos, a cada 5 anos"], correctIndex: 1, explanation: "O rastreamento do câncer de colo de útero no Brasil é recomendado para mulheres de 25 a 64 anos. Após dois exames citopatológicos normais consecutivos, com intervalo de um ano, o rastreamento passa a ser realizado a cada três anos.", category: "Medicina de Família" },
  { id: 942, question: "Um recém-nascido de 3 dias de vida, a termo, parto vaginal, procura a UBS para a primeira consulta. A mãe questiona sobre a realização da Triagem Neonatal. Qual o exame realizado na maternidade que permite o diagnóstico precoce de fenilcetonúria, hipotireoidismo congênito, fibrose cística, hiperplasia adrenal congênita, deficiência de biotinidase e anemia falciforme?", options: ["Teste do Olhinho", "Teste da Orelhinha", "Teste do Pezinho", "Teste do Coraçãozinho"], correctIndex: 2, explanation: "O Teste do Pezinho é a triagem neonatal que identifica precocemente diversas doenças metabólicas, genéticas e infecciosas, incluindo as mencionadas na questão, permitindo o tratamento oportuno e prevenindo sequelas graves.", category: "Medicina de Família" },
  { id: 943, question: "Qual a principal intervenção não farmacológica recomendada para pacientes com insuficiência cardíaca com fração de ejeção reduzida (ICFEr), a fim de prevenir a piora da doença e reduzir hospitalizações?", options: ["Restrição hídrica severa para todos os pacientes", "Repouso absoluto prolongado", "Vacinação anual contra influenza e pneumonia pneumocócica", "Monitoramento domiciliar de eletrólitos"], correctIndex: 2, explanation: "A vacinação anual contra influenza e a vacinação contra pneumonia pneumocócica são fundamentais para pacientes com insuficiência cardíaca, pois infecções respiratórias são gatilhos comuns para descompensação e hospitalização.", category: "Medicina de Família" },
  { id: 944, question: "Um homem de 68 anos, hipertenso e dislipidêmico, é trazido à UBS pela família com queixa de perda progressiva de memória recente, dificuldade em planejar atividades e desorientação em locais conhecidos há cerca de 1 ano. Ao exame físico, não há sinais neurológicos focais. Qual o diagnóstico diferencial mais provável para este quadro?", options: ["Delirium agudo", "Depressão maior", "Doença de Alzheimer", "Demência frontotemporal"], correctIndex: 2, explanation: "Os sintomas descritos (perda progressiva de memória recente, dificuldade em planejar, desorientação) são característicos do início da Doença de Alzheimer, a causa mais comum de demência em idosos. Outras demências e condições como delirium e depressão causam quadros diferentes.", category: "Medicina de Família" },
  { id: 945, question: "Qual o principal objetivo do tratamento farmacológico da asma, conforme as diretrizes GINA (Global Initiative for Asthma)?", options: ["Cura da doença em longo prazo", "Alívio rápido dos sintomas agudos", "Controle dos sintomas e redução do risco de exacerbações futuras", "Prevenção da progressão para DPOC"], correctIndex: 2, explanation: "O principal objetivo do tratamento da asma é alcançar o controle dos sintomas e reduzir o risco de exacerbações futuras, minimizando a necessidade de medicação de resgate e melhorando a qualidade de vida do paciente.", category: "Medicina de Família" },
  { id: 946, question: "Paciente sexualmente ativa de 22 anos busca a UBS com queixa de dispareunia, dor pélvica crônica e infertilidade. Ao exame ginecológico, apresenta dor à mobilização do colo uterino e nódulos endurecidos no fundo de saco. Qual a hipótese diagnóstica mais provável?", options: ["Doença inflamatória pélvica aguda", "Miomatose uterina", "Endometriose", "Síndrome do ovário policístico"], correctIndex: 2, explanation: "Os sintomas e achados ao exame físico são altamente sugestivos de endometriose, uma condição em que há tecido semelhante ao endométrio fora do útero, causando dor pélvica, dispareunia e infertilidade.", category: "Medicina de Família" },
  { id: 947, question: "Em relação à Prevenção Quaternária, qual a sua definição e principal objetivo na Atenção Primária à Saúde?", options: ["Identificar fatores de risco para doenças e agir antes que a doença se instale.", "Detectar e tratar precocemente doenças assintomáticas.", "Evitar ou reduzir a iatrogenia médica, protegendo o paciente de intervenções desnecessárias ou prejudiciais.", "Reabilitar pacientes com doenças crônicas para restaurar a funcionalidade."], correctIndex: 2, explanation: "A Prevenção Quaternária visa proteger os pacientes de intervenções médicas excessivas, desnecessárias ou potencialmente prejudiciais, focando em evitar a iatrogenia e a medicalização da vida.", category: "Medicina de Família" },
  { id: 948, question: "Qual a principal causa infecciosa de faringoamigdalite bacteriana em crianças e adolescentes, que necessita de tratamento antibiótico para prevenir complicações como febre reumática?", options: ["Streptococcus pneumoniae", "Haemophilus influenzae", "Streptococcus pyogenes (Estreptococo beta-hemolítico do grupo A)", "Staphylococcus aureus"], correctIndex: 2, explanation: "O Streptococcus pyogenes, também conhecido como Estreptococo beta-hemolítico do grupo A, é o principal agente etiológico da faringoamigdalite bacteriana que causa febre reumática e necessita de tratamento com penicilina.", category: "Medicina de Família" },
  { id: 949, question: "Mulher de 42 anos, relata dor em queimação retroesternal que piora após refeições e ao deitar, aliviando com antiácidos. Nega outros sintomas. Qual a conduta inicial mais apropriada para esta paciente na Atenção Primária?", options: ["Encaminhamento para endoscopia digestiva alta imediata", "Prescrição de omeprazol 20 mg 1x/dia por 8 semanas e medidas comportamentais", "Aconselhamento para dieta livre e aguardar evolução", "Solicitação de pHmetria esofágica de 24h"], correctIndex: 1, explanation: "A queixa é sugestiva de Doença do Refluxo Gastroesofágico. Na Atenção Primária, a conduta inicial para casos típicos sem sinais de alarme é a terapia empírica com inibidor de bomba de prótons por 4-8 semanas, associado a mudanças no estilo de vida.", category: "Medicina de Família" },
  { id: 950, question: "Sobre a avaliação da dor em crianças, qual a escala recomendada para crianças de 0 a 3 anos de idade, que ainda não conseguem se comunicar verbalmente sobre a dor?", options: ["Escala Visual Analógica (EVA)", "Escala de Faces de Wong-Baker", "Escala FLACC (Face, Legs, Activity, Cry, Consolability)", "Escala Numérica de Dor (END)"], correctIndex: 2, explanation: "A escala FLACC (Face, Legs, Activity, Cry, Consolability) é amplamente recomendada para a avaliação da dor em crianças pequenas (0 a 3 anos) que não conseguem verbalizar sua dor, baseando-se em indicadores comportamentais e fisiológicos.", category: "Medicina de Família" },
  { id: 951, question: "Qual o principal critério diagnóstico para Síndrome Metabólica em adultos, conforme as diretrizes brasileiras, que envolve necessariamente a presença de obesidade abdominal?", options: ["Triglicerídeos ≥ 150 mg/dL", "Colesterol HDL < 40 mg/dL (homens) ou < 50 mg/dL (mulheres)", "Pressão arterial ≥ 130/85 mmHg ou uso de anti-hipertensivo", "Circunferência da cintura ≥ 94 cm (homens) ou ≥ 80 cm (mulheres)"], correctIndex: 3, explanation: "O diagnóstico de Síndrome Metabólica requer a presença de obesidade abdominal (circunferência da cintura ≥ 94 cm para homens ou ≥ 80 cm para mulheres) mais dois outros fatores de risco metabólicos dos listados, incluindo triglicerídeos elevados, HDL baixo, pressão arterial elevada ou glicemia de jejum alterada.", category: "Medicina de Família" },
  { id: 952, question: "Um paciente de 65 anos, hipertenso e diabético tipo 2, apresenta-se com angina de início recente. A estratificação de risco cardiovascular indica alto risco. Qual das classes de medicamentos antianginosos é geralmente evitada como monoterapia inicial em pacientes com disfunção de ventrículo esquerdo (FEVE < 40%)?", options: ["Nitratos de longa ação", "Betabloqueadores", "Bloqueadores dos canais de cálcio não di-hidropiridínicos", "Ivabradina"], correctIndex: 2, explanation: "Bloqueadores dos canais de cálcio não di-hidropiridínicos (verapamil, diltiazem) têm efeito inotrópico negativo e cronotrópico negativo, podendo piorar a insuficiência cardíaca com disfunção sistólica grave.", category: "Farmacologia" },
  { id: 953, question: "No tratamento da crise asmática grave em um adulto, além de oxigênio e broncodilatadores inalatórios de curta ação, qual das seguintes classes de medicamentos é indicada para reduzir a inflamação e prevenir a recorrência dos sintomas?", options: ["Antibióticos", "Antileucotrienos", "Corticosteroides sistêmicos", "Imunossupressores"], correctIndex: 2, explanation: "Corticosteroides sistêmicos são fundamentais na crise asmática grave para controlar a inflamação brônquica, melhorar a resposta aos broncodilatadores e reduzir a taxa de exacerbações.", category: "Farmacologia" },
  { id: 954, question: "Qual dos seguintes medicamentos é um inibidor seletivo da recaptação de serotonina (ISRS) e é frequentemente a primeira escolha para o tratamento de transtorno depressivo maior devido ao seu perfil de segurança e tolerabilidade?", options: ["Amitriptilina", "Fluoxetina", "Venlafaxina", "Alprazolam"], correctIndex: 1, explanation: "A fluoxetina é um ISRS amplamente utilizado como primeira linha para depressão, com bom perfil de tolerabilidade e eficácia em muitos pacientes, conforme as diretrizes atuais.", category: "Farmacologia" },
  { id: 955, question: "Uma paciente de 72 anos, com fibrilação atrial não valvar e escore CHA2DS2-VASc de 4, necessita de anticoagulação. Qual dos seguintes medicamentos é contraindicado se a paciente apresentar disfunção renal grave (clearance de creatinina < 15 mL/min)?", options: ["Varfarina", "Dabigatrana", "Edoxabana", "Apixabana"], correctIndex: 1, explanation: "A dabigatrana é extensivamente eliminada pelos rins e é contraindicada em pacientes com clearance de creatinina < 15 mL/min. Outros NOACs e a varfarina requerem ajuste ou monitoramento, mas não contraindicação absoluta nesta situação.", category: "Farmacologia" },
  { id: 956, question: "No tratamento da hipertensão arterial, a combinação de um inibidor da enzima conversora da angiotensina (IECA) e um bloqueador do receptor da angiotensina II (BRA) é geralmente desaconselhada. Qual a principal razão para essa recomendação?", options: ["Risco aumentado de hipocalemia", "Maior probabilidade de tosse refratária", "Aumento significativo do risco de hipercalemia e lesão renal aguda", "Potencial de bradicardia severa"], correctIndex: 2, explanation: "A combinação de IECA e BRA eleva significativamente o risco de hipercalemia, hipotensão e lesão renal aguda, sem benefício cardiovascular adicional comprovado, sendo, portanto, contraindicada.", category: "Farmacologia" },
  { id: 957, question: "Qual das seguintes estatinas possui a maior potência para reduzir o colesterol LDL em doses equivalentes?", options: ["Sinvastatina", "Pravastatina", "Rosuvastatina", "Fluvastatina"], correctIndex: 2, explanation: "A rosuvastatina é considerada a estatina com maior potência na redução do colesterol LDL, seguida pela atorvastatina, sendo eficazes mesmo em baixas doses.", category: "Farmacologia" },
  { id: 958, question: "Um paciente é diagnosticado com úlcera péptica causada por Helicobacter pylori. Qual esquema terapêutico, de acordo com as diretrizes brasileiras, representa uma primeira linha para erradicação?", options: ["Inibidor de bomba de prótons (IBP) + Amoxicilina + Claritromicina", "Ranitidina + Doxiciclina + Metronidazol", "Cimetidina + Azitromicina + Tetraciclina", "Pantoprazol + Levofloxacino + Tinidazol"], correctIndex: 0, explanation: "O esquema clássico de primeira linha para erradicação de H. pylori inclui um IBP, amoxicilina e claritromicina, geralmente por 7 a 14 dias, salvo em áreas de alta resistência à claritromicina.", category: "Farmacologia" },
  { id: 959, question: "No tratamento da osteoporose pós-menopausa, qual das classes de medicamentos abaixo atua inibindo a reabsorção óssea pelos osteoclastos?", options: ["Teriparatida", "Ranelato de estrôncio", "Bifosfonatos", "Denosumabe"], correctIndex: 2, explanation: "Os bifosfonatos (ex: alendronato, risedronato) são a classe de medicamentos que inibe diretamente a função dos osteoclastos, reduzindo a reabsorção óssea e aumentando a densidade mineral óssea.", category: "Farmacologia" },
  { id: 960, question: "Qual dos seguintes fármacos é um agonista do receptor GLP-1 e é utilizado no tratamento do diabetes mellitus tipo 2, associado a benefícios cardiovasculares e renais?", options: ["Metformina", "Glibenclamida", "Semaglutida", "Sitagliptina"], correctIndex: 2, explanation: "A semaglutida é um agonista do receptor de GLP-1 que, além do controle glicêmico, demonstrou benefícios significativos na mortalidade cardiovascular e progressão da doença renal em pacientes com DM2.", category: "Farmacologia" },
  { id: 961, question: "Um paciente em uso crônico de anti-inflamatório não esteroide (AINE) para osteoartrite desenvolve gastropatia. Qual das seguintes opções é uma estratégia adequada para reduzir o risco de complicações gastrointestinais?", options: ["Adicionar um antagonista H2 (ex: ranitidina)", "Adicionar um inibidor de bomba de prótons (IBP)", "Aumentar a dose do AINE", "Substituir o AINE por um paracetamol em dose máxima"], correctIndex: 1, explanation: "A coadministração de um IBP com AINEs é a estratégia mais eficaz para prevenir úlceras e complicações gastrointestinais superiores em pacientes em risco, conforme as diretrizes.", category: "Farmacologia" },
  { id: 962, question: "Em um paciente com insuficiência cardíaca com fração de ejeção reduzida (ICFEr), qual das seguintes classes de medicamentos demonstrou, consistentemente, reduzir mortalidade?", options: ["Diuréticos de alça", "Digoxina", "Inibidores do cotransportador de sódio-glicose 2 (iSGLT2)", "Bloqueadores dos canais de cálcio di-hidropiridínicos"], correctIndex: 2, explanation: "Os iSGLT2 (ex: dapagliflozina, empagliflozina) são uma nova classe que demonstrou redução de mortalidade e hospitalização por IC em pacientes com ICFEr, independentemente da presença de diabetes.", category: "Farmacologia" },
  { id: 963, question: "Qual o principal mecanismo de ação dos inibidores da bomba de prótons (IBP) no tratamento da doença do refluxo gastroesofágico (DRGE)?", options: ["Neutralização do ácido gástrico", "Formação de barreira protetora na mucosa esofágica", "Inibição irreversível da H+/K+-ATPase nas células parietais", "Aumento do tônus do esfíncter esofágico inferior"], correctIndex: 2, explanation: "Os IBPs exercem seu efeito antisecretor gástrico através da inibição irreversível da bomba de prótons nas células parietais, resultando em supressão prolongada da produção de ácido.", category: "Farmacologia" },
  { id: 964, question: "Um paciente com insuficiência renal crônica (clearance de creatinina de 25 mL/min) desenvolve anemia. Qual agente eritropoético é geralmente indicado para estimular a produção de glóbulos vermelhos?", options: ["Ácido fólico", "Ferro parenteral", "Eritropoetina ou análogos", "Vitamina B12"], correctIndex: 2, explanation: "A anemia associada à doença renal crônica é primariamente causada pela deficiência na produção renal de eritropoetina. A suplementação com eritropoetina ou análogos é o tratamento de escolha.", category: "Farmacologia" },
  { id: 965, question: "Qual das seguintes drogas é uma contraindicação absoluta para o uso de betabloqueadores em pacientes com DPOC?", options: ["Asma grave", "Hipertensão arterial sistêmica", "Angina estável", "Taquicardia supraventricular"], correctIndex: 0, explanation: "A asma grave e a doença pulmonar obstrutiva crônica (DPOC) com componente broncoespástico são contraindicações absolutas para o uso de betabloqueadores não seletivos, devido ao risco de desencadear broncoespasmo severo.", category: "Farmacologia" },
  { id: 966, question: "No tratamento da candidíase vulvovaginal não complicada, qual das seguintes classes de antifúngicos é a mais comumente utilizada para tratamento tópico ou oral de curta duração?", options: ["Anfotericina B", "Griseofulvina", "Azóis (ex: fluconazol, clotrimazol)", "Equinocandinas"], correctIndex: 2, explanation: "Antifúngicos azólicos, como o fluconazol oral em dose única ou clotrimazol tópico, são o tratamento de primeira linha para candidíase vulvovaginal não complicada devido à sua eficácia e conveniência.", category: "Farmacologia" },
  { id: 967, question: "Qual o principal efeito adverso que limita o uso de estatina em dose máxima ou em pacientes mais sensíveis?", options: ["Hipotensão", "Hipercalemia", "Mioglobinúria e rabdomiólise", "Hipoglicemia"], correctIndex: 2, explanation: "A miopatia e, em casos graves, a rabdomiólise com mioglobinúria, são os eventos adversos mais sérios e limitantes das estatinas, exigindo monitoramento de enzimas musculares e sintomas musculares.", category: "Farmacologia" },
  { id: 968, question: "Um paciente com diagnóstico recente de HIV, sem tratamento prévio, apresenta contagem de CD4 de 150 células/mm³ e carga viral de 100.000 cópias/mL. Qual a recomendação atual para início da terapia antirretroviral (TARV) neste cenário?", options: ["Aguardar a contagem de CD4 atingir 200 células/mm³", "Iniciar TARV imediatamente, independentemente da contagem de CD4", "Iniciar TARV apenas se houver sintomas de AIDS", "Aguardar um segundo exame de carga viral para confirmação"], correctIndex: 1, explanation: "As diretrizes atuais do Ministério da Saúde recomendam o início da TARV para todos os indivíduos vivendo com HIV, independentemente da contagem de CD4 ou do estágio clínico, o mais rápido possível para melhorar o prognóstico e reduzir a transmissibilidade.", category: "Farmacologia" },
  { id: 969, question: "Qual das seguintes ações farmacológicas NÃO é um efeito esperado dos glicocorticoides em doses farmacológicas?", options: ["Imunossupressão", "Anti-inflamação", "Retenção de sódio e água", "Aumento da síntese de colágeno"], correctIndex: 3, explanation: "Os glicocorticoides em doses farmacológicas inibem a síntese de colágeno e podem levar ao afinamento da pele e prejuízo da cicatrização de feridas, ao contrário do aumento da síntese.", category: "Farmacologia" },
  { id: 970, question: "Um paciente de 82 anos, portador de demência avançada e insuficiência cardíaca classe funcional IV, é internado com pneumonia grave. A família solicita explicitamente que não sejam realizados procedimentos invasivos (intubação, reanimação cardiopulmonar). O médico assistente, diante da gravidade do quadro, pondera sobre a possibilidade de intubação para melhor oxigenação, apesar do desejo da família. Qual princípio bioético está em maior evidência neste conflito?", options: ["Autonomia", "Beneficência", "Não-maleficência", "Justiça"], correctIndex: 0, explanation: "O conflito principal reside entre o desejo da família (representando a autonomia do paciente, mesmo que indiretamente) em relação à intervenção médica. A autonomia, neste caso, preconiza o respeito às escolhas do paciente ou de seus representantes legais.", category: "Bioética" },
  { id: 971, question: "Em uma situação de recursos escassos em uma unidade de terapia intensiva (UTI) durante uma epidemia, qual princípio bioético deve Nortear a decisão sobre a admissão de pacientes, buscando equidade?", options: ["Beneficência individual", "Não-maleficência estrita", "Justiça distributiva", "Autonomia do paciente"], correctIndex: 2, explanation: "A justiça distributiva é o princípio que orienta a alocação de recursos em situações de escassez, buscando uma distribuição equitativa e racional, priorizando o bem-estar coletivo e critérios objetivos.", category: "Bioética" },
  { id: 972, question: "Um médico decide não informar a um paciente oncológico sobre todas as opções de tratamento, por acreditar que o paciente não seria capaz de lidar com a complexidade das informações e pela expectativa de que a informação completa causaria mais danos psicológicos do que benefícios. Qual o termo que melhor descreve essa atitude do médico?", options: ["Paternalismo médico", "Beneficência plena", "Não-maleficência primária", "Autonomia mitigada"], correctIndex: 0, explanation: "O paternalismo médico ocorre quando o profissional de saúde age em benefício do paciente, mas sem considerar ou desrespeitando sua autonomia, tomando decisões que ele considera melhores, mesmo que o paciente não as deseje.", category: "Bioética" },
  { id: 973, question: "Conforme o Código de Ética Médica brasileiro, é um direito do paciente, e dever do médico, recusar-se a ser tratado. Qual dos princípios bioéticos fundamenta primariamente esse direito?", options: ["Não-maleficência", "Beneficência", "Justiça", "Autonomia"], correctIndex: 3, explanation: "O direito de recusar tratamento está intrinsecamente ligado ao princípio da autonomia, que garante ao indivíduo a capacidade de tomar decisões sobre sua própria saúde e corpo, desde que esteja em pleno gozo de suas faculdades mentais.", category: "Bioética" },
  { id: 974, question: "Uma pesquisa clínica com um novo medicamento envolve a participação de voluntários. Para garantir a ética na pesquisa, um dos requisitos fundamentais é que os participantes compreendam os riscos e benefícios envolvidos e consintam livremente. Qual o conceito que abrange esses requisitos?", options: ["Confidencialidade", "Declaração de Helsinque", "Comitê de Ética em Pesquisa", "Termo de Consentimento Livre e Esclarecido"], correctIndex: 3, explanation: "O Termo de Consentimento Livre e Esclarecido (TCLE) é o documento formal que garante que o participante da pesquisa recebeu e compreendeu todas as informações relevantes sobre o estudo e concordou em participar de forma voluntária e consciente.", category: "Bioética" },
  { id: 975, question: "Um médico realiza um procedimento complexo em um paciente sem a devida especialização e sem informar o paciente sobre sua limitação, causando um dano iatrogênico. Qual princípio bioético foi violado principalmente?", options: ["Beneficência", "Não-maleficência", "Autonomia", "Confidencialidade"], correctIndex: 1, explanation: "A não-maleficência, expressa pelo primum non nocere (primeiro, não causar dano), foi violada, pois o médico causou um dano ao paciente ao realizar um procedimento para o qual não estava adequadamente habilitado.", category: "Bioética" },
  { id: 976, question: "Em relação à confidencialidade das informações do paciente, qual das seguintes condutas é eticamente aceitável no contexto médico brasileiro?", options: ["Compartilhar informações com colegas de outras especialidades por curiosidade", "Discutir o caso de um paciente em redes sociais para obter opiniões", "Apresentar um caso clínico em uma aula, omitindo dados de identificação do paciente", "Informar à família do paciente sobre o diagnóstico grave, mesmo sem autorização"], correctIndex: 2, explanation: "Apresentar um caso clínico de forma anonimizada em um contexto educacional ou científico, sem nenhuma forma de identificação do paciente, é uma conduta eticamente aceitável e prevista no Código de Ética Médica para fins de ensino e pesquisa.", category: "Bioética" },
  { id: 977, question: "Qual dos seguintes cenários representa um dilema ético mais complexo, envolvendo múltiplas perspectivas e valores conflitantes?", options: ["Paciente com diagnóstico de apendicite aguda necessitando de cirurgia de emergência e que concorda com o procedimento.", "Recusa de transfusão de sangue por paciente Testemunha de Jeová em situação de risco de vida, com familiares solicitando a transfusão.", "Paciente com febre e tosse que busca atendimento em uma Unidade Básica de Saúde.", "Prescrição de antibiótico para uma infecção bacteriana comum em um paciente jovem."], correctIndex: 1, explanation: "A recusa de transfusão por Testemunha de Jeová envolve conflitos entre a autonomia do paciente, a beneficência (salvar a vida) e, por vezes, a posição da família, configurando um complexo dilema ético.", category: "Bioética" },
  { id: 978, question: "Qual é a principal contraindicação ao uso de betabloqueadores em pacientes com insuficiência cardíaca crônica?", options: ["Bradicardia sinusal assintomática", "Asma brônquica grave não controlada", "Diabetes mellitus tipo 2", "Doença renal crônica"], correctIndex: 1, explanation: "Betabloqueadores são contraindicados em pacientes com asma brônquica grave não controlada ou DPOC grave, devido ao risco de broncoespasmo. As outras condições não são contraindicações absolutas e, em alguns casos, são até indicações para o uso.", category: "Medicações" },
  { id: 979, question: "Um paciente de 45 anos com diagnóstico recente de hipertensão arterial estágio 1, sem comorbidades associadas, não obteve controle pressórico adequado apenas com mudanças no estilo de vida. Qual é o fármaco de primeira linha recomendado para iniciar o tratamento anti-hipertensivo neste caso, de acordo com as diretrizes brasileiras?", options: ["Anlodipino", "Hidroclorotiazida", "Captopril", "Propranolol"], correctIndex: 1, explanation: "As diretrizes brasileiras (7ª Diretriz Brasileira de Hipertensão Arterial) recomendam diuréticos tiazídicos como primeira linha para a maioria dos pacientes hipertensos sem comorbidades específicas que justifiquem outra classe. Anlodipino (bloqueador de canal de cálcio), Captopril (iECA) e Propranolol (betabloqueador) são opções, mas não a primeira escolha isolada neste cenário.", category: "Medicações" },
  { id: 980, question: "Qual das seguintes medicações é a conduta inicial mais apropriada para um paciente com crise asmática grave em pronto-socorro?", options: ["Corticosteroide oral em dose única", "Nebulização com salbutamol e ipratrópio", "Aminofilina intravenosa", "Antibiótico de amplo espectro"], correctIndex: 1, explanation: "A nebulização com broncodilatadores de curta ação (beta-2 agonistas como salbutamol) associados a anticolinérgicos (ipratrópio) é o tratamento de primeira linha para crises asmáticas, devido à sua rápida ação broncodilatadora. Corticosteroides orais são usados, mas não é a primeira conduta isoladamente para reverter a crise aguda.", category: "Medicações" },
  { id: 981, question: "Uma paciente de 30 anos em uso de anticoncepcional oral combinado relata dor de cabeça de início súbito e alteração visual. Qual das medicações a seguir deve ser descontinuada imediatamente e investigada a causa?", options: ["Paracetamol", "Anticoncepcional oral combinado", "Dipirona", "Sinvastatina"], correctIndex: 1, explanation: "Anticoncepcionais orais combinados aumentam o risco de eventos tromboembólicos (AVC, trombose). Cefaleia intensa súbita com sintomas neurológicos (alteração visual) pode indicar um evento cerebrovascular, e o anticoncepcional deve ser suspenso enquanto a causa é investigada. As outras medicações não têm essa associação de risco.", category: "Medicações" },
  { id: 982, question: "Qual das seguintes medicações é considerada o tratamento de primeira linha para o hipertiroidismo de Graves em pacientes adultos?", options: ["Metimazol", "Iodo radioativo", "Propranolol", "Levotiroxina"], correctIndex: 0, explanation: "O metimazol é a droga antitireoidiana de primeira linha para o tratamento do hipertiroidismo de Graves na maioria dos adultos, devido à sua eficácia e menor frequência de efeitos colaterais graves em comparação com o propiltiouracil (outra tionamida). O iodo radioativo e a cirurgia são tratamentos definitivos, e o propranolol trata os sintomas.", category: "Medicações" },
  { id: 983, question: "Um paciente de 70 anos, com fibrilação atrial não valvar, HAS e insuficiência cardíaca com fração de ejeção reduzida, apresenta um CHA2DS2-VASc escore de 4. Qual a conduta de anticoagulação mais apropriada para este paciente?", options: ["AAS em baixa dose", "Anticoagulante oral de ação direta (DOAC)", "Clopidogrel", "Warfarina e AAS"], correctIndex: 1, explanation: "Com um CHA2DS2-VASc escore de 2 ou mais para homens (ou 3 ou mais para mulheres), a anticoagulação é fortemente recomendada. Os DOACs (Apixaban, Rivaroxaban, Dabigatran, Edoxaban) são preferidos à varfarina na FA não valvar, por sua maior segurança e conveniência, conforme as diretrizes da SBC e AHA.", category: "Medicações" },
  { id: 984, question: "Qual medicação é a primeira escolha para o tratamento da dor neuropática localizada, como na neuralgia pós-herpética?", options: ["Paracetamol", "Gabapentina", "Ibuprofeno", "Morfina"], correctIndex: 1, explanation: "A gabapentina (e a pregabalina) são anticonvulsivantes que atuam na modulação de canais de cálcio dependentes de voltagem e são considerados de primeira linha para o tratamento da dor neuropática. Analgésicos comuns como paracetamol e ibuprofeno são ineficazes, e opioides (morfina) são de segunda ou terceira linha devido aos efeitos colaterais e risco de dependência.", category: "Medicações" },
  { id: 985, question: "Qual dos seguintes fármacos é um inibidor direto do fator Xa?", options: ["Varfarina", "Dabigatran", "Rivaroxabana", "Enoxaparina"], correctIndex: 2, explanation: "A rivaroxabana é um anticoagulante oral de ação direta (DOAC) que inibe seletivamente o fator Xa. A varfarina é um antagonista da vitamina K, o dabigatran é um inibidor direto da trombina e a enoxaparina é uma heparina de baixo peso molecular que atua principalmente no fator Xa indiretamente via antitrombina.", category: "Medicações" },
  { id: 986, question: "Em um paciente com diabetes mellitus tipo 2 e doença cardiovascular aterosclerótica estabelecida, qual classe de hipoglicemiantes é recomendada para reduzir risco cardiovascular?", options: ["Sulfonilureias", "Inibidores de DPP-4", "Análogos do GLP-1 ou inibidores de SGLT2", "Metformina"], correctIndex: 2, explanation: "Análogos do GLP-1 e Inibidores de SGLT2 demonstraram em grandes ensaios clínicos reduzir eventos cardiovasculares adversos maiores e mortalidade em pacientes com DM2 e doença cardiovascular estabelecida, tornando-os a escolha preferencial neste cenário, conforme diretrizes da AHA/ADA/SBC. Metformina é primeira linha para controle glicêmico, mas não possui o mesmo perfil de proteção cardiovascular nos pacientes com DCV estabelecida.", category: "Medicações" },
  { id: 987, question: "Qual das seguintes medicações deve ser evitada em pacientes idosos com delirium, devido ao risco de piora da confusão mental e outros efeitos anticolinérgicos?", options: ["Haloperidol", "Paracetamol", "Omeprazol", "Oxibutinina"], correctIndex: 3, explanation: "A oxibutinina é um anticolinérgico potente, usado para bexiga hiperativa. Em idosos, especialmente aqueles com delirium ou risco de delirium, anticolinérgicos podem exacerbar a confusão mental e causar outros efeitos adversos como boca seca, constipação e retenção urinária. Haloperidol pode ser usado para controle da agitação no delirium, paracetamol e omeprazol são geralmente seguros neste contexto.", category: "Medicações" },
  { id: 988, question: "Qual a principal alteração eletrocardiográfica que contraindica o uso de digoxina?", options: ["Fibrilação atrial persistente", "Taquicardia ventricular polimórfica", "Bradicardia sinusal", "Bloqueio atrioventricular de 1º grau"], correctIndex: 1, explanation: "A digoxina é contraindicada ou deve ser usada com extrema cautela em taquicardias ventriculares polimórficas ou arritmias ventriculares complexas, pois pode aumentar o automatismo e agravar as arritmias, levando a intoxicação digitálica ameaçadora à vida. As outras condições não são contraindicações absolutas (FA e bradicardia podem até ser indicações, e BAV de 1º grau é uma contraindicação relativa).", category: "Medicações" },
  { id: 989, question: "Qual o principal mecanismo de ação dos inibidores da bomba de prótons (IBPs), como o omeprazol?", options: ["Neutralização do ácido gástrico", "Bloqueio dos receptores H2 de histamina", "Inibição direta da enzima H+/K+-ATPase", "Formação de barreira protetora na mucosa gástrica"], correctIndex: 2, explanation: "Os IBPs atuam inibindo de forma irreversível a enzima H+/K+-ATPase (bomba de prótons) nas células parietais gástricas, resultando na supressão mais potente e prolongada da secreção de ácido gástrico. Antiácidos neutralizam o ácido, bloqueadores H2 bloqueiam receptores de histamina e sucralfato forma uma barreira.", category: "Medicações" },
  { id: 990, question: "Um paciente em uso de varfarina para trombose venosa profunda apresenta um INR de 6,5, sem sangramento ativo. Qual a conduta mais apropriada neste cenário?", options: ["Suspender varfarina e administrar 5mg de vitamina K oral", "Suspender varfarina e administrar concentrado de complexo protrombínico", "Reduzir a dose de varfarina e reavaliar INR em 24h", "Manter varfarina e monitorar INR diariamente"], correctIndex: 0, explanation: "Para INR > 4,5 e < 10, sem sangramento, as diretrizes (como as do Colégio Americano de Médicos do Tórax - CHEST) recomendam a interrupção da varfarina e administração de 1 a 2,5 mg de vitamina K oral para reverter a coagulação excessiva. Doses mais altas ou concentrado de complexo protrombínico são para INR muito elevado ou com sangramento.", category: "Medicações" },
  { id: 991, question: "A Atenção Primária à Saúde (APS) é reconhecida como o nível de atenção que deve ser o contato inicial preferencial dos usuários com o sistema de saúde. Em relação aos atributos essenciais da APS, qual das opções abaixo NÃO se enquadra como um desses atributos?", options: ["Acesso de primeiro contato", "Longitudinalidade", "Competência cultural", "Integralidade"], correctIndex: 2, explanation: "Os atributos essenciais da APS são: acesso de primeiro contato, longitudinalidade, integralidade e coordenação. Competência cultural é um atributo derivado, mas não essencial neste contexto.", category: "Saúde Pública" },
  { id: 992, question: "Um surto de sarampo foi identificado em uma comunidade. A equipe de saúde local, seguindo as diretrizes do Ministério da Saúde para vigilância epidemiológica, deve priorizar qual das seguintes ações para o controle imediato do surto?", options: ["Início de quimioprofilaxia em todos os contatos domiciliares", "Vacinação de bloqueio em todas as pessoas suscetíveis na área afetada", "Coleta de amostras de sangue de todos os casos suspeitos para sorologia", "Isolamento hospitalar de todos os casos confirmados de sarampo"], correctIndex: 1, explanation: "A vacinação de bloqueio de suscetíveis na área afetada é a medida mais eficaz e imediata para interromper a cadeia de transmissão do sarampo em um surto, conforme as diretrizes de vigilância epidemiológica.", category: "Saúde Pública" },
  { id: 993, question: "Um usuário de 65 anos, com hipertensão arterial e diabetes mellitus tipo 2, comparece à Unidade Básica de Saúde (UBS) para consulta de rotina. Durante a estratificação de risco cardiovascular, a equipe de saúde deve considerar fatores que potencializam o risco. Qual dos seguintes exames laboratoriais, se alterado, indica um maior risco cardiovascular, além das comorbidades já presentes?", options: ["Hemoglobina glicada de 6,0%", "Colesterol LDL de 110 mg/dL", "Taxa de filtração glomerular estimada de 55 mL/min/1,73m²", "Ácido úrico de 4,5 mg/dL"], correctIndex: 2, explanation: "Uma taxa de filtração glomerular estimada (TFGe) abaixo de 60 mL/min/1,73m² (doença renal crônica) é um importante fator de risco cardiovascular independente, potencializando o risco em pacientes já com hipertensão e diabetes.", category: "Saúde Pública" },
  { id: 994, question: "Em relação aos indicadores de saúde utilizados na avaliação do Sistema Único de Saúde (SUS), qual das opções abaixo representa um indicador de impacto em saúde?", options: ["Número de consultas médicas por habitante/ano", "Taxa de mortalidade infantil", "Proporção de cobertura vacinal", "Tempo médio de espera para cirurgias eletivas"], correctIndex: 1, explanation: "A taxa de mortalidade infantil reflete o resultado final da interação de diversos fatores socioeconômicos e assistenciais, sendo um indicador clássico de impacto na saúde da população, ao contrário dos demais que são indicadores de processo ou acesso.", category: "Saúde Pública" },
  { id: 995, question: "Um paciente de 45 anos, tabagista, procurou a UBS para auxílio na cessação do tabagismo. Conforme as diretrizes do Ministério da Saúde, qual a abordagem farmacológica de primeira linha, quando indicada, para auxiliar na cessação do tabagismo neste paciente?", options: ["Vareniclina", "Nortriptilina", "Clonidina", "Bupropiona"], correctIndex: 0, explanation: "A vareniclina e a bupropiona são consideradas terapias de primeira linha para cessação do tabagismo, de acordo com as diretrizes do Ministério da Saúde. Ambas possuem eficácia comprovada, sendo a vareniclina frequentemente citada como uma das mais eficazes.", category: "Saúde Pública" },
  { id: 996, question: "O Programa Nacional de Imunizações (PNI) do Brasil é referência mundial. Qual o principal objetivo da introdução da vacina contra o Papilomavírus Humano (HPV) no calendário vacinal dos adolescentes?", options: ["Prevenir verrugas genitais em homens e mulheres", "Reduzir a incidência de câncer de mama em mulheres", "Controlar a transmissão de HIV/Aids", "Reduzir a incidência de câncer de colo de útero e outras neoplasias associadas ao HPV"], correctIndex: 3, explanation: "O principal objetivo da vacinação contra o HPV é a prevenção de infecções persistentes pelos tipos oncogênicos do vírus, visando a redução da incidência de câncer de colo de útero e outras neoplasias ano-genitais e orofaríngeas associadas ao HPV.", category: "Saúde Pública" },
  { id: 997, question: "A Estratégia Saúde da Família (ESF) é o modelo prioritário de organização da Atenção Primária no SUS. Um dos princípios que norteiam a ESF é o da 'territorialização'. O que o conceito de territorialização implica na prática da equipe de saúde?", options: ["A atuação da equipe se restringe ao atendimento dentro dos limites físicos da UBS", "A equipe deve conhecer e atuar sobre os determinantes sociais e de saúde específicos de sua área de adscrição", "O território é o espaço administrativo de delimitação das ações intersetoriais com outros municípios", "Significa que cada equipe é responsável por um número fixo de famílias, independentemente da localização geográfica"], correctIndex: 1, explanation: "A territorialização implica no reconhecimento e na atuação da equipe sobre as características geográficas, sociais, epidemiológicas e culturais da área de adscrição, compreendendo os determinantes do processo saúde-doença da população local.", category: "Saúde Pública" },
  { id: 998, question: "Para o diagnóstico de tuberculose pulmonar ativa em um paciente com tosse persistente por mais de três semanas, febre e sudorese noturna, qual o método diagnóstico prioritário e de escolha conforme as diretrizes do Ministério da Saúde?", options: ["Radiografia de tórax", "Cultura de escarro para Mycobacterium tuberculosis", "Teste rápido molecular para tuberculose (TRM-TB)", "Teste cutâneo de Mantoux (PPD)"], correctIndex: 2, explanation: "O Teste Rápido Molecular para Tuberculose (TRM-TB) é o método diagnóstico prioritário e de escolha inicial, devido à sua alta sensibilidade, especificidade e capacidade de detectar resistência à rifampicina em poucas horas, conforme as diretrizes atuais do MS.", category: "Saúde Pública" },
  { id: 999, question: "No contexto da saúde do idoso no SUS, a avaliação multidimensional é fundamental. Um dos instrumentos utilizados para rastrear vulnerabilidades e planejar intervenções é a Avaliação Geriátrica Ampla (AGA). Qual a finalidade principal da AGA?", options: ["Diagnosticar demência em estágios iniciais para tratamento imediato", "Identificar idosos em risco de fragilidade e perda de autonomia", "Avaliar exclusivamente a capacidade funcional física do idoso", "Determinar a elegibilidade do idoso para programas de socialização comunitária"], correctIndex: 1, explanation: "A Avaliação Geriátrica Ampla (AGA) tem como finalidade principal identificar idosos em risco de fragilidade, comorbidades, síndromes geriátricas e perda de autonomia, permitindo um planejamento de cuidado individualizado e preventivo.", category: "Saúde Pública" },
  { id: 1000, question: "Em relação à saúde mental na Atenção Primária à Saúde, qual das seguintes afirmativas está correta de acordo com as diretrizes atuais do Ministério da Saúde?", options: ["O atendimento em saúde mental deve ser realizado exclusivamente por psiquiatras e psicólogos em ambulatórios especializados", "A Atenção Primária tem um papel fundamental na identificação, manejo e acompanhamento de transtornos mentais leves e moderados", "Pacientes com transtornos mentais graves devem ser encaminhados diretamente a hospitais psiquiátricos para internação prolongada", "A prescrição de psicofármacos é de competência exclusiva dos Centros de Atenção Psicossocial (CAPS)"], correctIndex: 1, explanation: "A Atenção Primária tem um papel central na Rede de Atenção Psicossocial (RAPS), sendo responsável pela identificação precoce, manejo inicial, acompanhamento longitudinal e coordenação do cuidado de casos leves a moderados, e encaminhamento para serviços especializados quando necessário.", category: "Saúde Pública" },
  { id: 1001, question: "Uma comunidade apresenta alta incidência de casos de dengue. Para o controle vetorial, qual das seguintes estratégias é considerada pilar fundamental e de maior impacto na redução da proliferação do Aedes aegypti, de acordo com as diretrizes do Ministério da Saúde?", options: ["Aplicação de fumacê espacial em todas as casas", "Uso de armadilhas ovitrampas para monitoramento", "Eliminação de focos e criadouros do mosquito pela população e agentes de saúde", "Distribuição em massa de repelentes dérmicos"], correctIndex: 2, explanation: "A eliminação de focos e criadouros do mosquito Aedes aegypti, com forte participação comunitária e atuação dos agentes de saúde, é a estratégia mais eficaz e sustentável no controle vetorial da dengue, conforme as diretrizes nacionais.", category: "Saúde Pública" },
  { id: 1002, question: "Um paciente de 30 anos, sem comorbidades conhecidas, apresenta índice de massa corporal (IMC) de 32 kg/m². Qual a classificação do seu estado nutricional e qual a principal recomendação inicial para o manejo na Atenção Primária à Saúde?", options: ["Sobrepeso; encaminhamento imediato para cirurgia bariátrica", "Obesidade grau I; acompanhamento multiprofissional com foco em mudança de estilo de vida", "Obesidade grau II; início de fármacos para perda de peso", "Obesidade grau I; restrição calórica severa e exercícios intensos"], correctIndex: 1, explanation: "Um IMC de 32 kg/m² classifica o paciente como obesidade grau I. O manejo inicial na Atenção Primária foca em mudança de estilo de vida (dieta equilibrada e atividade física), com acompanhamento multiprofissional, antes de considerar terapias mais complexas.", category: "Saúde Pública" },
  { id: 1003, question: "Um paciente de 65 anos, diabético e hipertenso, é admitido na UTI com quadro de sepse grave de foco pulmonar. Encontra-se em choque séptico, necessitando de noradrenalina em altas doses. Qual dos seguintes parâmetros é o MAIS recomendado para guiar a ressuscitação volêmica e o ajuste de vasopressores, visando o desfecho do paciente, conforme as diretrizes atuais?", options: ["Pressão Venosa Central (PVC)", "Pressão Arterial Média (PAM)", "Débito Urinário (DU)", "Saturação Venosa Central de Oxigênio (SvO2)"], correctIndex: 3, explanation: "A SvO2, quando disponível e interpretada no contexto clínico, é um parâmetro útil para avaliar o equilíbrio entre oferta e consumo de oxigênio sistêmico na sepse. As diretrizes atuais enfatizam a avaliação dinâmica da resposta a fluidos e a adequação da perfusão, e a SvO2 pode guiar o tratamento de forma mais eficaz do que PVC isolada ou PAM.", category: "UTI" },
  { id: 1004, question: "Qual das seguintes estratégias de ventilação mecânica é recomendada para pacientes com Síndrome do Desconforto Respiratório Agudo (SDRA) moderada a grave, conforme as diretrizes atuais para reduzir a mortalidade?", options: ["Volume corrente de 8-10 mL/kg de peso predito e PEEP titulada para manter o platô < 35 cmH2O.", "Volume corrente de 4-6 mL/kg de peso predito e PEEP titulada para manter o platô < 30 cmH2O.", "Volume corrente de 10-12 mL/kg de peso predito e PEEP fixa de 5 cmH2O.", "Ventilação com pressão controlada, sem limite de pressão de platô, para otimizar a oxigenação."], correctIndex: 1, explanation: "A estratégia de ventilação protetora pulmonar na SDRA envolve o uso de baixo volume corrente (4-6 mL/kg de peso predito) e PEEP titulada para manter a pressão de platô inferior a 30 cmH2O. Esta abordagem demonstrou reduzir a mortalidade e a lesão pulmonar induzida pela ventilação.", category: "UTI" },
  { id: 1005, question: "Um paciente de 70 anos, com histórico de fibrilação atrial em uso de anticoagulação, apresenta rebaixamento do nível de consciência súbito e é diagnosticado com hemorragia intracraniana por tomografia computadorizada. Ele está intubado e hemodinamicamente estável. Qual a conduta inicial mais adequada em relação à anticoagulação?", options: ["Manter o anticoagulante, pois o risco de trombose é alto.", "Administrar protamina para reverter o efeito do anticoagulante imediatamente.", "Suspender o anticoagulante e aguardar a avaliação neurocirúrgica.", "Suspender o anticoagulante e solicitar dosagem do INR para guiar a reversão, se aplicável."], correctIndex: 3, explanation: "Em casos de hemorragia intracraniana em pacientes anticoagulados, a suspensão imediata do anticoagulante é prioritária. Em seguida, a reversão específica, se necessária, deve ser guiada por exames laboratoriais (ex: INR para antagonistas da vitamina K ou dosagem de outros anticoagulantes), não de forma empírica como protamina para todos os casos.", category: "UTI" },
  { id: 1006, question: "No manejo do delirium em pacientes internados na UTI, qual das seguintes estratégias é considerada de primeira linha, conforme as evidências atuais?", options: ["Uso rotineiro de benzodiazepínicos para sedação.", "Imobilização física para prevenir quedas.", "Medidas não farmacológicas para otimizar o sono, mobilidade e cognição.", "Administração preventiva de antipsicóticos em baixas doses."], correctIndex: 2, explanation: "As diretrizes atuais priorizam as medidas não farmacológicas como primeira linha para a prevenção e tratamento do delirium. Isso inclui a otimização do ambiente, promoção do sono, mobilização precoce, reorientação e manejo da dor, reduzindo a necessidade de sedoanalgesia excessiva.", category: "UTI" },
  { id: 1007, question: "Um paciente em ventilação mecânica invasiva desenvolve hipotensão refratária e piora da oxigenação. Ao exame físico, observa-se distensão jugular, desvio da traqueia contralateral e diminuição do murmúrio vesicular no hemitórax direito. Qual a conduta IMEDIATA mais apropriada?", options: ["Realizar radiografia de tórax e aguardar resultado.", "Iniciar vasopressor em alta dose.", "Realizar drenagem torácica de alívio por agulha no hemitórax direito.", "Aumentar a PEEP e o volume corrente para melhorar a oxigenação."], correctIndex: 2, explanation: "O quadro clínico é altamente sugestivo de pneumotórax hipertensivo, uma emergência médica. A drenagem de alívio por agulha deve ser realizada imediatamente para descomprimir o pulmão e restaurar o débito cardíaco, antes de outras intervenções.", category: "UTI" },
  { id: 1008, question: "Qual das seguintes afirmações sobre a monitorização da dor na UTI é a mais correta?", options: ["A monitorização da dor deve ser realizada exclusivamente por escalas numéricas de dor em pacientes com comunicação verbal preservada.", "Em pacientes sedados e não comunicativos, a monitorização behavioral da dor (p. ex., escala de agitação e sedação) é suficiente.", "A monitorização da dor deve ser contínua e utilizar ferramentas validadas, adaptadas ao nível de consciência do paciente.", "A dor deve ser tratada apenas após a estabilização hemodinâmica completa do paciente."], correctIndex: 2, explanation: "As diretrizes recomendam a monitorização regular e contínua da dor utilizando escalas validadas, que devem ser adaptadas ao nível de consciência e capacidade de comunicação do paciente. Isso pode incluir escalas de autoavaliação ou escalas comportamentais.", category: "UTI" },
  { id: 1009, question: "No tratamento inicial da cetoacidose diabética grave, qual dos seguintes é o pilar fundamental do tratamento, além da insulina?", options: ["Bicarbonato de sódio intravenoso.", "Administração agressiva de potássio.", "Hidratação venosa vigorosa com cristaloides.", "Dose em bolus de insulina de ação rápida intravenosa."], correctIndex: 2, explanation: "A hidratação venosa com cristaloides é crucial no tratamento da cetoacidose diabética, visando repor o déficit hídrico significativo e melhorar a perfusão tecidual e a depuração de corpos cetônicos. A insulina é administrada após início da hidratação, e a reposição de potássio é guiada pelos níveis séricos.", category: "UTI" },
  { id: 1010, question: "Qual é a principal indicação para o uso de corticosteroides em pacientes com sepse e choque séptico?", options: ["Rotineiramente em todos os pacientes com sepse.", "Quando há evidência de insuficiência adrenal aguda.", "Quando o choque séptico persiste apesar de vasopressores e hidratação adequada.", "Para reduzir a resposta inflamatória em sepse de foco pulmonar."], correctIndex: 2, explanation: "Os corticosteroides (hidrocortisona) são recomendados apenas para pacientes adultos com choque séptico refratário a vasopressores, ou seja, que permanecem em choque apesar da ressuscitação volêmica adequada e uso de vasopressores (geralmente noradrenalina).", category: "UTI" },
  { id: 1011, question: "Um paciente com insuficiência cardíaca descompensada é admitido na UTI com edema agudo de pulmão e hipoxemia grave. Qual a terapia inicial MAIS apropriada para melhorar a troca gasosa e reduzir o trabalho respiratório?", options: ["Ventilação mecânica invasiva com PEEP elevada.", "Oxigenoterapia de alto fluxo por cateter nasal.", "Ventilação não invasiva (VNI) com pressão positiva contínua nas vias aéreas (CPAP/BiPAP).", "Administração de altas doses de diuréticos de alça intravenosos."], correctIndex: 2, explanation: "A ventilação não invasiva (VNI), especialmente o CPAP, é a terapia de primeira linha para pacientes com edema agudo de pulmão cardiogênico e hipoxemia, pois melhora a oxigenação, reduz o trabalho respiratório e a pré-carga cardíaca, evitando a intubação orotraqueal em muitos casos.", category: "UTI" },
  { id: 1012, question: "Em relação à prevenção de úlcera de estresse gastrointestinal em pacientes críticos, qual das seguintes afirmativas está correta?", options: ["Todos os pacientes internados na UTI devem receber profilaxia.", "A profilaxia é prioritária em pacientes com baixo risco, como aqueles em jejum prolongado.", "A profilaxia com inibidores de bomba de prótons ou antagonistas de receptores H2 é recomendada para pacientes de alto risco.", "A nutrição enteral precoce não tem impacto na prevenção de úlcera de estresse."], correctIndex: 2, explanation: "A profilaxia para úlcera de estresse gastrointestinal é recomendada apenas para pacientes de alto risco (p. ex., ventilação mecânica prolongada, coagulopatia, sepse grave, lesão renal aguda). Inibidores de bomba de prótons e antagonistas H2 são as classes de fármacos mais utilizadas para este fim.", category: "UTI" },
  { id: 1013, question: "Um paciente em ventilação mecânica apresenta assincronia paciente-ventilador. Qual das seguintes medidas é uma estratégia INICIAL para otimizar a interação paciente-ventilador?", options: ["Aumentar a frequência respiratória controlada do ventilador para suprimir o drive do paciente.", "Aplicar sedação profunda e prolongada para eliminar a respiração espontânea do paciente.", "Ajustar os parâmetros do ventilador (p. ex., fluxo inspiratório, tempo inspiratório, trigger) e considerar a otimização da sedoanalgesia.", "Realizar traqueostomia imediata para facilitar o desmame."], correctIndex: 2, explanation: "A otimização dos parâmetros do ventilador para melhor se adequar ao padrão respiratório do paciente é a primeira e mais importante etapa no manejo da assincronia. A sedoanalgesia deve ser revisada e ajustada para atender às necessidades do paciente sem excesso, que pode causar outros problemas.", category: "UTI" },
  { id: 1014, question: "Qual das seguintes drogas é a MAIS utilizada como vasopressor de primeira linha para choque séptico em adultos, conforme as diretrizes atuais?", options: ["Dopamina", "Fenilefrina", "Noradrenalina", "Vasopressina"], correctIndex: 2, explanation: "A noradrenalina é o vasopressor de primeira linha recomendado para o tratamento do choque séptico devido à sua eficácia em aumentar a pressão arterial média e sua menor incidência de arritmias em comparação com a dopamina.", category: "UTI" },
  { id: 1015, question: "No contexto da terapia com fluidos para ressuscitação em sepse, qual das seguintes afirmativas é a mais apropriada?", options: ["Cristaloides balanceados são preferíveis a soro fisiológico 0,9% para a ressuscitação inicial.", "Grandes volumes de fluidos em bolus devem ser administrados sem reavaliação contínua.", "Coloides são superiores a cristaloides na redução da mortalidade em choque séptico.", "A ressuscitação com fluidos deve ser interrompida após atingir uma PVC > 12 mmHg."], correctIndex: 0, explanation: "Estudos recentes e diretrizes sugerem que cristaloides balanceados (como Ringer Lactato ou solução multi-eletrolítica) podem ser preferíveis ao soro fisiológico 0,9% devido a um menor risco de hipercloremia e lesão renal aguda associada ao soro fisiológico.", category: "UTI" },
  { id: 1016, question: "Qual é o objetivo principal da sedação em pacientes críticos em ventilação mecânica?", options: ["Alcançar o nível mais profundo possível de sedação para garantir o conforto do paciente.", "Permitir que o paciente durma profundamente durante todo o período de ventilação mecânica.", "Manter o paciente acordado e responsivo para facilitar o desmame.", "Proporcionar conforto, reduzir o estresse e otimizar a interação com o ventilador, com o nível de sedação mais leve possível."], correctIndex: 3, explanation: "O objetivo da sedação em UTI é alcançar o conforto e a segurança do paciente, facilitar os procedimentos e a ventilação mecânica, minimizando os efeitos adversos. O ideal é manter o nível de sedação mais leve possível, buscando a sedação superficial para permitir o despertar diário e a avaliação da extubação.", category: "UTI" },
  { id: 1017, question: "Um paciente de 45 anos, previamente hígido, é admitido com diagnóstico de Pancreatite Aguda Grave. Apresenta falência renal aguda, respiratória e circulatória. Qual a principal complicação que pode levar a um pior prognóstico em pacientes com pancreatite aguda grave?", options: ["Hiperglicemia persistente.", "Insuficiência de múltiplos órgãos.", "Derrame pleural isolado.", "Dor abdominal refratária."], correctIndex: 1, explanation: "A principal causa de mortalidade na pancreatite aguda grave é a insuficiência de múltiplos órgãos (IMO), que resulta da resposta inflamatória sistêmica exacerbada. O desenvolvimento de IMO indica um pior prognóstico e necessita de suporte intensivo.", category: "UTI" },
  { id: 1018, question: "Qual a principal causa de mortalidade tardia na Síndrome do Desconforto Respiratório Agudo (SDRA)?", options: ["Barotrauma.", "Fibrose pulmonar.", "Insuficiência de múltiplos órgãos (IMO) e sepse nosocomial.", "Hipertensão pulmonar."], correctIndex: 2, explanation: "Embora a hipoxemia refratária e o barotrauma sejam complicações iniciais da SDRA, a principal causa de mortalidade tardia é a insuficiência de múltiplos órgãos (IMO) e as infecções nosocomiais, como a pneumonia associada à ventilação mecânica.", category: "UTI" },
  { id: 1019, question: "Um paciente com choque hemorrágico devido a trauma abdominal é admitido na UTI. A abordagem inicial inclui fluidoterapia, controle da hemorragia e transfusão de hemocomponentes. Qual a proporção MAIS adequada para a transfusão de hemocomponentes no protocolo de transfusão massiva?", options: ["Apenas concentrado de hemácias (CH) até estabilização.", "1:1:1 (CH:Plasma Fresco Congelado:Plaquetas).", "2:1:1 (CH:Plasma Fresco Congelado:Plaquetas).", "Apenas plasma fresco congelado (PFC) até normalização da coagulação."], correctIndex: 1, explanation: "As diretrizes atuais para transfusão massiva em choque hemorrágico recomendam uma proporção de 1:1:1 de concentrado de hemácias, plasma fresco congelado e plaquetas. Esta abordagem visa corrigir a coagulopatia e minimizar a disfunção orgânica.", category: "UTI" },
  { id: 1020, question: "Na avaliação do estado nutricional em pacientes críticos, qual das seguintes estratégias é a mais adequada para iniciar a nutrição enteral?", options: ["Aguardar a estabilização hemodinâmica completa e a resolução da paralisação intestinal.", "Iniciar a nutrição enteral o mais precocemente possível (dentro de 24-48h) se o paciente estiver hemodinamicamente estável.", "Optar por nutrição parenteral total como primeira linha em todos os pacientes críticos.", "Iniciar a nutrição enteral em volumes baixos apenas após 7 dias de internação, independentemente do estado do paciente."], correctIndex: 1, explanation: "A nutrição enteral precoce (dentro de 24 a 48 horas) é recomendada para pacientes críticos hemodinamicamente estáveis, pois reduz complicações infecciosas, melhora a função imunológica e mantém a integridade da barreira intestinal. A nutrição parenteral é reservada para quando a enteral não é possível ou suficiente.", category: "UTI" },
  { id: 1021, question: "Qual é a intervenção de enfermagem MAIS eficaz para prevenir a Pneumonia Associada à Ventilação Mecânica (PAV) em pacientes intubados?", options: ["Administração profilática de antibióticos por tempo prolongado.", "Elevação da cabeceira do leito entre 30 e 45 graus.", "Rotina de troca diária do circuito do ventilador.", "Uso de antissépticos bucais sem higiene oral mecânica."], correctIndex: 1, explanation: "A elevação da cabeceira do leito entre 30 e 45 graus é uma medida simples e altamente eficaz na prevenção da PAV, pois reduz o risco de aspiração de conteúdo gástrico e secreções orofaríngeas, sendo parte fundamental dos bundles de PAV.", category: "UTI" },
  { id: 1022, question: "No manuseio de pacientes com edema cerebral pós-lesão traumática encefálica (LCE), qual das seguintes medidas é uma estratégia de primeira linha para reduzir a pressão intracraniana (PIC)?", options: ["Hiperventilação prolongada mantendo PaCO2 abaixo de 25 mmHg.", "Administração de solução salina hipertônica ou manitol.", "Sedação profunda com benzodiazepínicos e bloqueadores neuromusculares em todos os casos.", "Manutenção da temperatura corporal elevada para promover vasodilatação cerebral."], correctIndex: 1, explanation: "A administração de soluções osmóticas como salina hipertônica ou manitol é uma estratégia de primeira linha para reduzir a PIC em pacientes com LCE, pois retira água do parênquima cerebral. A hiperventilação controlada e breve também pode ser usada, mas a hiperventilação prolongada é prejudicial.", category: "UTI" },
  { id: 1023, question: "Qual a principal causa de mortalidade por infecção na UTI?", options: ["Infecções do trato urinário.", "Sepse e choque séptico.", "Celulite e infecções de pele.", " Meningite."], correctIndex: 1, explanation: "Sepse e choque séptico são as principais causas de morbidade e mortalidade infecciosa na UTI, representando um desafio diagnóstico e terapêutico constante e sendo foco de diversas diretrizes e pesquisas.", category: "UTI" },
  { id: 1024, question: "Em pacientes com lesão renal aguda (LRA) na UTI, qual das seguintes intervenções é a mais importante para prevenir a progressão da lesão?", options: ["Administração de altas doses de diuréticos de alça.", "Monitorização para evitar nefrotoxinas e otimização hemodinâmica e volêmica.", "Início precoce de terapia de substituição renal em todos os casos de LRA.", "Restrição hídrica agressiva para evitar edema."], correctIndex: 1, explanation: "A prevenção e o manejo da LRA na UTI envolvem evitar nefrotoxinas (incluindo alguns contrastes, antimicrobianos, anti-inflamatórios), otimizar o estado hemodinâmico e volêmico para garantir a perfusão renal adequada, além de suporte nutricional e correção de distúrbios eletrolíticos.", category: "UTI" },
  { id: 1025, question: "Qual das seguintes estratégias é recomendada para o desmame de pacientes de ventilação mecânica invasiva?", options: ["Tentativa de extubação imediata após 24h de ventilação, independentemente da causa.", "Testes de respiração espontânea diários em pacientes com critérios de prontidão para o desmame.", "Uso de sedação contínua e profunda durante todo o processo de desmame.", "Manter o paciente em ventilação assistida por mais tempo para prevenir falha da extubação."], correctIndex: 1, explanation: "Os testes de respiração espontânea (TRE) diários são fundamentais para o processo de desmame em pacientes que preenchem os critérios de prontidão. Essa abordagem dinâmica e diária reduz o tempo de ventilação mecânica e as complicações associadas.", category: "UTI" },
  { id: 1026, question: "Um paciente em choque cardiogênico necessita de suporte inotrópico. Qual fármaco é o MAIS indicado, conforme as diretrizes, para aumentar a contratilidade miocárdica com menor aumento significativo da frequência cardíaca?", options: ["Adrenalina", "Dobutamina", "Noradrenalina", "Vasopressina"], correctIndex: 1, explanation: "A dobutamina é o inotrópico de escolha em choque cardiogênico para melhorar o débito cardíaco, pois aumenta a contratilidade miocárdica de forma mais proeminente e com menor efeito cronotrópico significativo em comparação com a adrenalina.", category: "UTI" },
  { id: 1027, question: "Qual é a principal complicação metabólica associada à realimentação em pacientes gravemente desnutridos na UTI?", options: ["Hipernatremia", "Síndrome de Realimentação", "Acidose metabólica severa", "Hipercalemia"], correctIndex: 1, explanation: "A Síndrome de Realimentação é uma complicação potencialmente grave que ocorre ao iniciar a nutrição em pacientes gravemente desnutridos. Caracteriza-se por distúrbios eletrolíticos (hipofosfatemia, hipocalemia, hipomagnesemia), retenção de fluidos e sobrecarga cardíaca.", category: "UTI" },
];